// ============================================================== lot 4 ======
void crypto() {
    std::printf("empreintes et codes : SHA-256, HMAC, mots de passe, TOTP\n");
    same(toHex(sha256("abc")), "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad", "SHA-256(\"abc\") (FIPS 180-4)");
    same(toHex(sha256("")), "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", "SHA-256 du vide");
    same(toHex(sha256("abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq")),
         "248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1", "SHA-256 sur deux blocs");
    same(toHex(hmacSha256("Jefe", "what do ya want for nothing?")),
         "5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843", "HMAC-SHA-256 (RFC 4231, cas 2)");
    const std::string salt = randomHex(16);
    check(salt.size() == 32 && fromHex(salt).size() == 16, "un sel de 16 octets al\xC3\xA9" "atoires");
    check(randomHex(16) != salt, "deux sels diff\xC3\xA8rent");
    const std::string hash = passwordHash(salt, "Gaz-2026!");
    check(hash.size() == 64, "empreinte SHA-256 en hexa");
    check(passwordMatches(salt, hash, "Gaz-2026!"), "le bon mot de passe passe");
    check(!passwordMatches(salt, hash, "gaz-2026!"), "la casse compte");
    check(passwordHash(randomHex(16), "Gaz-2026!") != hash, "m\xC3\xAAme mot de passe, autre sel : autre empreinte");
    // RFC 6238, annexe B, variante SHA-256 (secret de 32 octets, 8 chiffres).
    const std::string secret = toHex(reinterpret_cast<const std::uint8_t*>("12345678901234567890123456789012"), 32);
    same(dynamicCode(secret, 59, 30, 8), "46119246", "TOTP T=59");
    same(dynamicCode(secret, 1111111109, 30, 8), "68084774", "TOTP T=1111111109");
    same(dynamicCode(secret, 1234567890, 30, 8), "91819424", "TOTP T=1234567890");
    same(dynamicCode(secret, 2000000000, 30, 8), "90698825", "TOTP T=2000000000");
    const std::string code = dynamicCode(secret, 1000000000, 30, 6);
    check(code.size() == 6 && dynamicCodeMatches(secret, code, 1000000000, 30, 6), "un code \xC3\xA0 6 chiffres v\xC3\xA9rifi\xC3\xA9");
    check(dynamicCodeMatches(secret, code, 1000000025, 30, 6), "... accept\xC3\xA9 25 s plus tard (p\xC3\xA9riode voisine)");
    check(!dynamicCodeMatches(secret, code, 1000000100, 30, 6), "... refus\xC3\xA9 100 s plus tard");
    check(dynamicCodeRemaining(1000000005, 30) == 15, "secondes restantes avant le code suivant (15 s)");
}

namespace {
// Un projet de supervision : une vue, des variables de l'automate simule.
struct Supervision {
    Project   p;
    FakePlc   plc;
    History   history;
    Runtime   rt;
    Id        view{kNoId};
    double    t{0};
    Supervision() {
        View v = makeView(p, "Vue_Gaz");
        view = v.id;
        p.views.push_back(v);
        p.config.startView = view;
        plc.values["Pression"] = sim::Value::real(6.0);
        plc.values["Bouteille_Vide"] = sim::Value::boolean(false);
        plc.values["Porte_Ouverte"] = sim::Value::boolean(false);
        plc.values["Consigne"] = sim::Value::real(0);
        plc.values["Debit"] = sim::Value::integer(sim::Type::Int, 0);
        plc.values["Cle"] = sim::Value::boolean(false);
    }
    View& v() { return *p.view(view); }
    void start() {
        rt.bind(&p, &plc);
        rt.setHistory(&history);
        rt.start(t);
    }
    void run(double seconds) {
        const double end = t + seconds;
        while (t < end - 1e-9) {
            t += 0.05;
            rt.tick(t);
        }
    }
    AlarmDef& alarm(const char* name, const char* condition, int priority, const char* group = "Armoire A") {
        AlarmDef a;
        a.id = p.allocate();
        a.name = name;
        a.condition = condition;
        a.message = std::string(name) + " : pression {Pression:0.0} bar";
        a.priority = priority;
        a.group = group;
        p.alarms.push_back(a);
        return p.alarms.back();
    }
    const LiveAlarm* live(const char* name) const {
        for (const auto& a : rt.alarms()) if (a.name == name) return &a;
        return nullptr;
    }
};
bool eventHas(const Runtime& rt, std::string_view kind, std::string_view text) {
    for (const auto& e : rt.events())
        if ((kind.empty() || e.kind == kind) && (e.message.find(text) != std::string::npos || e.source.find(text) != std::string::npos))
            return true;
    return false;
}
} // namespace

void alarmes() {
    std::printf("alarmes : apparition, acquittement, disparition, historique\n");
    Supervision s;
    s.alarm("Bouteille_Vide", "Bouteille_Vide", 1);
    s.alarm("Pression_Haute", "Pression > 8.0", 2);
    auto& porte = s.alarm("Porte_Ouverte", "Porte_Ouverte", 3, "Armoire B");
    porte.delayMs = 2000;
    porte.ackRequired = false;
    s.start();
    s.run(0.5);
    check(s.rt.alarms().empty(), "au d\xC3\xA9part, aucune alarme");
    s.plc.values["Bouteille_Vide"] = sim::Value::boolean(true);
    s.plc.values["Pression"] = sim::Value::real(8.6);
    s.run(0.2);
    check(s.rt.alarms().size() == 2, "deux alarmes apparues");
    const auto* bv = s.live("Bouteille_Vide");
    check(bv && bv->active && !bv->acked && bv->state() == "Active", "Bouteille_Vide : active, non acquitt\xC3\xA9" "e");
    check(bv && bv->message == "Bouteille_Vide : pression 8.6 bar", "le message est rempli \xC3\xA0 l'apparition : " + (bv ? bv->message : std::string{}));
    check(bv && bv->appeared.size() == 23 && bv->appeared[4] == '-', "horodatage \xC3\xA0 la milliseconde : " + (bv ? bv->appeared : std::string{}));
    check(s.rt.alarms().front().priority == 1, "la plus grave en t\xC3\xAAte de liste");
    check(s.rt.unacknowledged() == 2 && s.rt.highestPriority() == 1, "2 \xC3\xA0 acquitter, priorit\xC3\xA9 1 (critique)");
    check(eventHas(s.rt, "Apparition", "Bouteille_Vide"), "\xC3\xA9v\xC3\xA9nement : apparition");
    // Acquitter une alarme : elle reste tant qu'elle est active.
    check(s.rt.acknowledge("Bouteille_Vide", s.t) == 1, "acquitter Bouteille_Vide");
    bv = s.live("Bouteille_Vide");
    check(bv && bv->acked && bv->active && bv->state() == "Acquitt\xC3\xA9" "e" && !bv->ackedAt.empty(), "acquitt\xC3\xA9" "e, toujours active");
    check(s.rt.acknowledge("Bouteille_Vide", s.t) == 0, "d\xC3\xA9j\xC3\xA0 acquitt\xC3\xA9" "e : rien \xC3\xA0 faire");
    // La pression redescend avant l'acquittement : disparue, a acquitter.
    s.plc.values["Pression"] = sim::Value::real(6.1);
    s.run(0.2);
    const auto* ph = s.live("Pression_Haute");
    check(ph && !ph->active && !ph->acked && ph->state() == "Disparue, \xC3\xA0 acquitter", "Pression_Haute : disparue, \xC3\xA0 acquitter");
    check(!ph || !ph->cleared.empty(), "heure de disparition");
    // Acquitter le groupe : elle se termine et passe a l'historique.
    check(s.rt.acknowledge("groupe:Armoire A", s.t) == 1, "acquitter le groupe Armoire A");
    check(!s.live("Pression_Haute"), "disparue et acquitt\xC3\xA9" "e : elle quitte la liste");
    check(s.history.alarms.size() == 1 && s.history.alarms.front().name == "Pression_Haute"
              && !s.history.alarms.front().acked.empty() && !s.history.alarms.front().cleared.empty(),
          "l'historique garde ses trois heures");
    // Temporisation : 2 s avant l'apparition ; sans acquittement demande.
    s.plc.values["Porte_Ouverte"] = sim::Value::boolean(true);
    s.run(1.0);
    check(!s.live("Porte_Ouverte"), "porte ouverte depuis 1 s : pas encore (temporisation 2 s)");
    s.run(1.2);
    const auto* po = s.live("Porte_Ouverte");
    check(po && po->acked, "apr\xC3\xA8s 2 s : appara\xC3\xAEt, d\xC3\xA9j\xC3\xA0 acquitt\xC3\xA9" "e (acquittement non demand\xC3\xA9)");
    check(po && po->state() == "Active, sans acquittement", "son \xC3\xA9tat le dit : active, sans acquittement");
    s.plc.values["Porte_Ouverte"] = sim::Value::boolean(false);
    s.run(0.2);
    check(!s.live("Porte_Ouverte") && s.history.alarms.size() == 2, "sa disparition la termine directement");
    // Reapparition avant acquittement.
    s.plc.values["Bouteille_Vide"] = sim::Value::boolean(false);
    s.run(0.2);
    check(!s.live("Bouteille_Vide"), "Bouteille_Vide (acquitt\xC3\xA9" "e) dispara\xC3\xAEt : termin\xC3\xA9" "e");
    // L'action "Acquitter une alarme" sur un bouton.
    auto& btn = addButton(s.p, s.v(), "Btn_Acquitter", 10, 10);
    btn.actions.push_back(act(Trigger::Click, Operation::AckAlarm, "*"));
    const Id btnId = btn.id;
    s.plc.values["Pression"] = sim::Value::real(9.0);
    s.run(0.2);
    check(s.rt.unacknowledged() == 1, "Pression_Haute revient");
    s.rt.press(btnId, s.t);
    s.rt.release(btnId, s.t, true);
    check(s.rt.unacknowledged() == 0, "clic sur Btn_Acquitter : tout est acquitt\xC3\xA9");
    check(eventHas(s.rt, "Acquittement", "Pression_Haute"), "\xC3\xA9v\xC3\xA9nement : acquittement");
    check(s.history.events.size() >= 6, "les \xC3\xA9v\xC3\xA9nements vont \xC3\xA0 l'historique (" + std::to_string(s.history.events.size()) + ")");
    check(!s.history.system.empty(), "le journal va \xC3\xA0 l'historique syst\xC3\xA8me");
    // Une condition illisible est dite une fois, sans bloquer les autres.
    s.alarm("Cassee", "Pression >", 3);
    s.run(0.3);
    std::size_t said = 0;
    for (const auto& e : s.rt.journal()) said += e.message.find("condition illisible") != std::string::npos;
    check(said == 1, "condition illisible : dite une fois");
}

void recettes() {
    std::printf("recettes : appliquer, lire, comparer, CSV, action\n");
    Supervision s;
    Variable gaz;
    gaz.id = s.p.allocate();
    gaz.name = "Gaz_Choisi";
    gaz.type = "STRING";
    gaz.initial = "''";
    s.p.programs.variables.push_back(gaz);
    Recipe r;
    r.id = s.p.allocate();
    r.name = "Gaz";
    r.fields = {{"Consigne", "Consigne", "bar", "0", "10"}, {"D\xC3\xA9" "bit", "Debit", "m3/h", "0", "500"}, {"Gaz", "Gaz_Choisi", "", "", ""}};
    RecipeRecord azote{s.p.allocate(), "Azote", {"7.5", "120", "'Azote'"}, "", ""};
    RecipeRecord argon{s.p.allocate(), "Argon", {"6.2", "90", "'Argon'"}, "", ""};
    RecipeRecord fou{s.p.allocate(), "Hors_Bornes", {"12", "90", "'Argon'"}, "", ""};
    r.records = {azote, argon, fou};
    const Id rid = r.id;
    s.p.recipes.push_back(r);
    s.start();
    std::string why;
    check(s.rt.applyRecipe("Gaz", "Azote", s.t, &why), "appliquer Gaz / Azote");
    check(std::fabs(s.plc.values["Consigne"].asReal() - 7.5) < 1e-9 && s.plc.values["Debit"].asInteger() == 120,
          "les variables de l'automate re\xC3\xA7oivent 7.5 et 120");
    same(formatValue(*s.rt.variable("Gaz_Choisi")), "Azote", "la variable IHM re\xC3\xA7oit 'Azote'");
    check(eventHas(s.rt, "Recette", "Azote appliqu"), "\xC3\xA9v\xC3\xA9nement : recette appliqu\xC3\xA9" "e");
    check(!s.rt.applyRecipe("Gaz", "Hors_Bornes", s.t, &why) && why.find("hors bornes") != std::string::npos,
          "12 bar hors de [0 ; 10] : refus\xC3\xA9 (" + why + ")");
    check(std::fabs(s.plc.values["Consigne"].asReal() - 7.5) < 1e-9, "... la consigne n'a pas boug\xC3\xA9");
    check(!s.rt.applyRecipe("Gaz", "Helium", s.t, &why), "jeu inconnu refus\xC3\xA9 : " + why);
    std::vector<std::string> live;
    check(s.rt.readRecipe("Gaz", live), "lire les valeurs de l'installation");
    check(live.size() == 3 && live[0] == "7.5" && live[1] == "120" && live[2] == "Azote",
          "lues : " + (live.size() == 3 ? live[0] + ", " + live[1] + ", " + live[2] : std::string("?")));
    const auto diff = compareValues(s.p.recipes[0], azote.values, live);
    check(diff.size() == 3 && !diff[0].differs && !diff[1].differs && !diff[2].differs, "Azote = l'installation (7.5 = 7.5, 'Azote' = Azote)");
    const auto diff2 = compareValues(s.p.recipes[0], azote.values, argon.values);
    check(diff2[0].differs && diff2[1].differs && diff2[2].differs, "Azote et Argon diff\xC3\xA8rent partout");
    check(sameRecipeValue("7.50", "7.5") && !sameRecipeValue("7.5", "7.6"), "7.50 = 7.5 (nombres)");
    // L'action "Charger une recette" : le jeu nomme, ou donne par une expression.
    auto& btn = addButton(s.p, s.v(), "Btn_Argon", 10, 10);
    btn.actions.push_back(act(Trigger::Click, Operation::LoadRecipe, "Gaz", "Argon"));
    const Id btnId = btn.id;
    s.rt.press(btnId, s.t);
    s.rt.release(btnId, s.t, true);
    check(std::fabs(s.plc.values["Consigne"].asReal() - 6.2) < 1e-9, "clic : le jeu Argon est charg\xC3\xA9");
    // CSV : exporter, puis importer dans une autre recette.
    const std::string csv = recipeCsv(s.p.recipes[0]);
    same(csv.substr(0, csv.find('\n')), "Jeu;Consigne (bar);D\xC3\xA9" "bit (m3/h);Gaz", "ent\xC3\xAAte du CSV");
    check(csv.find("Azote;7.5;120;'Azote'") != std::string::npos, "une ligne par jeu");
    Recipe copy;
    copy.id = s.p.allocate();
    copy.name = "Gaz_B";
    copy.fields = s.p.recipes[0].fields;
    copy.records = {{s.p.allocate(), "Argon", {"1", "1", "'x'"}, "", ""}};
    const Id cid = copy.id;
    s.p.recipes.push_back(copy);
    RecipeImport rep;
    check(importRecipeCsv(s.p, cid, csv + "Inconnu;1;2;3\n", &rep), "importer le CSV");
    check(rep.added == 3 && rep.replaced == 1, "3 jeux ajout\xC3\xA9s, Argon remplac\xC3\xA9 (" + std::to_string(rep.added) + "/" + std::to_string(rep.replaced) + ")");
    const auto* imported = s.p.recipe(cid);
    check(imported && imported->record("Argon") && imported->record("Argon")->values[0] == "6.2", "Argon import\xC3\xA9 : 6.2");
    std::string error;
    check(importRecipeCsv(s.p, cid, "Jeu;Inconnu\nX;1\n", &rep) && !rep.warnings.empty(), "colonne inconnue : signal\xC3\xA9" "e, pas invent\xC3\xA9" "e");
    check(!importRecipeCsv(s.p, cid, "", nullptr, &error) && !error.empty(), "fichier vide refus\xC3\xA9");
    (void)rid;
}

void securite() {
    std::printf("utilisateurs : groupes, roles, mots de passe, niveaux d'acces\n");
    Supervision s;
    const auto& sec = s.p.security;
    check(sec.groups.size() == 4 && sec.groups[0].name == "Op\xC3\xA9rateur" && sec.groups[3].name == "Administrateur",
          "4 groupes par d\xC3\xA9" "faut : Op\xC3\xA9rateur, Maintenance, Superviseur, Administrateur");
    check(sec.groups[0].level == 1 && sec.groups[3].level == 4, "niveaux 1 \xC3\xA0 4");
    check(sec.roles.size() == 4 && s.p.role("Conduite"), "4 r\xC3\xB4les par d\xC3\xA9" "faut");
    auto addUser = [&](const char* login, const char* group, const char* protection) -> User& {
        User u;
        u.id = s.p.allocate();
        u.login = login;
        u.fullName = std::string("M. ") + login;
        u.group = s.p.groupByName(group)->id;
        u.protection = protection;
        s.p.security.users.push_back(u);
        return s.p.security.users.back();
    };
    auto& op = addUser("operateur", "Op\xC3\xA9rateur", "classique");
    op.salt = randomHex(16);
    op.passwordHash = passwordHash(op.salt, "1234");
    auto& tech = addUser("technicien", "Maintenance", "dynamique");
    tech.secret = randomHex(20);
    const std::string techSecret = tech.secret;
    auto& cle = addUser("cle", "Superviseur", "expression");
    cle.expression = "Cle";
    s.p.security.enabled = true;
    check(userHas(s.p, *s.p.userByLogin("operateur"), "Acquitter") && !userHas(s.p, *s.p.userByLogin("operateur"), "Recettes"),
          "op\xC3\xA9rateur : acquitter oui, recettes non");
    check(userHas(s.p, *s.p.userByLogin("cle"), "Recettes"), "superviseur : recettes");
    // Un bouton de niveau 2, un de niveau 0 qui pilote.
    auto& maint = addButton(s.p, s.v(), "Btn_Maintenance", 10, 10);
    maint.setNumber("access", 2);
    maint.actions.push_back(act(Trigger::Click, Operation::Set, "Porte_Ouverte"));
    const Id maintId = maint.id;
    auto& pilot = addButton(s.p, s.v(), "Btn_Consigne", 10, 60);
    pilot.actions.push_back(act(Trigger::Click, Operation::Assign, "Consigne", "5.5"));
    const Id pilotId = pilot.id;
    auto& guarded = addButton(s.p, s.v(), "Btn_Garde", 10, 110);
    guarded.set("auth", "NOT Porte_Ouverte");
    guarded.actions.push_back(act(Trigger::Click, Operation::Assign, "Debit", "42"));
    const Id guardedId = guarded.id;
    s.start();
    const auto click = [&](Id id) { s.rt.press(id, s.t); s.rt.release(id, s.t, true); };
    check(s.rt.userLogin().empty() && s.rt.level() == 0, "personne connect\xC3\xA9 : niveau 0");
    click(pilotId);
    check(std::fabs(s.plc.values["Consigne"].asReal()) < 1e-9, "sans utilisateur, \xC2\xAB Piloter \xC2\xBB est refus\xC3\xA9");
    check(eventHas(s.rt, "Acc\xC3\xA8s refus\xC3\xA9", "Piloter"), "\xC3\xA9v\xC3\xA9nement : acc\xC3\xA8s refus\xC3\xA9 (permission)");
    std::string why;
    check(!s.rt.login("operateur", "0000", s.t, &why) && why == "mot de passe incorrect", "mauvais mot de passe : refus\xC3\xA9");
    check(eventHas(s.rt, "Connexion refus\xC3\xA9" "e", "operateur"), "\xC3\xA9v\xC3\xA9nement : connexion refus\xC3\xA9" "e");
    check(s.rt.login("operateur", "1234", s.t, &why), "operateur / 1234 : connect\xC3\xA9");
    check(s.rt.level() == 1 && s.rt.permitted("Piloter") && !s.rt.permitted("Recettes"), "niveau 1, piloter oui, recettes non");
    click(pilotId);
    check(std::fabs(s.plc.values["Consigne"].asReal() - 5.5) < 1e-9, "connect\xC3\xA9 : la consigne est \xC3\xA9" "crite");
    click(maintId);
    check(!s.plc.values["Porte_Ouverte"].isTruthy(), "Btn_Maintenance (niveau 2) : refus\xC3\xA9 \xC3\xA0 l'op\xC3\xA9rateur");
    check(eventHas(s.rt, "Acc\xC3\xA8s refus\xC3\xA9", "niveau d'acc\xC3\xA8s 2"), "\xC3\xA9v\xC3\xA9nement : niveau d'acc\xC3\xA8s 2 requis");
    // Le code dynamique : juste, puis faux.
    const double unixTime = 1790000000;
    check(!s.rt.login("technicien", "000000", s.t, &why, unixTime), "technicien, mauvais code : " + why);
    check(s.rt.login("technicien", dynamicCode(techSecret, unixTime, 30, 6), s.t, &why, unixTime), "technicien, code du moment : connect\xC3\xA9");
    check(s.rt.level() == 2, "niveau 2");
    click(maintId);
    check(s.plc.values["Porte_Ouverte"].isTruthy(), "Btn_Maintenance : accept\xC3\xA9 au niveau 2");
    // L'autorisation par expression (objet) : Porte_Ouverte vrai -> refuse.
    click(guardedId);
    check(s.plc.values["Debit"].asInteger() == 0, "Btn_Garde : autorisation NOT Porte_Ouverte fausse, refus\xC3\xA9");
    s.plc.values["Porte_Ouverte"] = sim::Value::boolean(false);
    click(guardedId);
    check(s.plc.values["Debit"].asInteger() == 42, "Btn_Garde : autorisation vraie, accept\xC3\xA9");
    // Connexion par expression (une cle) : refusee tant que Cle est faux.
    check(!s.rt.login("cle", {}, s.t, &why), "utilisateur \xC2\xAB cle \xC2\xBB : Cle est faux, refus\xC3\xA9");
    s.plc.values["Cle"] = sim::Value::boolean(true);
    check(s.rt.login("cle", {}, s.t, &why) && s.rt.level() == 3, "Cle vrai : connect\xC3\xA9 au niveau 3");
    // Changer d'utilisateur par une action : vers "cle" (expression) directement,
    // vers "operateur" par le dialogue (hook).
    std::string asked;
    Runtime::Hooks hooks;
    hooks.askLogin = [&](const std::string& login) { asked = login; };
    s.rt.setHooks(hooks);
    auto& change = addButton(s.p, s.v(), "Btn_Utilisateur", 10, 160);
    change.actions.push_back(act(Trigger::Click, Operation::ChangeUser, "operateur"));
    const Id changeId = change.id;
    click(changeId);
    check(asked == "operateur", "Changer d'utilisateur : l'\xC3\xA9" "cran demande le mot de passe de operateur");
    s.rt.logout(s.t, "test");
    check(s.rt.userLogin().empty() && eventHas(s.rt, "D\xC3\xA9" "connexion", "cle"), "d\xC3\xA9" "connexion, dite dans les \xC3\xA9v\xC3\xA9nements");
    // Compte desactive, utilisateur de depart, deconnexion automatique.
    for (auto& u : s.p.security.users) if (u.login == "operateur") u.enabled = false;
    check(!s.rt.login("operateur", "1234", s.t, &why) && why.find("sactiv") != std::string::npos, "compte d\xC3\xA9sactiv\xC3\xA9 : refus\xC3\xA9");
    for (auto& u : s.p.security.users) if (u.login == "operateur") u.enabled = true;
    s.p.security.startUser = "operateur";
    s.p.security.autoLogoutMin = 1;
    s.rt.start(s.t);
    check(s.rt.userLogin() == "operateur", "au lancement : l'utilisateur de d\xC3\xA9part est connect\xC3\xA9");
    s.run(59);
    check(s.rt.userLogin() == "operateur", "59 s sans clic : toujours connect\xC3\xA9");
    s.run(2);
    check(s.rt.userLogin().empty(), "60 s sans clic : d\xC3\xA9" "connexion automatique");
    // Securite eteinte : tout est permis.
    s.p.security.enabled = false;
    check(s.rt.level() == 99 && s.rt.permitted("Administrer"), "s\xC3\xA9" "curit\xC3\xA9 \xC3\xA9teinte : tout est permis");
}

void courbes() {
    std::printf("courbes : echantillons temps reel, variables archivees\n");
    Supervision s;
    const Id trend = edit::add(s.p, s.v(), Kind::Trend, 0, 0);
    s.v().object(trend)->set("variables", "Pression; Debit");
    s.v().object(trend)->setNumber("duration", 2);
    s.p.history.archived = {"Pression"};
    s.p.history.samplePeriodMs = 500;
    s.start();
    s.run(1.0);
    const auto* series = s.rt.trend(s.view, trend);
    check(series && series->size() == 2 && (*series)[0].expression == "Pression" && (*series)[1].expression == "Debit",
          "deux plumes : Pression et Debit");
    check(series && (*series)[0].points.size() >= 9, "un point par cycle IHM (" + std::to_string(series ? (*series)[0].points.size() : 0) + ")");
    s.plc.values["Pression"] = sim::Value::real(7.25);
    s.run(0.2);
    check(series && std::fabs((*series)[0].points.back().second - 7.25) < 1e-9, "la courbe suit la variable (7.25)");
    s.run(5);
    check(series && (*series)[0].points.front().first >= s.t - 3.5, "fen\xC3\xAAtre glissante : les points trop vieux tombent");
    check(s.history.samples.size() >= 12 && s.history.samples.size() <= 14,
          "variable archiv\xC3\xA9" "e toutes les 500 ms : " + std::to_string(s.history.samples.size()) + " mesures en 6,2 s");
    check(!s.history.samples.empty() && s.history.samples.back().variable == "Pression" && s.history.samples.back().epoch > 1.7e9,
          "mesure horodat\xC3\xA9" "e (secondes depuis 1970)");
}

void persistanceLot4() {
    std::printf("persistance : alarmes, recettes, securite, historiques\n");
    Supervision s;
    auto& a = s.alarm("Bouteille_Vide", "Bouteille_Vide AND NOT Porte_Ouverte", 1);
    a.category = "D\xC3\xA9" "faut";
    a.delayMs = 1500;
    a.ackRequired = false;
    a.description = "Bouteille \"A\" ; vide";
    Recipe r;
    r.id = s.p.allocate();
    r.name = "Gaz";
    r.description = "Consignes par gaz";
    r.fields = {{"Consigne", "Consigne", "bar", "0", "10"}, {"Gaz", "Gaz_Choisi", "", "", ""}};
    r.records = {{s.p.allocate(), "Azote", {"7.5", "'Azote ; pur'"}, "d\xC3\xA9" "faut", "2026-09-22 08:00"}};
    s.p.recipes.push_back(r);
    User u;
    u.id = s.p.allocate();
    u.login = "operateur";
    u.fullName = "Op\xC3\xA9rateur de nuit";
    u.group = s.p.security.groups[0].id;
    u.salt = randomHex(16);
    // Un mot de passe qui ne peut pas sortir par hasard d'une empreinte en
    // hexadecimal ou d'une heure (1234 le pouvait : le test echouait parfois).
    u.passwordHash = passwordHash(u.salt, "Nuit-Gaz!");
    s.p.security.users.push_back(u);
    s.p.security.enabled = true;
    s.p.security.startUser = "operateur";
    s.p.security.roles[0].permissions.push_back("Recettes");
    s.p.security.groups[1].level = 3;
    s.p.history.archived = {"Pression", "Debit"};
    s.p.history.maxEntries = 500;
    const fs::path dir = fs::temp_directory_path() / "hmi_test_lot4";
    fs::remove_all(dir);
    check(static_cast<bool>(save(s.p, dir.string())), "enregistrer");
    auto back = load(dir.string());
    check(static_cast<bool>(back), "relire");
    if (back) {
        Project expected = s.p;
        expected.config.created = back->config.created;
        expected.config.modified = back->config.modified;
        check(back->alarms == expected.alarms, "alarmes relues \xC3\xA0 l'identique (guillemets, point-virgule)");
        check(back->recipes == expected.recipes, "recettes relues \xC3\xA0 l'identique");
        check(back->security == expected.security, "s\xC3\xA9" "curit\xC3\xA9 relue \xC3\xA0 l'identique (r\xC3\xB4les, groupes, utilisateurs)");
        check(back->history == expected.history, "r\xC3\xA9glages des historiques relus");
        check(*back == expected, "le projet entier est identique");
        check(passwordMatches(back->security.users[0].salt, back->security.users[0].passwordHash, "Nuit-Gaz!"),
              "le mot de passe marche apr\xC3\xA8s relecture (empreinte, pas de clair)");
    }
    std::string index;
    {
        std::ifstream in(dir / "ihm" / "ihm.txt", std::ios::binary);
        index.assign(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
    }
    check(index.find("Nuit-Gaz!") == std::string::npos, "le mot de passe n'est nulle part en clair dans ihm.txt");
    // Un projet sans securite (format 3) garde les groupes par defaut.
    Project old;
    old.views.push_back(makeView(old, "V"));
    old.security = Security{};
    const fs::path dir3 = fs::temp_directory_path() / "hmi_test_lot4_f3";
    fs::remove_all(dir3);
    (void)save(old, dir3.string());
    {
        std::ifstream in(dir3 / "ihm" / "ihm.txt", std::ios::binary);
        std::string text((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
        std::string kept;
        std::istringstream lines(text);
        for (std::string line; std::getline(lines, line);)
            if (line.rfind("securite", 0) != 0 && line.rfind("role", 0) != 0 && line.rfind("groupe", 0) != 0
                && line.rfind("historique", 0) != 0)
                kept += line + "\n";
        std::ofstream out(dir3 / "ihm" / "ihm.txt", std::ios::binary);
        out << kept;
    }
    auto old3 = load(dir3.string());
    check(old3 && old3->security.groups.size() == 4 && !old3->security.enabled, "un projet du lot 3 se relit : 4 groupes par d\xC3\xA9" "faut, s\xC3\xA9" "curit\xC3\xA9 \xC3\xA9teinte");
    fs::remove_all(dir3);
    // L'historique : quatre CSV, relus a l'identique.
    History h;
    h.alarms.push_back({3, "Bouteille_Vide", "Bouteille A ; vide \"test\"", "Armoire A", "D\xC3\xA9" "faut", 1,
                        "2026-09-22 08:00:00.000", "2026-09-22 08:00:05.000", "2026-09-22 08:01:00.000", "operateur"});
    h.events.push_back({"2026-09-22 08:00:00.000", "Apparition", "Bouteille_Vide", "[Critique] Bouteille A\nvide", "operateur"});
    h.system.push_back({"2026-09-22 07:59:00.000", "Syst\xC3\xA8me", "", "IHM d\xC3\xA9marr\xC3\xA9" "e", ""});
    h.samples.push_back({"2026-09-22 08:00:00.500", 1790000000.5, "Pression", 7.25});
    check(static_cast<bool>(saveHistory(h, dir.string())), "enregistrer l'historique");
    check(fs::exists(dir / "ihm" / "historique" / "alarmes.csv") && fs::exists(dir / "ihm" / "historique" / "mesures.csv"),
          "ihm/historique/alarmes.csv, evenements.csv, systeme.csv, mesures.csv");
    std::vector<std::string> warnings;
    const History h2 = loadHistory(dir.string(), &warnings);
    check(h2 == h && warnings.empty(), "historique relu \xC3\xA0 l'identique (; \" et retour \xC3\xA0 la ligne)");
    // Borner : les plus anciennes tombent ; la conservation en jours.
    History big;
    for (int i = 0; i < 30; ++i)
        big.events.push_back({i < 10 ? "2026-01-01 00:00:00.000" : "2026-09-22 00:00:00.000", "E", "", std::to_string(i), ""});
    HistorySettings hs;
    hs.maxEntries = 25;
    hs.retentionDays = 30;
    big.trim(hs, "2026-09-22 08:00:00.000");
    check(big.events.size() == 20 && big.events.front().message == "10", "25 au plus, et rien de plus vieux que 30 jours");
    fs::remove_all(dir);
}

void archive() {
    std::printf("exporter / importer : archive, manifeste, controle de coherence\n");
    Supervision s;
    s.alarm("Bouteille_Vide", "Bouteille_Vide", 1);
    Recipe r;
    r.id = s.p.allocate();
    r.name = "Gaz";
    r.fields = {{"Consigne", "Consigne", "bar", "0", "10"}};
    r.records = {{s.p.allocate(), "Azote", {"7.5"}, "", ""}};
    s.p.recipes.push_back(r);
    Resource res;
    res.id = s.p.allocate();
    res.name = "logo.png";
    res.format = "PNG";
    res.data = std::make_shared<Bytes>(Bytes{0x89, 'P', 'N', 'G', 1, 2, 3, 0, 255});
    res.bytes = res.data->size();
    s.p.assets.resources.push_back(res);
    Script sc;
    sc.id = s.p.allocate();
    sc.name = "Init";
    sc.event = "Demarrage";
    sc.body = "Consigne := 1.0;\n";
    s.p.programs.scripts.push_back(sc);
    (void)edit::add(s.p, s.v(), Kind::Button, 10, 10);
    History h;
    h.events.push_back({"2026-09-22 08:00:00.000", "Apparition", "Bouteille_Vide", "vide", ""});
    const fs::path zip = fs::temp_directory_path() / "hmi_test_archive.zip";
    fs::remove(zip);
    ArchiveReport rep;
    check(static_cast<bool>(exportArchive(s.p, &h, zip.string(), &rep)), "exporter l'archive");
    check(fs::exists(zip) && rep.archiveBytes == fs::file_size(zip), "le fichier .zip, de la taille annonc\xC3\xA9" "e");
    bool hasIndex = false, hasScript = false, hasResource = false, hasHistory = false;
    for (const auto& e : rep.entries) {
        hasIndex = hasIndex || e.path == "ihm/ihm.txt";
        hasScript = hasScript || e.path.rfind("ihm/scripts/", 0) == 0;
        hasResource = hasResource || e.path.rfind("ihm/ressources/", 0) == 0;
        hasHistory = hasHistory || e.path == "ihm/historique/evenements.csv";
        check(e.sha256.size() == 64, "empreinte SHA-256 : " + e.path);
    }
    check(hasIndex && hasScript && hasResource && hasHistory, "l'archive contient index, vues, scripts, ressources, historique");
    History back;
    ArchiveReport in;
    auto imported = importArchive(zip.string(), &back, &in);
    check(static_cast<bool>(imported), "importer l'archive");
    if (imported) {
        Project expected = s.p;
        // Le contenu des ressources est compare a part (octet pour octet) :
        // l'egalite du projet compare leurs pointeurs.
        if (imported->assets.resources.size() == expected.assets.resources.size())
            for (std::size_t i = 0; i < expected.assets.resources.size(); ++i)
                if (imported->assets.resources[i].data && expected.assets.resources[i].data
                    && *imported->assets.resources[i].data == *expected.assets.resources[i].data)
                    expected.assets.resources[i].data = imported->assets.resources[i].data;
        check(*imported == expected, "reconstruction compl\xC3\xA8te : le projet relu est identique");
        check(imported->assets.resources.size() == 1 && *imported->assets.resources[0].data == *res.data, "la ressource, octet pour octet");
    }
    check(back == h, "l'historique suit l'archive");
    check(in.coherent(), "contr\xC3\xB4le de coh\xC3\xA9rence : rien \xC3\xA0 redire");
    bool counted = false;
    for (const auto& c : in.counts) counted = counted || (c.section == "Alarmes" && c.expected == 1 && c.found == 1);
    check(counted, "le manifeste annonce 1 alarme, 1 est relue");
    // Une archive alteree : un octet de la ressource change.
    std::string bytes;
    {
        std::ifstream f(zip, std::ios::binary);
        bytes.assign(std::istreambuf_iterator<char>(f), std::istreambuf_iterator<char>());
    }
    const auto at = bytes.find(std::string("\x89PNG\x01\x02\x03", 7));
    check(at != std::string::npos, "la ressource est stock\xC3\xA9" "e telle quelle (sans compression)");
    if (at != std::string::npos) {
        bytes[at + 5] = 9;
        const fs::path bad = fs::temp_directory_path() / "hmi_test_archive_alteree.zip";
        {
            std::ofstream f(bad, std::ios::binary);
            f << bytes;
        }
        ArchiveReport badRep;
        auto again = importArchive(bad.string(), nullptr, &badRep);
        check(!badRep.coherent(), "archive alt\xC3\xA9r\xC3\xA9" "e : le contr\xC3\xB4le le voit (" + (badRep.problems.empty() ? std::string{} : badRep.problems.front()) + ")");
        fs::remove(bad);
    }
    auto none = importArchive((fs::temp_directory_path() / "absent_hmi.zip").string());
    check(!none, "une archive absente est refus\xC3\xA9" "e");
    fs::remove(zip);
}

void verificationsLot4() {
    std::printf("generer et compiler : alarmes, recettes, utilisateurs, courbes\n");
    Supervision s;
    const NameExists plc = [&](std::string_view n) { return s.plc.values.count(std::string(n)) != 0; };
    s.alarm("Sans_Condition", "", 2);
    s.alarm("Inconnue", "Niveau_Inconnu > 3", 2);
    auto& msg = s.alarm("Message_Casse", "Pression > 8", 2);
    msg.message = "pression {Pression +} bar";
    auto& dup = s.alarm("Inconnue", "Pression > 1", 5);
    (void)dup;
    Recipe r;
    r.id = s.p.allocate();
    r.name = "Gaz";
    r.fields = {{"Consigne", "Consigne_Inconnue", "bar", "0", "10"}, {"Debit", "Debit", "", "10", "1"}};
    r.records = {{s.p.allocate(), "Azote", {"12", "("}, "", ""}};
    s.p.recipes.push_back(r);
    User nopass;
    nopass.id = s.p.allocate();
    nopass.login = "sans_mdp";
    nopass.group = s.p.security.groups[0].id;
    s.p.security.users.push_back(nopass);
    User badgroup = nopass;
    badgroup.id = s.p.allocate();
    badgroup.login = "SANS_MDP";
    badgroup.group = 12345;
    s.p.security.users.push_back(badgroup);
    s.p.security.enabled = true;
    const Id trend = edit::add(s.p, s.v(), Kind::Trend, 0, 0);
    s.v().object(trend)->set("variables", "Pression;Temperature_Inconnue");
    auto& b = addButton(s.p, s.v(), "Btn", 10, 10);
    b.actions.push_back(act(Trigger::Click, Operation::AckAlarm, "Alarme_Absente"));
    b.actions.push_back(act(Trigger::Click, Operation::LoadRecipe, "Recette_Absente", "X"));
    b.actions.push_back(act(Trigger::Click, Operation::ChangeUser, "fantome"));
    b.setNumber("access", 7);
    const auto issues = generate(s.p, plc, {});
    const auto has = [&](std::string_view cat, std::string_view text) {
        for (const auto& i : issues) if (i.category == cat && i.message.find(text) != std::string::npos) return true;
        return false;
    };
    check(has("Alarme", "aucune condition"), "alarme sans condition");
    check(has("Alarme", "variable inexistante dans la condition : Niveau_Inconnu"), "alarme : variable inexistante");
    check(has("Alarme", "alarme en double : Inconnue"), "alarme en double");
    check(has("Alarme", "hors de 1"), "priorit\xC3\xA9 5 hors de 1 \xC3\xA0 4");
    check(has("Alarme", "message"), "message d'alarme mal form\xC3\xA9");
    check(has("Recette", "variable inexistante Consigne_Inconnue"), "recette : variable inexistante");
    check(has("Recette", "minimum sup\xC3\xA9rieur au maximum"), "recette : bornes invers\xC3\xA9" "es");
    check(has("Recette", "hors bornes"), "recette : 12 hors de [0 ; 10]");
    check(has("Recette", "illisible"), "recette : valeur illisible");
    check(has("Utilisateur", "aucun mot de passe"), "utilisateur sans mot de passe");
    check(has("Utilisateur", "identifiant en double"), "identifiant en double (sans casse)");
    check(has("Utilisateur", "groupe introuvable"), "groupe introuvable");
    check(has("Courbe", "variable inexistante : Temperature_Inconnue"), "courbe : plume inconnue");
    check(has("Action", "alarme 'Alarme_Absente' introuvable"), "action : alarme introuvable");
    check(has("Action", "recette 'Recette_Absente' introuvable"), "action : recette introuvable");
    check(has("Action", "utilisateur 'fantome' introuvable"), "action : utilisateur introuvable");
    check(has("S\xC3\xA9" "curit\xC3\xA9", "niveau d'acc\xC3\xA8s 7"), "niveau d'acc\xC3\xA8s 7 : aucun groupe ne l'atteint");
    bool itemSet = false;
    for (const auto& i : issues) itemSet = itemSet || (i.category == "Alarme" && i.item != kNoId);
    check(itemSet, "un constat d'alarme d\xC3\xA9signe l'alarme (aller \xC3\xA0 la source)");
    const auto compiled = compile(s.p);
    bool bilan = false, alarmExpr = false;
    for (const auto& i : compiled) {
        bilan = bilan || (i.category == "Bilan" && i.message.find("alarme(s)") != std::string::npos);
        alarmExpr = alarmExpr || (i.category == "Recette" && i.message.find("(") != std::string::npos);
    }
    check(bilan, "Compiler : le bilan compte les alarmes");
    check(alarmExpr, "Compiler : une valeur de recette illisible");
}


// ================================================================= lot 6 ====
//  Les ecrans modeles, l'en-tete et le pied : composition, ordre d'execution,
//  origine dans le journal, disque, verifications.
Script viewScript(Project& p, const char* event, const char* body) {
    Script sc;
    sc.id = p.allocate();
    sc.name = event;
    sc.event = event;
    sc.body = body;
    return sc;
}

void modelesLot6() {
    std::printf("lot 6 : ecrans modeles, en-tete, pied de page\n");
    Supervision s;
    // Un ecran modele : un cadre, un bouton, un script et une action d'ouverture.
    View modele = makeView(s.p, "Modele");
    modele.role = "modele";
    modele.width = 1280;
    modele.height = 800;
    const Id cadre = edit::add(s.p, modele, Kind::Rectangle, 0, 0);
    modele.object(cadre)->name = "Cadre";
    auto& nav = addButton(s.p, modele, "Btn_Nav", 1170, 120);
    nav.actions.push_back(act(Trigger::Click, Operation::Log, {}, "modele clic"));
    const Id navId = nav.id;
    modele.scripts.push_back(viewScript(s.p, "OnOpen", "IHM_JOURNAL('modele OnOpen');"));
    modele.actions.push_back(act(Trigger::ViewOpen, Operation::Log, {}, "modele ouverture"));
    // Un en-tete de 80 et un pied de 40.
    View entete = makeView(s.p, "Entete");
    entete.role = "entete";
    entete.width = 1280;
    entete.height = 80;
    const Id titre = edit::add(s.p, entete, Kind::Text, 20, 10);
    entete.object(titre)->name = "Titre";
    entete.object(titre)->set("text", "Pression {Pression:0.0}");
    View pied = makeView(s.p, "Pied");
    pied.role = "pied";
    pied.width = 1280;
    pied.height = 40;
    const Id bas = edit::add(s.p, pied, Kind::Text, 20, 8);
    pied.object(bas)->name = "Bas";
    // La vue : elle herite du modele, coche l'en-tete et le pied.
    View& vue = s.v();
    vue.width = 1280;
    vue.height = 800;
    vue.templateView = modele.id;
    vue.showHeader = true;
    vue.showFooter = true;
    const Id contenu = edit::add(s.p, vue, Kind::Text, 40, 100);
    vue.object(contenu)->name = "Contenu";
    vue.scripts.push_back(viewScript(s.p, "OnOpen", "IHM_JOURNAL('vue OnOpen');"));
    vue.actions.push_back(act(Trigger::ViewOpen, Operation::Log, {}, "vue ouverture"));
    const Id modeleId = modele.id, enteteId = entete.id, piedId = pied.id;
    s.p.views.push_back(std::move(modele));
    s.p.views.push_back(std::move(entete));
    s.p.views.push_back(std::move(pied));

    const View& v = s.v();
    const auto chain = templateChain(s.p, v);
    check(chain.size() == 1 && chain[0]->id == modeleId, "la cha\xC3\xAEne de mod\xC3\xA8les : Modele");
    check(headerOf(s.p, v) && headerOf(s.p, v)->id == enteteId, "l'en-t\xC3\xAAte coch\xC3\xA9 : le premier du projet");
    check(footerOf(s.p, v) && footerOf(s.p, v)->id == piedId, "le pied coch\xC3\xA9");
    check(inherits(s.p, v) && !inherits(s.p, *s.p.view(modeleId)), "la vue emprunte, le mod\xC3\xA8le non");
    const View c = compose(s.p, v);
    std::string order;
    for (const auto* o : c.paintOrder()) order += o->name + " ";
    same(order, "Cadre Btn_Nav Contenu Titre Bas ", "le dessin : le mod\xC3\xA8le dessous, la vue, puis l'en-t\xC3\xAAte et le pied");
    near(c.object(bas)->number("y"), 8 + 800 - 40, "le pied est descendu en bas de la vue (y = 768)");
    check(c.scripts.size() == 2 && c.scripts[0].body.find("modele") != std::string::npos, "les scripts : ceux du mod\xC3\xA8le d'abord");
    const auto origins = actionOrigins(s.p, v);
    check(origins.size() == 2 && origins[0] == modeleId && origins[1] == v.id, "l'origine de chaque action de vue");
    check(viewsUsing(s.p, modeleId).size() == 1 && viewsUsing(s.p, enteteId).size() == 1, "le mod\xC3\xA8le et l'en-t\xC3\xAAte : utilis\xC3\xA9s par une vue");
    same(std::string(viewRoleLabel("modele")), "\xC3\x89" "cran mod\xC3\xA8le", "le libell\xC3\xA9 d'un r\xC3\xB4le");
    same(std::string(viewRoleFromLabel("Mod\xC3\xA8le de pied de page")), "pied", "et l'inverse");

    // En marche : le modele passe en premier, et le journal dit d'ou vient l'action.
    s.start();
    std::vector<std::string> msgs;
    for (const auto& e : s.rt.journal()) if (e.kind == "Journal") msgs.push_back(e.source + " | " + e.message);
    std::size_t iModele = 99, iVue = 99, iOuvM = 99, iOuvV = 99;
    for (std::size_t i = 0; i < msgs.size(); ++i) {
        if (msgs[i].find("modele OnOpen") != std::string::npos) iModele = i;
        if (msgs[i].find("vue OnOpen") != std::string::npos) iVue = i;
        if (msgs[i].find("modele ouverture") != std::string::npos) iOuvM = i;
        if (msgs[i].find("vue ouverture") != std::string::npos) iOuvV = i;
    }
    check(iModele < iVue, "OnOpen du mod\xC3\xA8le avant celui de la vue");
    check(iOuvM < iOuvV, "l'action d'ouverture du mod\xC3\xA8le avant celle de la vue");
    check(iModele < msgs.size() && msgs[iModele].find("(Modele)") != std::string::npos, "le journal : le script vient du mod\xC3\xA8le (" +
          (iModele < msgs.size() ? msgs[iModele] : std::string("?")) + ")");
    check(iOuvM < msgs.size() && msgs[iOuvM].find("Vue_Gaz (Modele)") != std::string::npos, "le journal : l'action vient du mod\xC3\xA8le");
    s.rt.press(navId, s.t);
    s.rt.release(navId, s.t, true);
    check(journalHas(s.rt, "Journal", "modele clic"), "un bouton du mod\xC3\xA8le r\xC3\xA9pond au clic dans la vue");
    bool fromTemplate = false;
    for (const auto& e : s.rt.journal())
        fromTemplate = fromTemplate || (e.message == "modele clic" && e.source.find("Btn_Nav (Modele)") != std::string::npos);
    check(fromTemplate, "... et le journal le dit : Vue_Gaz/Btn_Nav (Modele)");
    const auto* composed = s.rt.composedView(s.view);
    check(composed && composed->objects.size() == 5, "le moteur tourne la vue compos\xC3\xA9" "e (5 objets)");

    // Le disque : roles, modele, cases cochees.
    const fs::path dir = fs::temp_directory_path() / "hmi_test_lot6_modeles";
    fs::remove_all(dir);
    check(static_cast<bool>(save(s.p, dir.string())), "enregistrer");
    auto back = load(dir.string());
    check(static_cast<bool>(back), "relire");
    if (back) {
        const auto* bv = back->view(s.view);
        const auto* bm = back->view(modeleId);
        check(bv && bv->templateView == modeleId && bv->showHeader && bv->showFooter, "relu : le mod\xC3\xA8le et les deux cases");
        check(bm && bm->role == "modele" && back->view(enteteId)->role == "entete" && back->view(piedId)->role == "pied",
              "relu : les r\xC3\xB4les");
        check(back->views == s.p.views, "relu : les vues identiques");
    }
    fs::remove_all(dir);

    // Generer : rien a redire, puis les erreurs du lot 6.
    const NameExists plc = [&](std::string_view n) { return s.plc.values.count(std::string(n)) != 0; };
    const auto has = [&](const std::vector<Issue>& issues, std::string_view cat, std::string_view text) {
        for (const auto& i : issues) if (i.category == cat && i.message.find(text) != std::string::npos) return true;
        return false;
    };
    const auto clean = generate(s.p, plc, {});
    bool anyModel = false;
    for (const auto& i : clean) anyModel = anyModel || (i.category == "Mod\xC3\xA8le" && i.severity == Issue::Severity::Error);
    check(!anyModel, "G\xC3\xA9n\xC3\xA9rer : aucune erreur de mod\xC3\xA8le sur un projet sain");
    Project bad = s.p;
    bad.view(modeleId)->templateView = s.view;                        // un modele qui herite d'une vue ordinaire
    View m2 = makeView(bad, "Modele_2");
    m2.role = "modele";
    m2.templateView = modeleId;
    const Id m2Id = m2.id;
    bad.views.push_back(m2);
    bad.view(modeleId)->templateView = m2Id;                          // Modele -> Modele_2 -> Modele
    std::string broken;
    (void)templateChain(bad, *bad.view(s.view), &broken);
    check(broken.find("circulaire") != std::string::npos, "un h\xC3\xA9ritage circulaire s'arr\xC3\xAAte : " + broken);
    bad.config.startView = modeleId;
    bad.view(s.view)->role = "bizarre";
    auto& btn = addButton(bad, *bad.view(s.view), "Btn_Vers_Entete", 10, 10);
    btn.actions.push_back(act(Trigger::Click, Operation::Navigate, "Entete"));
    bad.views.erase(std::remove_if(bad.views.begin(), bad.views.end(), [&](const View& x) { return x.id == piedId; }), bad.views.end());
    const auto issues = generate(bad, plc, {});
    check(has(issues, "Mod\xC3\xA8le", "circulaire"), "G\xC3\xA9n\xC3\xA9rer : h\xC3\xA9ritage circulaire");
    check(has(issues, "Mod\xC3\xA8le", "vue de d\xC3\xA9marrage"), "G\xC3\xA9n\xC3\xA9rer : la vue de d\xC3\xA9marrage est un mod\xC3\xA8le");
    check(has(issues, "Mod\xC3\xA8le", "r\xC3\xB4le inconnu"), "G\xC3\xA9n\xC3\xA9rer : r\xC3\xB4le inconnu");
    check(has(issues, "Mod\xC3\xA8le", "aucun mod\xC3\xA8le de ce genre"), "G\xC3\xA9n\xC3\xA9rer : pied coch\xC3\xA9 sans mod\xC3\xA8le de pied");
    check(has(issues, "Action", "on n'y navigue pas"), "G\xC3\xA9n\xC3\xA9rer : naviguer vers un mod\xC3\xA8le d'en-t\xC3\xAAte");
}

// Les objets a contenu : image animee, tableau, courbe, gestionnaire de
// recettes ; les actions sur les ressources.
void objetsLot6() {
    std::printf("lot 6 : image animee, tableau, gestionnaire de recettes, ressources\n");
    // ---- les formats en texte
    const auto states = parseImageStates("Bouteille_Vide => a.png, b.png @ 100\n\n  Pression > 5 => c.png\nd.png");
    check(states.size() == 3, "trois \xC3\xA9tats (une ligne vide ignor\xC3\xA9" "e)");
    check(states[0].condition == "Bouteille_Vide" && states[0].images.size() == 2 && states[0].periodMs == 100, "\xC3\xA9tat 1 : condition, 2 images, 100 ms");
    check(states[2].condition.empty() && states[2].images == std::vector<std::string>{"d.png"}, "une ligne sans => : toujours vraie");
    same(formatImageStates(states), "Bouteille_Vide => a.png, b.png @ 100\nPression > 5 => c.png\nTRUE => d.png", "et r\xC3\xA9\xC3\xA9" "crits");
    same(imageFrame(states[0], 500, 0.05), "a.png", "d\xC3\xA9" "filement : 1re image \xC3\xA0 50 ms");
    same(imageFrame(states[0], 500, 0.15), "b.png", "d\xC3\xA9" "filement : 2e image \xC3\xA0 150 ms");
    same(imageFrame(states[0], 500, 0.25), "a.png", "d\xC3\xA9" "filement : on reboucle");
    const auto cells = parseCells("Pression\t{Pression:0.0}\t=Pression * 2\nDebit\t=Debit\t");
    check(cells.size() == 2 && cells[0].size() == 3 && cells[1].size() == 3, "deux lignes de trois cases");
    check(cellIsExpression(cells[0][2]) && cellIsTemplate(cells[0][1]) && !cellIsTemplate(cells[0][0]), "case : expression, texte \xC3\xA0 trous, texte");
    same(formatCells(cells), "Pression\t{Pression:0.0}\t=Pression * 2\nDebit\t=Debit\t", "les cases r\xC3\xA9\xC3\xA9" "crites");
    Object t;
    t.set("widths", "2;1;1");
    const auto fr = columnFractions(t, 3);
    near(fr[0], 0.5, "largeurs relatives 2;1;1 : la premi\xC3\xA8re moiti\xC3\xA9");
    near(fr[1] + fr[2], 0.5, "... les deux autres le reste");
    check(splitSemicolons(" a ; b;;c ") == std::vector<std::string>{"a", "b", "", "c"}, "a;b;;c : les vides gard\xC3\xA9s");

    // ---- l'evaluation en marche (LiveView)
    Supervision s;
    const Id tab = edit::add(s.p, s.v(), Kind::Table, 10, 10);
    s.v().object(tab)->name = "Tab";
    s.v().object(tab)->set("cells", "Pression\t{Pression:0.0}\t=Pression * 2\nX\t=Inconnue + 1\t");
    const Id anim = edit::add(s.p, s.v(), Kind::AnimatedImage, 300, 10);
    s.v().object(anim)->name = "Anim";
    s.v().object(anim)->set("states", "Bouteille_Vide => a.png, b.png @ 100\nPression > 5 => c.png");
    s.v().object(anim)->set("image", "defaut.png");
    LiveView live;
    live.bind(s.v());
    std::vector<LiveValue> values;
    auto shown = live.evaluate(s.plc, &values, nullptr, 0.0);
    same(shown.object(tab)->text("cells"), "Pression\t6.0\t12\nX\t###\t", "le tableau \xC3\xA9valu\xC3\xA9 : 6.0, 12, ### (variable inconnue)");
    bool cellError = false;
    for (const auto& lv : values) cellError = cellError || (lv.key == "cells[2,2]" && lv.error);
    check(cellError, "la case en erreur est signal\xC3\xA9" "e (cells[2,2])");
    same(shown.object(anim)->text("image"), "c.png", "image anim\xC3\xA9" "e : le 2e \xC3\xA9tat est vrai (Pression > 5)");
    near(shown.object(anim)->number("stateShown"), 2, "... son rang");
    s.plc.values["Bouteille_Vide"] = sim::Value::boolean(true);
    same(live.evaluate(s.plc, nullptr, nullptr, 0.05).object(anim)->text("image"), "a.png", "le 1er \xC3\xA9tat l'emporte : a.png");
    same(live.evaluate(s.plc, nullptr, nullptr, 0.15).object(anim)->text("image"), "b.png", "... puis b.png 100 ms plus tard");
    s.plc.values["Bouteille_Vide"] = sim::Value::boolean(false);
    s.plc.values["Pression"] = sim::Value::real(2.0);
    same(live.evaluate(s.plc, nullptr, nullptr, 0.0).object(anim)->text("image"), "defaut.png", "aucun \xC3\xA9tat vrai : l'image par d\xC3\xA9" "faut");
    s.plc.values["Pression"] = sim::Value::real(6.0);

    // ---- le gestionnaire de recettes : sa geometrie, ses clics
    const Id gm = edit::add(s.p, s.v(), Kind::RecipeManager, 10, 300);
    auto* g = s.v().object(gm);
    g->name = "Gestion";
    g->set("recipe", "Gaz");
    const auto l = recipeManagerLayout(*g, 560, 260);
    check(l.buttons.size() == 5 && l.buttons[0].label == "Ajouter" && l.buttons[4].label == "Lire", "cinq boutons, dans l'ordre");
    check(l.visibleRows >= 5, "des lignes pour les jeux");
    same(recipeManagerHit(*g, 560, 260, l.buttons[3].box.cx(), l.buttons[3].box.cy(), 3), "bouton:Appliquer", "un clic sur Appliquer");
    same(recipeManagerHit(*g, 560, 260, 100, l.table.y + l.headerH + l.rowH * 1.5, 3), "ligne:1", "un clic sur la 2e ligne");
    same(recipeManagerHit(*g, 560, 260, 100, l.table.y + l.headerH + l.rowH * 4.5, 3), "", "sous le dernier jeu : rien");
    g->set("buttons", "Appliquer;Lire");
    check(recipeManagerLayout(*g, 560, 260).buttons.size() == 2, "buttons : seulement ceux qu'on veut");
    g->set("buttons", "Ajouter;Modifier;Supprimer;Appliquer;Lire");
    Recipe r;
    r.id = s.p.allocate();
    r.name = "Gaz";
    r.fields = {{"Consigne", "Consigne", "bar", "0", "10"}, {"D\xC3\xA9" "bit", "Debit", "m3/h", "0", "500"}};
    const RecipeRecord azote{s.p.allocate(), "Azote", {"7.5", "120"}, "", ""};
    const RecipeRecord argon{s.p.allocate(), "Argon", {"6.2", "90"}, "", ""};
    r.records = {azote, argon};
    s.p.recipes.push_back(r);
    Variable gazVar;
    gazVar.id = s.p.allocate();
    gazVar.name = "Gaz_Choisi";
    gazVar.type = "STRING";
    gazVar.initial = "'Azote'";
    s.p.programs.variables.push_back(gazVar);
    s.p.recipes[0].fields.push_back({"Gaz", "Gaz_Choisi", "", "", ""});
    s.p.recipes[0].records[0].values.push_back("'Azote'");
    s.p.recipes[0].records[1].values.push_back("'Argon'");
    std::vector<RecipeRequest> requests;
    Runtime::Hooks hooks;
    hooks.recipeRequest = [&](const RecipeRequest& rq) { requests.push_back(rq); };
    std::vector<ResourceRequest> resourceAsks;
    hooks.requestResource = [&](const ResourceRequest& rq) { resourceAsks.push_back(rq); };
    std::vector<std::string> sounds;
    hooks.playSound = [&](const std::string& n) { sounds.push_back(n); };
    s.rt.setHooks(hooks);
    s.start();
    check(s.rt.recipeSelection(gm) == kNoId, "au d\xC3\xA9part : aucun jeu choisi");
    s.rt.recipeManagerClick(gm, "bouton:Appliquer", s.t);
    check(journalHas(s.rt, "Action", "aucun jeu choisi"), "Appliquer sans jeu : le journal le dit");
    s.rt.recipeManagerClick(gm, "ligne:1", s.t);
    check(s.rt.recipeSelection(gm) == argon.id, "un clic sur la 2e ligne choisit Argon");
    s.rt.recipeManagerClick(gm, "bouton:Appliquer", s.t);
    near(s.plc.values["Consigne"].asReal(), 6.2, "Appliquer \xC3\xA9" "crit le jeu : Consigne = 6.2");
    same(formatValue(*s.rt.variable("Gaz_Choisi")), "Argon", "... et la variable IHM : Argon");
    s.rt.recipeManagerClick(gm, "bouton:Ajouter", s.t);
    check(requests.size() == 1 && requests[0].op == "ajouter" && requests[0].record == kNoId, "Ajouter : l'\xC3\xA9" "cran est sollicit\xC3\xA9");
    check(requests.size() == 1 && requests[0].values.size() == 3 && requests[0].values[0] == "6.2" && requests[0].values[2] == "'Argon'",
          "... avec les valeurs de l'installation (un texte entre apostrophes)");
    s.rt.recipeManagerClick(gm, "bouton:Modifier", s.t);
    s.rt.recipeManagerClick(gm, "bouton:Lire", s.t);
    s.rt.recipeManagerClick(gm, "bouton:Supprimer", s.t);
    check(requests.size() == 4 && requests[1].op == "modifier" && requests[1].record == argon.id && requests[2].op == "lire"
              && requests[3].op == "supprimer",
          "Modifier, Lire, Supprimer : le jeu choisi");
    // Le jeu choisi supprime du projet : plus rien de choisi.
    s.p.recipes[0].records.pop_back();
    check(s.rt.recipeSelection(gm) == kNoId, "un jeu supprim\xC3\xA9 n'est plus choisi");
    // Sous securite, sans la permission Recettes : refuse, rien n'est demande.
    s.p.security.enabled = true;
    s.rt.recipeManagerClick(gm, "ligne:0", s.t);
    s.rt.recipeManagerClick(gm, "bouton:Ajouter", s.t);
    check(requests.size() == 4 && eventHas(s.rt, "Acc\xC3\xA8s refus\xC3\xA9", "Recettes"), "s\xC3\xA9" "curit\xC3\xA9 : Ajouter refus\xC3\xA9 sans la permission Recettes");
    s.p.security.enabled = false;

    // ---- les actions sur les ressources
    check(parseExtensionFilter("*.PNG; jpg, .svg jpg") == std::vector<std::string>{"png", "jpg", "svg"}, "le filtre : png, jpg, svg (sans doublon)");
    check(extensionAccepted({"png", "jpg"}, "C:\\Photos\\Vue.JPG") && !extensionAccepted({"png"}, "schema.bmp") && extensionAccepted({}, "x"),
          "extension accept\xC3\xA9" "e ou refus\xC3\xA9" "e ; sans filtre, tout");
    Resource bip;
    bip.id = s.p.allocate();
    bip.name = "bip.wav";
    bip.format = "WAV";
    s.p.assets.resources.push_back(bip);
    Resource img = bip;
    img.id = s.p.allocate();
    img.name = "a.png";
    img.format = "PNG";
    s.p.assets.resources.push_back(img);
    ExternalFile base;
    base.id = s.p.allocate();
    base.name = "historique";
    base.kind = ExternalKind::Sqlite;
    base.path = "donnees/historique.db";
    s.p.assets.files.push_back(base);
    Variable choisie;
    choisie.id = s.p.allocate();
    choisie.name = "Image_Choisie";
    choisie.type = "STRING";
    s.p.programs.variables.push_back(choisie);
    auto& b = addButton(s.p, s.v(), "Btn", 600, 10);
    b.actions.push_back(act(Trigger::Click, Operation::RequestResource, "Image_Choisie", "png;jpg"));
    b.actions.push_back(act(Trigger::Click, Operation::BindTable, "Tab", "historique"));
    b.actions.push_back(act(Trigger::Click, Operation::PlaySound, "bip.wav"));
    b.actions.push_back(act(Trigger::Click, Operation::ShowSystem));
    const Id btnId = b.id;
    s.start();
    s.rt.press(btnId, s.t);
    s.rt.release(btnId, s.t, true);
    check(resourceAsks.size() == 1 && resourceAsks[0].variable == "Image_Choisie"
              && resourceAsks[0].extensions == std::vector<std::string>{"png", "jpg"},
          "Demander une ressource : l'\xC3\xA9" "cran re\xC3\xA7oit le filtre et la variable");
    if (!resourceAsks.empty()) s.rt.resourceProvided(resourceAsks[0], "photo.jpg", s.t);
    same(formatValue(*s.rt.variable("Image_Choisie")), "photo.jpg", "la ressource ajout\xC3\xA9" "e : son nom dans la variable");
    check(s.rt.tableSource(tab) && *s.rt.tableSource(tab) == "historique", "Lier un tableau : Tab montre la base historique");
    check(sounds == std::vector<std::string>{"bip.wav"}, "Jouer un son : bip.wav");
    check(s.rt.systemShown(), "Param\xC3\xA8tres syst\xC3\xA8me : le panneau s'ouvre");
    bool viewLine = false;
    for (const auto& [k, val] : s.rt.systemInfo()) viewLine = viewLine || (k == "Vue courante" && val.find("Vue_Gaz") != std::string::npos);
    check(viewLine, "... il dit la vue courante");
    s.rt.showSystem(false);
    auto& unbind = addButton(s.p, s.v(), "Btn_Retour", 600, 60);
    unbind.actions.push_back(act(Trigger::Click, Operation::BindTable, "Tab"));
    unbind.actions.push_back(act(Trigger::Click, Operation::PlaySound, "inconnu.wav"));
    const Id unbindId = unbind.id;
    s.rt.press(unbindId, s.t);
    s.rt.release(unbindId, s.t, true);
    check(!s.rt.tableSource(tab), "Lier un tableau sans fichier : sa source de l'\xC3\xA9" "diteur revient");
    check(journalHas(s.rt, "Erreur", "inconnu.wav") && sounds.size() == 1, "un son introuvable : une erreur, rien de jou\xC3\xA9");

    // ---- les ressources citees et renommees
    s.v().object(anim)->set("states", "Bouteille_Vide => a.png, b.png");
    bool byState = false, byAction = false;
    for (const auto& ci : citations(s.p, "a.png")) byState = byState || ci.where.find("Anim.states") != std::string::npos;
    for (const auto& ci : citations(s.p, "bip.wav")) byAction = byAction || ci.where.find("Btn") != std::string::npos;
    check(byState, "une image d'un \xC3\xA9tat est cit\xC3\xA9" "e (plus inutilis\xC3\xA9" "e)");
    check(byAction, "le son de Jouer un son est cit\xC3\xA9");
    std::size_t renamed = 0;
    check(renameResource(s.p, img.id, "alerte.png", &renamed), "renommer a.png");
    same(s.v().object(anim)->text("states"), "Bouteille_Vide => alerte.png, b.png", "... l'\xC3\xA9tat suit");
    check(renameResource(s.p, bip.id, "sonnerie.wav", &renamed) && s.v().object(btnId)->actions[2].target == "sonnerie.wav",
          "renommer bip.wav : l'action suit");

    // ---- le disque : cases (tabulations, retours a la ligne), etats, actions du lot 6
    {
        const fs::path dir = fs::temp_directory_path() / "hmi_test_lot6_objets";
        fs::remove_all(dir);
        check(static_cast<bool>(save(s.p, dir.string())), "enregistrer les objets du lot 6");
        auto back = load(dir.string());
        check(back && back->views == s.p.views, "relus \xC3\xA0 l'identique : cases, \xC3\xA9tats, recette, actions sur les ressources");
        if (back) {
            const auto* bt = back->view(s.view) ? back->view(s.view)->object(tab) : nullptr;
            check(bt && parseCells(bt->text("cells")).size() == 2, "... les deux lignes du tableau");
        }
        fs::remove_all(dir);
    }

    // ---- Generer et Compiler
    const NameExists plc = [&](std::string_view n) { return s.plc.values.count(std::string(n)) != 0; };
    const auto has = [](const std::vector<Issue>& issues, std::string_view cat, std::string_view text) {
        for (const auto& i : issues) if (i.category == cat && i.message.find(text) != std::string::npos) return true;
        return false;
    };
    s.v().object(gm)->set("recipe", "Recette_Absente");
    s.v().object(gm)->set("buttons", "Ajouter;Imprimer");
    s.v().object(anim)->set("states", "Niveau_Inconnu > 3 => absente.png, sonnerie.wav");
    s.v().object(tab)->set("cells", "=Pression +\t{Debit_Inconnu}");
    auto& bad = addButton(s.p, s.v(), "Btn_Faux", 600, 110);
    bad.actions.push_back(act(Trigger::Click, Operation::BindTable, "Gestion", "base_absente"));
    bad.actions.push_back(act(Trigger::Click, Operation::PlaySound, "alerte.png"));
    Variable entier;
    entier.id = s.p.allocate();
    entier.name = "Compteur";
    entier.type = "INT";
    s.p.programs.variables.push_back(entier);
    bad.actions.push_back(act(Trigger::Click, Operation::RequestResource, "Compteur", ""));
    const auto issues = generate(s.p, plc, {});
    check(has(issues, "Recette", "recette 'Recette_Absente' introuvable"), "G\xC3\xA9n\xC3\xA9rer : gestionnaire, recette introuvable");
    check(has(issues, "Recette", "bouton inconnu : 'Imprimer'"), "G\xC3\xA9n\xC3\xA9rer : bouton inconnu");
    check(has(issues, "Ressource", "image 'absente.png' introuvable"), "G\xC3\xA9n\xC3\xA9rer : image d'un \xC3\xA9tat introuvable");
    check(has(issues, "Ressource", "'sonnerie.wav' n'est pas une image"), "G\xC3\xA9n\xC3\xA9rer : un son dans un \xC3\xA9tat");
    check(has(issues, "Variable", "variable inexistante : Niveau_Inconnu"), "G\xC3\xA9n\xC3\xA9rer : condition d'\xC3\xA9tat, variable inconnue");
    check(has(issues, "Variable", "case : variable inexistante dans le programme : Debit_Inconnu"), "G\xC3\xA9n\xC3\xA9rer : case, variable inconnue");
    check(has(issues, "Action", "Gestion n'est pas un tableau"), "G\xC3\xA9n\xC3\xA9rer : Lier un tableau vise un gestionnaire");
    check(has(issues, "Action", "'alerte.png' n'est pas un son"), "G\xC3\xA9n\xC3\xA9rer : Jouer un son vise une image");
    check(has(issues, "Action", "Compteur est INT"), "G\xC3\xA9n\xC3\xA9rer : Demander une ressource dans un INT");
    const auto compiled = compile(s.p);
    check(has(compiled, "Expression", "case [1,1]"), "Compiler : une case =expression illisible");
    s.v().object(anim)->set("states", "Pression > => a.png");
    check(has(compile(s.p), "Expression", "\xC3\xA9tat 1"), "Compiler : une condition d'\xC3\xA9tat illisible");
}

// ============================================================== lot 7 ======
//  Les variables locales des scripts (VAR gardees, VAR_TEMP remises) et les
//  fonctions IHM du projet (avec ou sans retour).
namespace {

Variable hmiVar(Project& p, const char* name, const char* type, const char* initial = "") {
    Variable v;
    v.id = p.allocate();
    v.name = name;
    v.type = type;
    v.initial = initial;
    return v;
}
HmiFunction hmiFunction(Project& p, const char* name, const char* ret, const char* body, const char* description = "") {
    HmiFunction f;
    f.id = p.allocate();
    f.name = name;
    f.returnType = ret;
    f.body = body;
    f.description = description;
    return f;
}
Script generalScript(Project& p, const char* name, const char* body) {
    Script sc;
    sc.id = p.allocate();
    sc.name = name;
    sc.event = "Appel";
    sc.body = body;
    return sc;
}

} // namespace

void localesLot7() {
    std::printf("lot 7 : variables locales des scripts (VAR gardees, VAR_TEMP remises)\n");
    // ---- le decoupage
    const std::string code = "(* compteur *)\nVAR\n    Compte : INT := 5;\n    Dernier, Autre : STRING;\nEND_VAR\n"
                             "VAR_TEMP\n    i : INT;\n    Somme : REAL := 0.5;\nEND_VAR\nCompte := Compte + 1;\n";
    const auto parts = splitDeclarations(code);
    check(parts.errors.empty(), "d\xC3\xA9" "clarations lues sans faute");
    check(parts.locals.size() == 5, "5 locales (Dernier, Autre : deux noms sur une ligne)");
    const auto* compte = parts.local("compte");
    check(compte && compte->type == "INT" && compte->initial == "5" && compte->section == LocalVar::Section::Var && compte->line == 3,
          "Compte : INT := 5, bloc VAR, ligne 3 (trouv\xC3\xA9" "e sans casse)");
    check(parts.local("Somme") && parts.local("Somme")->section == LocalVar::Section::Temp && parts.local("Somme")->initial == "0.5",
          "Somme : VAR_TEMP, := 0.5");
    check(std::count(parts.body.begin(), parts.body.end(), '\n') == std::count(code.begin(), code.end(), '\n'),
          "les blocs blanchis gardent leurs lignes (une faute reste \xC3\xA0 sa ligne)");
    check(parts.body.find("Compte := Compte + 1;") != std::string::npos && parts.body.find("VAR") == std::string::npos
              && parts.body.find("(* compteur *)") != std::string::npos,
          "le corps : sans les d\xC3\xA9" "clarations, le commentaire reste");
    auto bad = splitDeclarations("VAR\n  x : INT\nEND_VAR\nx := 1;");
    check(!bad.errors.empty() && bad.errors[0].line == 2, "';' manquant : dit ligne 2");
    bad = splitDeclarations("VAR\n  x : T_ANA;\nEND_VAR");
    check(!bad.errors.empty() && bad.errors[0].message.find("T_ANA") != std::string::npos, "type non pris en charge (T_ANA) : dit");
    bad = splitDeclarations("VAR\n  x : INT;\n");
    check(!bad.errors.empty() && bad.errors[0].message.find("END_VAR") != std::string::npos, "VAR sans END_VAR");
    bad = splitDeclarations("VAR_INPUT\n  x : INT;\nEND_VAR");
    check(!bad.errors.empty() && bad.errors[0].message.find("fonction") != std::string::npos, "VAR_INPUT hors d'une fonction : refus\xC3\xA9");
    check(splitDeclarations("VAR_INPUT\n  x : INT;\nEND_VAR", true).errors.empty(), "... permis dans une fonction");
    bad = splitDeclarations("VAR\n  x : INT;\n  X : REAL;\nEND_VAR");
    check(!bad.errors.empty() && bad.errors[0].message.find("double") != std::string::npos, "locale en double (sans casse)");
    bad = splitDeclarations("VAR\n  IF : INT;\nEND_VAR");
    check(!bad.errors.empty() && bad.errors[0].message.find("invalide") != std::string::npos, "un mot-cl\xC3\xA9 n'est pas un nom");
    check(splitDeclarations("VAR RETAIN\n  x : INT;\nEND_VAR").errors.empty(), "VAR RETAIN accept\xC3\xA9");
    check(splitDeclarations("x := 'VAR'; (* VAR *)\n// END_VAR").locals.empty(), "VAR dans une cha\xC3\xAEne ou un commentaire : rien");
    const auto diag = checkScript(ScriptLang::ST, "VAR\n  n : INT;\nEND_VAR\nn := n + ;");
    check(!diag.empty() && diag[0].line == 4, "une faute apr\xC3\xA8s les d\xC3\xA9" "clarations : \xC3\xA0 sa vraie ligne (4)");
    const auto diag2 = checkScript(ScriptLang::ST, "VAR\n  n : BIDULE;\nEND_VAR\nn := 1;");
    check(!diag2.empty() && diag2[0].line == 2 && diag2[0].severity == ScriptDiagnostic::Severity::Error,
          "une faute de d\xC3\xA9" "claration : ligne 2, erreur");
    bool leaked = false;
    for (const auto& u : scriptNames(code)) leaked = leaked || u.name == "Compte" || u.name == "i";
    check(!leaked, "scriptNames : une locale n'est pas une variable du projet");

    // ---- en marche
    Project p;
    View a = makeView(p, "Vue_A");
    p.programs.variables.push_back(hmiVar(p, "Total", "INT"));
    p.programs.variables.push_back(hmiVar(p, "Ombre", "INT", "7"));
    p.programs.scripts.push_back(generalScript(p, "Compter",
        "VAR\n  Fois : INT;\nEND_VAR\nVAR_TEMP\n  Tmp : INT := 10;\nEND_VAR\nFois := Fois + 1;\nTmp := Tmp + Fois;\nTotal := Tmp;"));
    p.programs.scripts.push_back(generalScript(p, "Masque", "VAR_TEMP\n  Ombre : INT := 100;\nEND_VAR\nOmbre := Ombre + 1;"));
    p.programs.scripts.push_back(generalScript(p, "Faux", "VAR\n  x : T_ANA;\nEND_VAR\nx := 1;"));
    p.programs.scripts.push_back(generalScript(p, "Initiale", "VAR_TEMP\n  t : TIME := T#1500ms;\n  s : STRING := 'pr\xC3\xAAt';\nEND_VAR\nTotal := TIME_TO_INT(t);"));
    p.programs.scripts.push_back(generalScript(p, "Appelant", "VAR_TEMP\n  Tmp : INT := 1;\nEND_VAR\nIHM_APPELER('Compter');\nTotal := Total + Tmp * 1000;"));
    auto& btn = addButton(p, a, "Btn", 0, 0);
    btn.actions.push_back(act(Trigger::Click, Operation::RunScript, {}, "VAR\n  n : INT;\nEND_VAR\nn := n + 1;\nTotal := n;"));
    const Id btnId = btn.id;
    p.views = {a};
    p.config.startView = a.id;
    Runtime rt;
    rt.bind(&p, nullptr);
    rt.start(0.0);
    for (int i = 1; i <= 3; ++i) (void)rt.callScript("Compter", 0.1 * i);
    check(rt.variable("Total")->asInteger() == 13, "VAR gard\xC3\xA9" "e (Fois = 3), VAR_TEMP repartie de 10 : Total = 13 ("
                                                     + std::to_string(rt.variable("Total")->asInteger()) + ")");
    (void)rt.callScript("Masque", 0.4);
    check(rt.variable("Ombre")->asInteger() == 7, "une locale du m\xC3\xAAme nom cache la variable IHM (Ombre IHM reste 7)");
    std::string why;
    bool ok = !rt.callScript("Faux", 0.5, &why) && why.find("T_ANA") != std::string::npos;
    check(ok, "d\xC3\xA9" "claration fautive : le script ne part pas (" + why + ")");
    check(journalHas(rt, "Erreur", "T_ANA"), "... et le journal le dit");
    // TIME_TO_INT est une fonction de l'automate : sans automate, l'appel echoue - la valeur initiale, elle, est lue.
    (void)rt.callScript("Initiale", 0.6, &why);
    check(!journalHas(rt, "Erreur", "valeur initiale illisible"), "valeurs initiales T#1500ms et 'pr\xC3\xAAt' lues");
    rt.start(1.0);
    (void)rt.callScript("Compter", 1.1);
    check(rt.variable("Total")->asInteger() == 11, "relancer l'IHM remet les VAR \xC3\xA0 leur valeur initiale : Total = 11");
    (void)rt.callScript("Appelant", 1.2);
    check(rt.variable("Total")->asInteger() == 1012,
          "un script appel\xC3\xA9 a ses locales \xC3\xA0 lui : Tmp de l'appelant reste 1 (Total = 1012 : "
              + std::to_string(rt.variable("Total")->asInteger()) + ")");
    rt.press(btnId, 1.3);
    rt.release(btnId, 1.35, true);
    rt.press(btnId, 1.4);
    rt.release(btnId, 1.45, true);
    check(rt.variable("Total")->asInteger() == 2, "le code d'une action garde ses VAR d'un clic \xC3\xA0 l'autre (Total = 2)");
}

void fonctionsLot7() {
    std::printf("lot 7 : fonctions IHM (avec ou sans retour)\n");
    Project p;
    View a = makeView(p, "Vue_A");
    View b = makeView(p, "Vue_B");
    p.programs.variables.push_back(hmiVar(p, "Resultat", "REAL"));
    p.programs.variables.push_back(hmiVar(p, "Traces", "INT"));
    p.programs.variables.push_back(hmiVar(p, "Fact5", "DINT"));
    p.programs.functions.push_back(hmiFunction(p, "Moyenne", "REAL",
        "VAR_INPUT\n  a : REAL;\n  b : REAL := 10.0;\nEND_VAR\nMoyenne := (a + b) / 2.0;", "la moyenne de deux mesures"));
    p.programs.functions.push_back(hmiFunction(p, "Tracer", "",
        "VAR_INPUT\n  Message : STRING;\nEND_VAR\nTraces := Traces + 1;\nIHM_JOURNAL(Message);"));
    p.programs.functions.push_back(hmiFunction(p, "Sans_Memoire", "INT", "VAR\n  n : INT;\nEND_VAR\nn := n + 1;\nSans_Memoire := n;"));
    p.programs.functions.push_back(hmiFunction(p, "Fact", "DINT",
        "VAR_INPUT\n  n : DINT;\nEND_VAR\nIF n <= 1 THEN\n  Fact := 1;\nELSE\n  Fact := n * Fact(n - 1);\nEND_IF;"));
    p.programs.functions.push_back(hmiFunction(p, "Ecrit", "INT", "Traces := 99;\nEcrit := 1;"));
    p.programs.functions.push_back(hmiFunction(p, "Navigue", "BOOL", "Navigue := IHM_NAVIGUER('Vue_B');"));
    p.programs.functions.push_back(hmiFunction(p, "Casse", "INT", "VAR\n  x : INT\nEND_VAR\nCasse := 1;"));
    p.programs.scripts.push_back(generalScript(p, "Calcul",
        "Resultat := Moyenne(Resultat, 8.0);\nTracer('calcul fait');\nTracer(Message := 'deuxi\xC3\xA8me');\nFact5 := Fact(5);"));
    p.programs.scripts.push_back(generalScript(p, "Profond", "Fact5 := Fact(40);\nTraces := -1;"));
    p.programs.scripts.push_back(generalScript(p, "AppelCasse", "Resultat := Casse();\nTraces := -2;"));
    p.views = {a, b};
    p.config.startView = a.id;

    // ---- les textes
    same(functionSignature(*p.functionByName("Moyenne")), "Moyenne(a : REAL, b : REAL) : REAL", "signature avec retour");
    same(functionSignature(*p.functionByName("Tracer")), "Tracer(Message : STRING)", "signature sans retour");
    check(p.functionByName("moyenne") == p.function(p.programs.functions[0].id), "une fonction se trouve sans casse");
    check(checkFunction(*p.functionByName("Moyenne")).empty(), "Moyenne : aucune faute");
    const auto noReturn = checkFunction(hmiFunction(p, "Oubli", "REAL", "VAR_INPUT\n  a : REAL;\nEND_VAR\na := a + 1.0;"));
    check(!noReturn.empty() && noReturn[0].severity == ScriptDiagnostic::Severity::Warning
              && noReturn[0].message.find("Oubli :=") != std::string::npos,
          "une fonction \xC3\xA0 retour qui n'affecte jamais son nom : avertie (" + (noReturn.empty() ? std::string("?") : noReturn[0].message) + ")");
    const auto badType = checkFunction(hmiFunction(p, "T", "T_ANA", "T := 1;"));
    check(!badType.empty() && badType[0].message.find("T_ANA") != std::string::npos, "type de retour non pris en charge");
    const auto shadow = checkFunction(hmiFunction(p, "Dup", "INT", "VAR\n  Dup : INT;\nEND_VAR\nDup := 1;"));
    check(!shadow.empty() && shadow[0].message.find("nom de la fonction") != std::string::npos, "une locale au nom de la fonction : refus\xC3\xA9" "e");
    const auto callees = scriptCallees("x := Moyenne(1.0, 2.0) + ABS(y);\nTracer('a');\nIF Moyenne (a) > 0 THEN END_IF;");
    check(callees.size() == 3 && callees[0].name == "Moyenne" && callees[1].name == "ABS" && callees[2].name == "Tracer" && callees[2].line == 2,
          "les appels d'un code : Moyenne, ABS, Tracer (ligne 2), une fois chacun");
    same(renameCalls("Moyenne := Moyenne(a, b); (* Moyenne( *) s := 'Moyenne(';", "Moyenne", "Mean"),
         "Moyenne := Mean(a, b); (* Moyenne( *) s := 'Moyenne(';", "renommer : les appels, pas une variable du m\xC3\xAAme nom ni un commentaire ni une cha\xC3\xAEne");
    same(renameCalls("Moyenne := x;", "Moyenne", "Mean", true), "Mean := x;", "renommer dans son propre corps : le retour suit");
    same(renameCallsInText("Moy. : {Moyenne(a, b):0.0} bar", "Moyenne", "Mean"), "Moy. : {Mean(a, b):0.0} bar", "texte \xC3\xA0 trous : dans les accolades");
    same(renameCallsInText("=Moyenne(a, b) * 2", "Moyenne", "Mean"), "=Mean(a, b) * 2", "=expression : partout");
    // 1.11.18 (refonte, lot 5) : sans bloc VAR - son parametre et sa locale dans le modele.
    const auto tpl = functionTemplate("Carre", "REAL", "x au carr\xC3\xA9");
    HmiFunction carre = hmiFunction(p, "Carre", "REAL", tpl.c_str());
    carre.decls = functionTemplateDecls("REAL");
    check(tpl.find("VAR") == std::string::npos && tpl.find("Carre := Resultat;") != std::string::npos && carre.decls.size() == 2
              && carre.decls[0].kind == DeclKind::Parameter && carre.decls[1].name == "Resultat" && checkFunction(carre).empty(),
          "le mod\xC3\xA8le d'une nouvelle fonction (sans bloc VAR, ses d\xC3\xA9" "clarations dans le mod\xC3\xA8le) se v\xC3\xA9rifie sans faute");
    HmiFunction proc = hmiFunction(p, "Proc", "", functionTemplate("Proc", "", {}).c_str());
    proc.decls = functionTemplateDecls("");
    check(checkFunction(proc).empty() && proc.decls.size() == 1 && proc.decls[0].type == "STRING", "... sans retour aussi");

    // ---- en marche : depuis un script
    Runtime rt;
    rt.bind(&p, nullptr);
    rt.start(0.0);
    std::string why;
    bool ok = rt.callScript("Calcul", 0.1, &why);
    check(ok, "le script qui appelle les fonctions tourne" + (why.empty() ? std::string{} : " (" + why + ")"));
    near(rt.variable("Resultat")->asReal(), 4.0, "Moyenne(Resultat, 8.0) : (0 + 8) / 2 = 4");
    check(rt.variable("Traces")->asInteger() == 2 && journalHas(rt, "Journal", "calcul fait") && journalHas(rt, "Journal", "deuxi\xC3\xA8me"),
          "Tracer (sans retour) : appel\xC3\xA9" "e deux fois, par position puis par nom");
    check(rt.variable("Fact5")->asInteger() == 120, "Fact(5) = 120 : une fonction s'appelle elle-m\xC3\xAAme (5 niveaux)");
    ok = !rt.callScript("Profond", 0.2, &why) && why.find("appel circulaire") != std::string::npos;
    check(ok, "Fact(40) : plus de 32 niveaux (1.11.10 ; 8 avant), coup\xC3\xA9 (" + why + ")");
    check(rt.variable("Traces")->asInteger() == 2, "... et le script s'arr\xC3\xAAte l\xC3\xA0 (la ligne suivante ne passe pas)");
    ok = !rt.callScript("AppelCasse", 0.3, &why) && why.find("fonction Casse") != std::string::npos;
    check(ok, "une fonction mal d\xC3\xA9" "clar\xC3\xA9" "e fait \xC3\xA9" "chouer son appelant (" + why + ")");

    // ---- le banc d'essai (volet Fonctions)
    sim::Value r;
    check(rt.runFunction("Moyenne", {{"", sim::Value::real(2.0)}, {"", sim::Value::real(4.0)}}, r) && std::fabs(r.asReal() - 3.0) < 1e-9,
          "Moyenne(2, 4) = 3 (par position)");
    check(rt.runFunction("Moyenne", {{"b", sim::Value::real(4.0)}, {"a", sim::Value::real(2.0)}}, r) && std::fabs(r.asReal() - 3.0) < 1e-9,
          "Moyenne(b := 4, a := 2) = 3 (par nom)");
    check(rt.runFunction("Moyenne", {{"", sim::Value::real(2.0)}}, r) && std::fabs(r.asReal() - 6.0) < 1e-9,
          "Moyenne(2) = 6 : b prend sa valeur initiale (10)");
    check(rt.runFunction("MOYENNE", {{"", sim::Value::integer(sim::Type::Int, 3)}, {"", sim::Value::integer(sim::Type::Int, 4)}}, r)
              && std::fabs(r.asReal() - 3.5) < 1e-9,
          "sans casse, et des INT convertis en REAL : 3.5");
    ok = !rt.runFunction("Moyenne", {{"", sim::Value::real(1)}, {"", sim::Value::real(2)}, {"", sim::Value::real(3)}}, r, &why)
         && why.find("trop d'arguments") != std::string::npos;
    check(ok, "trop d'arguments : refus\xC3\xA9 (" + why + ")");
    ok = !rt.runFunction("Moyenne", {{"c", sim::Value::real(1)}}, r, &why) && why.find("inconnu : c") != std::string::npos;
    check(ok, "param\xC3\xA8tre inconnu : refus\xC3\xA9 (" + why + ")");
    check(!rt.runFunction("Absente", {}, r, &why) && why.find("introuvable") != std::string::npos, "fonction absente : dit");
    check(rt.runFunction("Sans_Memoire", {}, r) && rt.runFunction("Sans_Memoire", {}, r) && r.asInteger() == 1,
          "une fonction n'a pas de m\xC3\xA9moire : ses VAR repartent \xC3\xA0 chaque appel (1, puis 1)");
    check(rt.runFunction("Tracer", {{"", sim::Value::text("banc")}}, r) && r.isTruthy() && journalHas(rt, "Journal", "banc"),
          "sans retour : l'appel rend TRUE, son effet a lieu");

    // ---- dans une expression de vue : en lecture seule
    const auto moy = Expression::compile("Moyenne(2.0, 4.0) + 1.0").evaluate(rt.environment());
    check(moy && std::fabs(moy->asReal() - 4.0) < 1e-9, "une expression de vue appelle une fonction du projet : 4");
    const auto nested = Expression::compile("Moyenne(Moyenne(0.0, 2.0), 3.0)").evaluate(rt.environment());
    check(nested && std::fabs(nested->asReal() - 2.0) < 1e-9, "... imbriqu\xC3\xA9" "e : Moyenne(Moyenne(0, 2), 3) = 2");
    const auto before = rt.variable("Traces")->asInteger();
    const auto ecrit = Expression::compile("Ecrit() + 1").evaluate(rt.environment());
    (void)Expression::compile("Ecrit() + 1").evaluate(rt.environment());
    check(rt.variable("Traces")->asInteger() == before, "une fonction appel\xC3\xA9" "e par une expression n'\xC3\xA9" "crit pas au-dehors");
    std::size_t said = 0;
    for (const auto& e : rt.journal()) said += e.kind == "Erreur" && e.message.find("variables locales") != std::string::npos;
    check(said == 1, "... la faute est dite une fois au journal, pas \xC3\xA0 chaque image (" + std::to_string(said) + ")");
    (void)ecrit;
    const Id viewBefore = rt.currentView();
    (void)Expression::compile("Navigue()").evaluate(rt.environment());
    check(rt.currentView() == viewBefore && journalHas(rt, "Erreur", "IHM_NAVIGUER : interdit"),
          "... ni ne navigue (IHM_NAVIGUER refus\xC3\xA9 depuis une expression)");
    check(rt.callScript("Calcul", 0.4) && rt.variable("Traces")->asInteger() > before,
          "le m\xC3\xAAme appel depuis un script, lui, \xC3\xA9" "crit");

    // ---- le banc : les variables IHM a leur valeur initiale, sans lancer l'IHM
    Runtime bench;
    bench.bind(&p, nullptr);
    bench.prime(0.0);
    check(!bench.running() && bench.currentView() == kNoId && bench.variable("Traces") && bench.variable("Traces")->asInteger() == 0,
          "prime : variables IHM pr\xC3\xAAtes, ni vue ni script de d\xC3\xA9marrage");
    check(bench.runFunction("Tracer", {{"", sim::Value::text("essai")}}, r) && bench.variable("Traces")->asInteger() == 1,
          "le banc ex\xC3\xA9" "cute la fonction : Traces 0 -> 1");

    // ---- renommer partout, qui appelle
    const Id btnMoy = addButton(p, p.views[0], "Btn_Moy", 0, 0).id;
    p.views[0].object(btnMoy)->actions.push_back(act(Trigger::Click, Operation::Assign, "Resultat", "Moyenne(1.0, 3.0)"));
    const Id txtMoy = addButton(p, p.views[0], "Txt_Moy", 0, 50).id;
    p.views[0].object(txtMoy)->set("text", "Moy : {Moyenne(1.0, 3.0):0.0}");
    AlarmDef al;
    al.id = p.allocate();
    al.name = "Moyenne_Haute";
    al.condition = "Moyenne(Resultat, 0.0) > 50.0";
    p.alarms.push_back(al);
    const auto callers = functionCallers(p, "Moyenne");
    const auto hasCaller = [&](std::string_view c) { return std::find(callers.begin(), callers.end(), c) != callers.end(); };
    check(hasCaller("script Calcul") && hasCaller("Vue_A/Btn_Moy (action)") && hasCaller("Vue_A/Txt_Moy (text)")
              && hasCaller("alarme Moyenne_Haute"),
          "qui appelle Moyenne : le script, l'action, le texte \xC3\xA0 trous, l'alarme (" + std::to_string(callers.size()) + ")");
    check(functionCallers(p, "Fact").size() == 2, "Fact : Calcul, Profond (pas elle-m\xC3\xAAme)");
    const auto changed = renameFunctionEverywhere(p, "Moyenne", "Mean");
    for (auto& f : p.programs.functions) if (f.name == "Moyenne") f.name = "Mean";
    check(changed == 5, "renommer Moyenne : 5 textes suivent (corps, script, action, texte, alarme) : " + std::to_string(changed));
    check(p.programs.scripts[0].body.find("Mean(Resultat, 8.0)") != std::string::npos
              && p.views[0].object(btnMoy)->actions[0].value == "Mean(1.0, 3.0)"
              && p.views[0].object(txtMoy)->text("text") == "Moy : {Mean(1.0, 3.0):0.0}"
              && p.alarms[0].condition == "Mean(Resultat, 0.0) > 50.0" && p.functionByName("Mean")->body.find("Mean := (a + b)") != std::string::npos,
          "... les appels et le retour dans son corps");
    check(p.alarms[0].name == "Moyenne_Haute", "... pas un nom qui ne fait que lui ressembler");

    // ---- Generer et Compiler
    p.programs.functions.push_back(hmiFunction(p, "IHM_Moi", "INT", "IHM_Moi := 1;"));
    // 1.11.20 : une seconde Mean de la meme forme que la premiere (a, b : REAL) - une autre forme
    // serait une surcharge permise.
    p.programs.functions.push_back(hmiFunction(p, "Mean", "INT", "VAR_INPUT\n  x : REAL;\n  y : REAL;\nEND_VAR\nMean := 1;"));
    p.programs.functions.push_back(hmiFunction(p, "Mean", "INT", "VAR_INPUT\n  t : STRING;\nEND_VAR\nMean := 2;"));
    p.programs.functions.push_back(hmiFunction(p, "Resultat", "INT", "Resultat := 1;"));
    p.programs.functions.push_back(hmiFunction(p, "Fantome", "INT", "Fantome := Inconnue_X + 1;"));
    p.programs.functions.push_back(hmiFunction(p, "Ping", "INT", "Ping := Pong();"));
    p.programs.functions.push_back(hmiFunction(p, "Pong", "INT", "Pong := Ping();"));
    const NameExists plcNames = [](std::string_view n) { return n == "Niveau" || n == "Fantome"; };
    const auto issues = generate(p, plcNames);
    const auto has = [&](std::string_view text, Issue::Severity s) {
        for (const auto& i : issues)
            if (i.category == "Fonction" && i.severity == s && i.message.find(text) != std::string::npos) return true;
        return false;
    };
    using S = Issue::Severity;
    check(has("pr\xC3\xA9" "fixe IHM_ est r\xC3\xA9serv\xC3\xA9", S::Error), "G\xC3\xA9n\xC3\xA9rer : IHM_ r\xC3\xA9serv\xC3\xA9");
    check(has("deux fonctions Mean ont la m\xC3\xAAme forme Mean(REAL, REAL)", S::Error), "G\xC3\xA9n\xC3\xA9rer : deux surcharges de m\xC3\xAAme forme");
    {
        int clashes = 0;
        for (const auto& i : issues) clashes += i.message.find("deux fonctions Mean") != std::string::npos ? 1 : 0;
        check(clashes == 2, "... les deux dites, pas Mean(STRING) (une vraie surcharge) : " + std::to_string(clashes));
    }
    check(has("une variable IHM porte d\xC3\xA9j\xC3\xA0 ce nom : Resultat", S::Error), "G\xC3\xA9n\xC3\xA9rer : nom d'une variable IHM");
    check(has("variable inexistante : Inconnue_X", S::Error), "G\xC3\xA9n\xC3\xA9rer : variable inconnue dans une fonction");
    check(has("existe aussi dans l'automate", S::Warning), "G\xC3\xA9n\xC3\xA9rer : un nom de l'automate, averti");
    check(has("Ping \xE2\x86\x92 Pong \xE2\x86\x92 Ping", S::Warning), "G\xC3\xA9n\xC3\xA9rer : appel r\xC3\xA9" "cursif entre fonctions (averti)");
    check(has("Fact \xE2\x86\x92 Fact", S::Warning), "... et une fonction qui s'appelle elle-m\xC3\xAAme (permis, averti)");
    const auto compiled = compile(p);
    bool casse = false, bilan = false;
    for (const auto& i : compiled) {
        casse = casse || (i.category == "Fonction" && i.property == "Casse" && i.line == 2 && i.item == p.functionByName("Casse")->id);
        bilan = bilan || i.message.find(std::to_string(p.programs.functions.size()) + " fonction(s) compil") != std::string::npos;
    }
    check(casse, "Compiler : la fonction fautive, son identifiant, sa ligne (2)");
    check(bilan, "Compiler : le bilan compte les fonctions");

    // ---- l'archive (Exporter / Importer) les emporte
    {
        const fs::path zip = fs::temp_directory_path() / "hmi_test_lot7.zip";
        fs::remove(zip);
        ArchiveReport out;
        check(static_cast<bool>(exportArchive(p, nullptr, zip.string(), &out)), "exporter une IHM qui a des fonctions");
        bool listed = false, counted = false;
        for (const auto& e : out.entries) listed = listed || e.path.rfind("ihm/fonctions/", 0) == 0;
        ArchiveReport in;
        auto imported = importArchive(zip.string(), nullptr, &in);
        for (const auto& c : in.counts)
            counted = counted || (c.section == "Fonctions IHM" && c.expected == static_cast<long long>(p.programs.functions.size())
                                  && c.found == c.expected);
        check(listed && imported && imported->programs.functions == p.programs.functions,
              "l'archive les emporte (ihm/fonctions/) et les rend \xC3\xA0 l'identique");
        check(counted, "le manifeste les compte, le contr\xC3\xB4le les retrouve");
        fs::remove(zip);
    }

    // ---- le disque (format 6) : un fichier .st par fonction
    const fs::path dir = fs::temp_directory_path() / "hmi_test_lot7";
    fs::remove_all(dir);
    check(static_cast<bool>(save(p, dir.string())), "enregistrer les fonctions");
    std::size_t files = 0;
    if (fs::exists(dir / "ihm" / "fonctions"))
        for (const auto& e : fs::directory_iterator(dir / "ihm" / "fonctions")) files += e.path().extension() == ".st";
    check(files == p.programs.functions.size(), "un fichier .st par fonction dans ihm/fonctions (" + std::to_string(files) + ")");
    auto back = load(dir.string());
    check(back && back->programs.functions == p.programs.functions, "relues \xC3\xA0 l'identique : nom, retour, description, corps");
    if (back) {
        const auto* mean = back->functionByName("Mean");
        check(mean && mean->description == "la moyenne de deux mesures" && mean->returnType == "REAL", "... la description, le retour");
    }
    // Retirer une fonction : son fichier ne reste pas.
    p.programs.functions.pop_back();
    check(static_cast<bool>(save(p, dir.string())), "r\xC3\xA9" "enregistrer sans Pong");
    std::size_t after = 0;
    for (const auto& e : fs::directory_iterator(dir / "ihm" / "fonctions")) after += e.path().extension() == ".st";
    check(after == files - 1, "le fichier de la fonction retir\xC3\xA9" "e est parti");
    fs::remove_all(dir);
}


void guideLot7() {
    std::printf("lot 7 : le guide de l'IHM (aide F1 et guide Word / PDF, une seule source)\n");
    namespace g = hmi::guide;
    const auto& all = g::topics();
    check(all.size() >= 25, "le guide : " + std::to_string(all.size()) + " sujets");
    std::set<std::string> keys;
    bool summaries = true, bodies = true, links = true, steps = true, tables = true;
    for (const auto& t : all) {
        keys.insert(t.key);
        summaries = summaries && !t.summary.empty() && !t.title.empty() && !t.chapter.empty();
        bodies = bodies && !t.blocks.empty();
        for (const auto& s : t.see) links = links && g::topic(s) != nullptr && s != t.key;
        for (const auto& b : t.blocks) {
            if (b.kind == g::BlockKind::Step) steps = steps && !b.label.empty();
            if (b.kind == g::BlockKind::Table) tables = tables && b.text.find('\t') != std::string::npos;
        }
    }
    check(keys.size() == all.size(), "chaque sujet a sa cl\xC3\xA9");
    check(summaries, "chaque sujet a un titre, un chapitre et un r\xC3\xA9sum\xC3\xA9");
    check(bodies, "chaque sujet a un corps");
    check(links, "chaque \xC2\xAB Voir aussi \xC2\xBB m\xC3\xA8ne \xC3\xA0 un sujet qui existe");
    check(steps && tables, "les \xC3\xA9tapes sont num\xC3\xA9rot\xC3\xA9" "es, les tableaux ont leurs colonnes");
    const auto chapters = g::chapters();
    // Lot 8 : un septieme, La bibliotheque d'objets ; lot 9 : un huitieme, les
    // variables systeme et d'instances.
    // 1.10 (H) : un neuvieme, L'automate (API) - le grafcet et son code.
    check(chapters.size() == 9 && chapters.front() == "D\xC3\xA9marrer" && chapters[7] == "Tester et livrer"
              && chapters.back() == "L'automate (API)",
          "neuf chapitres, de D\xC3\xA9marrer \xC3\xA0 Tester et livrer, puis L'automate (API)");
    check(std::find(chapters.begin(), chapters.end(), "Variables syst\xC3\xA8me et d'instances") != chapters.end(),
          "un chapitre pour les variables syst\xC3\xA8me et d'instances");
    // F1 : un nom sous le curseur.
    same(g::topicForWord("ihm_naviguer"), "reference", "F1 sur IHM_NAVIGUER (sans casse) : la r\xC3\xA9" "f\xC3\xA9rence");
    same(g::topicForWord("VAR_TEMP"), "variables-locales", "F1 sur VAR_TEMP : les variables locales");
    same(g::topicForWord("VAR_INPUT"), "fonctions", "F1 sur VAR_INPUT : les fonctions");
    same(g::topicForWord("Pression"), "", "F1 sur un nom quelconque : rien (l'\xC3\xA9" "cran d\xC3\xA9" "cide)");
    // F1 : l'endroit. Tous les volets de l'IHM ont leur sujet.
    for (const char* place : {"ihm", "config", "fichiers", "ressources", "echange", "vues", "vue", "scripts", "scripts-vue",
                              "simulation", "generer", "compiler", "variables", "fonctions", "alarmes", "recettes",
                              "utilisateurs", "historiques", "actions", "contenu", "aide", "langues", "unites", "essais"})
        check(!g::topicForPlace(place).empty(), std::string("F1 depuis le volet ") + place + " : " + g::topicForPlace(place));
    same(g::topicForPlace("vue"), "editeur", "l'\xC3\xA9" "diteur de vues");
    same(g::topicForPlace("generer"), "verifier", "G\xC3\xA9n\xC3\xA9rer et Compiler : un sujet");
    // La recherche : sans casse ni accents.
    auto hits = g::search("variables locales");
    check(!hits.empty() && hits.front().key == "variables-locales", "chercher \xC2\xAB variables locales \xC2\xBB : le sujet en t\xC3\xAAte");
    const auto accent = g::search("\xC3\x89" "chap"), plainHits = g::search("echap");
    check(!accent.empty() && accent.size() == plainHits.size() && accent.front().key == plainHits.front().key,
          "\xC3\x89" "chap et echap trouvent la m\xC3\xAAme chose (" + std::to_string(accent.size()) + " sujets)");
    hits = g::search("IHM_SON");
    check(!hits.empty() && hits.front().key == "reference" && !hits.front().excerpt.empty(),
          "IHM_SON : la r\xC3\xA9" "f\xC3\xA9rence, avec un extrait (" + (hits.empty() ? std::string("?") : hits.front().excerpt) + ")");
    check(g::search("zzz introuvable").empty(), "un mot absent : aucun sujet");
    same(g::plain("le dossier **IHM** et `IHM_VUE()`"), "le dossier IHM et IHM_VUE()", "les marques \xC3\xB4t\xC3\xA9" "es");
    same(g::fold("\xC3\x89" "chap \xC3\xA9t\xC3\xA9 \xC3\xA7" "a"), "echap ete ca", "le repli des accents");
    // Le contenu du lot 7 est bien la.
    const auto* f = g::topic("fonctions");
    bool code = false;
    for (const auto& b : f->blocks) code = code || (b.kind == g::BlockKind::Code && b.text.find("VAR_INPUT") != std::string::npos);
    check(f && code && f->shots.size() >= 2, "Fonctions IHM : un exemple avec VAR_INPUT, des captures pour le guide");
}

// ============================================================ LOT 8 ========
// Les popups intelligentes et parametrees, le champ de saisie, les objets des
// utilisateurs, les verifications, les exemples animes et l'aide des objets.

void popupsLot8() {
    std::printf("lot 8 : popups intelligentes et param\xC3\xA9tr\xC3\xA9" "es\n");
    Project p;
    p.config.width = 1000;
    p.config.height = 600;
    View base = makeView(p, "Base");
    base.width = 1000;
    base.height = 600;
    View pop = makeView(p, "Pop");
    pop.width = 300;
    pop.height = 200;
    pop.role = "popup";
    pop.params = {{"Consigne", "Consigne_A", ""}, {"Nom", "'A'", ""}};
    View aide = makeView(p, "Aide");
    aide.width = 200;
    aide.height = 100;
    aide.role = "popup";
    aide.popup.placement = "haut-droite";
    aide.popup.modal = false;
    p.programs.variables.push_back(hmiVar(p, "Consigne_A", "REAL", "1.0"));
    p.programs.variables.push_back(hmiVar(p, "Consigne_B", "REAL", "2.0"));
    p.programs.variables.push_back(hmiVar(p, "Lu", "STRING", "''"));
    // Un bouton de la base ouvre la popup sous lui, pour B.
    auto& ouvrir = addButton(p, base, "Btn_Ouvrir", 100, 100);
    Action a = act(Trigger::Click, Operation::Popup, "Pop", "Consigne := Consigne_B; Nom := 'B'");
    a.placement = "objet";
    ouvrir.actions.push_back(a);
    const Id btnOuvrir = ouvrir.id;   // (la reference ne survit pas a l'ajout suivant)
    // Dans la popup : un champ qui ecrit la consigne, un bouton qui lit le nom.
    const Id champ = edit::add(p, pop, Kind::InputField, 10, 10);
    pop.object(champ)->name = "Saisie";
    pop.object(champ)->set("variable", "Consigne");
    auto& lire = addButton(p, pop, "Btn_Lire", 10, 80);
    lire.actions.push_back(act(Trigger::Click, Operation::Assign, "Lu", "Nom"));
    const Id btnLire = lire.id;
    // Un temoin de la base lit IHM_POPUP_OUVERTE (en lecture seule).
    auto& lamp = addButton(p, base, "Temoin", 400, 400);
    lamp.setExpr("visible", "IHM_POPUP_OUVERTE('Aide')");
    // Depuis un script : IHM_POPUP (parametres, position), IHM_POPUP_OUVERTE,
    // IHM_CHANGER_POPUP, IHM_POPUP_PRECEDENTE, IHM_CENTRER_POPUP, IHM_FERMER_POPUPS.
    p.programs.variables.push_back(hmiVar(p, "Ouverte", "BOOL", "FALSE"));
    p.programs.scripts.push_back(generalScript(p, "Popups",
        "IHM_POPUP('Pop', 'Consigne := Consigne_A; Nom := $'S$'', 'haut-gauche');\n"
        "Ouverte := IHM_POPUP_OUVERTE('Pop');\n"
        "IHM_CHANGER_POPUP('Pop', 'Nom := $'T$'');\n"
        "IHM_POPUP_PRECEDENTE();\n"
        "IHM_CENTRER_POPUP();\n"));
    p.programs.scripts.push_back(generalScript(p, "Fermer", "IHM_FERMER_POPUPS();\nOuverte := IHM_POPUP_OUVERTE('Pop');"));
    p.views = {base, pop, aide};
    p.config.startView = base.id;
    const Id baseId = base.id, popId = pop.id, aideId = aide.id;

    Runtime rt;
    rt.bind(&p, nullptr);
    rt.start(0.0);
    rt.press(btnOuvrir, 0.1);
    rt.release(btnOuvrir, 0.15, true);
    check(rt.popups().size() == 1 && rt.popups().front() == popId, "le bouton ouvre la popup");
    if (rt.popupSlots().empty()) return;
    const auto& slot = rt.popupSlots().front();
    near(slot.x, 100, "Sous l'objet cliqu\xC3\xA9 : align\xC3\xA9" "e sur le bouton");
    near(slot.y, 100 + 44 + 6, "... juste dessous (6 pixels)");
    check(rt.viewScope(popId) != nullptr, "la popup a ses param\xC3\xA8tres");
    rt.press(btnLire, 0.2);
    rt.release(btnLire, 0.25, true);
    same(rt.variable("Lu") ? rt.variable("Lu")->asString() : std::string("?"), "B", "un param\xC3\xA8tre valeur : Nom vaut 'B'");
    // Le champ ecrit A TRAVERS le parametre : Consigne -> Consigne_B.
    rt.objectPart(champ, "champ", 0.3);
    rt.typeText("12,5", 0.31);
    rt.typeKey(EditKey::Enter, 0.32);
    near(rt.variable("Consigne_B")->asReal(), 12.5, "la saisie \xC3\xA9" "crit Consigne_B (Consigne := Consigne_B)");
    near(rt.variable("Consigne_A")->asReal(), 1.0, "... et pas Consigne_A");
    // Changer de popup : la meme, pour A ; puis revenir.
    check(rt.changePopup(popId, Transition{}, 0.4, "Consigne := Consigne_A; Nom := 'A'"), "changer de popup : la m\xC3\xAAme, pour A");
    check(rt.popupSlots().size() == 1 && rt.popupSlots().front().history.size() == 1, "... au m\xC3\xAAme endroit, elle se souvient de B");
    near(rt.popupSlots().front().x, 100, "... \xC3\xA0 la m\xC3\xAAme place");
    rt.press(btnLire, 0.5);
    rt.release(btnLire, 0.55, true);
    same(rt.variable("Lu")->asString(), "A", "apr\xC3\xA8s le changement, Nom vaut 'A'");
    check(rt.previousPopup(Transition{}, 0.6), "popup pr\xC3\xA9" "c\xC3\xA9" "dente");
    rt.press(btnLire, 0.7);
    rt.release(btnLire, 0.75, true);
    same(rt.variable("Lu")->asString(), "B", "... elle revient \xC3\xA0 B, avec ses param\xC3\xA8tres");
    check(rt.popupSlots().front().history.empty(), "... et son historique se vide");
    // Deplacer, centrer, et rester dans la vue.
    rt.movePopup(0, 5000, -30);
    near(rt.popupSlots().front().x, 1000 - 300, "tir\xC3\xA9" "e trop loin : elle reste dans la vue (x)");
    near(rt.popupSlots().front().y, 0, "... (y)");
    check(rt.centerPopup(), "centrer la popup");
    near(rt.popupSlots().front().x, (1000 - 300) / 2.0, "centr\xC3\xA9" "e : x");
    near(rt.popupSlots().front().y, (600 - (200 + kPopupTitleHeight)) / 2.0, "centr\xC3\xA9" "e : y (barre de titre comprise)");
    // Une seconde popup, a sa position reglee (en haut a droite), puis devant/derriere.
    check(rt.openPopup(aideId, Transition{}, 0.8, {}, {}, kNoId), "une seconde popup");
    check(rt.popups().size() == 2 && rt.topView() == aideId, "deux popups, l'aide au-dessus");
    near(rt.popupSlots().back().x, 1000 - 200 - 16, "En haut \xC3\xA0 droite : x");
    near(rt.popupSlots().back().y, 16, "En haut \xC3\xA0 droite : y");
    check(rt.raisePopup(0) && rt.topView() == popId, "un clic dans la popup du dessous la ram\xC3\xA8ne devant");
    // Deja ouverte : elle revient devant, avec les nouveaux parametres.
    check(rt.openPopup(aideId, Transition{}, 0.9, {}, "12,40", kNoId) && rt.popups().size() == 2 && rt.topView() == aideId,
          "d\xC3\xA9j\xC3\xA0 ouverte : pas de doublon, elle revient devant");
    check(rt.closeAllPopups(Transition{}, 1.0) == 2 && rt.popups().empty(), "fermer toutes les popups");
    // A sa derniere place.
    rt.openPopup(popId, Transition{}, 1.1, "Consigne := Consigne_A", "derniere", kNoId);
    near(rt.popupSlots().front().x, (1000 - 300) / 2.0, "\xC3\x80 sa derni\xC3\xA8re place : l\xC3\xA0 o\xC3\xB9 elle \xC3\xA9tait");
    rt.closeAllPopups(Transition{}, 1.2);
    rt.openPopup(popId, Transition{}, 1.3, {}, "12,40", kNoId);
    near(rt.popupSlots().front().x, 12, "x,y : une place fixe (x)");
    near(rt.popupSlots().front().y, 40, "x,y : une place fixe (y)");
    rt.closeAllPopups(Transition{}, 1.4);

    const auto truthy = [&](const char* n) { const auto* v = rt.variable(n); return v && v->isTruthy(); };
    std::string why;
    check(rt.callScript("Popups", 1.5, &why), "le script des popups tourne" + (why.empty() ? std::string{} : " (" + why + ")"));
    check(truthy("Ouverte"), "IHM_POPUP_OUVERTE('Pop') : vrai");
    check(rt.popups().size() == 1 && rt.popupSlots().front().history.empty() && rt.popupSlots().front().arguments.find("'S'") != std::string::npos,
          "IHM_CHANGER_POPUP puis IHM_POPUP_PRECEDENTE : de retour \xC3\xA0 S");
    near(rt.popupSlots().front().x, (1000 - 300) / 2.0, "IHM_CENTRER_POPUP");
    check(rt.callScript("Fermer", 1.6, &why) && rt.popups().empty() && !truthy("Ouverte"),
          "IHM_FERMER_POPUPS : plus rien d'ouvert");
    // Le temoin de la base lit IHM_POPUP_OUVERTE('Aide').
    rt.openPopup(aideId, Transition{}, 1.7, {}, {}, kNoId);
    LiveView lv;
    lv.bind(*rt.composedView(baseId));
    std::vector<LiveValue> vals;
    const View shown = lv.evaluate(rt.environment(), &vals, rt.viewScope(baseId), 0.0);
    bool visible = false, error = false;
    for (const auto& v : vals) if (v.objectName == "Temoin") { visible = v.value == "TRUE"; error = v.error; }
    check(visible && !error, "une expression lit IHM_POPUP_OUVERTE('Aide') : vrai");

    // Une vue ordinaire ouverte en popup : comme avant le lot 8 (centree, modale,
    // sans barre de titre) ; ses reglages de popup ne servent qu'au role Popup.
    {
        Project o;
        o.config.width = 800;
        o.config.height = 600;
        View b0 = makeView(o, "Base");
        b0.width = 800;
        b0.height = 600;
        View pl = makeView(o, "Ordinaire");
        pl.width = 400;
        pl.height = 200;
        pl.popup.placement = "haut-gauche";
        o.views = {b0, pl};
        o.config.startView = b0.id;
        Runtime ro;
        ro.bind(&o, nullptr);
        ro.start(0.0);
        check(ro.openPopup(pl.id, Transition{}, 0.1), "une vue ordinaire s'ouvre en popup");
        const auto ps = popupSettingsOf(pl);
        check(!ps.titleBar && ps.modal && !ps.movable && !ps.closeButton && !ps.closeOutside,
              "... sans barre de titre ni croix, modale : comme avant le lot 8");
        if (!ro.popupSlots().empty()) {
            near(ro.popupSlots().front().x, 200, "... centr\xC3\xA9" "e (x)");
            near(ro.popupSlots().front().y, 200, "... centr\xC3\xA9" "e, sans barre de titre (y)");
        }
        pl.role = "popup";
        check(popupSettingsOf(pl).titleBar && popupSettingsOf(pl).placement == "haut-gauche", "devenue Popup : ses r\xC3\xA9glages comptent");
    }

    // Sur le disque : les reglages de la popup et les parametres (format 7).
    Project q = p;
    q.views[1].popup.title = "Armoire {Nom}";
    q.views[1].popup.closeOutside = true;
    q.views[1].popup.modal = false;
    q.views[1].popup.placement = "bas-gauche";
    q.views[1].params[0].description = "la consigne relue";
    auto back = parseView(serializeView(q.views[1]));
    check(back && back->role == "popup" && back->popup == q.views[1].popup && back->params == q.views[1].params,
          "une popup relue : r\xC3\xB4le, r\xC3\xA9glages et param\xC3\xA8tres");
    auto backBase = parseView(serializeView(q.views[0]));
    check(backBase && backBase->objects.front().actions.front().placement == "objet"
              && backBase->objects.front().actions.front().value == "Consigne := Consigne_B; Nom := 'B'",
          "une action relue : sa position et ses param\xC3\xA8tres");
    // Un fichier du format 6 : la valeur d'une navigation ne servait a rien, on ne la reprend pas.
    std::string old = serializeView(q.views[0]);
    const auto head = old.find("(format ");
    if (head != std::string::npos) old.replace(head, 10, "(format 6)");
    auto migrated = parseView(old);
    check(migrated && migrated->objects.front().actions.front().value.empty(),
          "un fichier du lot 7 : la valeur rest\xC3\xA9" "e d'une popup est oubli\xC3\xA9" "e (ce sont maintenant ses param\xC3\xA8tres)");
}

void saisieLot8() {
    std::printf("lot 8 : le champ de saisie\n");
    Project p;
    View v = makeView(p, "Saisies");
    p.programs.variables.push_back(hmiVar(p, "Reel", "REAL", "1.5"));
    p.programs.variables.push_back(hmiVar(p, "Entier", "INT", "3"));
    p.programs.variables.push_back(hmiVar(p, "Texte", "STRING", "'abc'"));
    p.programs.variables.push_back(hmiVar(p, "Secret", "STRING", "''"));
    const auto field = [&](const char* name, const char* var, double y) {
        const Id id = edit::add(p, v, Kind::InputField, 10, y);
        v.object(id)->name = name;
        v.object(id)->set("variable", var);
        return id;
    };
    const Id fReel = field("F_Reel", "Reel", 10);
    v.object(fReel)->set("min", "0");
    v.object(fReel)->set("max", "40");
    const Id fEntier = field("F_Entier", "Entier", 60);
    const Id fTexte = field("F_Texte", "Texte", 110);
    v.object(fTexte)->set("mode", "texte");
    v.object(fTexte)->setNumber("maxLength", 5);
    const Id fSecret = field("F_Secret", "Secret", 160);
    v.object(fSecret)->set("mode", "mot de passe");
    const Id fQuitter = field("F_Quitter", "Reel", 210);
    v.object(fQuitter)->setFlag("validateOnExit", true);
    p.views = {v};
    p.config.startView = v.id;
    Runtime rt;
    rt.bind(&p, nullptr);
    rt.start(0.0);
    const auto msg = [&](Id id) { const auto* f = rt.formState(id); return f ? f->message : std::string("?"); };

    rt.objectPart(fReel, "champ", 0.1);
    check(rt.focusedObject() == fReel, "un clic prend le champ");
    same(rt.formState(fReel)->text.at("valeur"), "1.5", "il montre la valeur de sa variable (format 0.0)");
    rt.typeText("2", 0.11);
    same(rt.formState(fReel)->text.at("valeur"), "2", "la premi\xC3\xA8re touche remplace la valeur montr\xC3\xA9" "e");
    rt.typeText("x4,5", 0.12);
    same(rt.formState(fReel)->text.at("valeur"), "24,5", "un champ num\xC3\xA9rique ignore les lettres");
    // 1.11.22 (le client : "les champs de saisie n'ecrivent pas en continu") : tant qu'on tape,
    // la variable ne bouge pas - la valeur tapee attend dans le champ.
    near(rt.variable("Reel")->asReal(), 1.5, "pendant la frappe : la variable n'a pas boug\xC3\xA9 (1.5)");
    rt.tick(0.125);
    near(rt.variable("Reel")->asReal(), 1.5, "... ni apr\xC3\xA8s un cycle de l'IHM");
    rt.typeKey(EditKey::Enter, 0.13);
    near(rt.variable("Reel")->asReal(), 24.5, "Entr\xC3\xA9" "e \xC3\xA9" "crit 24,5 (la virgule vaut le point)");
    check(rt.focusedObject() == kNoId, "... et le champ rend le focus");
    rt.objectPart(fReel, "champ", 0.2);
    rt.typeText("45", 0.21);
    rt.typeKey(EditKey::Enter, 0.22);
    near(rt.variable("Reel")->asReal(), 24.5, "45 : hors bornes, rien n'est \xC3\xA9" "crit");
    check(msg(fReel).find("hors bornes") != std::string::npos && rt.focusedObject() == fReel, "... le champ le dit et garde le focus (" + msg(fReel) + ")");
    rt.typeKey(EditKey::Escape, 0.23);
    check(rt.focusedObject() == kNoId && rt.formState(fReel)->focus.empty(), "\xC3\x89" "chap annule");
    check(rt.formState(fReel)->text.empty(), "1.11.22 : \xC3\x89" "chap efface aussi la saisie en attente (comme un clic ailleurs)");
    rt.objectPart(fEntier, "champ", 0.3);
    rt.typeText("2.5", 0.31);
    rt.typeKey(EditKey::Enter, 0.32);
    check(rt.variable("Entier")->asInteger() == 3 && msg(fEntier).find("entier") != std::string::npos, "une variable INT refuse 2.5 (" + msg(fEntier) + ")");
    rt.typeKey(EditKey::Backspace, 0.33);
    rt.typeKey(EditKey::Backspace, 0.34);
    rt.typeKey(EditKey::Backspace, 0.35);
    rt.typeText("7", 0.36);
    check(rt.variable("Entier")->asInteger() == 3, "1.11.22 : corrig\xC3\xA9" "e mais pas valid\xC3\xA9" "e, la variable garde 3");
    rt.typeKey(EditKey::Enter, 0.37);
    check(rt.variable("Entier")->asInteger() == 7, "corrig\xC3\xA9 au retour arri\xC3\xA8re : 7");
    rt.objectPart(fTexte, "champ", 0.4);
    rt.typeText("abcdefg", 0.41);
    check(msg(fTexte).find("5 caract") != std::string::npos, "texte : la longueur maximale est tenue (" + msg(fTexte) + ")");
    rt.typeKey(EditKey::Escape, 0.42);
    rt.objectPart(fTexte, "champ", 0.43);
    rt.typeText("Lot 8", 0.44);
    rt.typeKey(EditKey::Enter, 0.45);
    same(rt.variable("Texte")->asString(), "Lot 8", "un texte \xC3\xA9" "crit dans une STRING");
    rt.objectPart(fSecret, "champ", 0.5);
    rt.typeText("Code42", 0.51);
    rt.typeKey(EditKey::Enter, 0.52);
    same(rt.variable("Secret")->asString(), "Code42", "mot de passe : \xC3\xA9" "crit");
    check(journalHas(rt, "Action", "Secret = ********") && !journalHas(rt, "", "Code42"), "... et jamais en clair au journal");
    // Valider en quittant : un clic ailleurs ecrit ; sinon, il annule.
    rt.objectPart(fQuitter, "champ", 0.6);
    rt.typeText("9", 0.61);
    rt.unfocus(0.62);
    near(rt.variable("Reel")->asReal(), 9.0, "Valider en quittant : un clic ailleurs \xC3\xA9" "crit");
    rt.objectPart(fReel, "champ", 0.7);
    rt.typeText("8", 0.71);
    rt.unfocus(0.72);
    near(rt.variable("Reel")->asReal(), 9.0, "sans : un clic ailleurs annule");
    // Tab : valide, puis le champ suivant de la vue.
    rt.objectPart(fReel, "champ", 0.8);
    rt.typeText("5", 0.81);
    rt.typeKey(EditKey::Tab, 0.82);
    near(rt.variable("Reel")->asReal(), 5.0, "Tab valide");
    check(rt.focusedObject() == fEntier, "... et passe au champ suivant");
    rt.typeKey(EditKey::BackTab, 0.83);
    check(rt.focusedObject() == fReel, "Maj+Tab : le pr\xC3\xA9" "c\xC3\xA9" "dent");
    rt.typeKey(EditKey::Escape, 0.84);
    // Sous securite : ecrire demande Piloter.
    Project s = p;
    s.security = Security::defaults();
    s.security.enabled = true;
    User u;
    u.id = s.allocate();
    u.login = "lecteur";
    u.group = s.security.groups[0].id;
    s.security.roles[0].permissions = {"Naviguer"};   // Conduite, sans Piloter
    s.security.users.push_back(u);
    s.security.startUser = "lecteur";
    Runtime rs;
    rs.bind(&s, nullptr);
    rs.start(0.0);
    rs.objectPart(fReel, "champ", 0.1);
    check(rs.focusedObject() == kNoId && rs.formState(fReel) && rs.formState(fReel)->message.find("Piloter") != std::string::npos,
          "sans la permission Piloter, le champ refuse et le dit");
    check(journalHas(rs, "", "Piloter"), "... le refus va au journal");
}

void utilisateursLot8() {
    std::printf("lot 8 : connexion, d\xC3\xA9" "connexion, mot de passe, gestion des utilisateurs\n");
    Project p;
    p.security = Security::defaults();
    p.security.enabled = true;
    const auto user = [&](const char* login, const char* name, std::size_t group, const char* pwd) {
        User u;
        u.id = p.allocate();
        u.login = login;
        u.fullName = name;
        u.group = p.security.groups[group].id;
        if (*pwd) { u.salt = randomHex(16); u.passwordHash = passwordHash(u.salt, pwd); }
        p.security.users.push_back(u);
        return u.id;
    };
    const Id op = user("operateur", "Paul Martin", 0, "1234");
    (void)user("chef", "Claire Dubois", 2, "chef1");
    const Id admin = user("admin", "", 3, "admin2026");
    const Id stag = user("stagiaire", "", 0, "");
    p.security.startUser = "operateur";
    View v = makeView(p, "Comptes");
    const auto add = [&](Kind k, const char* name) {
        const Id id = edit::add(p, v, k, 10, 10);
        v.object(id)->name = name;
        return id;
    };
    const Id login = add(Kind::LoginPanel, "Connexion");
    const Id logout = add(Kind::LogoutButton, "Deconnexion");
    v.object(logout)->setFlag("confirm", true);
    const Id pwd = add(Kind::PasswordChange, "Mot_De_Passe");
    v.object(pwd)->setFlag("requireDigit", true);
    const Id manager = add(Kind::UserManager, "Gestion");
    p.views = {v};
    p.config.startView = v.id;
    p.programs.variables.push_back(hmiVar(p, "Qui", "STRING", "''"));
    p.programs.variables.push_back(hmiVar(p, "Niveau", "INT", "0"));
    p.programs.scripts.push_back(generalScript(p, "Qui_Est_La", "Qui := CONCAT(IHM_UTILISATEUR(), '/', IHM_GROUPE());\nNiveau := IHM_NIVEAU();"));
    p.programs.scripts.push_back(generalScript(p, "Sortir", "IHM_DECONNECTER();"));
    Runtime rt;
    rt.bind(&p, nullptr);
    std::vector<UserRequest> requests;
    Runtime::Hooks hooks;
    hooks.userRequest = [&](const UserRequest& rq) {
        requests.push_back(rq);
        if (auto* u = p.user(rq.user)) {
            if (rq.op == "activer") u->enabled = rq.enabled;
            if (rq.op == "changer") { u->salt = rq.salt; u->passwordHash = rq.hash; }
        }
    };
    rt.setHooks(hooks);
    rt.start(0.0);
    const auto msg = [&](Id id) { const auto* f = rt.formState(id); return f ? f->message : std::string("?"); };

    check(rt.loginChoice(login) && rt.loginChoice(login)->id == op, "la liste montre l'utilisateur connect\xC3\xA9 (operateur)");
    // La gestion : refusee a l'operateur.
    rt.objectPart(manager, "bouton:Ajouter", 0.1);
    check(requests.empty() && msg(manager).find("Administrer") != std::string::npos, "l'op\xC3\xA9rateur ne g\xC3\xA8re pas les comptes");
    // La deconnexion, confirmee.
    rt.objectPart(logout, "bouton", 0.2);
    check(rt.userLogin() == "operateur" && msg(logout).find("confirmer") != std::string::npos, "un premier clic demande confirmation");
    rt.objectPart(logout, "bouton", 0.3);
    check(rt.userLogin().empty(), "le second d\xC3\xA9" "connecte");
    check(msg(manager).empty(), "les r\xC3\xA9ponses d'avant (refus) s'effacent \xC3\xA0 la d\xC3\xA9" "connexion");
    rt.objectPart(logout, "bouton", 4.0);
    rt.objectPart(logout, "bouton", 4.1);
    check(msg(logout).find("personne") != std::string::npos, "d\xC3\xA9" "connexion sans utilisateur : dit");
    // La connexion : les fleches, puis le mot de passe.
    rt.objectPart(login, "suivant", 4.2);
    rt.objectPart(login, "suivant", 4.3);
    check(rt.loginChoice(login)->id == admin, "deux fois suivant (operateur, chef, admin) : admin");
    rt.typeText("mauvais", 4.5);
    rt.objectPart(login, "bouton", 4.6);
    check(rt.userLogin().empty() && msg(login).find("incorrect") != std::string::npos, "mot de passe faux : refus\xC3\xA9 (" + msg(login) + ")");
    check(rt.formState(login)->text.at("motdepasse").empty(), "... le champ se vide");
    rt.typeText("admin2026", 4.7);
    rt.objectPart(login, "bouton", 4.8);
    check(rt.userLogin() == "admin" && msg(login).find("Bienvenue") != std::string::npos, "admin connect\xC3\xA9 (" + msg(login) + ")");
    // La gestion, en administrateur : choisir, desactiver, proteger soi-meme.
    rt.objectPart(manager, "bouton:Supprimer", 4.9);
    check(requests.empty() && msg(manager).find("choisir") != std::string::npos, "sans ligne choisie : dit");
    rt.objectPart(manager, "ligne:3", 5.0);
    rt.objectPart(manager, "bouton:Activer", 5.1);
    check(requests.size() == 1 && requests.back().op == "activer" && !requests.back().enabled && requests.back().user == stag,
          "d\xC3\xA9sactiver le stagiaire : demand\xC3\xA9 \xC3\xA0 l'\xC3\xA9" "cran");
    check(!p.user(stag)->enabled, "... et fait");
    rt.objectPart(manager, "ligne:2", 5.2);
    rt.objectPart(manager, "bouton:Supprimer", 5.3);
    check(requests.size() == 1 && msg(manager).find("connect") != std::string::npos, "on ne se supprime pas soi-m\xC3\xAAme");
    rt.objectPart(manager, "bouton:Ajouter", 5.4);
    check(requests.size() == 2 && requests.back().op == "ajouter", "Ajouter : demand\xC3\xA9 \xC3\xA0 l'\xC3\xA9" "cran");
    check(rt.loginChoice(login)->id == admin, "le choix reste sur admin, m\xC3\xAAme quand la liste change");
    // Changer son mot de passe : ancien faux, trop court, sans chiffre, confirmation fausse, puis bon.
    const auto tryChange = [&](const char* old, const char* now, const char* confirm, double t) {
        rt.objectPart(pwd, "champ:ancien", t);
        rt.typeText(old, t);
        rt.objectPart(pwd, "champ:nouveau", t);
        rt.typeText(now, t);
        rt.objectPart(pwd, "champ:confirmation", t);
        rt.typeText(confirm, t);
        rt.objectPart(pwd, "bouton", t);
        auto* f = rt.formState(pwd);
        const std::string m = f ? f->message : std::string{};
        // les champs restants sont vides pour l'essai suivant
        rt.typeKey(EditKey::Escape, t);
        return m;
    };
    check(tryChange("faux", "Nouveau9", "Nouveau9", 6.0).find("ancien") != std::string::npos, "ancien mot de passe faux : refus\xC3\xA9");
    check(tryChange("admin2026", "a1", "a1", 6.1).find("au moins 6") != std::string::npos, "trop court : refus\xC3\xA9");
    check(tryChange("admin2026", "abcdefgh", "abcdefgh", 6.2).find("chiffre") != std::string::npos, "sans chiffre : refus\xC3\xA9");
    check(tryChange("admin2026", "Nouveau9", "Nouveau8", 6.3).find("confirmation") != std::string::npos, "confirmation fausse : refus\xC3\xA9" "e");
    check(tryChange("admin2026", "Nouveau9", "Nouveau9", 6.4).find("chang") != std::string::npos, "le bon : chang\xC3\xA9");
    check(requests.back().op == "changer" && passwordMatches(p.user(admin)->salt, p.user(admin)->passwordHash, "Nouveau9"),
          "le nouveau mot de passe est gard\xC3\xA9 en empreinte sal\xC3\xA9" "e");
    // L'utilisateur connecte, en texte : les fonctions IHM_.
    std::string why;
    check(rt.callScript("Qui_Est_La", 7.0, &why), "IHM_UTILISATEUR, IHM_GROUPE, IHM_NIVEAU" + (why.empty() ? std::string{} : " (" + why + ")"));
    same(rt.variable("Qui") ? rt.variable("Qui")->asString() : std::string("?"), "admin/Administrateur", "IHM_UTILISATEUR() / IHM_GROUPE()");
    check(rt.variable("Niveau") && rt.variable("Niveau")->asInteger() == 4, "IHM_NIVEAU() : 4");
    check(rt.callScript("Sortir", 7.1, &why) && rt.userLogin().empty(), "IHM_DECONNECTER()");
    // Le gabarit de l'utilisateur connecte.
    UserInfoValues vals;
    vals.login = "admin";
    vals.group = "Administrateur";
    vals.level = 4;
    vals.since = 125;
    vals.remaining = -1;
    same(fillUserInfo("{nom} ({groupe}, niveau {niveau}) depuis {depuis}, reste {reste} {autre}", vals),
         "admin (Administrateur, niveau 4) depuis 2 min 05 s, reste - {autre}", "le gabarit : sans nom, le login ; {reste} sans minuterie : -");
}

// =============================================================================
//  1.11.7 (« quand je fais tourner l'IHM il n'envoie pas le parametre car il y a les $$ ;
//  si je les enleve ca fonctionne ; je veux pouvoir laisser des references dans les
//  parametres des popups ») : un repere dans un argument (IN_V := $V[2]$, pose par
//  Dupliquer...) est transparent - la popup recoit V[2] en reference.
// =============================================================================
void reperesArgumentsPopup1117() {
    std::printf("1.11.7 : un rep\xC3\xA8re dans les param\xC3\xA8tres d'une popup (IN_V := $V[2]$)\n");
    Project p;
    HmiType tv;
    tv.id = p.allocate();
    tv.name = "T_Vanne";
    tv.members = {{"CMD_OUV", "BOOL"}, {"OUV", "BOOL"}};
    p.programs.types = {tv};
    p.programs.variables.push_back(hmiVar(p, "V", "ARRAY[0..3] OF T_Vanne"));
    p.programs.variables.push_back(hmiVar(p, "Lu", "BOOL", "FALSE"));
    View base = makeView(p, "Base");
    View pop = makeView(p, "Popup");
    pop.role = "popup";
    pop.params = {{"IN_V", "", "", "T_Vanne", ParamMode::Reference}};
    auto& ouvrir = addButton(p, base, "Valve_1", 10, 10);
    ouvrir.actions.push_back(act(Trigger::Click, Operation::Popup, "Popup", "IN_V := $V[2]$"));
    const Id btnOuvrir = ouvrir.id;
    auto& cmd = addButton(p, pop, "Btn_Ouvrir", 10, 10);
    cmd.actions.push_back(act(Trigger::Click, Operation::Set, "IN_V.CMD_OUV"));
    const Id btnCmd = cmd.id;
    auto& lire = addButton(p, pop, "Btn_Lire", 10, 60);
    lire.actions.push_back(act(Trigger::Click, Operation::Assign, "Lu", "IN_V.OUV"));
    const Id btnLire = lire.id;
    p.views = {base, pop};
    p.config.startView = base.id;
    const Id popId = pop.id;
    // La verification : ni type refuse, ni variable inexistante.
    check(hmi::params::checkArguments(p, p.view(base.id), *p.view(popId), "IN_V := $V[2]$", {}).empty(),
          "IN_V := $V[2]$ : une r\xC3\xA9" "f\xC3\xA9rence T_Vanne, rien \xC3\xA0 revoir");
    const auto issues = generate(p, [](std::string_view) { return false; });
    check(std::none_of(issues.begin(), issues.end(), [](const Issue& i) { return i.message.find("IN_V") != std::string::npos; }),
          "G\xC3\xA9n\xC3\xA9rer ne dit rien de IN_V");
    // En marche : la popup recoit V[2] en reference (elle l'ecrit et le lit).
    Runtime rt;
    rt.bind(&p, nullptr);
    rt.start(0.0);
    rt.press(btnOuvrir, 0.1);
    rt.release(btnOuvrir, 0.15, true);
    check(rt.popups().size() == 1 && rt.popups().front() == popId, "le clic ouvre la popup");
    const auto* scope = rt.viewScope(popId);
    check(scope && scope->resolve("IN_V.CMD_OUV") == "V[2].CMD_OUV", "IN_V est V[2] (" + (scope ? scope->resolve("IN_V.CMD_OUV") : std::string("pas de param\xC3\xA8tres")) + ")");
    rt.press(btnCmd, 0.2);
    rt.release(btnCmd, 0.25, true);
    sim::Value v2, v0;
    check(rt.environment().read("V[2].CMD_OUV", v2) && v2.isTruthy() && rt.environment().read("V[0].CMD_OUV", v0) && !v0.isTruthy(),
          "Mettre \xC3\xA0 1 IN_V.CMD_OUV \xC3\xA9" "crit V[2].CMD_OUV (et pas V[0])");
    rt.environment().write("V[2].OUV", sim::Value::boolean(true));
    rt.press(btnLire, 0.3);
    rt.release(btnLire, 0.35, true);
    check(rt.variable("Lu") && rt.variable("Lu")->isTruthy(), "Lu := IN_V.OUV lit V[2].OUV");
}

// =============================================================================
//  1.11.8 (« j'aimerais pouvoir dire que la ligne selectionnee deviendrait une variable
//  interne dans Variables IHM ; chaque membre peut choisir s'il est interne ou attribue a
//  l'equipement de la structure » ; « un bouton Recalculer la place memoire » ; « modifier
//  les adresses %MW meme dans une structure ») : V : ARRAY[0..63] OF Vanne a %MW17, sur
//  l'Esclave virtuel 1 (la capture du client).
// =============================================================================
void membresInternes1118() {
    std::printf("1.11.8 : les membres internes d'une structure li\xC3\xA9" "e, la place recalcul\xC3\xA9" "e, le d\xC3\xA9part d'un membre\n");
    namespace ty = hmi::types;
    Project p;
    HmiType vanne;
    vanne.id = p.allocate();
    vanne.name = "Vanne";
    vanne.members = {{"POSITION", "INT"}, {"OUV", "BOOL"}, {"NOM", "STRING"}, {"CMD_OUV", "BOOL"}, {"CMD_FERM", "BOOL"}};
    p.programs.types = {vanne};
    Equipment e;
    e.id = p.allocate();
    e.name = "Esclave virtuel 1";
    e.host = "127.0.0.1";
    e.port = 502;
    p.equipments.push_back(e);
    Variable v = hmiVar(p, "V", "ARRAY[0..63] OF Vanne");
    v.equipment = "Esclave virtuel 1";
    v.address = "%MW17";
    p.programs.variables.push_back(v);
    const auto addressOf = [&](std::string_view name) {
        for (const auto& l : ty::leafVariables(p, p.programs.variables[0]))
            if (l.name == name) return l.bound() ? l.address : std::string("interne");
        return std::string("?");
    };
    const auto var = [&]() -> Variable& { return p.programs.variables[0]; };
    // La place d'origine (la capture : 19 mots par vanne, NOM en prend 16).
    same(addressOf("V[0].NOM"), "%MW19", "V[0].NOM : %MW19 (16 mots)");
    same(addressOf("V[0].CMD_OUV"), "%MW35.0", "V[0].CMD_OUV : %MW35.0");
    same(addressOf("V[1].POSITION"), "%MW36", "V[1] part de %MW36");
    same(ty::spanText(p, var()), "mots 17 \xC3\xA0 1232", "la place : mots 17 \xC3\xA0 1232");
    check(hmi::equip::buildPlan(p, p.equipments[0]).points().size() == 64 * 5, "le plan : 320 cases");
    // Le chemin d'un membre : une case, ou toutes ([*]), et tout ce qui est dessous.
    check(ty::memberCovers("[0].NOM", "[0].NOM") && !ty::memberCovers("[0].NOM", "[1].NOM") && ty::memberCovers("[*].NOM", "[63].NOM")
              && ty::memberCovers("[2]", "[2].CMD_OUV") && !ty::memberCovers("[2]", "[20].CMD_OUV") && !ty::memberCovers("[*].NOM", "[0].NOMBRE")
              && ty::memberCovers("vannes[*].position", "Vannes[2].Position"),
          "un chemin couvre lui-m\xC3\xAAme et ce qui est dessous ; [*] couvre tout indice ; sans casse");
    // 1. V[0].NOM interne : elle reste dans l'IHM, sa place reste reservee (rien ne bouge).
    var().internal = {"[0].NOM"};
    same(addressOf("V[0].NOM"), "interne", "V[0].NOM interne : ni \xC3\xA9quipement, ni adresse");
    same(addressOf("V[0].CMD_OUV"), "%MW35.0", "... V[0].CMD_OUV ne bouge pas (la place reste r\xC3\xA9serv\xC3\xA9" "e)");
    same(addressOf("V[1].NOM"), "%MW38", "... V[1].NOM reste li\xC3\xA9" "e");
    check(hmi::equip::buildPlan(p, p.equipments[0]).points().size() == 64 * 5 - 1 && hmi::equip::buildPlan(p, p.equipments[0]).refused().empty(),
          "le plan : 319 cases, aucune refus\xC3\xA9" "e");
    // 2. Recalculer la place : les 16 mots de V[0].NOM sont rendus, la suite se resserre.
    var().compact = true;
    same(addressOf("V[0].CMD_OUV"), "%MW19.0", "recalcul\xC3\xA9" "e : V[0].CMD_OUV passe \xC3\xA0 %MW19.0");
    same(addressOf("V[1].POSITION"), "%MW20", "... V[1] part de %MW20");
    same(ty::spanText(p, var()), "mots 17 \xC3\xA0 1216", "... la place : mots 17 \xC3\xA0 1216 (16 mots rendus)");
    // 3. NOM interne dans toutes les vannes ([*].NOM) : 3 mots par vanne.
    var().internal = {"[*].NOM"};
    same(addressOf("V[63].NOM"), "interne", "[*].NOM : V[63].NOM interne aussi");
    same(addressOf("V[1].POSITION"), "%MW20", "V[1] part de %MW20");
    same(addressOf("V[63].CMD_FERM"), "%MW208.1", "V[63].CMD_FERM : %MW208.1 (V[63] part de 17 + 63 x 3 = 206)");
    same(ty::spanText(p, var()), "mots 17 \xC3\xA0 208", "la place : mots 17 \xC3\xA0 208 (192 mots au lieu de 1216)");
    check(hmi::equip::buildPlan(p, p.equipments[0]).points().size() == 64 * 4, "le plan : 256 cases");
    // ... sans recalcul, les trous restent.
    var().compact = false;
    same(addressOf("V[1].POSITION"), "%MW36", "place r\xC3\xA9serv\xC3\xA9" "e : V[1] reste \xC3\xA0 %MW36");
    var().compact = true;
    // 4. Le depart d'un membre compose : V[2] a %MW500, ses cases le suivent.
    var().places = {{"[2]", "%MW500"}};
    same(addressOf("V[2].POSITION"), "%MW500", "V[2] part de %MW500");
    same(addressOf("V[2].OUV"), "%MW501.0", "V[2].OUV : %MW501.0");
    same(addressOf("V[2].CMD_FERM"), "%MW502.1", "V[2].CMD_FERM : %MW502.1 (NOM interne, place rendue)");
    same(addressOf("V[3].POSITION"), "%MW26", "V[3] garde sa place calcul\xC3\xA9" "e");
    // ... et une case corrigee a la main gagne sur le depart de son membre.
    var().places.push_back({"[2].OUV", "%MW600.3"});
    same(addressOf("V[2].OUV"), "%MW600.3", "V[2].OUV corrig\xC3\xA9" "e \xC3\xA0 la main : %MW600.3");
    // 5. En marche : un membre interne vit dans l'IHM ; les autres dans l'equipement.
    {
        Runtime rt;
        rt.bind(&p, nullptr);
        rt.start(0.0);
        check(rt.boundVariable("V[0].NOM") == nullptr && rt.boundVariable("V[0].POSITION") != nullptr,
              "le moteur : V[0].NOM est locale, V[0].POSITION li\xC3\xA9" "e");
        check(rt.environment().write("V[5].NOM", sim::Value::text("Vanne 5")) && rt.variable("V[5].NOM")
                  && rt.variable("V[5].NOM")->asString() == "Vanne 5",
              "\xC3\xA9" "crire V[5].NOM : gard\xC3\xA9 dans l'IHM (sans liaison, sans erreur)");
        rt.stop(1.0);
    }
    // 6. Enregistrer, relire : les membres internes et la place recalculee restent.
    {
        const fs::path dir = fs::temp_directory_path() / "hmi_test_1118";
        fs::remove_all(dir);
        check(static_cast<bool>(save(p, dir.string())), "enregistrer");
        const auto back = load(dir.string());
        check(back && back->variable("V") && back->variable("V")->internal == std::vector<std::string>{"[*].NOM"} && back->variable("V")->compact
                  && back->variable("V")->places.size() == 2,
              "relu : [*].NOM interne, place recalcul\xC3\xA9" "e, deux adresses corrig\xC3\xA9" "es");
        fs::remove_all(dir);
    }
    // 7. Generer : un membre interne ne designe plus rien -> un avertissement.
    var().internal.push_back("[*].ABSENT");
    const auto issues = generate(p, [](std::string_view) { return false; });
    check(std::any_of(issues.begin(), issues.end(), [](const Issue& i) { return i.message.find("[*].ABSENT") != std::string::npos; }),
          "un membre interne qui ne d\xC3\xA9signe rien : signal\xC3\xA9");
    check(std::none_of(issues.begin(), issues.end(), [](const Issue& i) { return i.message.find("V[0].NOM") != std::string::npos; }),
          "... un membre interne n'est pas \xC2\xAB sans place \xC2\xBB");
}

// =============================================================================
//  1.11.9 (« trier les actions disponibles avec un treeview » ; « maths : aide aux
//  formules, n parametres qui seront des references, un mode test » ; « ouvrir un
//  clavier virtuel, champ de saisie, et on met des parametres ») : le moteur.
// =============================================================================
void actionsMathsClavier1119() {
    std::printf("1.11.9 : les op\xC3\xA9rations rang\xC3\xA9" "es, Maths, le clavier virtuel\n");
    namespace ak = hmi::actionkinds;
    // Les familles : chaque operation y est une fois, avec sa phrase.
    {
        std::map<int, int> seen;
        for (const auto& g : ak::groups())
            for (const auto o : g.operations) ++seen[static_cast<int>(o)];
        bool once = true, help = true;
        for (const auto o : kOperations) {
            once = once && seen[static_cast<int>(o)] == 1;
            help = help && !ak::help(o).empty() && !ak::groupOf(o).empty();
        }
        check(once && seen.size() == std::size(kOperations), "les familles : chaque op\xC3\xA9ration une fois (" + std::to_string(seen.size()) + ")");
        check(help, "... chacune a sa famille et sa phrase");
        check(ak::groupOf(Operation::Maths) == ak::groupOf(Operation::Assign) && ak::groupOf(Operation::Popup) != ak::groupOf(Operation::Set),
              "Maths avec Affecter ; Ouvrir une popup ailleurs que Mettre \xC3\xA0 1");
    }
    // Les references de Maths.
    Action m;
    m.params = "Mesure := M; Consigne := C";
    const auto refs = ak::params(m);
    check(refs.size() == 2 && refs[0].first == "Mesure" && refs[1].second == "C" && ak::formatParams(refs) == m.params, "les r\xC3\xA9" "f\xC3\xA9rences, lues et r\xC3\xA9" "\xC3\xA9" "crites");
    same(ak::mathsExpression("(Mesure - Consigne) * 2 + MesureX", refs), "(M - C) * 2 + MesureX", "la formule avec les chemins (MesureX reste)");
    check(ak::checkMaths(refs, "(Mesure - Consigne) * 2").empty(), "une formule juste : rien \xC3\xA0 dire");
    {
        const auto bad = ak::checkMaths({{"X", "1 + 2"}, {"X", "Y"}}, "X * 2");
        check(bad.size() >= 2 && bad[0].badParam == 0 && bad[0].why.find("chemin") != std::string::npos, "une r\xC3\xA9" "f\xC3\xA9rence calcul\xC3\xA9" "e : refus\xC3\xA9" "e (" + (bad.empty() ? std::string{} : bad[0].why) + ")");
        check(std::any_of(bad.begin(), bad.end(), [](const ak::MathsIssue& i) { return i.why.find("deux fois") != std::string::npos; }), "un nom deux fois : dit");
    }
    {
        const auto t = ak::testMaths(refs, {"12.5", "10"}, "(Mesure - Consigne) * 2");
        check(t.ok && t.result == "5" && t.expression.find("12.5") != std::string::npos, "le mode test : (12.5 - 10) * 2 = " + t.result);
        check(!ak::testMaths(refs, {"1", "2"}, "Mesure +").ok, "le mode test : une formule illisible le dit");
    }
    // Le clavier virtuel : ses reglages.
    {
        Action k;
        ak::KeyboardSpec spec;
        spec.title = "'Code du badge'";
        spec.keyboard = "numerique";
        spec.min = "0";
        spec.max = "100";
        spec.unit = "%";
        spec.mask = true;
        ak::setKeyboardSpec(k, spec);
        const auto back = ak::keyboardSpec(k);
        check(back.title == spec.title && back.keyboard == "numerique" && back.min == "0" && back.max == "100" && back.unit == "%" && back.mask,
              "les r\xC3\xA9glages du clavier, enregistr\xC3\xA9s puis relus (" + k.params + ")");
        check(ak::keyboardFor("REAL", "auto") == "numerique" && ak::keyboardFor("STRING", "auto") == "complet", "auto : num\xC3\xA9rique pour un REAL, complet pour un texte");
    }
    // En marche.
    Project p;
    View base = makeView(p, "Base");
    p.programs.variables.push_back(hmiVar(p, "M", "REAL", "12.5"));
    p.programs.variables.push_back(hmiVar(p, "C", "REAL", "10"));
    p.programs.variables.push_back(hmiVar(p, "Sortie", "REAL", "0"));
    p.programs.variables.push_back(hmiVar(p, "Code", "INT", "0"));
    auto& calc = addButton(p, base, "Btn_Calc", 10, 10);
    {
        Action a = act(Trigger::Click, Operation::Maths, "Sortie", "(Mesure - Consigne) * 2");
        a.params = "Mesure := M; Consigne := C";
        calc.actions.push_back(a);
    }
    const Id btnCalc = calc.id;
    auto& saisie = addButton(p, base, "Btn_Saisie", 10, 80);
    {
        Action a = act(Trigger::Click, Operation::Keyboard, "Code");
        a.params = "titre := 'Code'; min := 0; max := 100";
        saisie.actions.push_back(a);
    }
    const Id btnSaisie = saisie.id;
    p.views = {base};
    p.config.startView = base.id;
    Runtime rt;
    rt.bind(&p, nullptr);
    rt.start(0.0);
    rt.press(btnCalc, 0.1);
    rt.release(btnCalc, 0.15, true);
    near(rt.variable("Sortie") ? rt.variable("Sortie")->asReal() : -1, 5.0, "Maths : Sortie := (M - C) * 2 = 5");
    rt.press(btnSaisie, 0.2);
    rt.release(btnSaisie, 0.25, true);
    check(rt.promptShown() && rt.keyboardPrompt() && rt.keyboardPrompt()->target == "Code" && rt.keyboardPrompt()->max && *rt.keyboardPrompt()->max == 100,
          "le clavier virtuel s'ouvre : Code, de 0 \xC3\xA0 100");
    rt.typeText("150", 0.3);
    rt.typeKey(EditKey::Enter, 0.31);
    check(rt.promptShown() && rt.promptForm().error && rt.promptForm().message.find("hors limites") != std::string::npos,
          "150 : refus\xC3\xA9, hors limites (le champ reste) - " + rt.promptForm().message);
    for (int k = 0; k < 3; ++k) rt.typeKey(EditKey::Backspace, 0.32);
    rt.typeText("42", 0.33);
    rt.typeKey(EditKey::Enter, 0.34);
    check(!rt.promptShown() && rt.variable("Code") && rt.variable("Code")->asInteger() == 42, "42 : \xC3\xA9" "crit dans Code, le champ se ferme");
    rt.press(btnSaisie, 0.4);
    rt.release(btnSaisie, 0.45, true);
    rt.typeText("7", 0.5);
    rt.typeKey(EditKey::Escape, 0.51);
    check(!rt.promptShown() && rt.variable("Code")->asInteger() == 42, "\xC3\x89" "chap : ferm\xC3\xA9, Code ne change pas");
}

// =============================================================================
//  1.11.10 : LES FONCTIONS D'UN SYMBOLE (la demande du 05/10 : « des fonctions aux
//  symboles utilisateurs [...] en virtual, modifiables par les instances, toutes les
//  variables dispos comme les scripts generaux [...] disponibles dans les scripts
//  generaux » ; et, a 19 h : « les fonctions utilisables entre elles et dans les
//  operateurs, les operateurs entre eux aussi »).
// =============================================================================
void fonctionsSymbole11110() {
    std::printf("1.11.10 : les fonctions d'un symbole (virtuelles, red\xC3\xA9" "finies, appel\xC3\xA9" "es partout) ; fonctions et op\xC3\xA9rateurs entre eux\n");
    Project p;
    {
        HmiType vec;
        vec.id = p.allocate();
        vec.name = "T_VEC";
        vec.members = {{"X", "REAL", "", ""}, {"Y", "REAL", "", ""}};
        p.programs.types.push_back(vec);
    }
    p.programs.variables.push_back(hmiVar(p, "Pos0", "INT", "0"));
    p.programs.variables.push_back(hmiVar(p, "Pos1", "INT", "0"));
    p.programs.variables.push_back(hmiVar(p, "Ouvertures", "INT", "0"));
    p.programs.variables.push_back(hmiVar(p, "Trace", "STRING", ""));
    p.programs.variables.push_back(hmiVar(p, "Purge", "BOOL", "FALSE"));
    p.programs.variables.push_back(hmiVar(p, "V0", "T_VEC", ""));
    p.programs.variables.push_back(hmiVar(p, "R", "T_VEC", ""));
    p.programs.variables.push_back(hmiVar(p, "Lu", "INT", "0"));
    // Une fonction IHM, appelee par une fonction de symbole et par un operateur.
    HmiFunction compter;
    compter.id = p.allocate();
    compter.name = "Compter";
    compter.body = "Ouvertures := Ouvertures + 1;";
    p.programs.functions.push_back(compter);
    HmiFunction bonus;
    bonus.id = p.allocate();
    bonus.name = "Bonus";
    bonus.returnType = "REAL";
    bonus.body = "VAR_INPUT\n  x : REAL;\nEND_VAR\nBonus := x + 0.5;";
    p.programs.functions.push_back(bonus);
    // Deux operateurs de T_VEC : * emploie + et la fonction Bonus.
    HmiOperator plus = makeOperator(p, "+", "T_VEC", "T_VEC", "T_VEC");
    plus.body = "Resultat.X := a.X + b.X;\nResultat.Y := a.Y + b.Y;";
    HmiOperator fois = makeOperator(p, "*", "T_VEC", "REAL", "T_VEC");
    fois.body = "IF b = 2.0 THEN\n  Resultat := a + a;\nELSE\n  Resultat.X := a.X * b;\n  Resultat.Y := a.Y * b;\nEND_IF;\nResultat.X := Bonus(Resultat.X);";
    p.programs.types[0].operators = {plus, fois};
    // Le symbole : un parametre Pos, trois fonctions.
    View sym = makeView(p, "S_Vanne");
    sym.role = "symbole";
    sym.params.push_back({"Pos", "0", "", "INT", ParamMode::Reference});
    const auto fn = [&](const char* name, const char* ret, const char* body, bool virt) {
        HmiFunction f;
        f.id = p.allocate();
        f.name = name;
        f.returnType = ret;
        f.body = body;
        f.isVirtual = virt;
        sym.functions.push_back(f);
    };
    fn("Ouvrir", "", "VAR_INPUT\n  Pas : INT := 10;\nEND_VAR\nPos := Pos + Pas;\nCompter();\nTrace := CONCAT(Trace, 'o');", true);
    fn("Etat", "INT", "Etat := Pos * 2;", false);
    fn("Double", "", "Ouvrir(Pas := Etat());", false);                 // ses fonctions entre elles
    fn("Vecteur", "T_VEC", "Vecteur := V0 * 2.0;", false);             // un operateur dans une fonction
    fn("Boucle", "", "Boucle();", false);                               // sans fin
    {
        auto& b = addButton(p, sym, "Btn", 0, 0);
        b.actions.push_back(act(Trigger::Click, Operation::RunScript, {}, "Ouvrir();"));
    }
    const Id symBtn = sym.objects.back().id;
    {
        auto& d = addButton(p, sym, "BtnDetail", 0, 40);
        d.actions.push_back(act(Trigger::Click, Operation::Popup, "Pop_Vanne"));    // sa popup, sans argument
    }
    const Id symDetail = sym.objects.back().id;
    const Id symId = sym.id;
    p.views.push_back(sym);
    // 1.11.10 : la popup du symbole - elle lit Pos (le parametre du symbole) et appelle Ouvrir.
    View pop = makeView(p, "Pop_Vanne");
    pop.role = "popup";
    pop.ownerSymbol = symId;
    Id popLire = kNoId, popOuvrir = kNoId;
    {
        auto& b1 = addButton(p, pop, "BtnLire", 0, 0);
        b1.actions.push_back(act(Trigger::Click, Operation::RunScript, {}, "Lu := Pos;"));
        popLire = b1.id;
        auto& b2 = addButton(p, pop, "BtnOuvrir", 0, 40);
        b2.actions.push_back(act(Trigger::Click, Operation::RunScript, {}, "Ouvrir(1);"));
        popOuvrir = b2.id;
    }
    p.views.push_back(pop);
    View v = makeView(p, "Vue_V");
    const Id vid = v.id;
    Id i1 = kNoId, i2 = kNoId, vBtn = kNoId, vPop = kNoId;
    {
        i1 = placeSymbol(p, v, "S_Vanne", 10, 10);
        v.object(i1)->name = "V1";
        v.object(i1)->set("params", "Pos := Pos0");
        i2 = placeSymbol(p, v, "S_Vanne", 200, 10);
        v.object(i2)->name = "V2";
        v.object(i2)->set("params", "Pos := Pos1");
        // V2 redefinit Ouvrir : la purge d'abord, puis le corps du symbole (SUPER), pas double.
        v.object(i2)->functionOverrides.push_back(
            {"Ouvrir", "VAR_INPUT\n  Pas : INT := 10;\nEND_VAR\nIF NOT Purge THEN\n  Trace := CONCAT(Trace, 'refus');\n  RETURN;\nEND_IF;\nSUPER.Ouvrir(Pas := Pas * 2);"});
        auto& b = addButton(p, v, "BtnV", 400, 10);
        b.actions.push_back(act(Trigger::Click, Operation::RunScript, {}, "V1.Ouvrir(5);"));   // depuis la vue : Instance.Fonction
        vBtn = b.id;
        auto& b2 = addButton(p, v, "BtnV2", 400, 60);
        b2.actions.push_back(act(Trigger::Click, Operation::Popup, "V2.Pop_Vanne"));          // la popup de V2, depuis la vue
        vPop = b2.id;
    }
    p.views.push_back(v);
    p.config.startView = vid;
    p.programs.scripts.push_back(generalScript(p, "Seq",
        "Vue_V.V1.Ouvrir();\nVue_V.V2.Ouvrir();\nPurge := TRUE;\nVue_V.V2.Ouvrir();\nVue_V.V1.Double();\nR := Vue_V.V1.Vecteur();"));
    p.programs.scripts.back().event = "Appel";
    p.programs.scripts.push_back(generalScript(p, "Inf", "Vue_V.V1.Boucle();"));
    p.programs.scripts.back().event = "Appel";
    p.programs.scripts.push_back(generalScript(p, "OuvrePop", "IHM_POPUP('Vue_V.V1.Pop_Vanne');"));
    p.programs.scripts.back().event = "Appel";
    // L'ecriture des appels, a l'expansion.
    {
        same(qualifySymbolCalls("Ouvrir(); x := Etat() + Pos; SUPER.Ouvrir(1); Autre(); 'Ouvrir()'", p, *p.viewByName("S_Vanne"), "Vue_V.V1"),
             "Vue_V.V1.Ouvrir(); x := Vue_V.V1.Etat() + Pos; Vue_V.V1.SUPER.Ouvrir(1); Autre(); 'Ouvrir()'",
             "dans le symbole : Ouvrir( et SUPER.Ouvrir( visent l'instance ; une autre fonction et une cha\xC3\xAEne restent");
        same(qualifyViewCalls("V1.Ouvrir(5); V2.Pos := 1; V9.Ouvrir(); Vue_V.V1.Etat()", p, *p.view(vid)),
             "Vue_V.V1.Ouvrir(5); V2.Pos := 1; V9.Ouvrir(); Vue_V.V1.Etat()",
             "dans la vue : V1.Ouvrir( devient Vue_V.V1.Ouvrir( ; le reste tel quel");
        BoundFunction b;
        check(boundSymbolFunction(p, "Vue_V.V2.Ouvrir", b) && b.overridden && b.function.body.find("Vue_V.V2.SUPER.Ouvrir(") != std::string::npos,
              "Vue_V.V2.Ouvrir : la red\xC3\xA9" "finition de V2, son SUPER complet");
        check(boundSymbolFunction(p, "Vue_V.V2.SUPER.Ouvrir", b) && !b.overridden && b.function.body.find("Pos1 := Pos1 + Pas") != std::string::npos,
              "Vue_V.V2.SUPER.Ouvrir : le corps du symbole, Pos remplac\xC3\xA9 par Pos1 (" + b.function.body + ")");
        check(!boundSymbolFunction(p, "Vue_V.V1.Inconnue", b) && !boundSymbolFunction(p, "Vue_V.V9.Ouvrir", b), "une fonction ou une instance inconnue : rien");
    }
    Runtime rt;
    rt.bind(&p, nullptr);
    rt.start(0.0);
    const auto num = [&](const char* name) { return rt.variable(name) ? rt.variable(name)->asInteger() : -999; };
    const auto txt = [&](const char* name) { return rt.variable(name) ? rt.variable(name)->asString() : std::string("?"); };
    std::string why;
    check(rt.callScript("Seq", 0.1, &why), "le script g\xC3\xA9n\xC3\xA9ral appelle les fonctions des instances (" + why + ")");
    check(num("Pos0") == 30 && num("Pos1") == 20 && num("Ouvertures") == 3 && txt("Trace") == "orefusoo",
          "V1.Ouvrir (+10), V2 refuse sans purge, puis SUPER (+20), V1.Double = Ouvrir(Etat()) (+20) : Pos0 = 30, Pos1 = 20, 3 ouvertures, "
          "trace orefusoo (" + std::to_string(num("Pos0")) + ", " + std::to_string(num("Pos1")) + ", " + std::to_string(num("Ouvertures")) + ", "
              + txt("Trace") + ")");
    sim::Value rx;
    (void)rt.environment().read("R.X", rx);
    sim::Value rY;
    (void)rt.environment().read("R.Y", rY);
    check(std::fabs(rx.asReal() - 0.5) < 1e-9 && std::fabs(rY.asReal()) < 1e-9,
          "Vecteur = V0 * 2.0 : l'op\xC3\xA9rateur * emploie + et la fonction Bonus (X = " + rx.display() + ", Y = " + rY.display() + ")");
    // Le bouton du symbole, dans V1 : Ouvrir() vise V1.
    rt.press(expandedId(i1, symBtn), 0.2);
    rt.release(expandedId(i1, symBtn), 0.25, true);
    check(num("Pos0") == 40, "le bouton du symbole dans V1 : Ouvrir() ouvre V1 (Pos0 = " + std::to_string(num("Pos0")) + ")");
    rt.press(expandedId(i2, symBtn), 0.3);
    rt.release(expandedId(i2, symBtn), 0.35, true);
    check(num("Pos1") == 40, "... dans V2 : la red\xC3\xA9" "finition de V2 (+20 : Pos1 = " + std::to_string(num("Pos1")) + ")");
    rt.press(vBtn, 0.4);
    rt.release(vBtn, 0.45, true);
    check(num("Pos0") == 45 && !journalHas(rt, "Erreur", ""), "le bouton de la vue : V1.Ouvrir(5) (Pos0 = " + std::to_string(num("Pos0")) + ")");
    // 1.11.10 : la popup du symbole, ouverte depuis le bouton du symbole dans V1 : Pos est Pos0.
    {
        const auto click = [&](Id id, double t) { rt.press(id, t); rt.release(id, t + 0.02, true); };
        click(expandedId(i1, symDetail), 1.0);
        check(rt.topView() == p.viewByName("Pop_Vanne")->id, "le bouton du symbole (V1) ouvre Pop_Vanne, la popup du symbole");
        click(popLire, 1.1);
        check(num("Lu") == 45, "dans la popup : Lu := Pos lit Pos0 (" + std::to_string(num("Lu")) + ")");
        click(popOuvrir, 1.2);
        check(num("Pos0") == 46 && !journalHas(rt, "Erreur", ""), "Ouvrir(1) dans la popup : la fonction de V1 (Pos0 = " + std::to_string(num("Pos0")) + ")");
        (void)rt.closePopup({}, 1.3);
        click(vPop, 1.4);
        click(popLire, 1.5);
        check(rt.topView() == p.viewByName("Pop_Vanne")->id && num("Lu") == 40, "V2.Pop_Vanne depuis la vue : la popup de V2 (Lu = " + std::to_string(num("Lu")) + ")");
        click(popOuvrir, 1.6);
        check(num("Pos1") == 42, "... Ouvrir(1) : la red\xC3\xA9" "finition de V2 (SUPER, pas double : Pos1 = " + std::to_string(num("Pos1")) + ")");
        (void)rt.closePopup({}, 1.7);
        std::string err;
        check(rt.callScript("OuvrePop", 1.8, &err) && rt.topView() == p.viewByName("Pop_Vanne")->id, "IHM_POPUP('Vue_V.V1.Pop_Vanne') (" + err + ")");
        click(popLire, 1.9);
        check(num("Lu") == 46, "... la popup de V1 (Lu = " + std::to_string(num("Lu")) + ")");
        (void)rt.closePopup({}, 2.0);
    }
    // Une expression de vue : {Vue_V.V1.Etat()}.
    {
        auto& env = rt.environment();
        auto* host = dynamic_cast<FunctionHost*>(&env);
        sim::Value out;
        check(host && host->hostsFunction("Vue_V.V1.Etat") && host->callFromExpression("Vue_V.V1.Etat", {}, out) && out.asInteger() == 92,
              "une expression lit Vue_V.V1.Etat() : 92 (" + out.display() + ")");
        const auto e = Expression::compile("Vue_V.V2.Etat() + 1");
        const auto x = e.evaluate(env);
        check(x && x->asInteger() == 85, "Vue_V.V2.Etat() + 1 = 85 (" + (x ? x->display() : std::string("erreur")) + ")");
        // Dans une popup du symbole : {Etat()} devient INSTANCE_DU_SYMBOLE.Etat(), un parametre de la popup.
        Scope inPopup;
        inPopup.setAlias(std::string(kInstanceAlias), "Vue_V.V1");
        const auto y = Expression::compile(std::string(kInstanceAlias) + ".Etat()").evaluate(env, &inPopup);
        check(y && y->asInteger() == 92, "dans la popup : INSTANCE_DU_SYMBOLE.Etat() = 92, celle de V1 (" + (y ? y->display() : std::string("erreur")) + ")");
    }
    // Sans fin : arretee et dite, l'IHM continue.
    {
        std::string err;
        const bool ran = rt.callScript("Inf", 0.5, &err);
        check(!ran && (journalHas(rt, "Erreur", "appel circulaire") || err.find("circulaire") != std::string::npos),
              "Boucle() sans fin : arr\xC3\xAAt\xC3\xA9" "e (appel circulaire) (" + err + ")");
        check(rt.callScript("Seq", 0.6, &err), "... et l'IHM continue : Seq tourne encore (" + err + ")");
    }
    // Exporter le symbole : ses fonctions et ses popups (meme celle qu'aucune action n'ouvre)
    // partent avec lui ; importes dans un projet neuf, la popup suit son symbole.
    {
        namespace pk = hmi::pkg;
        Project src = p;
        View info = makeView(src, "Pop_Info");
        info.role = "popup";
        info.ownerSymbol = symId;
        src.views.push_back(info);
        const auto pkg = pk::collectSymbols(src, {symId});
        const View* ps = pkg.content.viewByName("S_Vanne");
        check(ps && ps->functions.size() == 5 && pkg.content.viewByName("Pop_Vanne") && pkg.content.viewByName("Pop_Info"),
              "exporter S_Vanne : ses 5 fonctions et ses deux popups (Pop_Info : aucune action ne l'ouvre)");
        Project dst;
        const auto pl = pk::plan(dst, pkg);
        (void)pk::importInto(dst, pkg, pl);
        const View* s2 = dst.viewByName("S_Vanne");
        const View* i2 = dst.viewByName("Pop_Info");
        const View* v2 = dst.viewByName("Pop_Vanne");
        check(s2 && i2 && v2 && i2->ownerSymbol == s2->id && v2->ownerSymbol == s2->id && s2->functions.size() == 5
                  && s2->functions[0].isVirtual,
              "import\xC3\xA9 : les popups restent celles de S_Vanne (le nouvel identifiant), ses fonctions aussi");
    }
    // Enregistrer, relire : les fonctions, virtuelles, et la redefinition.
    {
        const auto files = serializeProject(p);
        const FileReader reader = [&](const std::string& path, std::string& content) {
            for (const auto& f : files)
                if (f.path == path) { content.assign(f.data->begin(), f.data->end()); return true; }
            return false;
        };
        auto back = parseProject(reader);
        check(back.has_value(), "le projet se relit");
        if (back) {
            const View* s2 = back->viewByName("S_Vanne");
            const View* v2 = back->viewByName("Vue_V");
            check(s2 && s2->functions == p.viewByName("S_Vanne")->functions, "relu : les 5 fonctions du symbole (Ouvrir virtuelle)");
            const Object* o2 = v2 ? v2->objectByName("V2") : nullptr;
            check(o2 && o2->functionOverrides == p.view(vid)->objectByName("V2")->functionOverrides, "relu : la red\xC3\xA9" "finition de V2");
        }
    }
}

void verificationsLot8() {
    std::printf("lot 8 : g\xC3\xA9n\xC3\xA9rer et compiler (popups, param\xC3\xA8tres, saisie, utilisateurs)\n");
    Project p;
    View base = makeView(p, "Base");
    View pop = makeView(p, "Pop");
    pop.role = "popup";
    pop.params = {{"Moteur", "Pompes[0]", ""}, {"Titre", "'P0'", ""}, {"moteur", "Pompes[1]", ""}, {"2x", "1", ""}};
    const Id jauge = edit::add(p, pop, Kind::Gauge, 10, 10);
    pop.object(jauge)->setExpr("value", "Moteur.Vitesse");
    const Id texte = edit::add(p, pop, Kind::Text, 10, 200);
    pop.object(texte)->set("text", "{Titre} : {Moteur.Vitesse:0} tr/min {Inconnu}");
    pop.popup.titleBar = false;       // ni croix, ni clic dehors, ni bouton
    pop.popup.title = "Pompe {Titre +}";
    pop.popup.placement = "au milieu";
    View help = makeView(p, "Aide");
    help.role = "popup";
    auto& nav = addButton(p, base, "Btn_Nav", 10, 10);
    nav.actions.push_back(act(Trigger::Click, Operation::Navigate, "Aide"));
    auto& open = addButton(p, base, "Btn_Pop", 10, 60);
    Action a = act(Trigger::Click, Operation::Popup, "Pop", "Moteur := Pompes[3]; Vitesse := 2; Rien := Absent[0]");
    a.placement = "partout";
    open.actions.push_back(a);
    auto& open2 = addButton(p, base, "Btn_Aide", 10, 110);
    open2.actions.push_back(act(Trigger::Click, Operation::Popup, "Aide", "Moteur := Pompes[1]"));
    auto& calc = addButton(p, base, "Btn_Calcul", 10, 160);
    calc.actions.push_back(act(Trigger::Click, Operation::ChangePopup, "Pop", "Titre := ('A' +"));
    const Id champ = edit::add(p, base, Kind::InputField, 300, 10);
    base.object(champ)->set("min", "50");
    base.object(champ)->set("max", "10");
    const Id champ2 = edit::add(p, base, Kind::InputField, 300, 60);
    base.object(champ2)->set("variable", "Consigne");
    base.object(champ2)->set("max", "Consigne_Max +");
    const Id connexion = edit::add(p, base, Kind::LoginPanel, 300, 110);
    base.object(connexion)->set("afterLogin", "Vue_Absente");
    const Id gestion = edit::add(p, base, Kind::UserManager, 300, 400);
    base.object(gestion)->set("buttons", "Ajouter;Imprimer");
    p.programs.variables.push_back(hmiVar(p, "Consigne", "REAL", "1.0"));
    p.views = {base, pop, help};
    p.config.startView = pop.id;
    const NameExists plc = [](std::string_view n) { return n == "Pompes"; };
    const auto issues = generate(p, plc);
    const auto has = [&](std::string_view text, Issue::Severity s) {
        for (const auto& i : issues) if (i.severity == s && i.message.find(text) != std::string::npos) return true;
        return false;
    };
    const auto none = [&](std::string_view text) {
        for (const auto& i : issues) if (i.message.find(text) != std::string::npos) return false;
        return true;
    };
    using S = Issue::Severity;
    check(none("inexistante dans le programme : Moteur") && none("inexistante dans le programme : Titre"),
          "un param\xC3\xA8tre se lit comme ce qu'il d\xC3\xA9signe (Moteur -> Pompes) : pas d'erreur");
    check(has("variable inexistante dans le programme : Inconnu", S::Error), "... mais un nom inconnu reste une erreur");
    check(has("d\xC3\xA9" "clar\xC3\xA9 deux fois : moteur", S::Error), "un param\xC3\xA8tre d\xC3\xA9" "clar\xC3\xA9 deux fois (sans casse)");
    check(has("nom de param\xC3\xA8tre invalide : '2x'", S::Error), "un nom de param\xC3\xA8tre invalide");
    check(has("est une popup : elle s'affichera", S::Warning), "une popup comme vue de d\xC3\xA9marrage");
    check(has("position inconnue : 'au milieu'", S::Warning), "la position d'une popup, inconnue");
    check(has("rien ne ferme cette popup", S::Warning), "une popup modale que rien ne ferme");
    check(has("Aide est une popup : Naviguer", S::Warning), "Naviguer vers une popup");
    check(has("position inconnue : 'partout'", S::Warning), "la position d'une action, inconnue");
    // 1.11.22 : une faute (un parametre retire ou renomme casse ceux qui ouvrent la vue avec lui).
    check(has("param\xC3\xA8tre inconnu de Pop : Vitesse", S::Error), "un param\xC3\xA8tre que la vue ne d\xC3\xA9" "clare pas : une faute");
    check(has("Rien := Absent[0] : variable inexistante : Absent", S::Error), "un param\xC3\xA8tre reli\xC3\xA9 \xC3\xA0 une variable absente");
    check(has("Aide ne d\xC3\xA9" "clare aucun param\xC3\xA8tre", S::Error), "des param\xC3\xA8tres donn\xC3\xA9s \xC3\xA0 une vue qui n'en a pas : une faute");
    check(has("champ de saisie sans variable", S::Error), "un champ de saisie sans variable");
    check(has("minimum au-dessus du maximum", S::Error), "un champ aux bornes invers\xC3\xA9" "es");
    check(has("vue 'Vue_Absente' introuvable", S::Error), "Vue apr\xC3\xA8s connexion introuvable");
    check(has("bouton inconnu : 'Imprimer'", S::Error), "un bouton inconnu de la gestion des utilisateurs");
    check(has("la s\xC3\xA9" "curit\xC3\xA9 est \xC3\xA9teinte", S::Warning), "des objets des utilisateurs sans s\xC3\xA9" "curit\xC3\xA9");
    const auto compiled = compile(p);
    const auto chas = [&](std::string_view text) {
        for (const auto& i : compiled) if (i.severity == S::Error && i.message.find(text) != std::string::npos) return true;
        return false;
    };
    check(chas("titre :"), "Compiler : le titre \xC3\xA0 trous de la popup");
    check(chas("param\xC3\xA8tre Titre :"), "Compiler : un param\xC3\xA8tre calcul\xC3\xA9 illisible");
    check(chas("Consigne_Max +"), "Compiler : une borne en expression, illisible");
    // Les fonctions IHM_ du lot 8 sont connues des scripts.
    Project s;
    s.programs.variables.push_back(hmiVar(s, "Ouvert", "BOOL"));
    s.programs.scripts.push_back(generalScript(s, "Tout",
        "IHM_CHANGER_POPUP('Vue_X');\nIHM_POPUP_PRECEDENTE();\nIHM_CENTRER_POPUP();\nIHM_FERMER_POPUPS();\n"
        "Ouvert := IHM_POPUP_OUVERTE('Vue_X');\nIHM_DECONNECTER();\nOuvert := IHM_NIVEAU() > 2 AND IHM_UTILISATEUR() <> '';"));
    const auto si = generate(s, [](std::string_view) { return false; });
    bool unknownFn = false, viewMissing = false;
    for (const auto& i : si) {
        unknownFn = unknownFn || i.message.find("variable inexistante : IHM_") != std::string::npos;
        viewMissing = viewMissing || i.message.find("vue 'Vue_X' introuvable") != std::string::npos;
    }
    check(!unknownFn, "les fonctions IHM_ du lot 8 ne sont pas prises pour des variables");
    check(viewMissing, "IHM_CHANGER_POPUP('Vue_X') : la vue vis\xC3\xA9" "e est v\xC3\xA9rifi\xC3\xA9" "e");
    // Sans automate, les fonctions standard restent la (SEL, SIN, conversions).
    Project f;
    View fv = makeView(f, "V");
    f.views = {fv};
    f.config.startView = fv.id;
    f.programs.variables.push_back(hmiVar(f, "R", "REAL", "0.0"));
    f.programs.scripts.push_back(generalScript(f, "Calcul", "R := SEL(TRUE, 1.0, 2.0) + SIN(0.0) + INT_TO_REAL(REAL_TO_INT(2.6));"));
    Runtime rf;
    rf.bind(&f, nullptr);
    rf.start(0.0);
    std::string why;
    check(rf.callScript("Calcul", 0.1, &why), "sans automate, SEL / SIN / conversions tournent" + (why.empty() ? std::string{} : " (" + why + ")"));
    near(rf.variable("R")->asReal(), 5.0, "SEL(TRUE, 1, 2) + SIN(0) + INT_TO_REAL(REAL_TO_INT(2.6)) = 2 + 0 + 3");
}

void exemplesLot8() {
    std::printf("lot 8 : les exemples anim\xC3\xA9s de la biblioth\xC3\xA8que\n");
    std::size_t withExample = 0, clean = 0;
    std::string dirty;
    for (const auto k : kPlaceableKinds) {
        auto ex = examples::exampleFor(k);
        if (!ex) continue;
        ++withExample;
        Runtime rt;
        rt.bind(&ex->project, nullptr);
        Runtime::Hooks h;
        h.userRequest = [&](const UserRequest& rq) {
            if (auto* u = ex->project.user(rq.user)) {
                if (rq.op == "activer") u->enabled = rq.enabled;
                else { u->salt = rq.salt; u->passwordHash = rq.hash; }
            }
        };
        rt.setHooks(h);
        rt.start(0.0);
        double played = 0;
        std::size_t errors = 0, steps = 0;
        std::map<double, std::string> probes;
        for (double t = 0.05; t <= ex->period + 1e-9; t += 0.05) {
            rt.tick(t);
            steps += examples::play(*ex, rt, played, t, t);
            played = t;
            LiveView lv;
            lv.bind(*rt.composedView(rt.currentView()));
            std::vector<LiveValue> vals;
            (void)lv.evaluate(rt.environment(), &vals, rt.viewScope(rt.currentView()), t);
            for (const auto& v : vals) errors += v.error;
            // Ce que le scenario doit avoir fait, a quelques instants choisis.
            const std::string key(kindKey(k));
            if (key == "Button" && std::fabs(t - 1.5) < 0.025) probes[1.5] = rt.variable("Marche") && rt.variable("Marche")->isTruthy() ? "on" : "off";
            if (key == "Button" && std::fabs(t - 4.0) < 0.025) probes[4.0] = rt.variable("Marche") && rt.variable("Marche")->isTruthy() ? "on" : "off";
            if (key == "RecipeManager" && std::fabs(t - 2.5) < 0.025) probes[2.5] = rt.variable("Seuil_A") ? formatValue(*rt.variable("Seuil_A")) : "?";
            if (key == "InputField" && std::fabs(t - 5.0) < 0.025) probes[5.0] = rt.variable("Consigne") ? formatValue(*rt.variable("Consigne"), "0.0") : "?";
            if (key == "InputField" && std::fabs(t - 9.0) < 0.025) probes[9.0] = rt.variable("Consigne") ? formatValue(*rt.variable("Consigne"), "0.0") : "?";
            if (key == "LoginPanel" && std::fabs(t - 4.0) < 0.025) probes[4.0] = rt.userLogin();
            if (key == "LogoutButton" && std::fabs(t - 2.5) < 0.025) probes[2.5] = rt.userLogin();
            if (key == "LogoutButton" && std::fabs(t - 4.0) < 0.025) probes[4.0] = rt.userLogin();
            if (key == "UserManager" && std::fabs(t - 3.0) < 0.025) probes[3.0] = ex->project.security.users[3].enabled ? "actif" : "inactif";
            if (key == "UserManager" && std::fabs(t - 6.0) < 0.025) probes[6.0] = ex->project.security.users[3].enabled ? "actif" : "inactif";
            if (key == "PasswordChange" && std::fabs(t - 8.5) < 0.025)
                probes[8.5] = passwordMatches(ex->project.security.users[0].salt, ex->project.security.users[0].passwordHash, "Abc2027") ? "change" : "ancien";
        }
        for (const auto& e : rt.journal()) errors += e.kind == "Erreur";
        if (errors == 0) ++clean;
        else dirty += std::string(kindKey(k)) + " ";
        const std::string key(kindKey(k));
        if (key == "Button") check(probes[1.5] == "on" && probes[4.0] == "off", "Bouton : le clic bascule Marche, le second la remet");
        if (key == "RecipeManager") same(probes[2.5], "9", "Gestion de recettes : le jeu Argon appliqu\xC3\xA9 (Seuil_A = 9)");
        if (key == "InputField") check(probes[5.0] == "18.5" && probes[9.0] == "18.5", "Champ de saisie : 18,5 \xC3\xA9" "crit, 45 refus\xC3\xA9 (hors bornes)");
        if (key == "LoginPanel") same(probes[4.0], "operateur", "Connexion : operateur connect\xC3\xA9 par son mot de passe");
        if (key == "LogoutButton") check(probes[2.5] == "operateur" && probes[4.0].empty(), "D\xC3\xA9" "connexion : confirm\xC3\xA9" "e au second clic");
        if (key == "UserManager") check(probes[3.0] == "inactif" && probes[6.0] == "actif", "Gestion des utilisateurs : stagiaire d\xC3\xA9sactiv\xC3\xA9 puis r\xC3\xA9" "activ\xC3\xA9");
        if (key == "PasswordChange") same(probes[8.5], "change", "Changer le mot de passe : la seconde tentative change le mot de passe");
        if (!ex->steps.empty()) check(steps == ex->steps.size(), std::string(kindKey(k)) + " : chaque geste du sc\xC3\xA9nario est jou\xC3\xA9");
    }
    check(withExample == std::size(kPlaceableKinds), "chaque objet de la biblioth\xC3\xA8que a son exemple (" + std::to_string(withExample) + ")");
    check(clean == withExample, "aucun exemple ne produit d'erreur" + (dirty.empty() ? std::string{} : " (" + dirty + ")"));
    check(!examples::exampleFor(Kind::Group).has_value(), "un groupe n'a pas d'exemple (il na\xC3\xAEt d'une s\xC3\xA9lection)");
}

void aideObjetsLot8() {
    std::printf("lot 8 : l'aide de chaque objet (guide, F1, param\xC3\xA8tres)\n");
    namespace g = hmi::guide;
    const std::set<std::string> common = {"x", "y", "w", "h", "rot", "flipH", "flipV", "visible", "opacity", "variable", "refresh", "access"};
    std::size_t pages = 0, documented = 0, keys = 0;
    std::string missing;
    for (const auto k : kPlaceableKinds) {
        const auto* t = g::topicForKind(kindKey(k));
        if (!t) { missing += std::string(kindKey(k)) + " (pas de page) "; continue; }
        ++pages;
        const auto o = makeObject(k, 1, "X", 0, 0, 1);
        for (const auto& prop : o.props) {
            if (common.count(prop.key)) continue;
            ++keys;
            bool found = false;
            for (const auto& prm : t->params) found = found || prm.key == prop.key;
            if (found) ++documented;
            else missing += std::string(kindKey(k)) + "." + prop.key + " ";
        }
        check(!t->example.empty(), t->title + " : la l\xC3\xA9gende de son exemple anim\xC3\xA9");
    }
    check(pages == std::size(kPlaceableKinds), "chaque objet a sa page (" + std::to_string(pages) + ")");
    check(documented == keys, "chaque param\xC3\xA8tre de chaque objet est d\xC3\xA9" "crit (" + std::to_string(documented) + " / "
                                  + std::to_string(keys) + (missing.empty() ? std::string{} : " ; manquent : " + missing) + ")");
    const auto* communs = g::topicForKind("*");
    bool allCommon = communs != nullptr;
    for (const auto& key : common) {
        bool found = false;
        if (communs) for (const auto& prm : communs->params) found = found || prm.key == key;
        allCommon = allCommon && found;
    }
    check(allCommon, "les param\xC3\xA8tres communs \xC3\xA0 tous les objets ont leur page");
    check(g::paramHelp("InputField", "keyboard").find("clavier") != std::string::npos, "paramHelp : celui de l'objet (Champ de saisie, keyboard)");
    check(g::paramHelp("Button", "opacity").find("opaque") != std::string::npos, "paramHelp : sinon celui des param\xC3\xA8tres communs");
    check(g::paramHelp("Button", "inconnue").empty(), "paramHelp : rien sur une cl\xC3\xA9 inconnue");
    same(g::topicForWord("IHM_CHANGER_POPUP"), "popups", "F1 sur IHM_CHANGER_POPUP : Les popups");
    same(g::topicForWord("IHM_NIVEAU"), "reference", "F1 sur IHM_NIVEAU : la r\xC3\xA9" "f\xC3\xA9rence IHM_");
    const auto* t = g::topicForKind("InputField");
    bool paramTable = false;
    if (t)
        for (const auto& b : t->blocks)
            paramTable = paramTable || (b.kind == g::BlockKind::Table && b.text.rfind("Param\xC3\xA8tre\tPar d\xC3\xA9" "faut\tCe qu'il r\xC3\xA8gle", 0) == 0);
    check(paramTable, "la page d'un objet porte le tableau de ses param\xC3\xA8tres (Param\xC3\xA8tre, Par d\xC3\xA9" "faut, Ce qu'il r\xC3\xA8gle)");
    const auto hits = g::search("clavier virtuel");
    check(!hits.empty() && (hits.front().key == "objet-champ-de-saisie" || hits.front().key == "objet-connexion"),
          "chercher \xC2\xAB clavier virtuel \xC2\xBB : la page du champ de saisie (ou de la connexion)");
}

// ------------------------------------------------ lot 9 : commandes et afficheurs --
//  Les petits langages (choix, etats, zones, dates, plages), la geometrie des
//  parties cliquables, les 7 segments, le compteur horaire et le code QR
//  (compare a une reference : qrcodegen de Nayuki, meme version, meme masque).
namespace {

// FNV-1a 64 bits des modules ("0" / "1", ligne par ligne) : une grille en un nombre.
std::uint64_t qrHash(const QrCode& q) {
    std::uint64_t h = 0xcbf29ce484222325ULL;
    for (int y = 0; y < q.size; ++y)
        for (int x = 0; x < q.size; ++x) {
            h ^= static_cast<unsigned char>(q.at(x, y) ? '1' : '0');
            h *= 0x100000001b3ULL;
        }
    return h;
}
std::string qrRows(const QrCode& q) {
    std::string out;
    for (int y = 0; y < q.size; ++y) {
        for (int x = 0; x < q.size; ++x) out += q.at(x, y) ? '1' : '0';
        out += '\n';
    }
    return out;
}
// La distance du centre d'un cercle a une boite (0 : dedans).
double distanceToBox(double cx, double cy, const Box& b) {
    const double dx = std::max({b.x - cx, 0.0, cx - b.right()});
    const double dy = std::max({b.y - cy, 0.0, cy - b.bottom()});
    return std::hypot(dx, dy);
}
bool overlaps(const Box& a, const Box& b) {
    return a.x < b.right() - 0.5 && b.x < a.right() - 0.5 && a.y < b.bottom() - 0.5 && b.y < a.bottom() - 0.5;
}
std::string digitsText(const std::vector<SegmentDigit>& d) {
    std::string s;
    for (const auto& x : d) {
        s += x.c;
        if (x.dot) s += '.';
    }
    return s;
}

} // namespace

void controlesLot9() {
    std::printf("lot 9 : commandes et afficheurs - listes, \xC3\xA9tats, zones, dates, plages, 7 segments, code QR\n");
    // ---- les listes et les choix
    {
        const auto items = listItems(" Manu ; ;Arr\xC3\xAAt;Auto ;");
        check(items.size() == 3 && items[0] == "Manu" && items[1] == "Arr\xC3\xAAt" && items[2] == "Auto", "listItems : sans les blancs, sans les vides");
        Object sel = makeObject(Kind::Selector, 1, "S", 0, 0, kNoId);
        sel.set("positions", "Manu;Arr\xC3\xAAt;Auto");
        sel.set("values", "10;;'Auto'");
        const auto ch = choicesOf(sel);
        check(ch.size() == 3 && ch[0].value == "10" && !ch[0].index && ch[1].index && ch[1].value == "1" && ch[2].value == "'Auto'",
              "choicesOf : la valeur donn\xC3\xA9" "e, sinon le rang");
        check(choiceIndexOf(ch, "10") == 0 && choiceIndexOf(ch, "10.0") == 0, "une valeur lue retrouve son choix (10 = 10.0)");
        check(choiceIndexOf(ch, "1") == 1, "... le rang d'un choix sans valeur");
        check(choiceIndexOf(ch, "'auto'") == 2 && choiceIndexOf(ch, "AUTO") == 2, "... un texte, sans casse ni apostrophes");
        check(choiceIndexOf(ch, "Arr\xC3\xAAt") == 1, "... ou le libell\xC3\xA9 (une STRING)");
        check(choiceIndexOf(ch, "7") == -1, "... et -1 sinon");
        const Object combo = makeObject(Kind::ComboBox, 2, "C", 0, 0, kNoId);
        check(choicesOf(combo).size() == 3 && choicesOf(combo)[2].label == "H\xC3\xA9lium", "la liste d\xC3\xA9roulante lit ses \xC3\xA9l\xC3\xA9ments (Azote;Argon;H\xC3\xA9lium)");
        Object radio = makeObject(Kind::RadioGroup, 3, "R", 0, 0, kNoId);
        radio.set("items", "Oui;Non");
        radio.set("values", "TRUE;FALSE");
        check(choiceIndexOf(choicesOf(radio), "TRUE") == 0 && choiceIndexOf(choicesOf(radio), "0") == 1, "TRUE vaut 1, FALSE vaut 0");
    }
    // ---- les etats
    {
        std::string why;
        const auto st = parseStateList("0 = Arr\xC3\xAAt | #4A5261; 1 = Marche|#2ECC71; 2..5 = D\xC3\xA9" "faut | #E5534B | clignote; 'Auto' = Automatique; * = Autre", &why);
        check(why.empty() && st.size() == 5, "parseStateList : cinq \xC3\xA9tats (" + why + ")");
        check(st.size() == 5 && st[1].text == "Marche" && st[1].color == "#2ECC71" && !st[1].blink, "texte|couleur, espaces libres");
        check(st.size() == 5 && st[2].blink && st[2].color == "#E5534B" && st[0].text == "Arr\xC3\xAAt", "... et clignote");
        check(stateIndexOf(st, "0") == 0 && stateIndexOf(st, "1.0") == 1 && stateIndexOf(st, "TRUE") == 1, "un nombre (1.0 = 1 = TRUE)");
        check(stateIndexOf(st, "3.5") == 2 && stateIndexOf(st, "5") == 2 && stateIndexOf(st, "2") == 2, "un intervalle 2..5, bornes comprises");
        check(stateIndexOf(st, "auto") == 3 && stateIndexOf(st, "'Auto'") == 3, "un texte, sans casse ni apostrophes");
        check(stateIndexOf(st, "42") == 4, "* : tout le reste");
        check(stateIndexOf(parseStateList("0 = A; 1 = B"), "7") == -1, "sans * : aucun \xC3\xA9tat (-1)");
        std::string bad;
        (void)parseStateList("0 = A; Marche; 2 = B", &bad);
        check(bad.find("sans") != std::string::npos, "un \xC3\xA9tat sans \xC2\xAB = \xC2\xBB est signal\xC3\xA9 (" + bad + ")");
        std::string bad2;
        (void)parseStateList("2 = B | #123456 | #654321", &bad2);
        check(bad2.find("inconnu") != std::string::npos, "une seconde couleur est signal\xC3\xA9" "e (" + bad2 + ")");
    }
    // ---- les zones
    {
        std::string why;
        const auto z = parseZones("0-60 = #2ECC71; 60..80 = #F2C94C; 100 - 80 = #E5534B; -20--5 = #2F6FD6", &why);
        check(why.empty() && z.size() == 4, "parseZones : quatre zones (" + why + ")");
        if (z.size() == 4) {
            check(z[2].from == 80 && z[2].to == 100, "des bornes \xC3\xA0 l'envers sont remises dans l'ordre");
            check(z[3].from == -20 && z[3].to == -5, "des nombres n\xC3\xA9gatifs (-20--5)");
            check(zoneOf(z, 30) == &z[0] && zoneOf(z, 60) == &z[0] && zoneOf(z, 70) == &z[1] && zoneOf(z, 90) == &z[2],
                  "zoneOf : la premi\xC3\xA8re qui contient la valeur");
            check(zoneOf(z, 150) == nullptr, "hors des zones : aucune");
        }
        std::string bad;
        (void)parseZones("0-60 #2ECC71", &bad);
        check(!bad.empty(), "une zone sans \xC2\xAB = \xC2\xBB est illisible");
    }
    // ---- les valeurs bornees, le potentiometre
    near(snapToStep(42.3, 0, 100, 5), 40, "snapToStep : au pas (42,3 -> 40)");
    near(snapToStep(43, 0, 100, 5), 45, "... au plus pr\xC3\xA8s (43 -> 45)");
    near(snapToStep(130, 0, 100, 1), 100, "... dans les bornes");
    near(snapToStep(0.1 + 0.2, 0, 1, 0.1), 0.3, "... sans 0,30000000000000004", 0);
    near(snapToStep(7, 2, 12, 4), 6, "... le pas compte depuis le minimum (2, 6, 10)");
    near(snapToStep(55, 100, 0, 10), 60, "... des bornes \xC3\xA0 l'envers");
    near(fractionOf(25, 0, 200), 0.125, "fractionOf");
    near(fractionOf(5, 10, 10), 0, "fractionOf : une course vide donne 0");
    near(knobFractionAt(100, 100, 50, 0), 0.5, "potentiom\xC3\xA8tre : en haut, la moiti\xC3\xA9 de la course");
    near(knobFractionAt(100, 100, 0, 50), 45.0 / 270.0, "... \xC3\xA0 gauche, 45\xC2\xB0 apr\xC3\xA8s le d\xC3\xA9part (bas gauche)", 1e-9);
    near(knobFractionAt(100, 100, 100, 50), 225.0 / 270.0, "... \xC3\xA0 droite, 225\xC2\xB0", 1e-9);
    near(knobFractionAt(100, 100, 50 - 30, 50 + 30), 0, "... en bas \xC3\xA0 gauche : le minimum", 1e-9);
    near(knobFractionAt(100, 100, 50 + std::cos(1.4) * 40, 50 + std::sin(1.4) * 40), 1, "le creux du bas, c\xC3\xB4t\xC3\xA9 droit : le maximum");
    near(knobFractionAt(100, 100, 50 + std::cos(1.75) * 40, 50 + std::sin(1.75) * 40), 0, "... c\xC3\xB4t\xC3\xA9 gauche : le minimum");
    // ---- le curseur : la piste, la valeur au bout
    {
        Object sl = makeObject(Kind::Slider, 4, "Sl", 0, 0, kNoId);
        const auto l = sliderLayout(sl, 260, 60);
        check(!l.vertical && l.track.w > 100 && l.value.w > 0 && l.track.right() <= l.value.x, "curseur horizontal : la piste, puis la valeur \xC3\xA0 droite");
        near(sliderFractionAt(sl, 260, 60, l.track.x, 20), 0, "au d\xC3\xA9" "but de la piste : 0");
        near(sliderFractionAt(sl, 260, 60, l.track.x + l.track.w * 0.25, 20), 0.25, "au quart : 0,25", 1e-9);
        near(sliderFractionAt(sl, 260, 60, 1000, 20), 1, "au-del\xC3\xA0 : 1");
        sl.set("orientation", "verticale");
        const auto lv = sliderLayout(sl, 60, 260);
        check(lv.vertical && lv.track.h > 100 && lv.track.bottom() <= lv.value.y, "curseur vertical : la piste, puis la valeur en bas");
        near(sliderFractionAt(sl, 60, 260, 20, lv.track.y), 1, "vertical : le haut vaut le maximum");
    }
    // ---- le selecteur : des libelles qui ne se touchent pas, ni le bouton ; le clic les retrouve
    for (const auto& [w, h, positions] : std::vector<std::tuple<double, double, const char*>>{
             {240, 120, "Manu;Arr\xC3\xAAt;Auto"}, {260, 150, "Manu;Arr\xC3\xAAt;Auto"}, {320, 170, "Arr\xC3\xAAt;Lent;Moyen;Rapide;Maxi"}, {180, 110, "Local;Distance"}}) {
        Object s = makeObject(Kind::Selector, 5, "Sel", 0, 0, kNoId);
        s.set("positions", positions);
        const std::size_t n = choicesOf(s).size();
        const auto l = selectorLayout(s, w, h, n);
        bool inside = true, apart = true, clear = true, found = true;
        for (std::size_t i = 0; i < l.labels.size(); ++i) {
            const auto& b = l.labels[i];
            inside = inside && b.x >= 0 && b.y >= 0 && b.right() <= w + 1e-9 && b.bottom() <= h + 1e-9;
            clear = clear && distanceToBox(l.cx, l.cy, b) >= l.radius;
            for (std::size_t j = i + 1; j < l.labels.size(); ++j) apart = apart && !overlaps(b, l.labels[j]);
            found = found && selectorHit(s, w, h, b.x + b.w / 2, b.y + b.h / 2, n) == "position:" + std::to_string(i);
        }
        const std::string what = std::to_string(static_cast<int>(w)) + " x " + std::to_string(static_cast<int>(h)) + ", "
                               + std::to_string(n) + " positions";
        check(l.rotary && l.labels.size() == n && l.angles.size() == n, "s\xC3\xA9lecteur rotatif (" + what + ") : un libell\xC3\xA9, un angle par position");
        check(inside, "... les libell\xC3\xA9s restent dans l'objet (" + what + ")");
        check(apart, "... ne se chevauchent pas (" + what + ")");
        check(clear, "... ne mordent pas sur le bouton (" + what + ")");
        check(found, "... un clic sur un libell\xC3\xA9 choisit sa position (" + what + ")");
        same(selectorHit(s, w, h, l.cx, l.cy, n), "suivant", "... un clic sur le bouton passe \xC3\xA0 la suivante (" + what + ")");
    }
    {
        Object s = makeObject(Kind::Selector, 6, "Sel", 0, 0, kNoId);
        s.set("style", "boutons");
        const auto l = selectorLayout(s, 300, 50, 3);
        check(!l.rotary && l.labels.size() == 3 && std::fabs(l.labels[0].w - l.labels[2].w) < 1e-9 && l.labels[2].right() <= 300 + 1e-9,
              "style boutons : trois segments \xC3\xA9gaux");
        same(selectorHit(s, 300, 50, 150, 25, 3), "position:1", "... le clic au milieu : la deuxi\xC3\xA8me position");
        same(selectorHit(s, 300, 50, 150, 80, 3), "", "... dehors : rien");
    }
    // ---- les boutons radio, la liste deroulante
    {
        Object r = makeObject(Kind::RadioGroup, 7, "R", 0, 0, kNoId);
        same(radioHit(r, 240, 120, 30, 60, 3), "option:1", "boutons radio verticaux : la deuxi\xC3\xA8me ligne");
        r.set("orientation", "horizontale");
        same(radioHit(r, 240, 40, 200, 20, 3), "option:2", "... horizontaux : la troisi\xC3\xA8me colonne");
        Object c = makeObject(Kind::ComboBox, 8, "C", 0, 0, kNoId);
        c.setNumber("maxVisible", 4);
        const auto l = comboLayout(c, 200, 36, 10, 8);
        check(l.rows.size() == 4 && l.first == 6 && l.up.w > 0 && l.down.w > 0 && l.list.y > 36, "liste ouverte : quatre lignes, sous l'objet, avec ses fl\xC3\xA8" "ches ; la premi\xC3\xA8re ramen\xC3\xA9" "e \xC3\xA0 6");
        same(comboHit(c, 200, 36, 100, l.rows[0].y + 2, 10, true, 3), "choix:3", "... la premi\xC3\xA8re ligne montr\xC3\xA9" "e est le choix 3");
        same(comboHit(c, 200, 36, 100, l.up.y + 2, 10, true, 3), "defiler:-1", "... la bande du haut fait remonter");
        same(comboHit(c, 200, 36, 100, 18, 10, false, 0), "ouvrir", "ferm\xC3\xA9" "e : un clic sur la bo\xC3\xAEte l'ouvre");
        same(comboHit(c, 200, 36, 100, 60, 10, false, 0), "", "... sous la bo\xC3\xAEte ferm\xC3\xA9" "e : rien");
        const auto few = comboLayout(c, 200, 36, 3, 0);
        check(few.rows.size() == 3 && few.up.w == 0, "trois \xC3\xA9l\xC3\xA9ments : pas de fl\xC3\xA8" "ches");
    }
    // ---- la date et l'heure
    {
        check(daysInMonth(2024, 2) == 29 && daysInMonth(2026, 2) == 28 && daysInMonth(1900, 2) == 28 && daysInMonth(2000, 2) == 29
                  && daysInMonth(2026, 4) == 30,
              "daysInMonth : bissextiles comprises (2024, 2000, pas 1900)");
        const DateTime d{2026, 1, 31, 23, 59, 30};
        check(stepDateTime(d, "mois", 1) == DateTime{2026, 2, 28, 23, 59, 30}, "31 janvier + 1 mois : le 28 f\xC3\xA9vrier (dernier jour)");
        check(stepDateTime(d, "minute", 1) == DateTime{2026, 1, 31, 23, 0, 30}, "une minute tourne en boucle (59 -> 0), l'heure ne bouge pas");
        check(stepDateTime(DateTime{2026, 1, 1, 0, 0, 0}, "jour", -1).day == 31, "le 1er - 1 jour : le 31");
        check(stepDateTime(DateTime{2099, 5, 1, 0, 0, 0}, "annee", 1).year == 2099, "l'ann\xC3\xA9" "e reste entre 1970 et 2099");
        const DateTime t{2026, 9, 23, 14, 30, 5};
        same(isoDateTime(t, "date et heure", false), "2026-09-23 14:30", "isoDateTime");
        same(isoDateTime(t, "date et heure", true), "2026-09-23 14:30:05", "... avec les secondes");
        same(isoDateTime(t, "date", false) + "|" + isoDateTime(t, "heure", false), "2026-09-23|14:30", "... la date seule, l'heure seule");
        same(frenchDateTime(t, "date et heure", false), "23/09/2026 14:30", "frenchDateTime");
        DateTime r{2020, 1, 1, 8, 0, 0};
        check(parseDateTime("2026-09-23 14:30", r) && r == DateTime{2026, 9, 23, 14, 30, 0}, "parseDateTime : 2026-09-23 14:30");
        check(parseDateTime("24/12/2026", r) && r == DateTime{2026, 12, 24, 14, 30, 0}, "... une date seule garde l'heure");
        check(parseDateTime("07:05:09", r) && r == DateTime{2026, 12, 24, 7, 5, 9}, "... une heure seule garde la date");
        check(parseDateTime("2026-09-23T08:15", r) && r.hour == 8 && r.minute == 15, "... le T de la norme ISO");
        DateTime keep = r;
        check(!parseDateTime("2026-02-30", keep) && !parseDateTime("25:00", keep) && !parseDateTime("demain", keep) && keep == r,
              "... refuse le 30 f\xC3\xA9vrier, 25:00, un mot - sans rien changer");
        const double e = epochFromDateTime(t);
        check(dateTimeFromEpoch(e) == t, "epochFromDateTime / dateTimeFromEpoch : aller-retour");
        check(weekdayFromEpoch(epochFromDateTime(DateTime{2026, 9, 23, 12, 0, 0})) == 2, "le 23 septembre 2026 est un mercredi (2)");
    }
    // ---- le programmateur horaire
    {
        check(resolutionMinutes("1 h") == 60 && resolutionMinutes("30 min") == 30 && resolutionMinutes("15 min") == 15 && resolutionMinutes("?") == 30,
              "resolutionMinutes : 1 h, 30 min, 15 min (30 sinon)");
        WeekSchedule ws;
        std::string why;
        const std::string text = "Lu-Ve=07:00-12:00,13:30-17:00; Sa=08:00-12:00";
        check(parseSchedule(text, 30, ws, &why), "parseSchedule : " + text + (why.empty() ? std::string{} : " (" + why + ")"));
        check(scheduleOn(ws, 0, 7 * 60) && !scheduleOn(ws, 0, 12 * 60) && !scheduleOn(ws, 0, 13 * 60 + 29) && scheduleOn(ws, 0, 13 * 60 + 30),
              "... lundi : 7 h dedans, midi dehors, 13 h 29 dehors, 13 h 30 dedans");
        check(scheduleOn(ws, 5, 9 * 60) && !scheduleOn(ws, 6, 9 * 60) && !scheduleOn(ws, 5, 14 * 60), "... samedi matin seulement, rien le dimanche");
        same(formatSchedule(ws), text, "formatSchedule : l'aller-retour, les jours pareils group\xC3\xA9s");
        WeekSchedule wrap;
        check(parseSchedule("Ve-Lu=10:00-11:00", 60, wrap) && scheduleOn(wrap, 4, 600) && scheduleOn(wrap, 6, 600) && scheduleOn(wrap, 0, 600)
                  && !scheduleOn(wrap, 1, 600),
              "Ve-Lu : du vendredi au lundi, en passant par le week-end");
        WeekSchedule all;
        check(parseSchedule("*=00:00-24:00", 15, all) && formatSchedule(all) == "Lu-Di=00:00-24:00" && all.slots() == 96,
              "* : tous les jours ; 24:00 ; 96 cases de 15 min");
        std::string e1, e2, e3;
        WeekSchedule dummy;
        check(!parseSchedule("Xy=07:00-08:00", 30, dummy, &e1) && e1.find("inconnu") != std::string::npos, "un jour inconnu (" + e1 + ")");
        check(!parseSchedule("Lu=08:00-07:00", 30, dummy, &e2) && e2.find("illisible") != std::string::npos, "une plage \xC3\xA0 l'envers (" + e2 + ")");
        check(!parseSchedule("Lu 07:00-08:00", 30, dummy, &e3) && e3.find("=") != std::string::npos, "une plage sans = (" + e3 + ")");
        Object prog = makeObject(Kind::WeeklySchedule, 9, "P", 0, 0, kNoId);
        const auto l = scheduleLayout(prog, 400, 200, 30);
        const double cx = l.grid.x + l.cellW * 17.5, cy = l.grid.y + l.cellH * 2.5;
        same(scheduleHit(prog, 400, 200, cx, cy, 30), "case:2,17", "un clic dans la grille : mercredi, 17e case");
        same(scheduleHit(prog, 400, 200, 4, cy, 30), "jour:2", "... sur le nom du jour : tout le jour");
        same(scheduleHit(prog, 400, 200, cx, 4, 30), "heure:17", "... sur l'heure : toute la colonne");
    }
    // ---- les 7 segments, le compteur horaire
    {
        check(segmentsOf('8') == 0x7F && segmentsOf('1') == 0x06 && segmentsOf('-') == 0x40 && segmentsOf(' ') == 0 && segmentsOf('E') == 0x79,
              "segmentsOf : 8, 1, -, blanc, E");
        same(digitsText(sevenSegmentDigits(12.5, 4, 1, false, true)), " 12.5", "12,5 sur 4 chiffres dont 1 d\xC3\xA9" "cimale");
        same(digitsText(sevenSegmentDigits(-3.2, 4, 1, false, true)), " -3.2", "-3,2 : le signe contre le nombre");
        same(digitsText(sevenSegmentDigits(-3.2, 4, 1, true, true)), "-03.2", "... avec les z\xC3\xA9ros de t\xC3\xAAte : le signe devant");
        same(digitsText(sevenSegmentDigits(7, 3, 0, true, true)), "007", "7 avec les z\xC3\xA9ros de t\xC3\xAAte");
        same(digitsText(sevenSegmentDigits(12345, 4, 0, false, true)), "----", "trop grand : des tirets");
        same(digitsText(sevenSegmentDigits(1, 3, 0, false, false)), "---", "une valeur illisible : des tirets");
        same(digitsText(sevenSegmentDigits(-0.04, 3, 1, false, true)), " 0.0", "-0,04 arrondi : pas de -0,0");
        same(digitsText(sevenSegmentDigits(5, 2, 5, false, true)), "5.0", "plus de d\xC3\xA9" "cimales que de chiffres : ramen\xC3\xA9 \xC3\xA0 1 (2 chiffres : 5.0)");
        same(formatRunTime(3725, "h:mm:ss"), "1:02:05", "formatRunTime h:mm:ss");
        same(formatRunTime(450000, "h:mm:ss"), "125:00:00", "... au-del\xC3\xA0 de 99 heures");
        same(formatRunTime(5 * 86400 + 5 * 3600 + 3 * 60 + 59, "jours"), "5 j 05 h 03 min", "... en jours");
        same(formatRunTime(4500, "heures"), "1.25 h", "... en heures");
        same(formatRunTime(-5, "h:mm:ss"), "0:00:00", "... jamais n\xC3\xA9gatif");
    }
    // ---- le code QR : comme qrcodegen (Nayuki), module pour module
    {
        check(qrCapacity('L') == 271 && qrCapacity('M') == 213 && qrCapacity('Q') == 151 && qrCapacity('H') == 119,
              "qrCapacity : 271 / 213 / 151 / 119 octets en version 10");
        const auto hello = encodeQr("HELLO WORLD", 'M');
        const std::string helloRef =
            "111111101100101111111\n100000100001001000001\n101110100101001011101\n101110101001001011101\n"
            "101110101110101011101\n100000101001001000001\n111111101010101111111\n000000001001100000000\n"
            "100010111111011111001\n000100001011100001111\n001111110011011010010\n111110001100010000000\n"
            "111110101010101100110\n000000001010111101011\n111111101110101011010\n100000100101110110011\n"
            "101110101101011000110\n101110100100100011011\n101110100111000111000\n100000100001010000000\n"
            "111111101111111110101\n";
        check(hello.ok() && hello.version == 1 && hello.size == 21 && hello.mask == 4, "HELLO WORLD en M : version 1, 21 x 21, masque 4");
        same(qrRows(hello), helloRef, "... module pour module, la grille de r\xC3\xA9" "f\xC3\xA9rence");
        const auto temp = encodeQr("Temp\xC3\xA9rature : 21,5 \xC2\xB0" "C", 'M');
        const std::string tempRef =
            "1111111010010010101111111\n1000001000010010101000001\n1011101010101111101011101\n1011101001001100101011101\n"
            "1011101000100100101011101\n1000001010110010001000001\n1111111010101010101111111\n0000000000010011000000000\n"
            "1010001101001011000100101\n1001100111100001011101101\n0010001101111111101110101\n1010000100001100010101010\n"
            "1100101111111101101000001\n0101110101101001011100001\n1111011001101011111011101\n0001110011111101001001100\n"
            "1100111000100010111111101\n0000000011100011100010010\n1111111011010110101010001\n1000001001100000100010111\n"
            "1011101001111101111111001\n1011101000101000010010110\n1011101010001011110010111\n1000001000011010110011000\n"
            "1111111011101111101110001\n";
        check(temp.ok() && temp.version == 2 && temp.mask == 1, "un texte accentu\xC3\xA9 (UTF-8) en M : version 2, masque 1");
        same(qrRows(temp), tempRef, "... module pour module");
        struct Ref {
            std::string text;
            char level;
            int version, mask;
            std::uint64_t hash;
        };
        const std::vector<Ref> refs = {
            {"Vanne V12 : ouverte", 'H', 3, 2, 0x07B3364846E40342ULL},
            {"https://example.com/pompe/P3", 'L', 2, 6, 0x2E09EF4AD29193E9ULL},
            {std::string(100, 'x'), 'M', 6, 3, 0x5F79FBAF41A33CAFULL},
            {[] { std::string s; for (int i = 0; i < 8; ++i) s += "0123456789"; return s; }(), 'Q', 7, 2, 0xC084DF67CA9E72FBULL},
            {std::string(213, 'z'), 'M', 10, 1, 0x08A05B8B23AB3B32ULL},
            {std::string(271, 'w'), 'L', 10, 4, 0xC8BF3C19F7C56F41ULL},
            {"", 'M', 1, 3, 0x27F4A3A3DC113261ULL},
        };
        for (const auto& r : refs) {
            const auto q = encodeQr(r.text, r.level);
            const std::string label = (r.text.size() > 20 ? std::to_string(r.text.size()) + " octets" : "'" + r.text + "'") + " en " + r.level;
            check(q.version == r.version && q.mask == r.mask,
                  label + " : version " + std::to_string(r.version) + ", masque " + std::to_string(r.mask) + " (obtenu " + std::to_string(q.version)
                      + ", " + std::to_string(q.mask) + ")");
            check(qrHash(q) == r.hash, label + " : la grille de r\xC3\xA9" "f\xC3\xA9rence");
        }
        const auto tooLong = encodeQr(std::string(214, 'z'), 'M');
        check(!tooLong.ok() && !tooLong.error.empty(), "214 octets en M : trop long, et dit pourquoi (" + tooLong.error + ")");
        check(encodeQr(std::string(214, 'z'), 'L').version == 9, "... en L, \xC3\xA7" "a passe (version 9)");
        check(!encodeQr("abc", 'X').ok(), "un niveau inconnu : rien");
        check(encodeQr("A", 'M', -1, 5).version == 5, "une version minimale impos\xC3\xA9" "e");
        check(encodeQr("HELLO WORLD", 'M', 6).mask == 6 && encodeQr("HELLO WORLD", 'M', 6).ok(), "un masque impos\xC3\xA9");
        bool timing = true;
        for (int i = 8; i < hello.size - 8; ++i) timing = timing && hello.at(i, 6) == (i % 2 == 0) && hello.at(6, i) == (i % 2 == 0);
        check(timing && hello.at(8, hello.size - 8), "les lignes de synchronisation alternent ; le module sombre fixe est l\xC3\xA0");
    }
}

// ------------------------------------------------------ lot 9 : les commandes en marche --
void commandesLot9() {
    std::printf("lot 9 : les commandes en marche (impulsion, bascules, choix, glisser, date, programmateur, confirmation)\n");
    Project p;
    View v = makeView(p, "Commandes");
    for (const auto& [n, t, i] : std::vector<std::tuple<const char*, const char*, const char*>>{
             {"Impulsion", "BOOL", "FALSE"}, {"Inverse", "BOOL", "TRUE"}, {"Pompe", "BOOL", "FALSE"}, {"Coche", "BOOL", "FALSE"},
             {"Lampe_1", "BOOL", "FALSE"}, {"Lampe_2", "BOOL", "FALSE"}, {"Lampe_3", "BOOL", "FALSE"}, {"Mode", "INT", "0"},
             {"Gaz", "STRING", "''"}, {"Gaz_Code", "STRING", "''"}, {"Rang", "INT", "0"}, {"Vitesse", "INT", "0"},
             {"Debit", "REAL", "0.0"}, {"Consigne", "REAL", "0.0"}, {"Niveau", "REAL", "50.0"},
             {"Echeance", "STRING", "'2026-09-23 14:30'"}, {"Heure", "TIME", "T#0s"}, {"Plages", "STRING", "''"},
             {"Plages_2", "STRING", "''"}, {"Sortie", "BOOL", "FALSE"}, {"Marche", "BOOL", "FALSE"}, {"Compteur", "TIME", "T#0s"},
             {"Heures", "REAL", "0.0"}, {"Moteur", "BOOL", "TRUE"}, {"Purge", "INT", "0"}})
        p.programs.variables.push_back(hmiVar(p, n, t, i));
    const auto put = [&](Kind k, const char* name, const char* var, double x, double y) {
        const Id id = edit::add(p, v, k, x, y);
        v.object(id)->name = name;
        v.object(id)->set("variable", var);
        return id;
    };
    const Id impulsion = put(Kind::PushButton, "Impulsion", "Impulsion", 10, 10);
    const Id inverse = put(Kind::PushButton, "Inverse", "Inverse", 10, 60);
    v.object(inverse)->setFlag("inverted", true);
    const Id pompe = put(Kind::Switch, "Pompe", "Pompe", 10, 110);
    const Id coche = put(Kind::CheckBox, "Coche", "Coche", 10, 160);
    const Id basculer = put(Kind::IlluminatedButton, "Basculer", "Lampe_1", 10, 210);
    const Id pulse = put(Kind::IlluminatedButton, "Pulse", "Lampe_2", 10, 270);
    v.object(pulse)->set("operation", "impulsion");
    const Id un = put(Kind::IlluminatedButton, "Un", "Lampe_3", 10, 330);
    v.object(un)->set("operation", "mettre \xC3\xA0 1");
    const Id zero = put(Kind::IlluminatedButton, "Zero", "Lampe_3", 10, 390);
    v.object(zero)->set("operation", "mettre \xC3\xA0 0");
    const Id mode = put(Kind::Selector, "Mode", "Mode", 200, 10);
    const Id gaz = put(Kind::RadioGroup, "Gaz", "Gaz", 200, 150);
    v.object(gaz)->set("items", "Azote;Argon");
    const Id code = put(Kind::RadioGroup, "Gaz_Code", "Gaz_Code", 200, 280);
    v.object(code)->set("items", "Azote;Argon");
    v.object(code)->set("values", "'N2';'AR'");
    const Id liste = put(Kind::ComboBox, "Liste", "Rang", 200, 400);
    v.object(liste)->set("items", "A;B;C;D;E;F;G;H;I;J");
    v.object(liste)->setNumber("maxVisible", 4);
    const Id vitesse = put(Kind::Slider, "Vitesse", "Vitesse", 500, 10);
    v.object(vitesse)->setNumber("step", 5);
    const Id debit = put(Kind::Slider, "Debit", "Debit", 500, 80);
    v.object(debit)->setNumber("max", 10);
    v.object(debit)->setNumber("step", 0.5);
    v.object(debit)->setFlag("continuous", true);
    const Id consigne = put(Kind::Knob, "Consigne", "Consigne", 500, 150);
    v.object(consigne)->setNumber("min", 20);
    v.object(consigne)->setExpr("max", "Niveau * 2");
    const Id echeance = put(Kind::DateTimePicker, "Echeance", "Echeance", 500, 300);
    const Id heure = put(Kind::DateTimePicker, "Heure", "Heure", 500, 420);
    v.object(heure)->set("fields", "heure");
    const Id prog = put(Kind::WeeklySchedule, "Prog", "Plages", 900, 10);
    v.object(prog)->set("schedule", "");
    v.object(prog)->set("output", "Sortie");
    const Id prog2 = put(Kind::WeeklySchedule, "Prog_2", "Plages_2", 900, 260);
    v.object(prog2)->set("schedule", "");
    const Id compteur = put(Kind::HourMeter, "Compteur", "Compteur", 900, 500);
    v.object(compteur)->set("condition", "Marche");
    const Id heures = put(Kind::HourMeter, "Heures", "Heures", 900, 580);
    const Id tendance = edit::add(p, v, Kind::TrendArrow, 900, 660);
    v.object(tendance)->name = "Tendance";
    v.object(tendance)->set("variable", "Niveau");
    v.object(tendance)->setNumber("window", 2);
    auto& arret = addButton(p, v, "Btn_Arret", 1200, 10);
    arret.set("confirmMode", "second clic");
    arret.actions.push_back(act(Trigger::Click, Operation::Reset, "Moteur"));
    auto& purge = addButton(p, v, "Btn_Purge", 1200, 80);
    purge.set("confirmMode", "maintien");
    purge.setNumber("holdMs", 1000);
    purge.actions.push_back(act(Trigger::Click, Operation::Increment, "Purge", "1"));
    const Id arretId = arret.id, purgeId = purge.id;
    const Id sansVar = put(Kind::Switch, "Sans_Variable", "", 1200, 150);
    p.views = {v};
    p.config.startView = v.id;
    Runtime rt;
    rt.bind(&p, nullptr);
    rt.start(0.0);
    const auto b = [&](const char* n) { return rt.variable(n) && rt.variable(n)->isTruthy(); };
    const auto num = [&](const char* n) { return rt.variable(n) ? rt.variable(n)->asReal() : -1.0; };
    const auto txt = [&](const char* n) { return rt.variable(n) ? rt.variable(n)->asString() : std::string("?"); };
    const auto clic = [&](Id id, double t) {
        rt.press(id, t);
        rt.release(id, t + 0.05, true);
    };

    // ---- l'impulsion : vraie a l'appui, fausse au relachement (meme dehors)
    rt.press(impulsion, 0.1);
    check(b("Impulsion"), "bouton \xC3\xA0 impulsion : vrai \xC3\xA0 l'appui");
    rt.release(impulsion, 0.4, true);
    check(!b("Impulsion"), "... faux au rel\xC3\xA2" "chement");
    rt.press(impulsion, 0.5);
    rt.release(impulsion, 0.6, false);
    check(!b("Impulsion"), "... rel\xC3\xA2" "ch\xC3\xA9 dehors, il retombe aussi");
    rt.press(inverse, 0.7);
    check(!b("Inverse"), "invers\xC3\xA9 : faux \xC3\xA0 l'appui");
    rt.release(inverse, 0.8, true);
    check(b("Inverse"), "... vrai au repos");
    // ---- les bascules
    clic(pompe, 1.0);
    check(b("Pompe"), "interrupteur : un clic le met en marche");
    clic(pompe, 1.2);
    check(!b("Pompe"), "... un second l'arr\xC3\xAAte");
    rt.press(pompe, 1.4);
    rt.release(pompe, 1.5, false);
    check(!b("Pompe"), "... rel\xC3\xA2" "ch\xC3\xA9 dehors : rien");
    clic(coche, 1.6);
    check(b("Coche"), "case \xC3\xA0 cocher : un clic la coche");
    check(journalHas(rt, "Action", "Coche = TRUE"), "... et le journal le dit");
    // ---- le bouton lumineux : ses operations
    clic(basculer, 2.0);
    check(b("Lampe_1"), "bouton lumineux, basculer : allum\xC3\xA9");
    clic(basculer, 2.1);
    check(!b("Lampe_1"), "... puis \xC3\xA9teint");
    rt.press(pulse, 2.2);
    check(b("Lampe_2"), "impulsion : vrai \xC3\xA0 l'appui");
    rt.release(pulse, 2.3, true);
    check(!b("Lampe_2"), "... faux au rel\xC3\xA2" "chement");
    clic(un, 2.4);
    clic(un, 2.5);
    check(b("Lampe_3"), "mettre \xC3\xA0 1 : vrai, et le reste");
    clic(zero, 2.6);
    check(!b("Lampe_3"), "mettre \xC3\xA0 0 : faux");
    // ---- les choix
    rt.objectPart(mode, "position:2", 3.0);
    near(num("Mode"), 2, "s\xC3\xA9lecteur : la position 2 \xC3\xA9" "crit son rang");
    check(journalHas(rt, "Action", "Mode = 2 (Auto)"), "... le journal dit la valeur et le libell\xC3\xA9");
    rt.objectPart(mode, "suivant", 3.1);
    near(num("Mode"), 0, "... le bouton rotatif passe \xC3\xA0 la suivante (apr\xC3\xA8s la derni\xC3\xA8re : la premi\xC3\xA8re)");
    rt.objectPart(gaz, "option:1", 3.2);
    same(txt("Gaz"), "Argon", "boutons radio sur une STRING, sans valeurs : le libell\xC3\xA9");
    rt.objectPart(code, "option:0", 3.3);
    same(txt("Gaz_Code"), "N2", "... avec des valeurs : 'N2'");
    rt.objectPart(liste, "ouvrir", 3.4);
    std::size_t first = 99;
    check(rt.comboOpen(liste, &first) && first == 0, "liste d\xC3\xA9roulante : un clic l'ouvre, en haut");
    for (int i = 0; i < 10; ++i) rt.objectPart(liste, "defiler:1", 3.5);
    check(rt.comboOpen(liste, &first) && first == 6, "... elle d\xC3\xA9" "file jusqu'aux derni\xC3\xA8res lignes (6 sur 10, 4 visibles)");
    rt.objectPart(liste, "choix:7", 3.6);
    check(num("Rang") == 7 && !rt.comboOpen(liste), "... un choix \xC3\xA9" "crit son rang (7) et la referme");
    rt.objectPart(liste, "ouvrir", 3.7);
    check(rt.comboOpen(liste, &first) && first == 4, "rouverte : le choix en vue (premi\xC3\xA8re ligne 4)");
    rt.objectPart(liste, "fermer", 3.8);
    // ---- glisser
    rt.dragValue(vitesse, 0.43, false, 4.0);
    check(rt.dragPreview(vitesse) && std::fabs(*rt.dragPreview(vitesse) - 45) < 1e-9 && num("Vitesse") == 0,
          "curseur : en glissant, la poign\xC3\xA9" "e montre 45 (au pas de 5), la variable attend");
    rt.dragValue(vitesse, 0.43, true, 4.1);
    check(num("Vitesse") == 45 && rt.variable("Vitesse")->type() == sim::Type::Int && !rt.dragPreview(vitesse),
          "... l\xC3\xA2" "ch\xC3\xA9 : 45 \xC3\xA9" "crit dans l'INT");
    rt.dragValue(debit, 0.26, false, 4.2);
    near(num("Debit"), 2.5, "\xC2\xAB \xC3\x89" "crire en glissant \xC2\xBB : \xC3\xA9" "crit pendant le geste (2,6 -> 2,5 au pas de 0,5)");
    rt.dragValue(consigne, 1.0, true, 4.3);
    near(num("Consigne"), 100, "potentiom\xC3\xA8tre : le maximum est une expression (Niveau * 2 = 100)");
    rt.dragValue(consigne, 0.0, true, 4.4);
    near(num("Consigne"), 20, "... le minimum : 20");
    // ---- la date et l'heure
    rt.tick(5.0);
    bool pending = true;
    check(rt.pickerValue(echeance, &pending) == DateTime{2026, 9, 23, 14, 30, 0} && !pending, "date et heure : elle montre sa variable (23/09/2026 14:30)");
    rt.objectPart(echeance, "plus:jour", 5.1);
    for (int i = 0; i < 31; ++i) rt.objectPart(echeance, "plus:minute", 5.2);
    check(rt.pickerValue(echeance, &pending) == DateTime{2026, 9, 24, 14, 1, 0} && pending, "... les fl\xC3\xA8" "ches r\xC3\xA8glent sans \xC3\xA9" "crire (24/09, 14:01)");
    same(txt("Echeance"), "2026-09-23 14:30", "... la variable attend Valider");
    rt.objectPart(echeance, "valider", 5.3);
    same(txt("Echeance"), "2026-09-24 14:01", "Valider \xC3\xA9" "crit la STRING");
    check(journalHas(rt, "Action", "(24/09/2026 14:01)"), "... et le journal la dit \xC3\xA0 la fran\xC3\xA7" "aise");
    rt.objectPart(heure, "plus:heure", 5.4);
    rt.objectPart(heure, "plus:heure", 5.5);
    rt.objectPart(heure, "valider", 5.6);
    check(rt.variable("Heure") && rt.variable("Heure")->type() == sim::Type::Time && rt.variable("Heure")->asInteger() == 2 * 3600 * 1000,
          "une heure seule dans un TIME : T#2h (en millisecondes)");
    // ---- le programmateur horaire
    rt.objectPart(prog2, "case:0,14", 6.0);
    same(txt("Plages_2"), "Lu=07:00-07:30", "programmateur : une case allum\xC3\xA9" "e \xC3\xA9" "crit sa plage");
    rt.objectPart(prog2, "case:0,15", 6.1);
    same(txt("Plages_2"), "Lu=07:00-08:00", "... la suivante l'allonge");
    rt.objectPart(prog2, "heure:16", 6.2);
    same(txt("Plages_2"), "Lu=07:00-08:30; Ma-Di=08:00-08:30", "... une heure : toute la colonne, les jours pareils group\xC3\xA9s");
    rt.objectPart(prog2, "jour:6", 6.3);
    same(txt("Plages_2"), "Lu=07:00-08:30; Ma-Sa=08:00-08:30", "... un jour allum\xC3\xA9 : il s'\xC3\xA9teint en entier");
    rt.objectPart(prog2, "case:0,14", 6.4);
    same(txt("Plages_2"), "Lu=07:30-08:30; Ma-Sa=08:00-08:30", "... une case allum\xC3\xA9" "e s'\xC3\xA9teint");
    rt.tick(7.0);
    check(!b("Sortie") && journalHas(rt, "Action", "Sortie = FALSE (programmateur)"), "sans plage : la sortie est fausse");
    rt.environment().write("Plages", sim::Value::text("*=00:00-24:00"));
    rt.tick(7.1);
    check(b("Sortie"), "des plages \xC3\xA9" "crites dans sa variable (par un script, une recette) : la sortie suit");
    check(rt.schedule(prog) && scheduleOn(*rt.schedule(prog), 3, 600), "... et la grille aussi");
    const int today = weekdayFromEpoch(rt.epochOf(7.2));
    rt.objectPart(prog, "jour:" + std::to_string(today), 7.2);
    rt.tick(7.3);
    check(!b("Sortie"), "aujourd'hui \xC3\xA9teint d'un clic : la sortie retombe");
    // ---- le compteur horaire
    rt.tick(8.0);
    rt.tick(9.0);
    near(num("Compteur"), 0, "compteur horaire : il ne compte pas tant que sa condition est fausse");
    rt.environment().write("Marche", sim::Value::boolean(true));
    rt.tick(10.0);
    rt.tick(12.0);
    check(rt.hourMeterRunning(compteur) && rt.variable("Compteur")->asInteger() == 3000, "... vraie : il compte (3 s dans un TIME, en ms)");
    near(rt.hourMeterSeconds(compteur), 3, "... hourMeterSeconds le dit aussi", 1e-6);
    rt.environment().write("Marche", sim::Value::boolean(false));
    rt.tick(13.0);
    rt.tick(14.0);
    check(!rt.hourMeterRunning(compteur) && rt.variable("Compteur")->asInteger() == 3000, "... fausse : il s'arr\xC3\xAAte et garde son total");
    rt.environment().write("Compteur", sim::Value::time(0));
    rt.environment().write("Marche", sim::Value::boolean(true));
    rt.tick(15.0);
    rt.tick(16.0);
    check(rt.variable("Compteur")->asInteger() == 2000, "remis \xC3\xA0 z\xC3\xA9ro par un script : il repart de z\xC3\xA9ro (2 s depuis)");
    near(num("Heures") * 3600.0, 16.0 - 5.0, "sans condition, il compte tout le temps ; une REAL compte en heures", 1e-6);
    check(rt.hourMeterRunning(heures) && std::fabs(rt.hourMeterSeconds(heures) - 11.0) < 1e-6, "... il tourne, et hourMeterSeconds le dit (11 s)");
    // ---- la fleche de tendance
    for (int i = 0; i < 6; ++i) {
        rt.environment().write("Niveau", sim::Value::real(50.0 + i));
        rt.tick(17.0 + i * 0.5);
    }
    check(rt.trendArrow(tendance) == 1, "fl\xC3\xA8" "che de tendance : la valeur monte (+1)");
    for (int i = 0; i < 6; ++i) {
        rt.environment().write("Niveau", sim::Value::real(55.0 - i * 2));
        rt.tick(20.0 + i * 0.5);
    }
    check(rt.trendArrow(tendance) == -1, "... elle descend (-1)");
    for (int i = 0; i < 6; ++i) {
        rt.environment().write("Niveau", sim::Value::real(45.0 + (i % 2) * 0.2));
        rt.tick(23.0 + i * 0.5);
    }
    check(rt.trendArrow(tendance) == 0, "... elle bouge moins que la zone morte : stable (0)");
    // ---- la confirmation d'un bouton
    clic(arretId, 30.0);
    check(b("Moteur") && rt.confirmPending(arretId, 30.1), "second clic : le premier arme le bouton (Confirmer ?), rien n'est fait");
    clic(arretId, 31.0);
    check(!b("Moteur") && !rt.confirmPending(arretId, 31.1), "... le second, dans les 3 s, lance l'action");
    rt.environment().write("Moteur", sim::Value::boolean(true));
    clic(arretId, 32.0);
    check(!rt.confirmPending(arretId, 35.5), "... sans second clic, il se d\xC3\xA9sarme apr\xC3\xA8s 3 s");
    clic(arretId, 35.6);
    check(b("Moteur") && rt.confirmPending(arretId, 35.7), "... et le clic suivant r\xC3\xA9" "arme seulement");
    rt.press(purgeId, 40.0);
    rt.tick(40.5);
    near(rt.holdProgress(purgeId, 40.5), 0.5, "maintien : la barre se remplit (la moiti\xC3\xA9 \xC3\xA0 0,5 s sur 1 s)", 1e-6);
    near(num("Purge"), 0, "... rien n'est fait avant la fin");
    rt.tick(41.1);
    near(num("Purge"), 1, "... l'action part quand la dur\xC3\xA9" "e est atteinte");
    rt.release(purgeId, 41.3, true);
    near(num("Purge"), 1, "... rel\xC3\xA2" "cher ensuite ne la relance pas");
    rt.press(purgeId, 42.0);
    rt.tick(42.4);
    rt.release(purgeId, 42.5, true);
    rt.tick(43.5);
    near(num("Purge"), 1, "... rel\xC3\xA2" "ch\xC3\xA9 trop t\xC3\xB4t : rien");
    // ---- sans variable ; sous securite
    clic(sansVar, 44.0);
    check(journalHas(rt, "Erreur", "sans variable"), "une commande sans variable : rien n'est \xC3\xA9" "crit, le journal le dit");
    Project s = p;
    s.security = Security::defaults();
    s.security.enabled = true;
    User u;
    u.id = s.allocate();
    u.login = "lecteur";
    u.group = s.security.groups[0].id;
    s.security.roles[0].permissions = {"Naviguer"};
    s.security.users.push_back(u);
    s.security.startUser = "lecteur";
    Runtime rs;
    rs.bind(&s, nullptr);
    rs.start(0.0);
    rs.press(pompe, 0.1);
    rs.release(pompe, 0.2, true);
    check(rs.variable("Pompe") && !rs.variable("Pompe")->isTruthy(), "sous s\xC3\xA9" "curit\xC3\xA9, sans Piloter : l'interrupteur n'\xC3\xA9" "crit pas");
    check(journalHas(rs, "", "Piloter") && rs.formState(pompe) && rs.formState(pompe)->message.find("Piloter") != std::string::npos,
          "... le refus est dit (journal, et sur l'objet)");
    rs.dragValue(vitesse, 0.8, false, 0.3);
    check(!rs.dragPreview(vitesse), "... la poign\xC3\xA9" "e d'un curseur ne suit pas");
    rs.objectPart(prog2, "case:1,10", 0.4);
    check(rs.variable("Plages_2") && rs.variable("Plages_2")->asString().empty(), "... le programmateur non plus");
}

// ------------------------------------------------------ lot 9 : generer et compiler --
void verificationsLot9() {
    std::printf("lot 9 : g\xC3\xA9n\xC3\xA9rer et compiler (commandes, afficheurs, confirmation)\n");
    Project p;
    View v = makeView(p, "Controles");
    p.programs.variables.push_back(hmiVar(p, "Marche", "BOOL", "FALSE"));
    p.programs.variables.push_back(hmiVar(p, "Niveau", "REAL", "0.0"));
    const auto put = [&](Kind k, const char* name, const char* var = "Marche") -> Object& {
        const Id id = edit::add(p, v, k, 10, 10 + 40.0 * static_cast<double>(v.objects.size()));
        auto* o = v.object(id);
        o->name = name;
        if (kindWritesVariable(k)) o->set("variable", var);
        return *o;
    };
    put(Kind::Switch, "Sans_Variable", "");
    put(Kind::Selector, "Sans_Choix").set("positions", "");
    auto& combo = put(Kind::ComboBox, "Valeurs_Courtes", "Niveau");
    combo.set("items", "A;B;C");
    combo.set("values", "1;2");
    put(Kind::Selector, "Sept_Positions", "Niveau").set("positions", "1;2;3;4;5;6;7");
    auto& inverse = put(Kind::Slider, "Bornes_Inversees", "Niveau");
    inverse.setNumber("min", 50);
    inverse.setNumber("max", 10);
    put(Kind::Knob, "Pas_Negatif", "Niveau").setNumber("step", -1);
    put(Kind::Slider, "Pas_Enorme", "Niveau").setNumber("step", 500);
    put(Kind::Slider, "Min_Texte", "Niveau").set("min", "abc");
    auto& expr = put(Kind::Slider, "Max_Expression", "Niveau");
    expr.setExpr("max", "Niveau * 2");
    put(Kind::Bargraph, "Zones_Illisibles").set("zones", "0-60 #2ECC71");
    put(Kind::Dial, "Zone_Dehors").set("zones", "150-200 = #FF0000");
    put(Kind::MultiStateIndicator, "Etats_Illisibles").set("stateList", "Marche");
    put(Kind::MultiStateText, "Sans_Etat").set("stateList", "");
    auto& vide = put(Kind::WeeklySchedule, "Prog_Inutile", "");
    vide.set("output", "");
    put(Kind::WeeklySchedule, "Prog_Illisible", "").set("schedule", "Xx=07:00-08:00");
    put(Kind::WeeklySchedule, "Prog_Sortie", "").set("output", "Sortie_Absente");
    put(Kind::SevenSegment, "Trop_De_Chiffres").setNumber("digits", 20);
    put(Kind::SevenSegment, "Trop_De_Decimales").setNumber("decimals", 4);
    put(Kind::QrCode, "QR_Long").set("text", std::string(300, 'q'));
    put(Kind::QrCode, "QR_Vide").set("text", "");
    put(Kind::QrCode, "QR_Trous").set("text", "https://example.com/{Niveau}");
    put(Kind::Marquee, "Immobile").setNumber("speed", 0);
    put(Kind::TrendArrow, "Sans_Fenetre").setNumber("window", 0);
    put(Kind::Button, "Confirme_Rien").set("confirmMode", "second clic");
    auto& court = put(Kind::Button, "Maintien_Court");
    court.set("confirmMode", "maintien");
    court.setNumber("holdMs", 100);
    court.actions.push_back(act(Trigger::Click, Operation::Toggle, "Marche"));
    auto& ok = put(Kind::Button, "Confirme_Bien");
    ok.set("confirmMode", "second clic");
    ok.actions.push_back(act(Trigger::Click, Operation::Toggle, "Marche"));
    put(Kind::IlluminatedButton, "Voyant_Absent").set("lamp", "Lampe_Absente");
    put(Kind::HourMeter, "Condition_Absente").set("condition", "Inconnue AND TRUE");
    put(Kind::Switch, "Retour_Illisible").set("state", "Marche AND");
    put(Kind::Switch, "Retour_Correct").set("state", "NOT Marche");
    p.views = {v};
    p.config.startView = v.id;
    p.config.quality = false;       // lot 13 : les objets empiles sortent de la vue - la qualite a son test
    const auto issues = generate(p, [](std::string_view) { return false; });
    using S = Issue::Severity;
    const auto has = [&](std::string_view object, std::string_view text, S sev) {
        const auto* o = v.objectByName(object);
        for (const auto& i : issues)
            if (i.severity == sev && (!o || i.object == o->id) && i.message.find(text) != std::string::npos) return true;
        return false;
    };
    const auto clean = [&](std::string_view object) {
        const auto* o = v.objectByName(object);
        for (const auto& i : issues)
            if (o && i.object == o->id && i.severity != S::Info) return false;
        return true;
    };
    check(has("Sans_Variable", "commande sans variable", S::Warning), "une commande sans variable (avertissement)");
    check(has("Sans_Choix", "aucun choix", S::Error), "un s\xC3\xA9lecteur sans position (erreur)");
    check(has("Valeurs_Courtes", "2 valeur(s) \xC3\xA9" "crite(s) pour 3 choix", S::Warning), "moins de valeurs que de choix");
    check(has("Sept_Positions", "plus de 6 positions", S::Warning), "un s\xC3\xA9lecteur rotatif \xC3\xA0 7 positions");
    check(has("Bornes_Inversees", "minimum au-dessus du maximum", S::Error), "un curseur aux bornes invers\xC3\xA9" "es");
    check(has("Pas_Negatif", "pas n\xC3\xA9gatif", S::Error), "un pas n\xC3\xA9gatif");
    check(has("Pas_Enorme", "pas plus grand que la course", S::Warning), "un pas plus grand que la course");
    check(has("Min_Texte", "n'est pas un nombre", S::Error), "une borne qui n'est pas un nombre");
    check(clean("Max_Expression"), "une borne en expression (=Niveau * 2) : rien \xC3\xA0 redire");
    check(has("Zones_Illisibles", "zones illisibles", S::Error), "des zones illisibles");
    check(has("Zone_Dehors", "hors de l'\xC3\xA9" "chelle", S::Warning), "une zone hors de l'\xC3\xA9" "chelle");
    check(has("Etats_Illisibles", "\xC3\xA9tats illisibles", S::Error), "des \xC3\xA9tats illisibles");
    check(has("Sans_Etat", "aucun \xC3\xA9tat", S::Warning), "aucun \xC3\xA9tat");
    check(has("Prog_Inutile", "ni sortie", S::Warning), "un programmateur sans variable ni sortie");
    check(has("Prog_Illisible", "plages illisibles", S::Error), "des plages illisibles");
    check(has("Prog_Sortie", "variable inexistante dans le programme : Sortie_Absente", S::Error), "une sortie inconnue");
    check(has("Trop_De_Chiffres", "de 1 \xC3\xA0 16 chiffres", S::Warning), "20 chiffres");
    check(has("Trop_De_Decimales", "plus de d\xC3\xA9" "cimales que de chiffres", S::Warning), "4 d\xC3\xA9" "cimales sur 4 chiffres");
    check(has("QR_Long", "trop long pour un code QR", S::Error), "un code QR trop long");
    check(has("QR_Vide", "code QR sans texte", S::Warning), "un code QR vide");
    check(clean("QR_Trous"), "un code QR \xC3\xA0 trous : sa longueur se juge en marche");
    check(has("Immobile", "vitesse nulle", S::Warning), "un texte d\xC3\xA9" "filant immobile");
    check(has("Sans_Fenetre", "fen\xC3\xAAtre nulle", S::Warning), "une fl\xC3\xA8" "che de tendance sans fen\xC3\xAAtre");
    check(has("Confirme_Rien", "sans action au clic", S::Warning), "une confirmation sans rien \xC3\xA0 confirmer");
    check(has("Maintien_Court", "moins de 200 ms", S::Warning), "un maintien trop court");
    check(clean("Confirme_Bien"), "une confirmation sur une action au clic : rien \xC3\xA0 redire");
    check(has("Voyant_Absent", "lamp : variable inexistante dans le programme : Lampe_Absente", S::Error), "un voyant qui lit une variable absente");
    check(has("Condition_Absente", "condition : variable inexistante dans le programme : Inconnue", S::Error), "une condition qui lit une variable absente");
    check(clean("Retour_Correct"), "un retour d'\xC3\xA9tat correct : rien \xC3\xA0 redire");
    const auto compiled = compile(p);
    bool illisible = false, correct = true;
    for (const auto& i : compiled) {
        if (i.severity != S::Error) continue;
        illisible = illisible || (i.object == v.objectByName("Retour_Illisible")->id && i.property == "state");
        correct = correct && i.object != v.objectByName("Retour_Correct")->id;
    }
    check(illisible, "Compiler : un retour d'\xC3\xA9tat illisible (Marche AND)");
    check(correct, "... et rien sur un retour d'\xC3\xA9tat correct");
}

// ---------------------------------------------------- lot 9 : les exemples animes --
void exemplesLot9() {
    std::printf("lot 9 : ce que font les exemples anim\xC3\xA9s des commandes\n");
    const auto run = [](Kind k, const std::vector<std::pair<double, std::string>>& at, const std::function<std::string(Runtime&)>& probe) {
        auto ex = examples::exampleFor(k);
        std::map<double, std::string> got;
        if (!ex) return got;
        Runtime rt;
        rt.bind(&ex->project, nullptr);
        rt.start(0.0);
        double played = 0;
        for (double t = 0.05; t <= ex->period + 1e-9; t += 0.05) {
            rt.tick(t);
            (void)examples::play(*ex, rt, played, t, t);
            played = t;
            for (const auto& [when, name] : at)
                if (std::fabs(t - when) < 0.025) got[when] += (got[when].empty() ? "" : ",") + probe(rt);
        }
        return got;
    };
    const auto var = [](const char* name) {
        return [name](Runtime& rt) { return rt.variable(name) ? formatValue(*rt.variable(name)) : std::string("?"); };
    };
    auto g = run(Kind::Button, {{3.0, ""}, {3.6, ""}}, var("Marche"));
    check(g[3.0] == "TRUE" && g[3.6] == "FALSE", "Bouton : Arr\xC3\xAAt attend son second clic (" + g[3.0] + " puis " + g[3.6] + ")");
    g = run(Kind::PushButton, {{2.0, ""}, {3.5, ""}}, var("Avance"));
    check(g[2.0] == "TRUE" && g[3.5] == "FALSE", "Bouton \xC3\xA0 impulsion : vrai tant qu'on appuie");
    g = run(Kind::Switch, {{2.0, ""}, {6.0, ""}}, var("Marche"));
    check(g[2.0] == "TRUE" && g[6.0] == "FALSE", "Interrupteur : marche puis arr\xC3\xAAt");
    g = run(Kind::IlluminatedButton, {{2.0, ""}, {2.8, ""}, {4.0, ""}, {5.0, ""}, {7.0, ""}, {8.0, ""}},
            [](Runtime& rt) { return formatValue(*rt.variable("Lampe_1")) + formatValue(*rt.variable("Lampe_2")) + formatValue(*rt.variable("Lampe_3")); });
    check(g[2.0] == "TRUEFALSEFALSE" && g[2.8] == "TRUETRUEFALSE" && g[4.0] == "TRUEFALSEFALSE" && g[5.0] == "TRUEFALSETRUE"
              && g[7.0] == "TRUEFALSEFALSE" && g[8.0] == "FALSEFALSEFALSE",
          "Bouton lumineux : basculer, impulsion, mettre \xC3\xA0 1, mettre \xC3\xA0 0, basculer");
    g = run(Kind::Selector, {{1.5, ""}, {3.0, ""}, {4.5, ""}, {6.0, ""}, {7.5, ""}},
            [](Runtime& rt) { return formatValue(*rt.variable("Mode")) + "/" + formatValue(*rt.variable("Vitesse")); });
    check(g[1.5] == "2/0" && g[3.0] == "0/0" && g[4.5] == "1/0" && g[6.0] == "1/2" && g[7.5] == "1/0", "S\xC3\xA9lecteur : positions, suivante, style boutons");
    g = run(Kind::ComboBox, {{4.0, ""}, {7.0, ""}}, [](Runtime& rt) { return rt.variable("Gaz")->asString(); });
    check(g[4.0] == "CO2" && g[7.0] == "Argon", "Liste d\xC3\xA9roulante : CO2 apr\xC3\xA8s d\xC3\xA9" "filement, puis Argon (" + g[4.0] + ", " + g[7.0] + ")");
    g = run(Kind::RadioGroup, {{1.5, ""}, {3.0, ""}, {4.5, ""}, {6.0, ""}, {7.5, ""}},
            [](Runtime& rt) { return formatValue(*rt.variable("Vitesse")) + "/" + formatValue(*rt.variable("Mode")); });
    check(g[1.5] == "1/0" && g[3.0] == "0/0" && g[4.5] == "0/1" && g[6.0] == "2/1" && g[7.5] == "2/0", "Boutons radio : chaque option \xC3\xA9" "crit son rang");
    g = run(Kind::DateTimePicker, {{5.0, ""}}, [](Runtime& rt) { return rt.variable("Echeance")->asString(); });
    DateTime written;
    check(g[5.0].size() == 16 && parseDateTime(g[5.0], written), "Date et heure : Valider \xC3\xA9" "crit une date lisible (" + g[5.0] + ")");
    g = run(Kind::WeeklySchedule, {{1.5, ""}, {3.0, ""}, {4.5, ""}, {6.0, ""}}, [](Runtime& rt) { return rt.variable("Plages")->asString(); });
    same(g[1.5], "Lu-Ve=07:00-12:00,13:00-17:00; Sa=00:00-24:00", "Programmateur : les heures de bureau, et le samedi entier");
    same(g[3.0], "Lu-Ma=07:00-12:00,13:00-17:00; Me=07:00-12:00,13:00-17:00,19:00-20:00; Je-Ve=07:00-12:00,13:00-17:00; Sa=00:00-24:00", "... une heure le mercredi soir");
    same(g[4.5], "Lu-Ma=07:00-12:00,13:00-17:00,20:00-21:00; Me=07:00-12:00,13:00-17:00,19:00-21:00; Je-Ve=07:00-12:00,13:00-17:00,20:00-21:00; Sa=00:00-24:00; Di=20:00-21:00", "... 20 h tous les jours");
    same(g[6.0], "Lu-Ma=07:00-12:00,13:00-17:00,20:00-21:00; Me=07:00-12:00,13:00-17:00,19:00-21:00; Je-Ve=07:00-12:00,13:00-17:00,20:00-21:00; Di=20:00-21:00", "... le samedi \xC3\xA9teint");
    g = run(Kind::HourMeter, {{5.4, ""}, {7.5, ""}}, [](Runtime& rt) { return formatValue(*rt.variable("Heures_Pompe")); });
    const double h1 = std::atof(g[5.4].c_str()) * 3600.0, h2 = std::atof(g[7.5].c_str()) * 3600.0;
    check(std::fabs(h1 - 4.4) < 0.2 && std::fabs(h2 - 4.5) < 0.2, "Compteur horaire : 4,5 s de marche, puis il s'arr\xC3\xAAte (" + g[5.4] + " h, " + g[7.5] + " h)");
}

// ------------------------------------------------------ lot 9 : sur le disque (format 8) --
void persistanceLot9() {
    std::printf("lot 9 : sur le disque (format 8) - les 23 objets, la confirmation, un format plus r\xC3\xA9" "cent refus\xC3\xA9\n");
    Project p;
    View v = makeView(p, "Vue_Lot9");
    const std::vector<Kind> kinds = {Kind::PushButton, Kind::Switch, Kind::IlluminatedButton, Kind::Selector, Kind::Slider, Kind::Knob,
                                     Kind::ComboBox, Kind::CheckBox, Kind::RadioGroup, Kind::DateTimePicker, Kind::WeeklySchedule,
                                     Kind::NumericDisplay, Kind::MultiStateIndicator, Kind::MultiStateText, Kind::Bargraph,
                                     Kind::Thermometer, Kind::Dial, Kind::Clock, Kind::HourMeter, Kind::SevenSegment,
                                     Kind::TrendArrow, Kind::Marquee, Kind::QrCode};
    double y = 10;
    for (const auto k : kinds) {
        const Id id = edit::add(p, v, k, 10, y);
        y += 30;
        auto* o = v.object(id);
        if (kindWritesVariable(k)) o->set("variable", "Consigne");
        if (k == Kind::Selector) o->set("values", "10;20;'Auto'");
        if (k == Kind::WeeklySchedule) o->set("schedule", "Lu-Ve=07:00-12:00; Sa=08:00-10:00");
        if (k == Kind::MultiStateText) o->set("stateList", "0 = Arr\xC3\xAAt; 1 = En marche | #2ECC71 | clignote");
        if (k == Kind::Dial) o->setExpr("value", "Consigne * 2");
        if (k == Kind::QrCode) o->set("text", "https://example.com/{Consigne}");
    }
    auto& b = addButton(p, v, "Btn_Arret", 400, 10);
    b.set("confirmMode", "maintien");
    b.setNumber("holdMs", 1500);
    b.actions.push_back(act(Trigger::Click, Operation::Reset, "Marche"));
    p.views = {v};
    p.config.startView = v.id;
    p.programs.variables.push_back(hmiVar(p, "Consigne", "REAL", "1.0"));
    const fs::path dir = fs::temp_directory_path() / "hmi_test_lot9";
    fs::remove_all(dir);
    check(static_cast<bool>(save(p, dir.string())), "enregistrer un projet avec les 23 objets du lot 9");
    check(kFormatVersion >= 8, "le format est au moins 8 (lot 9 ; " + std::to_string(kFormatVersion) + " aujourd'hui)");
    auto back = load(dir.string());
    check(static_cast<bool>(back) && back->views.size() == 1, "... il se relit");
    if (back && back->views.size() == 1) {
        const auto& bv = back->views[0];
        std::size_t same = 0;
        std::string differ;
        for (const auto& o : v.objects) {
            const auto* r = bv.object(o.id);
            if (r && *r == o) ++same;
            else differ += o.name + " ";
        }
        check(same == v.objects.size(), "... chaque objet revient \xC3\xA0 l'identique (genre, propri\xC3\xA9t\xC3\xA9s, expressions, actions)"
                                            + (differ.empty() ? std::string{} : " : " + differ));
        const Object* rb = nullptr;
        for (const auto& o : bv.objects)
            if (o.name == "Btn_Arret") rb = &o;
        check(rb && rb->text("confirmMode") == "maintien" && rb->number("holdMs") == 1500, "... la confirmation du bouton (maintien, 1 500 ms)");
    }
    // Un outil du lot 8 lirait ces objets comme des rectangles : un format plus recent est refuse.
    std::string index;
    {
        std::ifstream in(dir / "ihm" / "ihm.txt", std::ios::binary);
        index.assign(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
    }
    const std::string current = "format=" + std::to_string(kPlainFormat);
    const auto at = index.find(current);
    check(at != std::string::npos, "l'index dit " + current);
    if (at != std::string::npos) index.replace(at, current.size(), "format=" + std::to_string(kFormatVersion + 1));
    {
        std::ofstream out(dir / "ihm" / "ihm.txt", std::ios::binary);
        out << index;
    }
    auto newer = load(dir.string());
    check(!newer && newer.error().message().find("plus r") != std::string::npos,
          "un format plus r\xC3\xA9" "cent (" + std::to_string(kFormatVersion + 1) + ") est refus\xC3\xA9, et dit pourquoi"
              + (newer ? std::string{} : " (" + newer.error().message() + ")"));
    fs::remove_all(dir);
}

// ------------------------------------------------------ lot 9 : variables publiques --
void variablesPubliquesLot9() {
    std::printf("lot 9 : variables syst\xC3\xA8me (SYS.) et variables d'instances\n");
    // ---- le catalogue : des noms uniques, des domaines et des types connus
    {
        std::set<std::string> names;
        bool unique = true, typed = true, domains = true;
        const std::set<std::string> types = {"BOOL", "INT", "DINT", "UDINT", "REAL", "TIME", "STRING"};
        for (const auto& v : pub::kSysVars) {
            std::string u(v.name);
            for (auto& c : u) c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
            unique = unique && names.insert(u).second;
            typed = typed && types.count(std::string(v.type));
            domains = domains && v.domain >= 0 && static_cast<std::size_t>(v.domain) < pub::kSysDomainCount;
        }
        check(unique, "catalogue SYS : chaque nom une seule fois (sans casse)");
        check(typed, "catalogue SYS : des types connus");
        check(domains, "catalogue SYS : chaque variable dans un domaine");
        check(pub::kSysVarCount >= 100, "catalogue SYS : plus de 100 variables (" + std::to_string(pub::kSysVarCount) + ")");
        for (std::size_t d = 0; d < pub::kSysDomainCount; ++d)
            check(!pub::sysVarsOf(static_cast<int>(d)).empty(), "domaine " + std::string(pub::kSysDomains[d]) + " : des variables");
        for (const char* n : {"UserName", "UserLevel", "UserGroup", "UserFullName", "CurrentView", "DateTime", "AlarmCount",
                              "PlcRunning", "ProjectName", "ComputerName", "CycleCount"})
            check(pub::sysVar(n) != nullptr, std::string("SYS.") + n + " au catalogue");
        check(pub::sysVar("username") == pub::sysVar("UserName"), "SYS : sans casse");
        // Les informations d'un objet ne cachent aucune propriete d'aucun objet.
        bool clash = false;
        for (const auto k : kPlaceableKinds) {
            const Object o = makeObject(k, 1, "O", 0, 0, 1);
            for (const auto& prop : o.props)
                for (const auto& i : pub::kObjectInfo) clash = clash || pub::same(prop.key, i.name);
        }
        check(!clash, "aucune propri\xC3\xA9t\xC3\xA9 ne porte le nom d'une information (Name, Type, Pressed...)");
        // .Value : les objets qui montrent une variable, comme LiveView les relie.
        std::string differ;
        for (const auto k : kPlaceableKinds) {
            Object o = makeObject(k, 1, "O", 0, 0, 1);
            o.set("variable", "X");
            if (pub::linkedValue(k) != !autoValueSource(o).empty()) differ += std::string(kindKey(k)) + " ";
        }
        check(differ.empty(), "pub::linkedValue suit autoValueSource (LiveView) " + differ);
        // Le guide decrit chaque variable systeme, avec son type.
        const auto* topic = hmi::guide::topic("variables-systeme");
        std::string tables;
        if (topic)
            for (const auto& b : topic->blocks) if (b.kind == hmi::guide::BlockKind::Table) tables += hmi::guide::plain(b.text) + "\n";
        // 1.9 : le domaine Esclaves simules a son propre sujet (variables-esclaves, le texte
        // tools/guide-ihm/aide-1.9-page-simulation.txt) ; tant qu'il n'est pas dans le guide,
        // ses variables ne sont pas exigees ici.
        const auto* slaveTopic = hmi::guide::topic("variables-esclaves");
        if (slaveTopic)
            for (const auto& b : slaveTopic->blocks) if (b.kind == hmi::guide::BlockKind::Table) tables += hmi::guide::plain(b.text) + "\n";
        std::string undocumented;
        for (const auto& sv : pub::kSysVars)
            if (tables.find("SYS." + std::string(sv.name) + "\t" + std::string(sv.type)) == std::string::npos
                && (slaveTopic || sv.domain != pub::kSlaveDomain))
                undocumented += std::string(sv.name) + " ";
        check(topic && undocumented.empty(), "le guide d\xC3\xA9" "crit chaque variable syst\xC3\xA8me et son type " + undocumented);
    }

    // ---- un projet : un modele, une vue qui en herite, une popup
    Project p;
    p.config.name = "Essai_SYS";
    p.config.version = "2.1";
    p.config.author = "Q. B.";
    p.config.width = 1000;
    p.config.height = 600;
    View modele = makeView(p, "Modele");
    modele.role = "modele";
    View vue = makeView(p, "Vue_A");
    View pop = makeView(p, "Pop_B");
    pop.role = "popup";
    pop.width = 300;
    pop.height = 200;
    p.programs.variables.push_back(hmiVar(p, "Niveau", "REAL", "42.5"));
    p.programs.variables.push_back(hmiVar(p, "Montrer", "BOOL", "TRUE"));
    p.programs.variables.push_back(hmiVar(p, "Lu", "STRING", "''"));
    p.programs.variables.push_back(hmiVar(p, "N", "DINT", "0"));
    p.programs.variables.push_back(hmiVar(p, "B", "BOOL", "FALSE"));
    // Le modele porte un bandeau ; la vue, un texte a trous, un afficheur relie, un bouton.
    const Id bandeau = edit::add(p, modele, Kind::Text, 0, 0);
    modele.object(bandeau)->name = "Bandeau";
    modele.object(bandeau)->set("text", "Commun");
    vue.templateView = modele.id;
    const Id texte = edit::add(p, vue, Kind::Text, 10, 50);
    vue.object(texte)->name = "Texte";
    vue.object(texte)->set("text", "Niveau {Niveau:0.0} %");
    vue.object(texte)->setExpr("visible", "Montrer");
    const Id aff = edit::add(p, vue, Kind::NumericDisplay, 10, 120);
    vue.object(aff)->name = "Afficheur";
    vue.object(aff)->set("variable", "Niveau");
    auto& btn = addButton(p, vue, "Btn", 300, 50);
    btn.set("access", "0");
    const Id btnId = btn.id;
    // Un bouton de la popup, pour la position.
    auto& fermer = addButton(p, pop, "Fermer", 10, 10);
    (void)fermer;
    // Les scripts : ecrire des variables d'instances, lire des SYS.
    p.programs.scripts.push_back(generalScript(p, "Cacher", "Vue_A.Texte.Visible := FALSE;\nLu := Vue_A.Texte.Text;"));
    p.programs.scripts.push_back(generalScript(p, "Qui", "Lu := SYS.UserName;\nN := SYS.UserLevel;"));
    p.programs.scripts.push_back(generalScript(p, "Interdit", "SYS.UserName := 'pirate';"));
    p.programs.scripts.push_back(generalScript(p, "Couleur", "vue_a.texte.fill := '#FF0000';\nVue_A.Afficheur.Value := 7;"));
    p.programs.scripts.push_back(generalScript(p, "Modele", "Modele.Bandeau.Text := 'Change';"));
    p.programs.scripts.push_back(generalScript(p, "Deplacer", "Pop_B.X := 40;\nPop_B.Y := 30;"));
    p.programs.scripts.push_back(generalScript(p, "Fond", "Vue_A.Background := '#112233';"));
    p.programs.scripts.push_back(generalScript(p, "Acces", "Vue_A.Btn.Access := 3;"));
    p.views = {modele, vue, pop};
    p.config.startView = vue.id;
    const Id vueId = vue.id, popId = pop.id;
    // La securite : l'operateur au lancement.
    p.security.enabled = true;
    User op;
    op.id = p.allocate();
    op.login = "operateur";
    op.fullName = "Paul Martin";
    op.group = p.security.groups.front().id;
    p.security.users.push_back(op);
    p.security.startUser = "operateur";

    Runtime rt;
    rt.bind(&p, nullptr);
    rt.start(0.0);
    const auto read = [&](const std::string& path) {
        sim::Value v;
        return rt.environment().read(path, v) ? formatValue(v) : std::string("<introuvable>");
    };
    // ---- chaque variable systeme se lit, dans son type
    {
        bool all = true, types = true;
        std::string missing;
        for (const auto& v : pub::kSysVars) {
            sim::Value out;
            if (!rt.environment().read("SYS." + std::string(v.name), out)) { all = false; missing += std::string(v.name) + " "; continue; }
            const std::string t(v.type);
            const bool ok = (t == "STRING" && out.type() == sim::Type::String) || (t == "BOOL" && out.type() == sim::Type::Bool)
                         || (t == "REAL" && out.type() == sim::Type::Real) || (t == "TIME" && out.type() == sim::Type::Time)
                         || (t == "INT" && out.type() == sim::Type::Int) || (t == "DINT" && out.type() == sim::Type::DInt)
                         || (t == "UDINT" && out.type() == sim::Type::UDInt);
            if (!ok) { types = false; missing += std::string(v.name) + "(type) "; }
        }
        check(all, "chaque variable syst\xC3\xA8me se lit en marche " + missing);
        check(types, "... dans le type du catalogue " + missing);
    }
    same(read("SYS.UserName"), "operateur", "SYS.UserName : l'utilisateur de d\xC3\xA9part");
    same(read("sys.userfullname"), "Paul Martin", "sys.userfullname (sans casse) : son nom complet");
    same(read("SYS.UserGroup"), p.security.groups.front().name, "SYS.UserGroup : son groupe");
    same(read("SYS.UserLevel"), std::to_string(p.security.groups.front().level), "SYS.UserLevel : son niveau");
    same(read("SYS.UserLoggedIn"), "TRUE", "SYS.UserLoggedIn");
    same(read("SYS.SecurityEnabled"), "TRUE", "SYS.SecurityEnabled");
    same(read("SYS.CurrentView"), "Vue_A", "SYS.CurrentView : la vue de d\xC3\xA9marrage");
    same(read("SYS.StartView"), "Vue_A", "SYS.StartView");
    same(read("SYS.PopupCount"), "0", "SYS.PopupCount : aucune popup");
    same(read("SYS.ProjectName"), "Essai_SYS", "SYS.ProjectName");
    same(read("SYS.ProjectVersion"), "2.1", "SYS.ProjectVersion");
    same(read("SYS.ScreenWidth"), "1000", "SYS.ScreenWidth");
    same(read("SYS.ViewCount"), "3", "SYS.ViewCount");
    same(read("SYS.Running"), "TRUE", "SYS.Running");
    same(read("SYS.PlcConnected"), "FALSE", "SYS.PlcConnected : sans automate");
    same(read("SYS.PlcStatus"), "Absent", "SYS.PlcStatus : Absent");
    same(read("SYS.AppName"), "XpgAnalyzer", "SYS.AppName");
    {
        const std::string dt = read("SYS.DateTime");
        check(dt.size() == 19 && dt[4] == '-' && dt[10] == ' ' && dt[13] == ':', "SYS.DateTime : AAAA-MM-JJ hh:mm:ss (" + dt + ")");
        check(dt.substr(0, 10) == read("SYS.Date") && dt.substr(11) == read("SYS.Time"), "SYS.Date et SYS.Time : ses deux moiti\xC3\xA9s");
        const int wd = std::atoi(read("SYS.WeekDay").c_str());
        check(wd >= 1 && wd <= 7, "SYS.WeekDay de 1 \xC3\xA0 7");
        const std::string names[7] = {"lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche"};
        same(read("SYS.WeekDayName"), wd >= 1 && wd <= 7 ? names[wd - 1] : std::string("?"), "SYS.WeekDayName suit SYS.WeekDay");
        check(read("SYS.TimeZone").rfind("UTC", 0) == 0, "SYS.TimeZone : UTC+hh:mm");
    }
    // Un texte a trous et une expression les lisent comme le reste.
    {
        const auto t = TextTemplate::compile("{SYS.UserName} ({SYS.UserLevel}) sur {SYS.CurrentView}");
        same(t.render(rt.environment()), "operateur (" + std::to_string(p.security.groups.front().level) + ") sur Vue_A",
             "un texte \xC3\xA0 trous lit SYS.UserName, SYS.UserLevel, SYS.CurrentView");
        const auto e = Expression::compile("SYS.UserLevel >= 1 AND SYS.CurrentView = 'Vue_A'");
        const auto v = e.evaluate(rt.environment());
        check(v && v->isTruthy(), "une expression compare des variables syst\xC3\xA8me");
    }
    // ---- les variables d'instances, telles qu'en marche
    same(read("Vue_A.Texte.Visible"), "TRUE", "Vue_A.Texte.Visible : son expression (Montrer)");
    same(read("Vue_A.Texte.Text"), "Niveau 42.5 %", "Vue_A.Texte.Text : le texte \xC3\xA0 trous rempli");
    same(read("Vue_A.Afficheur.Value"), "42.5", "Vue_A.Afficheur.Value : la variable qu'il montre");
    same(read("Vue_A.Texte.X"), "10", "Vue_A.Texte.X");
    same(read("Vue_A.Texte.Width"), read("Vue_A.Texte.W"), "Width et W : la m\xC3\xAA" "me propri\xC3\xA9t\xC3\xA9");
    same(read("Vue_A.Texte.Visibility"), "TRUE", "Visibility : un synonyme de Visible");
    same(read("Vue_A.Texte.Name"), "Texte", "Vue_A.Texte.Name");
    same(read("Vue_A.Texte.Type"), "Texte", "Vue_A.Texte.Type : son genre");
    same(read("Vue_A.Btn.Pressed"), "FALSE", "Vue_A.Btn.Pressed au repos");
    same(read("Vue_A.Texte.Shown"), "TRUE", "Vue_A.Texte.Shown : \xC3\xA0 l'\xC3\xA9" "cran");
    same(read("Vue_A.Bandeau.Text"), "Commun", "un objet emprunt\xC3\xA9 au mod\xC3\xA8le se lit par la vue");
    same(read("Vue_A.Open"), "TRUE", "Vue_A.Open");
    same(read("Pop_B.Open"), "FALSE", "Pop_B.Open : ferm\xC3\xA9" "e");
    same(read("Vue_A.Width"), std::to_string(p.views[1].width), "Vue_A.Width");
    same(read("Vue_A.Role"), "Vue", "Vue_A.Role");
    same(read("Vue_A.Texte.Inconnue"), "<introuvable>", "une propri\xC3\xA9t\xC3\xA9 inconnue ne se lit pas");
    same(read("Vue_Z.Texte.Visible"), "<introuvable>", "une vue inconnue non plus");
    rt.press(btnId, 0.05);
    same(read("Vue_A.Btn.Pressed"), "TRUE", "Vue_A.Btn.Pressed pendant l'appui");
    same(read("SYS.PressedObject"), "Vue_A.Btn", "SYS.PressedObject");
    rt.release(btnId, 0.06, true);
    same(read("Vue_A.Btn.Pressed"), "FALSE", "... et plus apr\xC3\xA8s");
    // ---- ecrire : la propriete est figee, son expression tombe
    check(rt.callScript("Cacher", 0.1), "un script \xC3\xA9" "crit Vue_A.Texte.Visible");
    same(read("Vue_A.Texte.Visible"), "FALSE", "... elle se relit fausse (m\xC3\xAAme si Montrer est vrai)");
    same(rt.variable("Lu") ? rt.variable("Lu")->asString() : std::string("?"), "Niveau 42.5 %", "... et le script lit le texte");
    rt.tick(0.2);
    {
        const auto* shown = rt.composedView(vueId);
        const auto* o = shown ? shown->object(texte) : nullptr;
        check(o && !o->flag("visible", true) && o->expr("visible").empty(),
              "la vue compos\xC3\xA9" "e porte l'\xC3\xA9" "criture (visible faux, sans expression)");
        check(rt.overrideCount() == 1, "SYS.OverrideCount : une propri\xC3\xA9t\xC3\xA9 \xC3\xA9" "crite");
        same(read("SYS.OverrideCount"), "1", "... et SYS.OverrideCount le dit");
    }
    same(read("Vue_A.Texte.Shown"), "FALSE", "Vue_A.Texte.Shown : cach\xC3\xA9");
    check(rt.callScript("Couleur", 0.3), "\xC3\xA9" "crire sans casse (vue_a.texte.fill) et la valeur d'un afficheur");
    same(read("Vue_A.Texte.Fill"), "#FF0000", "Vue_A.Texte.Fill \xC3\xA9" "crite");
    same(read("Vue_A.Afficheur.Value"), "7", "Vue_A.Afficheur.Value : fig\xC3\xA9" "e \xC3\xA0 7 (la variable ne compte plus)");
    rt.tick(0.35);
    {
        LiveView lv;
        lv.bind(*rt.composedView(vueId));
        const auto shown = lv.evaluate(rt.environment());
        const auto* o = shown.object(aff);
        same(o ? o->text("value") : std::string("?"), "7", "en marche, l'afficheur montre 7 (et non sa variable)");
    }
    // Refus : une variable systeme, une propriete de securite.
    check(!rt.callScript("Interdit", 0.4), "SYS.UserName := ... : refus\xC3\xA9");
    same(read("SYS.UserName"), "operateur", "... SYS.UserName n'a pas chang\xC3\xA9");
    {
        std::string why;
        const int hour = rt.publicWrite("SYS.Hour", sim::Value::integer(sim::Type::Int, 3), &why);
        check(hour == 0 && why.find("lecture seule") != std::string::npos, "publicWrite(SYS.Hour) : refus\xC3\xA9 (" + why + ")");
        check(rt.publicWrite("Vue_A.Btn.Access", sim::Value::integer(sim::Type::Int, 3), &why) == 0,
              "Vue_A.Btn.Access : la s\xC3\xA9" "curit\xC3\xA9 ne s'\xC3\xA9" "crit pas en marche");
        check(rt.publicWrite("Vue_A.Btn.Pressed", sim::Value::boolean(true), &why) == 0, "Vue_A.Btn.Pressed : une information, en lecture seule");
        const int unknown = rt.publicWrite("Vue_A.Inconnu.Visible", sim::Value::boolean(true), &why);
        check(unknown == 0 && why.find("Inconnu") != std::string::npos, "un objet inconnu : refus\xC3\xA9 et dit (" + why + ")");
        check(rt.publicWrite("Niveau", sim::Value::real(1), &why) == -1, "une variable IHM n'est pas une variable publique (-1)");
        check(rt.publicWrite("Vue_A.Texte.X", sim::Value::text("abc"), &why) == 0, "X := 'abc' : un nombre est attendu");
    }
    // L'action Affecter ecrit aussi, et dit pourquoi elle refuse.
    {
        View& v = p.views[1];
        auto* b = v.object(btnId);
        b->actions.push_back(act(Trigger::Click, Operation::Assign, "Vue_A.Texte.Text", "'Par action'"));
        b->actions.push_back(act(Trigger::Click, Operation::Assign, "SYS.CurrentView", "'X'"));
        rt.press(btnId, 0.5);
        rt.release(btnId, 0.55, true);
        same(read("Vue_A.Texte.Text"), "Par action", "l'action Affecter \xC3\xA9" "crit Vue_A.Texte.Text");
        bool said = false;
        for (const auto& j : rt.journal()) said = said || (j.kind == "Erreur" && j.message.find("SYS.CurrentView") != std::string::npos
                                                           && j.message.find("lecture seule") != std::string::npos);
        check(said, "Affecter SYS.CurrentView : le journal dit \xC2\xAB en lecture seule \xC2\xBB");
        b->actions.clear();
    }
    // Un objet du modele : ecrit par le modele, vu dans la vue qui en herite.
    check(rt.callScript("Modele", 0.6), "Modele.Bandeau.Text := ...");
    rt.tick(0.65);
    {
        const auto* shown = rt.composedView(vueId);
        const auto* o = shown ? shown->object(bandeau) : nullptr;
        same(o ? o->text("text") : std::string("?"), "Change", "l'\xC3\xA9" "criture sur le mod\xC3\xA8le vaut dans la vue qui en h\xC3\xA9rite");
        same(read("Vue_A.Bandeau.Text"), "Change", "... et se lit par la vue");
    }
    // Le fond de la vue.
    check(rt.callScript("Fond", 0.7), "Vue_A.Background := ...");
    rt.tick(0.75);
    same(rt.composedView(vueId) ? rt.composedView(vueId)->background : std::string("?"), "#112233", "le fond de la vue, \xC3\xA9" "crit en marche");
    // Une popup : ouverte, deplacee par ses variables.
    check(rt.openPopup(popId, Transition{}, 0.8, {}, "centre", kNoId), "Pop_B ouverte");
    same(read("Pop_B.Open"), "TRUE", "Pop_B.Open");
    same(read("Pop_B.IsPopup"), "TRUE", "Pop_B.IsPopup");
    same(read("SYS.PopupCount"), "1", "SYS.PopupCount");
    same(read("SYS.TopPopup"), "Pop_B", "SYS.TopPopup");
    same(read("SYS.TopView"), "Pop_B", "SYS.TopView : la popup du dessus");
    check(rt.callScript("Deplacer", 0.9), "Pop_B.X := 40 ; Pop_B.Y := 30");
    near(rt.popupSlots().empty() ? -1 : rt.popupSlots().front().x, 40, "la popup est d\xC3\xA9plac\xC3\xA9" "e (x)");
    near(rt.popupSlots().empty() ? -1 : rt.popupSlots().front().y, 30, "... (y)");
    same(read("Pop_B.X"), "40", "Pop_B.X se relit");
    // Naviguer : PreviousView, NavigationCount, OpenCount.
    (void)rt.closeAllPopups(Transition{}, 1.0);
    check(rt.navigate(popId, Transition{}, 1.1), "naviguer vers Pop_B (comme une vue)");
    same(read("SYS.PreviousView"), "Vue_A", "SYS.PreviousView");
    same(read("SYS.NavigationCount"), "1", "SYS.NavigationCount");
    same(read("Pop_B.OpenCount"), "2", "Pop_B.OpenCount : ouverte deux fois");
    same(read("Vue_A.IsCurrent"), "FALSE", "Vue_A.IsCurrent apr\xC3\xA8s la navigation");
    // Le cycle compte.
    const long long before = std::atoll(read("SYS.CycleCount").c_str());
    for (int k = 1; k <= 5; ++k) rt.tick(1.2 + k * 0.2);
    check(std::atoll(read("SYS.CycleCount").c_str()) >= before + 4, "SYS.CycleCount avance avec les cycles");
    // Redemarrer : les ecritures repartent de l'editeur.
    rt.start(2.0);
    same(read("Vue_A.Texte.Visible"), "TRUE", "red\xC3\xA9marr\xC3\xA9" "e : Vue_A.Texte.Visible revient \xC3\xA0 son expression");
    same(read("Vue_A.Texte.Fill"), p.views[1].object(texte)->text("fill"), "... Fill \xC3\xA0 sa valeur de l'\xC3\xA9" "diteur");
    check(rt.overrideCount() == 0, "... et plus aucune propri\xC3\xA9t\xC3\xA9 \xC3\xA9" "crite");
    check(rt.callScript("Qui", 2.1), "un script lit SYS.UserName et SYS.UserLevel");
    same(rt.variable("Lu")->asString(), "operateur", "... Lu := SYS.UserName");
    // Securite eteinte : niveau 99, personne.
    rt.logout(2.2);
    same(read("SYS.UserName"), "", "d\xC3\xA9" "connect\xC3\xA9 : SYS.UserName vide");
    same(read("SYS.UserLevel"), "0", "... SYS.UserLevel 0");
    same(read("SYS.CanControl"), "FALSE", "... SYS.CanControl faux");
    same(read("Vue_A.Btn.Enabled"), "TRUE", "Vue_A.Btn.Enabled : niveau d'acc\xC3\xA8s 0, un bouton reste actif");

    // ---- le chemin : resolve, scriptPaths
    {
        const auto r1 = pub::resolve(p, "SYS.UserName");
        check(r1.what == pub::Resolved::What::Sys && r1.type == "STRING" && r1.access == pub::Access::Read, "resolve(SYS.UserName)");
        const auto r2 = pub::resolve(p, "Vue_A.Texte.Visible");
        check(r2.what == pub::Resolved::What::ObjectMember && r2.key == "visible" && r2.type == "BOOL" && r2.access == pub::Access::ReadWrite,
              "resolve(Vue_A.Texte.Visible) : BOOL, R/W");
        check(pub::resolve(p, "Vue_A.Texte.Pressed").access == pub::Access::Read, "resolve(Vue_A.Texte.Pressed) : R");
        check(pub::resolve(p, "SYS.Nimporte").what == pub::Resolved::What::Unknown, "resolve(SYS.Nimporte) : inconnue");
        check(pub::resolve(p, "Vue_A.Texte").what == pub::Resolved::What::Incomplete, "resolve(Vue_A.Texte) : incompl\xC3\xA8te");
        check(pub::resolve(p, "Armoires[0].x").what == pub::Resolved::What::None, "resolve(Armoires[0].x) : pas publique");
        check(pub::resolve(p, "Vue_A.Bandeau.Text").what == pub::Resolved::What::Unknown, "sans la vue compos\xC3\xA9" "e, l'objet du mod\xC3\xA8le n'est pas celui de la vue");
        const View composed = compose(p, p.views[1]);
        check(pub::resolve(p, "Vue_A.Bandeau.Text", &composed).what == pub::Resolved::What::ObjectMember, "... avec elle, il l'est");
        const auto uses = scriptPaths("IF SYS.UserLevel > 2 THEN\n  Vue_A.Texte.Visible := TRUE; (* Vue_A.X *)\nEND_IF;\nx := 'SYS.Hour';");
        check(uses.size() == 2, "scriptPaths : deux chemins (ni commentaire ni cha\xC3\xAEne)");
        if (uses.size() == 2) {
            check(uses[0].path == "SYS.UserLevel" && uses[0].line == 1 && !uses[0].assigned, "... SYS.UserLevel, ligne 1, lu");
            check(uses[1].path == "Vue_A.Texte.Visible" && uses[1].line == 2 && uses[1].assigned, "... Vue_A.Texte.Visible, ligne 2, \xC3\xA9" "crit");
        }
    }

    // ---- Generer : les chemins publics verifies partout
    {
        Project q = p;
        q.programs.scripts.push_back(generalScript(q, "Faux", "N := SYS.PasUneVariable;\nVue_A.Texte.Pressed := TRUE;\nVue_A.Absent.Visible := FALSE;"));
        auto& v = q.views[1];
        v.object(texte)->setExpr("fill", "SEL(SYS.UserLevel > 2, '#FF0000', '#00FF00')");
        v.object(btnId)->actions.push_back(act(Trigger::Click, Operation::Assign, "SYS.Hour", "3"));
        const auto issues = generate(q, [](std::string_view) { return false; });
        const auto has = [&](const std::string& part) {
            for (const auto& i : issues) if (i.message.find(part) != std::string::npos) return true;
            return false;
        };
        check(has("SYS.PasUneVariable"), "G\xC3\xA9n\xC3\xA9rer : variable syst\xC3\xA8me inconnue (SYS.PasUneVariable)");
        check(has("Vue_A.Texte.Pressed : en lecture seule"), "G\xC3\xA9n\xC3\xA9rer : \xC3\xA9" "crire Vue_A.Texte.Pressed est refus\xC3\xA9");
        check(has("objet inconnu dans la vue Vue_A : Absent"), "G\xC3\xA9n\xC3\xA9rer : objet inconnu");
        check(has("SYS.Hour : variable syst\xC3\xA8me, en lecture seule"), "G\xC3\xA9n\xC3\xA9rer : Affecter SYS.Hour refus\xC3\xA9");
        check(!has("variable inexistante dans le programme : SYS") && !has("variable inexistante : SYS") && !has("inexistante : Vue_A"),
              "G\xC3\xA9n\xC3\xA9rer : SYS et les vues ne sont pas des variables inexistantes");
        bool scriptLine = false;
        for (const auto& i : issues) scriptLine = scriptLine || (i.message.find("Pressed") != std::string::npos && i.line == 2);
        check(scriptLine, "... le constat dit la ligne du script (2)");
        const auto clean = generate(p, [](std::string_view) { return false; });
        bool anyPublic = false;
        for (const auto& i : clean)
            anyPublic = anyPublic || (i.severity == Issue::Severity::Error && (i.message.find("SYS.") != std::string::npos));
        // Le projet d'essai ecrit SYS.UserName (script Interdit) : c'est le seul constat attendu.
        std::size_t sysErrors = 0;
        for (const auto& i : clean) sysErrors += i.message.find("SYS.UserName : variable syst") != std::string::npos;
        check(sysErrors == 1, "le projet d'essai : un seul constat SYS (le script Interdit)");
        (void)anyPublic;
    }
}

// ------------------------------------------------ lot 10 : parametres systeme --
void parametresSystemeLot10() {
    std::printf("lot 10 : le menu natif Param\xC3\xA8tres syst\xC3\xA8me (r\xC3\xA9glages, maintenance, diagnostic, objet)\n");
    // ---- la bibliotheque du menu : reglages, pas, textes
    {
        SystemSettings s;
        check(s.brightness == 100 && s.screensaverMin == 0 && s.soundOn && s.volume == 100 && s.autoLogoutMin == -1
                  && s.keyboard == "automatique" && s.clockOffset == 0,
              "r\xC3\xA9glages par d\xC3\xA9" "faut : 100 %, veille jamais, son activ\xC3\xA9, volume 100 %, d\xC3\xA9" "connexion du projet, clavier automatique, heure du poste");
        check(kSettingCount == 11 && settingSpec("luminosite") && !settingSpec("luminosite")->guarded && settingSpec("veille")->guarded
                  && !settingSpec("son")->guarded && !settingSpec("volume")->guarded && settingSpec("deconnexion")->guarded
                  && settingSpec("clavier")->guarded && settingSpec("heure")->guarded && !settingSpec("inconnu")
                  && !settingSpec("texte")->guarded && !settingSpec("couleurs")->guarded && !settingSpec("symboles")->guarded
                  && !settingSpec("theme")->guarded,
              "onze r\xC3\xA9glages : luminosit\xC3\xA9, son, volume et (lot 13) l'affichage \xC3\xA0 tout le monde, les autres prot\xC3\xA9g\xC3\xA9s");
        check(maintenanceSpec("eteindre") && !maintenanceSpec("eteindre")->guarded && maintenanceSpec("journal")->guarded
                  && maintenanceSpec("redemarrer")->guarded && maintenanceSpec("defaut")->guarded,
              "maintenance : \xC3\xA9teindre l'\xC3\xA9" "cran \xC3\xA0 tout le monde, les trois autres prot\xC3\xA9g\xC3\xA9s");
        check(stepSetting(s, "luminosite", "moins") && s.brightness == 90 && settingText(s, "luminosite") == "90 %", "luminosit\xC3\xA9 - : 90 %");
        for (int i = 0; i < 12; ++i) (void)stepSetting(s, "luminosite", "moins");
        check(s.brightness == 20 && !stepSetting(s, "luminosite", "moins"), "... jamais sous 20 % (faux : d\xC3\xA9j\xC3\xA0 au bout)");
        s.brightness = 95;
        check(stepSetting(s, "luminosite", "plus") && s.brightness == 100 && !stepSetting(s, "luminosite", "plus"), "95 % + : 100 %, pas au-del\xC3\xA0");
        for (int i = 0; i < 12; ++i) (void)stepSetting(s, "volume", "moins");
        check(s.volume == 0 && settingText(s, "volume") == "0 %", "le volume descend jusqu'\xC3\xA0 0 %");
        check(stepSetting(s, "son", "bascule") && !s.soundOn && settingText(s, "son") == "Coup\xC3\xA9", "son bascul\xC3\xA9 : \xC2\xAB Coup\xC3\xA9 \xC2\xBB");
        check(stepSetting(s, "veille", "suivant") && s.screensaverMin == 1 && settingText(s, "veille") == "1 min", "veille : jamais, puis 1 min");
        check(stepSetting(s, "veille", "precedent") && stepSetting(s, "veille", "precedent") && s.screensaverMin == 60
                  && settingText(s, "veille") == "1 h",
              "... en boucle : 1 min, jamais, 1 h");
        check(settingText(s, "deconnexion", 15) == "Selon le projet (15 min)" && settingText(s, "deconnexion", 0) == "Selon le projet (jamais)",
              "d\xC3\xA9" "connexion : \xC2\xAB Selon le projet (15 min) \xC2\xBB");
        check(stepSetting(s, "deconnexion", "suivant") && s.autoLogoutMin == 0 && settingText(s, "deconnexion") == "Jamais",
              "... puis \xC2\xAB Jamais \xC2\xBB");
        check(stepSetting(s, "clavier", "suivant") && s.keyboard == "toujours" && stepSetting(s, "clavier", "suivant") && s.keyboard == "jamais"
                  && stepSetting(s, "clavier", "suivant") && s.keyboard == "automatique" && settingText(s, "clavier") == "Automatique",
              "clavier : automatique, toujours, jamais, automatique");
        check(!stepSetting(s, "heure", "plus") && !stepSetting(s, "inconnu", "plus") && !stepSetting(s, "son", "plus"),
              "l'heure, une cl\xC3\xA9 inconnue, un geste qui ne va pas : rien ne change");
        // Le volume : chaque echantillon multiplie.
        Pcm pcm;
        pcm.rate = 8000;
        pcm.channels = 1;
        pcm.samples = {1000, -2000, 32767};
        applyGain(pcm, 0.5);
        check(pcm.samples == std::vector<std::int16_t>{500, -1000, 16384}, "le volume \xC3\xA0 50 % : chaque \xC3\xA9" "chantillon divis\xC3\xA9 par deux");
        applyGain(pcm, 3.0);
        check(pcm.samples == std::vector<std::int16_t>{500, -1000, 16384}, "... un gain au-dessus de 1 ne change rien (born\xC3\xA9)");
        applyGain(pcm, 0.0);
        check(pcm.samples == std::vector<std::int16_t>{0, 0, 0}, "... \xC3\xA0 0 % : le silence");
    }

    // ---- la geometrie : ce qui se dessine est ce qui se clique
    {
        const auto l = systemMenuLayout(900, 560, 0, 0, 0);
        check(l.settings.size() == 10 && l.buttons.size() == 4 && l.clock.fields.size() == 5,
              "R\xC3\xA9glages : dix lignes (lot 13 : quatre pour l'affichage), l'heure (jour, mois, ann\xC3\xA9" "e, heure, minute), quatre boutons de maintenance");
        std::string wrong;
        for (const char* part : {"fermer", "onglet:reglages", "onglet:diagnostic", "moins:luminosite", "plus:luminosite", "bascule:son",
                                 "precedent:veille", "suivant:clavier", "moins:volume", "suivant:deconnexion", "heure:plus:jour",
                                 "heure:moins:minute", "heure:maintenant", "heure:appliquer", "action:eteindre", "action:journal",
                                 "action:redemarrer", "action:defaut"}) {
            Box b;
            if (!systemMenuPartBox(l, 0, part, b)) {
                wrong += std::string(part) + " (absente) ";
                continue;
            }
            const std::string hit = systemMenuHit(l, 0, b.cx(), b.cy());
            if (hit != part) wrong += std::string(part) + " -> " + hit + " ";
        }
        check(wrong.empty(), "chaque partie a son cadre, et un clic en son milieu la retrouve " + wrong);
        Box v;
        check(systemMenuPartBox(l, 0, "valeur:veille", v) && systemMenuHit(l, 0, v.cx(), v.cy()) == "suivant:veille",
              "un clic sur la valeur d'un choix : le suivant");
        check(systemMenuHit(l, 0, 2, 2) == "dehors" && systemMenuHit(l, 0, l.body.x + 2, l.body.bottom() - 2).empty(),
              "hors du panneau : \xC2\xAB dehors \xC2\xBB ; dans le panneau, ailleurs : rien");
        const auto small = systemMenuLayout(480, 240, 0, 0, 0);
        bool inside = small.panel.x >= 0 && small.panel.right() <= 480 && small.panel.bottom() <= 240;
        for (const auto& b : small.buttons) inside = inside && b.box.bottom() <= small.status.y + 1;
        check(inside, "un \xC3\xA9" "cran de 480 x 240 : le menu y tient, la maintenance au-dessus de la ligne d'\xC3\xA9tat");
        // Le diagnostic : 34 lignes en deux colonnes, un groupe jamais coupe quand tout tient.
        std::vector<DiagGroup> groups;
        for (const std::size_t n : {8u, 6u, 5u, 4u, 6u}) {
            DiagGroup g;
            g.title = "G" + std::to_string(groups.size());
            g.rows.resize(n);
            groups.push_back(g);
        }
        const auto d = systemMenuLayout(900, 560, 1, 34, 0);
        std::size_t maxScroll = 9;
        const auto lines = diagLines(groups, d, 0, &maxScroll);
        bool whole = lines.size() == 34 && maxScroll == 0 && d.up.w == 0;
        for (const auto& line : lines)
            for (const auto& other : lines)
                if (other.group == line.group && other.row < 0) whole = whole && other.column == line.column;
        check(whole && d.diagColumns.size() == 2, "Diagnostic : 34 lignes, deux colonnes, aucun groupe coup\xC3\xA9, pas de fl\xC3\xA8" "ches");
        const auto tiny = systemMenuLayout(480, 240, 1, 34, 0);
        const auto first = diagLines(groups, tiny, 0, &maxScroll);
        const std::size_t shown = first.size();
        const auto scrolled = diagLines(groups, tiny, 1000, &maxScroll);
        check(tiny.up.w > 0 && maxScroll > 0 && shown < 34 && !scrolled.empty() && scrolled.back().group == 4,
              "un petit \xC3\xA9" "cran : des fl\xC3\xA8" "ches ; d\xC3\xA9" "filer jusqu'au bout montre le dernier groupe");
    }

    // ---- en marche : sous securite, l'operateur puis l'administrateur
    Project p;
    p.security = Security::defaults();
    p.security.enabled = true;
    p.security.autoLogoutMin = 15;
    const auto user = [&](const char* login, std::size_t group, const char* pwd) {
        User u;
        u.id = p.allocate();
        u.login = login;
        u.group = p.security.groups[group].id;
        u.salt = randomHex(16);
        u.passwordHash = passwordHash(u.salt, pwd);
        p.security.users.push_back(u);
    };
    user("operateur", 0, "1234");
    user("admin", 3, "admin2026");
    p.security.startUser = "operateur";
    Resource bip;
    bip.id = p.allocate();
    bip.name = "bip.wav";
    bip.format = "WAV";
    p.assets.resources.push_back(bip);
    View v = makeView(p, "Vue_Poste");
    const Id btn = edit::add(p, v, Kind::SystemButton, 10, 10);
    v.object(btn)->name = "Btn_Parametres";
    const Id diag = edit::add(p, v, Kind::Button, 10, 80);
    v.object(diag)->name = "Btn_Diagnostic";
    v.object(diag)->actions.push_back(act(Trigger::Click, Operation::ShowSystem, {}, "Diagnostic"));
    const Id son = edit::add(p, v, Kind::Button, 10, 150);
    v.object(son)->name = "Btn_Son";
    v.object(son)->actions.push_back(act(Trigger::Click, Operation::PlaySound, "bip.wav"));
    const Id field = edit::add(p, v, Kind::InputField, 10, 220);
    v.object(field)->name = "Champ";
    v.object(field)->set("variable", "Consigne");
    const Id verrou = edit::add(p, v, Kind::SystemButton, 300, 10);
    v.object(verrou)->name = "Btn_Reserve";
    v.object(verrou)->setNumber("access", 4);
    p.views = {v};
    p.config.startView = v.id;
    p.programs.variables.push_back(hmiVar(p, "Consigne", "REAL", "0.0"));
    p.programs.scripts.push_back(generalScript(p, "Ouvrir_Diagnostic", "IHM_PARAMETRES_SYSTEME('Diagnostic');"));
    Runtime rt;
    std::vector<std::string> sounds;
    int restarts = 0;
    Runtime::Hooks hooks;
    hooks.playSound = [&](const std::string& name) { sounds.push_back(name); };
    hooks.restart = [&] { ++restarts; };
    rt.setHooks(hooks);
    rt.bind(&p, nullptr);
    rt.start(0);
    double t = 0.1;
    const auto click = [&](Id id) {
        rt.press(id, t);
        rt.release(id, t, true);
        t += 0.1;
    };
    const auto part = [&](const char* what) {
        rt.systemPart(what, t);
        t += 0.1;
    };
    const auto sys = [&](const char* name) {
        sim::Value out;
        (void)rt.publicRead(std::string("SYS.") + name, out);
        return out;
    };
    const auto journalHas = [&](std::string_view text) {
        for (const auto& e : rt.journal())
            if (e.message.find(text) != std::string::npos) return true;
        return false;
    };

    click(btn);
    check(rt.systemShown() && rt.systemTab() == 0, "l'objet Param\xC3\xA8tres syst\xC3\xA8me : un clic ouvre le menu, sur R\xC3\xA9glages");
    check(sys("SystemMenuOpen").isTruthy() && sys("SystemMenuTab").asString() == "R\xC3\xA9glages", "SYS.SystemMenuOpen, SYS.SystemMenuTab = R\xC3\xA9glages");
    bool sourced = false;
    for (const auto& e : rt.journal()) sourced = sourced || (e.source == "Vue_Poste/Btn_Parametres" && e.message == "param\xC3\xA8tres syst\xC3\xA8me");
    check(sourced, "le journal : \xC2\xAB param\xC3\xA8tres syst\xC3\xA8me \xC2\xBB, depuis Vue_Poste/Btn_Parametres");
    click(verrou);
    check(eventHas(rt, "Acc\xC3\xA8s refus\xC3\xA9", "Btn_Reserve"), "un objet de niveau 4 : refus\xC3\xA9 \xC3\xA0 l'op\xC3\xA9rateur (Acc\xC3\xA8s refus\xC3\xA9)");

    // L'operateur : la luminosite oui, la veille non.
    check(rt.settingAllowed("luminosite") && rt.settingAllowed("son") && rt.settingAllowed("eteindre") && !rt.settingAllowed("veille")
              && !rt.settingAllowed("heure") && !rt.settingAllowed("journal"),
          "l'op\xC3\xA9rateur : luminosit\xC3\xA9, son, \xC3\xA9teindre l'\xC3\xA9" "cran ; pas la veille, l'heure, la maintenance");
    part("moins:luminosite");
    check(rt.settings().brightness == 90 && journalHas("Luminosit\xC3\xA9 : 90 %") && rt.systemMessage() == "Luminosit\xC3\xA9 : 90 %"
              && !rt.systemMessageIsError() && sys("Brightness").asInteger() == 90,
          "luminosit\xC3\xA9 - : 90 %, au journal, dans le menu et en SYS.Brightness");
    part("suivant:veille");
    check(rt.settings().screensaverMin == 0 && rt.systemMessageIsError() && rt.systemMessage().find("Administrer") != std::string::npos
              && eventHas(rt, "Acc\xC3\xA8s refus\xC3\xA9", "Mise en veille"),
          "la veille : refus\xC3\xA9" "e \xC3\xA0 l'op\xC3\xA9rateur (message, \xC3\xA9v\xC3\xA9nement Acc\xC3\xA8s refus\xC3\xA9)");
    const std::size_t before = rt.journal().size();
    part("action:journal");
    check(rt.journal().size() > before, "vider le journal : refus\xC3\xA9 aussi (le journal reste)");

    // L'administrateur : tout.
    std::string why;
    check(rt.login("admin", "admin2026", t, &why), "admin se connecte " + why);
    part("suivant:veille");
    check(rt.settings().screensaverMin == 1 && sys("ScreenSaverMinutes").asInteger() == 1, "admin : veille 1 min (SYS.ScreenSaverMinutes)");
    check(rt.autoLogoutMinutes() == 15 && sys("AutoLogoutFromProject").isTruthy() && sys("AutoLogoutMinutes").asInteger() == 15,
          "d\xC3\xA9" "connexion : celle du projet (15 min)");
    part("suivant:deconnexion");
    check(rt.settings().autoLogoutMin == 0 && rt.autoLogoutMinutes() == 0 && rt.autoLogoutRemaining(t) < 0
              && !sys("AutoLogoutFromProject").isTruthy(),
          "... r\xC3\xA9gl\xC3\xA9" "e \xC3\xA0 Jamais : plus de minuterie");
    // Le clavier : le champ en demande un numerique ; jamais : aucun ; toujours : un meme sans.
    v.object(field)->set("keyboard", "num\xC3\xA9rique");
    p.views = {v};
    rt.objectPart(field, "champ", t);
    check(rt.focusedObject() == field && rt.keyboardMode() == "numerique", "clavier automatique : celui du champ (num\xC3\xA9rique)");
    part("suivant:clavier");
    part("suivant:clavier");
    check(rt.settings().keyboard == "jamais" && rt.keyboardMode().empty() && sys("KeyboardMode").asString() == "jamais",
          "clavier jamais : aucun clavier, m\xC3\xAAme demand\xC3\xA9");
    p.views.front().object(field)->set("keyboard", "aucun");
    part("suivant:clavier");
    part("suivant:clavier");
    check(rt.settings().keyboard == "toujours" && rt.keyboardMode() == "numerique", "clavier toujours : un clavier, m\xC3\xAAme sans le demander");
    rt.unfocus(t);

    // L'heure de l'IHM : +1 heure, appliquee ; puis celle du poste.
    bool pending = true;
    const DateTime shown = rt.systemClock(&pending);
    check(!pending, "l'heure du menu : celle de l'IHM, rien en attente");
    part("heure:plus:heure");
    const DateTime wanted = rt.systemClock(&pending);
    // (Le geste arrive un peu apres la lecture : une seconde a pu passer.) La
    // fleche change le champ heure comme un selecteur : 23 h -> 0 h le meme
    // jour (le test echouait entre 23 h et minuit, heure du poste).
    const double gap = epochFromDateTime(wanted) - epochFromDateTime(stepDateTime(shown, "heure", 1));
    check(pending && gap > -1e-6 && gap < 2.0 && wanted.hour == (shown.hour + 1) % 24,
          "une fl\xC3\xA8" "che : l'heure en attente d'Appliquer (une heure plus tard, 23 h \xE2\x86\x92 0 h)");
    part("heure:appliquer");
    const DateTime now = dateTimeFromEpoch(rt.epochOf(rt.now()));
    check(now.year == wanted.year && now.month == wanted.month && now.day == wanted.day && now.hour == wanted.hour
              && now.minute == wanted.minute && std::fabs(rt.settings().clockOffset) > 60,
          "Appliquer : l'IHM a pris l'heure r\xC3\xA9gl\xC3\xA9" "e (\xC3\xA9" "cart " + std::to_string(std::llround(rt.settings().clockOffset)) + " s)");
    check(sys("ClockOffset").asInteger() == std::llround(rt.settings().clockOffset) && sys("DeviceDateTime").asString() != sys("DateTime").asString(),
          "SYS.ClockOffset ; SYS.DeviceDateTime (le poste) diff\xC3\xA8re de SYS.DateTime (l'IHM)");
    part("heure:maintenant");
    part("heure:appliquer");
    check(rt.settings().clockOffset == 0 && journalHas("(celle du poste)"), "Heure du poste, Appliquer : l'\xC3\xA9" "cart revient \xC3\xA0 z\xC3\xA9ro");
    part("heure:appliquer");
    check(rt.systemMessage() == "Date et heure : inchang\xC3\xA9" "e", "Appliquer sans rien changer : inchang\xC3\xA9" "e");

    // Le son : coupe, l'action ne joue rien ; retabli, elle joue.
    part("bascule:son");
    part("fermer");
    click(son);
    check(sounds.empty() && journalHas("(son coup\xC3\xA9)") && sys("SoundCount").asInteger() == 0 && !sys("SoundEnabled").isTruthy(),
          "son coup\xC3\xA9 : Jouer un son ne joue rien (journal : son coup\xC3\xA9)");
    rt.openSystemMenu(0, t, "test");
    part("bascule:son");
    click(son);
    check(sounds == std::vector<std::string>{"bip.wav"} && sys("SoundCount").asInteger() == 1, "son r\xC3\xA9tabli : bip.wav jou\xC3\xA9");

    // La maintenance
    part("action:journal");
    check(rt.journal().size() == 1 && journalHas("journal vid\xC3\xA9"), "vider le journal : il ne dit plus que \xC3\xA7" "a");
    part("action:defaut");
    check(rt.settings() == SystemSettings{} && journalHas("r\xC3\xA9glages par d\xC3\xA9" "faut"), "r\xC3\xA9glages par d\xC3\xA9" "faut : tout revient");
    part("action:eteindre");
    check(!rt.systemShown() && rt.asleep(t) && sys("ScreenSaverActive").isTruthy() && journalHas("\xC3\xA9" "cran \xC3\xA9teint"),
          "\xC3\xA9teindre l'\xC3\xA9" "cran : le menu se ferme, l'\xC3\xA9" "cran est en veille (SYS.ScreenSaverActive)");
    check(rt.wake(t) && !rt.asleep(t) && journalHas("\xC3\xA9" "cran rallum\xC3\xA9") && !rt.wake(t), "un toucher le rallume (une fois)");
    rt.openSystemMenu(0, t, "test");
    part("action:redemarrer");
    check(restarts == 1, "red\xC3\xA9marrer l'IHM : l'\xC3\xA9" "cran le fait (son bouton)");

    // La veille au bout de N minutes sans toucher.
    rt.openSystemMenu(0, t, "test");
    part("suivant:veille");
    part("fermer");
    for (int i = 0; i < 1300; ++i) {
        t += 0.05;
        rt.tick(t);
    }
    check(rt.asleep(t) && journalHas("\xC3\xA9" "cran en veille (1 min sans toucher)"), "une minute sans toucher : l'\xC3\xA9" "cran s'\xC3\xA9teint (journal)");
    check(rt.wake(t) && !rt.asleep(t + 1), "... un toucher le rallume");

    // L'action (onglet Diagnostic) et la fonction IHM.
    click(diag);
    check(rt.systemShown() && rt.systemTab() == 1 && sys("SystemMenuTab").asString() == "Diagnostic", "l'action Param\xC3\xA8tres syst\xC3\xA8me (Diagnostic)");
    part("dehors");
    check(!rt.systemShown(), "un clic hors du panneau le ferme");
    check(rt.callScript("Ouvrir_Diagnostic", t, &why) && rt.systemShown() && rt.systemTab() == 1, "IHM_PARAMETRES_SYSTEME('Diagnostic') " + why);
    check(isHmiFunction("IHM_PARAMETRES_SYSTEME"), "IHM_PARAMETRES_SYSTEME : une fonction IHM connue");

    // Le diagnostic
    const auto groups = rt.diagnostics();
    std::string titles;
    std::size_t rows = 0;
    bool linked = true;
    std::string login, status;
    for (const auto& g : groups) {
        titles += g.title + ";";
        rows += 1 + g.rows.size();
        for (const auto& r : g.rows) {
            if (!r.sys.empty()) linked = linked && r.sys.rfind("SYS.", 0) == 0 && pub::sysVar(r.sys.substr(4)) != nullptr;
            if (r.label == "Connect\xC3\xA9") login = r.value;
            if (r.label == "\xC3\x89tat") status = r.value;
        }
    }
    same(titles, "IHM;Automate;Utilisateur;Alarmes;Poste;", "le diagnostic : IHM, automate, utilisateur, alarmes, poste");
    check(linked && rows == rt.diagnosticRows() && rows >= 30, "chaque ligne reli\xC3\xA9" "e \xC3\xA0 une variable SYS. (" + std::to_string(rows) + " lignes)");
    check(login == "admin" && status == "Absent", "il dit qui est connect\xC3\xA9 (admin) et l'automate (absent)");
    part("defiler:3");
    check(rt.systemScroll() == 3, "d\xC3\xA9" "filer de 3 lignes");
    part("defiler:=1000");
    check(rt.systemScroll() == rows - 1, "... born\xC3\xA9 \xC3\xA0 la derni\xC3\xA8re");
    part("defiler:-5000");
    check(rt.systemScroll() == 0, "... et \xC3\xA0 la premi\xC3\xA8re");
    part("onglet:reglages");
    check(rt.systemTab() == 0, "retour \xC3\xA0 l'onglet R\xC3\xA9glages");

    // Le catalogue SYS : le domaine Parametres systeme se lit en entier.
    std::string unread;
    for (const auto* sv : pub::sysVarsOf(11)) {
        sim::Value out;
        if (!rt.publicRead("SYS." + std::string(sv->name), out)) unread += std::string(sv->name) + " ";
    }
    check(pub::kSysDomains[11] == "Param\xC3\xA8tres syst\xC3\xA8me" && pub::sysVarsOf(11).size() == 16 && unread.empty(),
          "SYS : le domaine Param\xC3\xA8tres syst\xC3\xA8me, ses 16 variables lisibles (lot 13 : l'affichage) " + unread);

    // Les reglages restent au redemarrage ; le menu, lui, repart ferme.
    rt.openSystemMenu(0, t, "test");
    part("moins:volume");
    rt.stop(t);
    rt.start(t);
    check(rt.settings().volume == 90 && !rt.systemShown() && rt.systemTab() == 0, "red\xC3\xA9marr\xC3\xA9" "e : le volume reste (90 %), le menu repart ferm\xC3\xA9");
    // Sans ecran : Redemarrer l'IHM, le moteur repart seul.
    Runtime alone;
    alone.bind(&p, nullptr);
    alone.start(0);
    (void)alone.login("admin", "admin2026", 0.1);
    alone.openSystemMenu(0, 0.2, "test");
    alone.systemPart("action:redemarrer", 0.3);
    bool restarted = false;
    for (const auto& e : alone.journal()) restarted = restarted || e.message.find("IHM red\xC3\xA9marr\xC3\xA9" "e") != std::string::npos;
    check(alone.running() && restarted && !alone.systemShown(), "sans \xC3\xA9" "cran : l'IHM red\xC3\xA9marre seule (journal : IHM red\xC3\xA9marr\xC3\xA9" "e)");

    // ---- l'objet : ses proprietes, Generer, le disque, le guide
    const Object o = makeObject(Kind::SystemButton, 1, "P", 0, 0, 1);
    check(o.text("tab") == "R\xC3\xA9glages" && o.flag("icon", false) && o.text("text") == "Param\xC3\xA8tres" && kindKey(Kind::SystemButton) == "SystemButton"
              && kindFromKey("SystemButton") == Kind::SystemButton && kindLabel(Kind::SystemButton) == "Param\xC3\xA8tres syst\xC3\xA8me",
          "l'objet : texte Param\xC3\xA8tres, onglet R\xC3\xA9glages, l'engrenage ; SystemButton, \xC2\xAB Param\xC3\xA8tres syst\xC3\xA8me \xC2\xBB");
    {
        Project q;
        View w = makeView(q, "Vue_Check");
        const Id a = edit::add(q, w, Kind::SystemButton, 10, 10);
        w.object(a)->name = "Onglet_Inconnu";
        w.object(a)->set("tab", "Alarmes");
        const Id b = edit::add(q, w, Kind::SystemButton, 10, 80);
        w.object(b)->name = "Double_Emploi";
        w.object(b)->actions.push_back(act(Trigger::Click, Operation::ShowSystem));
        const Id c = edit::add(q, w, Kind::SystemButton, 10, 150);
        w.object(c)->name = "Correct";
        q.views = {w};
        q.config.startView = w.id;
        const auto issues = generate(q, [](std::string_view) { return false; });
        const auto has = [&](Id id, std::string_view text, Issue::Severity sev) {
            for (const auto& i : issues)
                if (i.object == id && i.severity == sev && i.message.find(text) != std::string::npos) return true;
            return false;
        };
        bool clean = true;
        for (const auto& i : issues) clean = clean && i.object != c;
        check(has(a, "onglet inconnu", Issue::Severity::Warning) && has(b, "de trop", Issue::Severity::Info) && clean,
              "G\xC3\xA9n\xC3\xA9rer : un onglet inconnu (avertissement), une action en double (info), rien sur l'objet correct");
        const fs::path dir = fs::temp_directory_path() / "hmi_test_lot10";
        fs::remove_all(dir);
        check(static_cast<bool>(save(q, dir.string())), "enregistrer l'objet Param\xC3\xA8tres syst\xC3\xA8me");
        auto back = load(dir.string());
        const Object* r = nullptr;
        if (back)
            for (const auto& bv : back->views)
                for (const auto& bo : bv.objects)
                    if (bo.name == "Onglet_Inconnu") r = &bo;
        check(r && r->kind == Kind::SystemButton && r->text("tab") == "Alarmes" && kFormatVersion >= 9,
              "relu : l'objet et son onglet (format 9 et suivants)");
        fs::remove_all(dir);
    }
    namespace g = hmi::guide;
    check(g::topic("parametres-systeme") && g::topicForKind("SystemButton") && !g::search("IHM_PARAMETRES_SYSTEME").empty(),
          "le guide : le menu Param\xC3\xA8tres syst\xC3\xA8me, la page de l'objet, IHM_PARAMETRES_SYSTEME");
}

// ------------------------------------------------ lot 10 : symboles de synoptique --
void synoptiqueLot10() {
    std::printf("lot 10 : les 24 symboles de synoptique (mod\xC3\xA8le, valeur, d\xC3\xA9" "faut, G\xC3\xA9n\xC3\xA9rer, disque)\n");
    const std::vector<std::pair<Kind, const char*>> all = {
        {Kind::Valve, "Vanne"}, {Kind::Pump, "Pompe"}, {Kind::Motor, "Moteur"}, {Kind::Pipe, "Tuyauterie"}, {Kind::Tank, "Cuve"},
        {Kind::GasBottle, "Bouteille de gaz"}, {Kind::Fan, "Ventilateur"}, {Kind::Compressor, "Compresseur"},
        {Kind::HeatExchanger, "\xC3\x89" "changeur"}, {Kind::Filter, "Filtre"}, {Kind::Boiler, "Chaudi\xC3\xA8re"}, {Kind::Conveyor, "Convoyeur"},
        {Kind::Cylinder, "V\xC3\xA9rin"}, {Kind::IsaInstrument, "Instrument ISA"}, {Kind::CircuitBreaker, "Disjoncteur"},
        {Kind::Disconnector, "Sectionneur"}, {Kind::Contactor, "Contacteur"}, {Kind::Lamp, "Lampe"}, {Kind::Transformer, "Transformateur"},
        {Kind::Silo, "Silo"}, {Kind::Hopper, "Tr\xC3\xA9mie"}, {Kind::Mixer, "M\xC3\xA9langeur"}, {Kind::CheckValve, "Clapet anti-retour"},
        {Kind::FlowArrow, "Fl\xC3\xA8" "che de flux"}};
    std::string wrong;
    std::size_t placeable = 0;
    for (const auto& [k, label] : all) {
        const Object o = makeObject(k, 1, "S", 0, 0, 1);
        placeable += std::count(std::begin(kPlaceableKinds), std::end(kPlaceableKinds), k);
        if (!kindIsSynoptic(k) || !kindShowsValue(k) || kindLabel(k) != label || kindFromKey(kindKey(k)) != k || !o.find("value")
            || !o.find("fault") || !o.find("colorFault") || !o.find("label") || !o.find("variable"))
            wrong += std::string(kindKey(k)) + " ";
    }
    check(all.size() == 24 && placeable == 24 && wrong.empty(),
          "24 symboles, tous dans la biblioth\xC3\xA8que : libell\xC3\xA9, cl\xC3\xA9, valeur, d\xC3\xA9" "faut, couleur de d\xC3\xA9" "faut, libell\xC3\xA9, variable " + wrong);
    check(!kindIsSynoptic(Kind::Button) && !kindIsSynoptic(Kind::SystemButton) && !kindIsSynoptic(Kind::QrCode), "... et rien d'autre");
    std::string levels;
    for (const auto& [k, label] : all) if (kindHasLevel(k)) levels += std::string(kindKey(k)) + " ";
    same(levels, "Tank GasBottle Cylinder Silo Hopper ", "un niveau entre min et max : cuve, bouteille, v\xC3\xA9rin, silo, tr\xC3\xA9mie");
    const Object valve = makeObject(Kind::Valve, 1, "V", 0, 0, 1), pipe = makeObject(Kind::Pipe, 1, "T", 0, 0, 1);
    const Object isa = makeObject(Kind::IsaInstrument, 1, "I", 0, 0, 1), gas = makeObject(Kind::GasBottle, 1, "B", 0, 0, 1);
    check(valve.text("valveType") == "manuelle" && pipe.text("pipeShape") == "droit" && pipe.number("thickness") == 14
              && isa.text("function") == "PT" && isa.text("loop") == "101" && isa.text("mounting") == "terrain"
              && gas.number("max") == 200 && gas.text("unit") == "bar" && !gas.text("gasColor").empty(),
          "leurs r\xC3\xA9glages : vanne manuelle, tube droit de 14, bulle PT 101 terrain, bouteille 0-200 bar");
    check(makeObject(Kind::Pump, 1, "P", 0, 0, 1).find("animate") && !valve.find("animate") && !isa.find("animate"),
          "\xC2\xAB Animer en marche \xC2\xBB : sur ce qui tourne ou coule seulement");

    // ---- en marche : la valeur vient de la variable ; le defaut, d'une expression
    Project p;
    p.programs.variables.push_back(hmiVar(p, "Niveau", "REAL", "42.0"));
    p.programs.variables.push_back(hmiVar(p, "Pompe_Marche", "BOOL", "TRUE"));
    View v = makeView(p, "Vue_Synoptique");
    const Id tank = edit::add(p, v, Kind::Tank, 10, 10);
    v.object(tank)->name = "Cuve_T1";
    v.object(tank)->set("variable", "Niveau");
    v.object(tank)->setExpr("fault", "Niveau > 40.0");
    const Id pump = edit::add(p, v, Kind::Pump, 200, 10);
    v.object(pump)->name = "P_101";
    v.object(pump)->set("variable", "Pompe_Marche");
    const Id isaId = edit::add(p, v, Kind::IsaInstrument, 300, 10);
    v.object(isaId)->name = "PT_101";
    v.object(isaId)->setExpr("value", "Niveau / 10.0");
    p.views = {v};
    p.config.startView = v.id;
    check(autoValueSource(*v.object(tank)) == "Niveau" && autoValueSource(*v.object(isaId)).empty(),
          "sans expression, la valeur est la variable ; avec, l'expression");
    Runtime rt;
    rt.bind(&p, nullptr);
    rt.start(0);
    rt.tick(0.1);
    LiveView lv;
    lv.bind(*rt.composedView(rt.currentView()));
    std::vector<LiveValue> values;
    const View shown = lv.evaluate(rt.environment(), &values, nullptr, 0.1);
    const auto* st = shown.object(tank);
    const auto* sp = shown.object(pump);
    const auto* si = shown.object(isaId);
    double lvl = 0, meas = 0;
    check(st && parseNumber(st->text("value"), lvl) && lvl == 42.0 && parseBool(st->text("fault"), false),
          "en marche : la cuve montre 42 (sa variable), son d\xC3\xA9" "faut est vrai (Niveau > 40)");
    check(sp && parseBool(sp->text("value"), false) && si && parseNumber(si->text("value"), meas) && std::fabs(meas - 4.2) < 1e-9,
          "la pompe : en marche ; la bulle ISA : Niveau / 10 = 4,2");
    sim::Value pv;
    check(rt.publicRead("Vue_Synoptique.Cuve_T1.Value", pv) && std::fabs(pv.asReal() - 42.0) < 1e-9,
          "variable d'instance : Vue_Synoptique.Cuve_T1.Value = 42");

    // ---- Generer
    {
        Project q;
        View w = makeView(q, "Vue_Check");
        const Id a = edit::add(q, w, Kind::Tank, 10, 10);
        w.object(a)->name = "Cuve_Inversee";
        w.object(a)->setNumber("min", 100);
        w.object(a)->setNumber("max", 0);
        const Id b = edit::add(q, w, Kind::Pipe, 10, 200);
        w.object(b)->name = "Tube_Plat";
        w.object(b)->setNumber("thickness", 0);
        const Id c = edit::add(q, w, Kind::IsaInstrument, 300, 10);
        w.object(c)->name = "Bulle_Vide";
        w.object(c)->set("function", " ");
        const Id d = edit::add(q, w, Kind::Pump, 400, 10);
        w.object(d)->name = "Pompe_Correcte";
        q.views = {w};
        q.config.startView = w.id;
        const auto issues = generate(q, [](std::string_view) { return false; });
        const auto has = [&](Id id, std::string_view text, Issue::Severity sev) {
            for (const auto& i : issues)
                if (i.object == id && i.severity == sev && i.message.find(text) != std::string::npos) return true;
            return false;
        };
        bool clean = true;
        for (const auto& i : issues) clean = clean && !(i.object == d && i.severity != Issue::Severity::Info);
        check(has(a, "minimum au-dessus du maximum", Issue::Severity::Error) && has(b, "paisseur nulle", Issue::Severity::Warning)
                  && has(c, "sans lettres ISA", Issue::Severity::Warning) && clean,
              "G\xC3\xA9n\xC3\xA9rer : bornes invers\xC3\xA9" "es (erreur), tube plat, bulle sans lettres (avertissements) ; rien sur la pompe");

        // ---- sur le disque : les 24, relus (format 9)
        Project r;
        View rv = makeView(r, "Vue_Disque");
        double y = 10;
        for (const auto& [k, label] : all) {
            const Id id = edit::add(r, rv, k, 10, y);
            y += 20;
            rv.object(id)->name = std::string("S_") + std::string(kindKey(k));
            rv.object(id)->set("label", label);
        }
        rv.object(rv.objects.front().id)->setExpr("fault", "Pompe_Marche");
        r.views = {rv};
        r.config.startView = rv.id;
        const fs::path dir = fs::temp_directory_path() / "hmi_test_lot10_synoptique";
        fs::remove_all(dir);
        check(static_cast<bool>(save(r, dir.string())), "enregistrer les 24 symboles");
        auto back = load(dir.string());
        std::size_t same24 = 0;
        bool faultKept = false;
        if (back)
            for (const auto& bv : back->views)
                for (const auto& bo : bv.objects) {
                    for (const auto& [k, label] : all)
                        if (bo.kind == k && bo.text("label") == label) ++same24;
                    if (const auto* f = bo.find("fault"); f && f->expr == "Pompe_Marche") faultKept = true;
                }
        check(same24 == 24 && faultKept, "relus : les 24 symboles, leur libell\xC3\xA9, l'expression de d\xC3\xA9" "faut");
        fs::remove_all(dir);
    }
    namespace g = hmi::guide;
    std::size_t pages = 0;
    for (const auto& [k, label] : all) pages += g::topicForKind(kindKey(k)) != nullptr;
    check(g::topic("synoptique") && pages == 24, "le guide : la page Les symboles de synoptique, et une page par symbole");
}

// ------------------------------------------------ lot 10 : SVG net et recolorable --
void svgLot10() {
    std::printf("lot 10 : le SVG \xC3\xA0 sa taille d'\xC3\xA9" "cran, recolori\xC3\xA9\n");
    const std::string text =
        "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 20 20\">"
        "<rect x=\"0\" y=\"0\" width=\"20\" height=\"20\" fill=\"#000000\"/>"
        "<circle cx=\"10\" cy=\"10\" r=\"5\" fill=\"#FF0000\"/></svg>";
    const Bytes svg(text.begin(), text.end());
    check(isSvgImage(svg, "") && isSvgImage(svg, "SVG") && !isSvgImage(Bytes{0x89, 'P', 'N', 'G', 13, 10, 26, 10}, ""), "reconna\xC3\xAEtre un SVG");
    const auto at = [](const Rgba& img, int x, int y) {
        const std::size_t i = (static_cast<std::size_t>(y) * static_cast<std::size_t>(img.width) + static_cast<std::size_t>(x)) * 4;
        return (static_cast<std::uint32_t>(img.pixels[i]) << 16) | (static_cast<std::uint32_t>(img.pixels[i + 1]) << 8) | img.pixels[i + 2];
    };
    Rgba small, big;
    check(rasterizeSvg(svg, 20, 20, small) && rasterizeSvg(svg, 400, 400, big) && small.width == 20 && big.width == 400 && big.height == 400,
          "le m\xC3\xAAme SVG, rasteris\xC3\xA9 \xC3\xA0 20 et \xC3\xA0 400 pixels (sa taille \xC3\xA0 l'\xC3\xA9" "cran)");
    check(at(big, 200, 200) == 0xFF0000u && at(big, 10, 10) == 0x000000u && at(big, 200, 90) == 0x000000u && at(big, 200, 115) == 0xFF0000u,
          "\xC3\xA0 400 pixels : le disque rouge net, le fond noir autour (le bord \xC3\xA0 sa place : 100 px du centre)");
    Rgba wide;
    check(rasterizeSvg(svg, 200, 50, wide) && wide.width == 200 && wide.height == 50 && at(wide, 100, 25) == 0xFF0000u && at(wide, 30, 25) == 0x000000u,
          "\xC3\xA9tir\xC3\xA9 (200 x 50) : le disque devient une ellipse, au centre");
    SvgRecolor rc;
    rc.active = true;
    rc.rgb = 0x2ECC71;
    Rgba all;
    check(rasterizeSvg(svg, 40, 40, all, &rc) && at(all, 20, 20) == 0x2ECC71u && at(all, 2, 2) == 0x2ECC71u, "recolori\xC3\xA9 \xC2\xAB tout \xC2\xBB : le fond et le disque verts");
    rc.mode = "une couleur";
    rc.from = 0xFF0000;
    Rgba one;
    check(rasterizeSvg(svg, 40, 40, one, &rc) && at(one, 20, 20) == 0x2ECC71u && at(one, 2, 2) == 0x000000u,
          "\xC2\xAB une couleur \xC2\xBB (le rouge) : seul le disque devient vert");
    rc.mode = "contours";
    Rgba strokes;
    check(rasterizeSvg(svg, 40, 40, strokes, &rc) && at(strokes, 20, 20) == 0xFF0000u, "\xC2\xAB contours \xC2\xBB : ce SVG sans contour garde ses couleurs");
    Rgba bad;
    std::string why;
    check(!rasterizeSvg(Bytes{'x', 'y'}, 10, 10, bad, nullptr, &why) && !why.empty() && !rasterizeSvg(svg, 0, 10, bad),
          "un contenu illisible, une taille nulle : refus\xC3\xA9s (" + why + ")");
    const Object img = makeObject(Kind::Image, 1, "I", 0, 0, 1), anim = makeObject(Kind::AnimatedImage, 1, "A", 0, 0, 1);
    check(img.find("recolor") && img.text("recolorMode") == "tout" && img.text("recolorFrom") == "#000000" && anim.find("recolor"),
          "l'image et l'image anim\xC3\xA9" "e : Recolorier (vide), tout, #000000");
}

// ------------------------------------------------ lot 10 : symboles reutilisables --
void symbolesLot10() {
    std::printf("lot 10 : les symboles r\xC3\xA9utilisables param\xC3\xA9tr\xC3\xA9s (faceplates)\n");
    // ---- le genre, le role
    check(kindKey(Kind::SymbolInstance) == "SymbolInstance" && kindLabel(Kind::SymbolInstance) == "Instance de symbole"
              && kindFromKey("SymbolInstance") == Kind::SymbolInstance,
          "le genre Instance de symbole (cl\xC3\xA9 SymbolInstance)");
    check(std::find(std::begin(kPlaceableKinds), std::end(kPlaceableKinds), Kind::SymbolInstance) == std::end(kPlaceableKinds),
          "pas dans la palette des genres : elle se pose depuis les symboles du projet");
    {
        const Object o = makeObject(Kind::SymbolInstance, 1, "I", 10, 20, 1);
        check(o.find("symbol") && o.text("params").empty() && o.number("w") == 160 && o.flag("visible", false),
              "une instance neuve : symbole et arguments vides, 160 x 100, visible");
    }
    check(std::find(std::begin(kViewRoles), std::end(kViewRoles), "symbole") != std::end(kViewRoles) && viewRoleLabel("symbole") == "Symbole"
              && viewRoleFromLabel("Symbole") == "symbole" && viewFolderOf("symbole") == ViewFolder::Symbols
              && viewFolderOf("vue") == ViewFolder::Views,
          "le r\xC3\xB4le Symbole : son dossier \xC3\xA0 lui (IHM > Symboles)");

    // ---- les remplacements
    const SymbolArguments args{{"Armoire", "Armoires[1]"}, {"Nom", "'B'"}, {"K", "a + b"}, {"T", "5"}};
    same(substituteParams("Armoire.ana.PT1.mes > 10", args), "Armoires[1].ana.PT1.mes > 10", "un chemin : Armoire.x devient Armoires[1].x");
    same(substituteParams("armoire.actif AND NOT ARMOIRE.defaut", args), "Armoires[1].actif AND NOT Armoires[1].defaut", "sans casse, comme le ST");
    same(substituteParams("Pompe.Armoire + Armoire2", args), "Pompe.Armoire + Armoire2", "un membre (x.Armoire) et un autre nom ne bougent pas");
    same(substituteParams("'Armoire' + \"Nom\" (* Armoire *)", args), "'Armoire' + \"Nom\" (* Armoire *)", "cha\xC3\xAEnes et commentaires tels quels");
    same(substituteParams("K * 2", args), "(a + b) * 2", "un calcul pass\xC3\xA9 en argument : entre parenth\xC3\xA8ses");
    same(substituteParams("Nom", args), "'B'", "une cha\xC3\xAEne pass\xC3\xA9" "e en argument : telle quelle");
    same(substituteParams("T#5s + T", args), "T#5s + 5", "un litt\xC3\xA9ral typ\xC3\xA9 (T#5s) n'est pas le param\xC3\xA8tre T");
    same(substituteParams("LIMIT(MN := T, IN := K, MX := 9)", args), "LIMIT(MN := 5, IN := (a + b), MX := 9)",
         "le nom d'un argument d'appel (MN :=) reste, sa valeur se relie");
    same(substituteParams("Armoire.actif := NOT Armoire.actif;\nIHM_JOURNAL('Armoire ' + Nom);", args, true),
         "Armoires[1].actif := NOT Armoires[1].actif;\nIHM_JOURNAL('Armoire ' + 'B');",
         "du ST : l'affectation \xC3\xA9" "crit \xC3\xA0 travers le param\xC3\xA8tre");
    same(substituteInTemplate("Armoire {Nom} : {Armoire.ana.PT1.mes:0.0} bar {{x}}", args),
         "Armoire {'B'} : {Armoires[1].ana.PT1.mes:0.0} bar {{x}}", "un texte \xC3\xA0 trous : chaque trou, son format gard\xC3\xA9");
    same(resolveLiteralHoles("Armoire {'B'} : {Armoires[1].ana.PT1.mes:0.0} bar {'{a'}"), "Armoire B : {Armoires[1].ana.PT1.mes:0.0} bar {{a",
         "un trou qui n'est qu'une cha\xC3\xAEne devient son texte (accolades doubl\xC3\xA9" "es)");
    same(replacePath("Armoires[0].ana.PT1.mes + Armoires[ 0 ].actif + Armoires[1].x + Armoires[0] + 'Armoires[0]'", "Armoires[0]", "Armoire"),
         "Armoire.ana.PT1.mes + Armoire.actif + Armoires[1].x + Armoire + 'Armoires[0]'",
         "cr\xC3\xA9" "er un symbole : Armoires[0] devient Armoire (Armoires[1] et les cha\xC3\xAEnes, non)");
    same(replacePath("Moteur_2 + Moteur.x", "Moteur", "M"), "Moteur_2 + M.x", "un chemin sans index : le nom entier seulement");

    // ---- creer un symbole depuis une selection
    Project p;
    View host = makeView(p, "Vue_Armoires");
    const Id hostId = host.id;
    const auto put = [&](Kind k, const std::string& name, double x, double y, double w, double h) -> Id {
        Object o = makeObject(k, p.allocate(), name, x, y, host.activeLayer);
        o.setNumber("w", w);
        o.setNumber("h", h);
        host.objects.push_back(std::move(o));
        return host.objects.back().id;
    };
    const Id cadre = put(Kind::Rectangle, "Cadre", 100, 50, 200, 120);
    const Id titre = put(Kind::Text, "Titre", 110, 55, 180, 24);
    host.object(titre)->set("text", "Armoire A : {Armoires[0].ana.PT1.mes:0.0} bar");
    const Id voyant = put(Kind::Indicator, "Voyant", 120, 90, 30, 30);
    host.object(voyant)->setExpr("value", "Armoires[0].actif");
    const Id bouton = put(Kind::Button, "Bouton", 160, 130, 120, 30);
    {
        Action a;
        a.trigger = Trigger::Click;
        a.operation = Operation::Toggle;
        a.target = "Armoires[0].actif";
        host.object(bouton)->actions.push_back(a);
        Action pop;
        pop.trigger = Trigger::DoubleClick;
        pop.operation = Operation::Popup;
        pop.target = "Popup_Armoire";
        pop.value = "Armoire := Armoires[0]; Nom := 'A'";
        host.object(bouton)->actions.push_back(pop);
    }
    const Id autre = put(Kind::Ellipse, "Autre", 600, 400, 50, 50);
    p.views.push_back(std::move(host));
    same(suggestSymbolParams(*p.view(hostId), {cadre, titre, voyant, bouton}), "Armoire := Armoires[0]",
         "les param\xC3\xA8tres propos\xC3\xA9s : un par chemin index\xC3\xA9 lu (Armoires[0] -> Armoire)");
    Id inst = kNoId;
    std::string why;
    check(!createSymbol(p, hostId, {}, "Carte", "", &inst, &why) && !why.empty(), "rien de choisi : refus\xC3\xA9 (" + why + ")");
    check(!createSymbol(p, hostId, {cadre}, "1carte", "", &inst, &why), "un nom invalide : refus\xC3\xA9 (" + why + ")");
    check(!createSymbol(p, hostId, {cadre}, "Vue_Armoires", "", &inst, &why), "un nom d\xC3\xA9j\xC3\xA0 pris : refus\xC3\xA9 (" + why + ")");
    check(createSymbol(p, hostId, {cadre, titre, voyant, bouton}, "Carte_Armoire", "Armoire := Armoires[0]; Nom := 'A'", &inst, &why),
          "Cr\xC3\xA9" "er un symbole : Carte_Armoire, param\xC3\xA8tres Armoire et Nom" + (why.empty() ? std::string{} : " (" + why + ")"));
    const View* sym = p.viewByName("Carte_Armoire");
    check(sym && isSymbolView(*sym) && sym->width == 200 && sym->height == 120 && sym->objects.size() == 4 && sym->params.size() == 2
              && sym->params[0].name == "Armoire" && sym->params[0].defaultValue == "Armoires[0]",
          "le symbole : une vue de r\xC3\xB4le symbole, \xC3\xA0 la taille de la s\xC3\xA9lection (200 x 120), ses 4 objets, ses 2 param\xC3\xA8tres");
    {
        const Object* t = sym ? sym->objectByName("Titre") : nullptr;
        const Object* v = sym ? sym->objectByName("Voyant") : nullptr;
        const Object* b = sym ? sym->objectByName("Bouton") : nullptr;
        check(t && t->text("text") == "Armoire A : {Armoire.ana.PT1.mes:0.0} bar" && v && v->expr("value") == "Armoire.actif" && b
                  && b->actions[0].target == "Armoire.actif" && b->actions[1].value == "Armoire := Armoire; Nom := 'A'",
              "dans le symbole, Armoires[0] est devenu Armoire (textes, expressions, actions, arguments d'une popup)");
        check(t && t->number("x") == 10 && t->number("y") == 5 && sym->objectByName("Cadre")->number("x") == 0,
              "les objets \xC3\xA0 la place qu'ils avaient dans la s\xC3\xA9lection (rep\xC3\xA8re du symbole)");
    }
    const View* hv = p.view(hostId);
    const Object* io = hv ? hv->object(inst) : nullptr;
    check(hv && hv->objects.size() == 2 && io && io->kind == Kind::SymbolInstance && io->text("symbol") == "Carte_Armoire"
              && io->text("params").empty() && io->box() == (Box{100, 50, 200, 120}) && hv->object(autre) && hv->indexOf(inst) == 0,
          "dans la vue : une instance \xC3\xA0 la place de la s\xC3\xA9lection (m\xC3\xAAme cadre, m\xC3\xAAme rang), l'autre objet gard\xC3\xA9");
    check(!createSymbol(p, hostId, {autre}, "Carte_Armoire", "", nullptr, &why), "le m\xC3\xAAme nom deux fois : refus\xC3\xA9");

    // ---- l'expansion
    {
        const Expansion e = expandInstance(p, *io);
        const auto find = [&](const std::string& n) -> const Object* {
            for (const auto& o : e.objects) if (o.name == n) return &o;
            return nullptr;
        };
        const Object* t = find(io->name + ".Titre");
        const Object* b = find(io->name + ".Bouton");
        check(e.objects.size() == 4 && t && b && t->id == expandedId(inst, sym->objectByName("Titre")->id) && (t->id & 0x80000000u) != 0,
              "d\xC3\xA9velopp\xC3\xA9" "e : 4 objets, nomm\xC3\xA9s Instance.Objet, identifiants d\xC3\xA9riv\xC3\xA9s (bit haut)");
        check(t && t->text("text") == "Armoire A : {Armoires[0].ana.PT1.mes:0.0} bar" && b && b->actions[0].target == "Armoires[0].actif"
                  && b->actions[1].value == "Armoire := Armoires[0]; Nom := 'A'",
              "sans argument : les valeurs par d\xC3\xA9" "faut (l'instance montre ce que montrait la s\xC3\xA9lection)");
        check(t && t->box() == (Box{110, 55, 180, 24}) && t->parent == inst && t->layer == io->layer, "\xC3\xA0 l'\xC3\xA9" "chelle 1 : chaque objet \xC3\xA0 sa place d'origine, rattach\xC3\xA9 \xC3\xA0 l'instance");
        const Expansion again = expandInstance(p, *io);
        check(again.objects.size() == e.objects.size() && again.objects[1].id == e.objects[1].id, "deux expansions : les m\xC3\xAAmes identifiants");
    }
    // Une seconde instance : Armoires[1], 'B', deux fois plus grande, tournee d'un quart de tour.
    p.viewByName("Carte_Armoire")->objectByName("Titre")->set("text", "Armoire {Nom} : {Armoire.ana.PT1.mes:0.0} bar");
    Id second = kNoId;
    {
        View* h = p.view(hostId);
        second = placeSymbol(p, *h, "Carte_Armoire", 500, 50);
        check(second != kNoId && h->object(second)->number("w") == 200 && h->object(second)->name == "Carte_Armoire_2"
                  && placeSymbol(p, *h, "Vue_Armoires", 0, 0) == kNoId,
              "poser une instance : \xC3\xA0 la taille du symbole, nomm\xC3\xA9" "e d'apr\xC3\xA8s lui ; une vue ordinaire n'est pas un symbole");
        Object& o2 = *h->object(second);
        o2.set("params", "Armoire := Armoires[1]; Nom := 'B'");
        o2.setNumber("w", 400);
        o2.setNumber("h", 240);
    }
    {
        const Object& o2 = *p.view(hostId)->object(second);
        const Expansion e = expandInstance(p, o2);
        const Object* t = nullptr;
        const Object* v = nullptr;
        for (const auto& o : e.objects) {
            if (o.name == o2.name + ".Titre") t = &o;
            if (o.name == o2.name + ".Voyant") v = &o;
        }
        check(t && t->text("text") == "Armoire B : {Armoires[1].ana.PT1.mes:0.0} bar" && v && v->expr("value") == "Armoires[1].actif",
              "ses arguments : Armoire := Armoires[1], Nom := 'B' ({Nom} devient B)");
        check(t && t->box() == (Box{520, 60, 360, 48}) && t->number("fontSize") == 32, "deux fois plus grande : cadres et texte \xC3\xA0 l'\xC3\xA9" "chelle");
    }
    {
        View* h = p.view(hostId);
        h->object(second)->setNumber("rot", 90);
        const Object& o2 = *h->object(second);
        const Expansion e = expandInstance(p, o2);
        const Object* cad = nullptr;
        for (const auto& o : e.objects) if (o.name == o2.name + ".Cadre") cad = &o;
        // Le cadre remplit l'instance : son centre reste au centre, il tourne avec elle.
        check(cad && std::fabs(cad->box().cx() - 700) < 1e-6 && std::fabs(cad->box().cy() - 170) < 1e-6 && cad->rotation() == 90,
              "tourn\xC3\xA9" "e de 90\xC2\xB0 : chaque objet tourne autour du centre de l'instance");
        h->object(second)->setNumber("rot", 0);
        h->object(second)->setFlag("flipH", true);
        const Expansion f = expandInstance(p, *h->object(second));
        const Object* tt = nullptr;
        for (const auto& o : f.objects) if (o.name == o2.name + ".Titre") tt = &o;
        // Le titre (x 20..380 dans l'instance de 400) : retourne, il va de 20 a 380 en partant de la droite.
        check(tt && std::fabs(tt->box().x - (500 + 400 - 20 - 360)) < 1e-6 && tt->flipH(), "retourn\xC3\xA9" "e : les objets en miroir dans son cadre");
        h->object(second)->setFlag("flipH", false);
        h->object(second)->setExpr("visible", "Montrer");
        h->object(second)->setNumber("opacity", 50);
        const Expansion g = expandInstance(p, *h->object(second));
        check(!g.objects.empty() && g.objects[0].expr("visible") == "Montrer" && g.objects[0].number("opacity") == 50,
              "sa visibilit\xC3\xA9 (expression) et son opacit\xC3\xA9 passent \xC3\xA0 ses objets");
        h->object(second)->setExpr("visible", {});
        h->object(second)->setNumber("opacity", 100);
    }
    {
        const View ex = expandInstances(p, *p.view(hostId));
        check(ex.objects.size() == 3 + 8 && ex.objects[0].id == inst && ex.objects[1].parent == inst && ex.objects[5].id == autre,
              "la vue d\xC3\xA9velopp\xC3\xA9" "e : chaque instance suivie de ses objets, le reste \xC3\xA0 sa place");
        std::set<Id> ids;
        for (const auto& o : ex.objects) ids.insert(o.id);
        check(ids.size() == ex.objects.size(), "aucun identifiant en double");
        check(usesSymbols(p, *p.view(hostId)) && !usesSymbols(p, *sym) && instancesOf(p, "Carte_Armoire").size() == 2
                  && symbolsOf(p).size() == 1,
              "usesSymbols, instancesOf, symbolsOf");
    }
    // ---- des symboles dans des symboles, et la boucle
    {
        Project q;
        View a = makeView(q, "A");
        a.role = "symbole";
        a.width = 100;
        a.height = 50;
        a.params = {{"X", "Var_1", ""}};
        Object r = makeObject(Kind::Rectangle, q.allocate(), "R", 0, 0, a.activeLayer);
        r.setNumber("w", 100);
        r.setNumber("h", 50);
        r.setExpr("visible", "X");
        a.objects.push_back(r);
        View b = makeView(q, "B");
        b.role = "symbole";
        b.width = 200;
        b.height = 50;
        b.params = {{"Y", "Var_2", ""}};
        for (int i = 0; i < 2; ++i) {
            Object in = makeObject(Kind::SymbolInstance, q.allocate(), "In_" + std::to_string(i + 1), i * 100, 0, b.activeLayer);
            in.setNumber("w", 100);
            in.setNumber("h", 50);
            in.set("symbol", "A");
            in.set("params", "X := Y");
            b.objects.push_back(in);
        }
        View v = makeView(q, "Vue");
        Object top = makeObject(Kind::SymbolInstance, q.allocate(), "Haut", 10, 10, v.activeLayer);
        top.setNumber("w", 200);
        top.setNumber("h", 50);
        top.set("symbol", "B");
        top.set("params", "Y := Pompes[3].Marche");
        v.objects.push_back(top);
        q.views.push_back(a);
        q.views.push_back(b);
        q.views.push_back(v);
        const View shown = expandInstances(q, q.views[2]);
        const Object* deep = nullptr;
        for (const auto& o : shown.objects) if (o.name == "Haut.In_2.R") deep = &o;
        check(shown.objects.size() == 1 + 2 + 2 && deep && deep->expr("visible") == "Pompes[3].Marche" && deep->box() == (Box{110, 10, 100, 50}),
              "un symbole dans un symbole : Haut.In_2.R reli\xC3\xA9 de proche en proche (X := Y := Pompes[3].Marche), \xC3\xA0 sa place");
        check(symbolContains(q, q.views[1], "A") && !symbolContains(q, q.views[0], "B"), "symbolContains : B contient A, pas l'inverse");
        Object loop = makeObject(Kind::SymbolInstance, q.allocate(), "Boucle", 0, 0, q.views[0].activeLayer);
        loop.set("symbol", "B");
        q.views[0].objects.push_back(loop);
        check(symbolContains(q, q.views[0], "A"), "A contient B qui contient A : la boucle se voit");
        const View looped = expandInstances(q, q.views[2]);
        check(looped.objects.size() < 200, "... et l'expansion s'arr\xC3\xAAte (" + std::to_string(looped.objects.size()) + " objets)");
        const auto issues = generate(q, {}, {});
        bool loopSaid = false, pumpSaid = false;
        for (const auto& i : issues) {
            loopSaid = loopSaid || (i.category == "Symbole" && i.message.find("se contient") != std::string::npos);
            pumpSaid = pumpSaid || i.message.find("Pompes") != std::string::npos;
        }
        check(loopSaid && !pumpSaid, "G\xC3\xA9n\xC3\xA9rer dit la boucle (sans automate, les variables ne sont pas v\xC3\xA9rifi\xC3\xA9" "es)");
    }
    // ---- Generer
    {
        View* h = p.view(hostId);
        Object* o2 = h->object(second);
        o2->set("params", "Armoire := Armoires[1]; Nom := 'B'; Couleur := 'rouge'");
        Object ghost = makeObject(Kind::SymbolInstance, p.allocate(), "Fantome", 0, 0, h->activeLayer);
        ghost.set("symbol", "Carte_Disparue");
        h->objects.push_back(ghost);
        Object wrong = makeObject(Kind::SymbolInstance, p.allocate(), "Mauvais", 0, 0, h->activeLayer);
        wrong.set("symbol", "Vue_Armoires");
        h->objects.push_back(wrong);
        View unused = makeView(p, "Symbole_Seul");
        unused.role = "symbole";
        unused.params = {{"Sans", "", ""}};
        p.views.push_back(unused);
        // 1.11.18 : ajouter une vue peut deplacer les vues du projet - h et o2 se relisent (avant :
        // un pointeur perdu, qui plantait selon la place des vues en memoire).
        h = p.view(hostId);
        o2 = h->object(second);
        const auto issues = generate(p, [](std::string_view n) { return n == "Armoires" || n == "Montrer"; }, {});
        const auto said = [&](const std::string& what) {
            for (const auto& i : issues) if (i.message.find(what) != std::string::npos) return true;
            return false;
        };
        check(said("symbole introuvable : Carte_Disparue") && said("Vue_Armoires n'est pas un symbole") && said("argument Couleur : Carte_Armoire n'a pas (ou plus) ce param")
                  && said("symbole pos\xC3\xA9 nulle part"),
              "G\xC3\xA9n\xC3\xA9rer : symbole introuvable, pas un symbole, argument inconnu, symbole pos\xC3\xA9 nulle part");
        o2->set("params", "Armoire := Cuves[1]");
        const auto again = generate(p, [](std::string_view n) { return n == "Armoires" || n == "Montrer"; }, {});
        bool unknownVar = false;
        for (const auto& i : again) unknownVar = unknownVar || i.message.find("argument Armoire : variable inexistante dans le programme : Cuves") != std::string::npos;
        check(unknownVar, "G\xC3\xA9n\xC3\xA9rer : l'argument d'une instance cite une variable inexistante");
        o2->set("params", "Armoire := Armoires[1]; Nom := 'B'");
        std::erase_if(h->objects, [](const Object& x) { return x.name == "Fantome" || x.name == "Mauvais"; });
        std::erase_if(p.views, [](const View& x) { return x.name == "Symbole_Seul"; });
    }
    // ---- renommer, enregistrer, relire
    check(renameSymbol(p, "Carte_Armoire", "Carte_Gaz") == 2 && p.view(hostId)->object(inst)->text("symbol") == "Carte_Gaz",
          "renommer un symbole : ses deux instances suivent");
    p.viewByName("Carte_Armoire")->name = "Carte_Gaz";
    {
        const auto dir = std::filesystem::temp_directory_path() / "xpg_symboles_lot10";
        std::filesystem::remove_all(dir);
        check(static_cast<bool>(save(p, dir.string())), "enregistr\xC3\xA9");
        auto back = load(dir.string());
        check(back && back->viewByName("Carte_Gaz") && back->viewByName("Carte_Gaz")->role == "symbole"
                  && back->viewByName("Carte_Gaz")->params.size() == 2 && back->view(hostId)->object(second)->text("params") == "Armoire := Armoires[1]; Nom := 'B'"
                  && back->view(hostId)->object(second)->kind == Kind::SymbolInstance && back->views == p.views,
              "relu \xC3\xA0 l'identique : le symbole (r\xC3\xB4le, param\xC3\xA8tres) et ses instances (arguments)");
        std::filesystem::remove_all(dir);
    }
    // ---- en marche : l'exemple (trois cartes, trois moteurs)
    {
        auto ex = examples::exampleFor(Kind::SymbolInstance);
        check(ex.has_value() && ex->project.views.size() == 2 && isSymbolView(ex->project.views[1]), "l'exemple : une vue, un symbole");
        if (ex) {
            Runtime rt;
            rt.bind(&ex->project, nullptr);
            rt.start(0.0);
            double played = 0;
            std::size_t errors = 0, steps = 0;
            std::string at2, at5, at9, speed;
            for (double t = 0.05; t <= ex->period + 1e-9; t += 0.05) {
                rt.tick(t);
                steps += examples::play(*ex, rt, played, t, t);
                played = t;
                LiveView lv;
                lv.bind(*rt.composedView(rt.currentView()));
                std::vector<LiveValue> vals;
                const View live = lv.evaluate(rt.environment(), &vals, rt.viewScope(rt.currentView()), t);
                for (const auto& v : vals) errors += v.error;
                const auto on = [&](const char* n) { return rt.variable(n) && rt.variable(n)->isTruthy() ? '1' : '0'; };
                if (std::fabs(t - 2.0) < 0.025) at2 = {on("Marche_1"), on("Marche_2"), on("Marche_3")};
                if (std::fabs(t - 5.0) < 0.025) {
                    at5 = {on("Marche_1"), on("Marche_2"), on("Marche_3")};
                    if (const auto* o = live.objectByName("Carte_2.Bouton")) speed = o->text("text");
                }
                if (std::fabs(t - 9.0) < 0.025) at9 = {on("Marche_1"), on("Marche_2"), on("Marche_3")};
            }
            for (const auto& e : rt.journal()) errors += e.kind == "Erreur";
            check(errors == 0 && steps == ex->steps.size(), "l'exemple tourne sans erreur, chaque geste jou\xC3\xA9");
            check(at2 == "100" && at5 == "111" && at9 == "010", "le bouton de chaque carte bascule SA variable (\xC3\xA0 2 s : M1 ; 5 s : les trois ; 9 s : M2)");
            same(speed, "Arr\xC3\xAAter", "le texte du bouton de la carte 2 suit Marche_2 (en marche : \xC2\xAB Arr\xC3\xAAter \xC2\xBB)");
            const View* shown = rt.composedView(rt.currentView());
            check(shown && shown->objectByName("Carte_3.Moteur") && shown->objectByName("Carte_3.Moteur")->expr("value") == "Marche_3",
                  "la vue qui tourne porte les objets des instances, reli\xC3\xA9s");
        }
    }
    // ---- un clic sur un objet de l'instance sans action : les actions de l'instance
    {
        auto ex = examples::exampleFor(Kind::SymbolInstance);
        if (ex) {
            View& v = ex->project.views[0];
            Object* c1 = v.objectByName("Carte_1");
            Action a;
            a.trigger = Trigger::Click;
            a.operation = Operation::Set;
            a.target = "Marche_3";
            c1->actions.push_back(a);
            Runtime rt;
            rt.bind(&ex->project, nullptr);
            rt.start(0.0);
            rt.tick(0.1);
            const View* shown = rt.composedView(v.id);
            const Object* moteur = shown ? shown->objectByName("Carte_1.Moteur") : nullptr;
            const Object* boutonCarte = shown ? shown->objectByName("Carte_1.Bouton") : nullptr;
            if (moteur && boutonCarte) {
                // (Les identifiants d'abord : un clic refait la vue composee, les pointeurs tombent.)
                const Id moteurId = moteur->id, boutonId = boutonCarte->id;
                rt.press(moteurId, 0.2);
                rt.release(moteurId, 0.25, true);
                const bool m3 = rt.variable("Marche_3")->isTruthy();
                rt.press(boutonId, 0.3);
                rt.release(boutonId, 0.35, true);
                check(m3 && rt.variable("Marche_1")->isTruthy(),
                      "clic sur le moteur de la carte (sans action) : l'action de l'instance (Marche_3) ; sur son bouton : la sienne (Marche_1)");
            } else {
                check(false, "les objets de Carte_1 dans la vue qui tourne");
            }
        }
    }
    // ---- l'aide
    {
        namespace g = hmi::guide;
        const auto* page = g::topicForKind("SymbolInstance");
        check(g::topic("symboles") && page && page->key == "objet-instance-de-symbole" && g::topicForPlace("symboles") == "symboles"
                  && !g::paramHelp("SymbolInstance", "params").empty() && !g::paramHelp("SymbolInstance", "symbol").empty(),
              "le guide : Les symboles r\xC3\xA9utilisables (F1 sur IHM > Symboles), la page Instance de symbole et ses param\xC3\xA8tres");
    }
}

// ------------------------------------------------------ fin du lot 10 --

// ------------------------------------------------ lot 11 : graphiques --
namespace {
// Un nom de fichier temporaire propre au lot 11.
fs::path lot11Temp(const char* name) {
    const fs::path dir = fs::temp_directory_path() / "hmi_test_lot11";
    fs::create_directories(dir);
    return dir / name;
}
std::string lot11Text(const Bytes& b) { return std::string(b.begin(), b.end()); }
// La valeur d'une variable IHM, en nombre (NaN : absente).
double lot11Number(Runtime& rt, const char* name) {
    const auto* v = rt.variable(name);
    return v ? v->asReal() : std::nan("");
}
sim::Value lot11Sys(Runtime& rt, const char* name) {
    sim::Value out;
    (void)rt.publicRead(std::string("SYS.") + name, out);
    return out;
}
// L'objet evalue comme a l'ecran (LiveView), a l'instant t.
Object lot11Live(Runtime& rt, Id object, double t) {
    LiveView lv;
    lv.bind(*rt.composedView(rt.currentView()));
    const View shown = lv.evaluate(rt.environment(), nullptr, rt.viewScope(rt.currentView()), t);
    const auto* o = shown.object(object);
    return o ? *o : Object{};
}
} // namespace

void graphiquesLot11() {
    std::printf("lot 11 : les graphiques (barres, courbe XY, chronogramme, camembert, radar, histogramme)\n");
    // ---- les six objets neufs
    const Kind charts[] = {Kind::BarChart, Kind::XYChart, Kind::StateChart, Kind::PieChart, Kind::RadarChart, Kind::Histogram};
    bool allCharts = true;
    for (const auto k : charts) {
        allCharts = allCharts && kindIsChart(k) && !kindIsAlarmView(k);
        allCharts = allCharts && std::find(std::begin(kPlaceableKinds), std::end(kPlaceableKinds), k) != std::end(kPlaceableKinds);
    }
    check(allCharts && !kindIsChart(Kind::Trend) && !kindIsChart(Kind::AlarmBanner) && !kindIsChart(Kind::Table),
          "six graphiques dans la biblioth\xC3\xA8que (la courbe reste \xC3\xA0 part)");
    std::string labels;
    for (const auto k : charts) labels += (labels.empty() ? "" : " | ") + std::string(kindLabel(k));
    same(labels,
         "Graphique en barres | Courbe XY | Chronogramme d'\xC3\xA9tats | Camembert | Radar | Histogramme", "leurs noms");
    {
        const auto bar = makeObject(Kind::BarChart, 1, "B", 0, 0, 1);
        const auto xy = makeObject(Kind::XYChart, 2, "X", 0, 0, 1);
        const auto st = makeObject(Kind::StateChart, 3, "S", 0, 0, 1);
        const auto hist = makeObject(Kind::Histogram, 4, "H", 0, 0, 1);
        check(bar.box().w == 420 && bar.box().h == 260 && bar.text("orientation") == "verticale" && bar.text("scale") == "fixe"
                  && bar.number("max") == 100 && bar.text("variables").empty() && bar.find("colorAlarm"),
              "un graphique en barres neuf : 420 x 260, vertical, \xC3\xA9" "chelle fixe 0-100, sans valeur");
        check(xy.number("maxPoints") == 300 && xy.text("interpolation") == "lin\xC3\xA9" "aire" && xy.find("reference") && xy.find("tolerance")
                  && xy.find("reset"),
              "une courbe XY : 300 points, sa r\xC3\xA9" "f\xC3\xA9rence, sa tol\xC3\xA9rance, sa remise \xC3\xA0 z\xC3\xA9ro");
        check(st.number("duration") == 60 && st.text("stateList").find("1 = Marche") != std::string::npos,
              "un chronogramme : 60 s, Arr\xC3\xAAt et Marche");
        check(hist.number("bins") == 10 && hist.number("samplePeriod") == 1000 && hist.number("maxSamples") == 5000
                  && hist.flag("showStats", false),
              "un histogramme : 10 classes, une mesure par seconde, ses statistiques");
    }

    // ---- la liste des elements (expressions, noms, couleurs)
    {
        Object o = makeObject(Kind::BarChart, 1, "B", 0, 0, 1);
        o.set("variables", "Cuve_1; Cuve_2;; Cuve_3 ");
        o.set("names", "Cuve 1;;Vide;Cuve 3");
        o.set("colors", "#111111");
        const auto items = chartItems(o);
        check(items.size() == 3 && items[0].expression == "Cuve_1" && items[0].name == "Cuve 1" && items[0].color == "#111111"
                  && items[1].expression == "Cuve_2" && items[1].name.empty() && items[1].color == chartPalette()[1]
                  && items[2].expression == "Cuve_3" && items[2].name == "Cuve 3" && items[2].color == chartPalette()[2],
              "trois \xC3\xA9l\xC3\xA9ments (le vide est saut\xC3\xA9) ; noms et couleurs \xC3\xA0 leur rang, la palette sinon");
        same(chartItemLabel(items[1]), "Cuve_2", "sans nom : l'expression");
        Object r = makeObject(Kind::RadarChart, 2, "R", 0, 0, 1);
        r.set("variables", "A;B;C");
        r.set("references", "50; 60 ;70");
        const auto refs = chartItems(r, "references");
        check(refs.size() == 3 && refs[1].expression == "60", "la consigne d'un radar : sa propre liste");
        same(joinLiveValues({"1.5", "a;b", "###"}), std::string("1.5") + kLiveSeparator + "a;b" + kLiveSeparator + "###",
             "les valeurs \xC3\xA9valu\xC3\xA9" "es, s\xC3\xA9par\xC3\xA9" "es par 0x1F (une valeur peut contenir un ;)");
        const auto back = splitLiveValues(joinLiveValues({"1.5", "a;b", "###"}));
        check(back.size() == 3 && back[1] == "a;b" && back[2] == "###", "... et relues");
        const auto nums = liveNumbers(joinLiveValues({"TRUE", "2.5", "###", "FALSE"}));
        check(nums.size() == 4 && nums[0] && *nums[0] == 1.0 && nums[1] && *nums[1] == 2.5 && !nums[2] && nums[3] && *nums[3] == 0.0,
              "en nombres : TRUE 1, 2.5, ### illisible, FALSE 0");
    }

    // ---- le camembert
    {
        const auto s = pieSlices({30, 10, -5, 60});
        check(s.size() == 4, "quatre parts");
        near(s[0].fraction, 0.3, "30 sur 100 : 30 %");
        near(s[0].from, 0, "la premi\xC3\xA8re part part d'en haut (0\xC2\xB0)");
        near(s[0].to, 108, "... jusqu'\xC3\xA0 108\xC2\xB0");
        near(s[1].from, 108, "la suivante la prolonge");
        near(s[2].fraction, 0, "une valeur n\xC3\xA9gative compte z\xC3\xA9ro");
        near(s[3].to, 360, "la derni\xC3\xA8re ferme le tour");
        check(pieSlices({0, 0}).empty() && pieSlices({}).empty(), "une somme nulle : aucune part");
    }

    // ---- l'histogramme et la capabilite
    {
        const auto h = histogram({1, 2, 2, 3, 3, 3, 4, 4, 5}, 0, 10, 5, 1.5, 6.0);
        check(h.counts == std::vector<std::size_t>{1, 5, 3, 0, 0} && h.n == 9 && h.below == 0 && h.above == 0 && h.tallest() == 5,
              "neuf mesures en cinq classes de 2 : 1, 5, 3, 0, 0");
        near(h.mean, 3.0, "la moyenne : 3");
        near(h.sigma, std::sqrt(1.5), "l'\xC3\xA9" "cart type de l'\xC3\xA9" "chantillon (n - 1) : racine de 1,5", 1e-9);
        near(h.cp, 4.5 / (6 * std::sqrt(1.5)), "Cp = (USL - LSL) / 6\xCF\x83", 1e-9);
        near(h.cpk, 1.5 / (3 * std::sqrt(1.5)), "Cpk = min(USL - moyenne, moyenne - LSL) / 3\xCF\x83", 1e-9);
        check(h.outOfTolerance == 1 && h.min == 1 && h.max == 5, "une mesure sous la tol\xC3\xA9rance basse ; min 1, max 5");
        const auto edges = histogram({-1, 11, 10, 0}, 0, 10, 5);
        check(edges.below == 1 && edges.above == 1 && edges.counts[4] == 1 && edges.counts[0] == 1 && edges.cp < 0 && edges.cpk < 0,
              "hors de l'\xC3\xA9" "chelle : dessous, dessus ; 10 dans la derni\xC3\xA8re classe ; sans tol\xC3\xA9rance, pas de Cp");
        const auto one = histogram({500}, 490, 510, 10, 495.0, 505.0);
        check(one.n == 1 && one.sigma == 0 && one.cp < 0, "une seule mesure : pas de dispersion, pas de Cp");
        const auto upper = histogram({8, 9, 10}, 0, 20, 4, std::nullopt, 12.0);
        near(upper.cpk, (12.0 - 9.0) / 3.0, "une seule tol\xC3\xA9rance (haute) : Cpk = (USL - moyenne) / 3\xCF\x83", 1e-9);
    }

    // ---- la courbe XY : la reference, l'interpolation
    {
        std::vector<std::pair<double, double>> ref;
        std::string why;
        check(parseXYPoints("40,8.1 0,9.2; 20,8.9", ref) && ref.size() == 3 && ref[0].first == 0 && ref[1].first == 20 && ref[2].first == 40,
              "la r\xC3\xA9" "f\xC3\xA9rence \xC2\xAB 40,8.1 0,9.2; 20,8.9 \xC2\xBB : trois points, rang\xC3\xA9s par X");
        near(*interpolateAt(ref, 10), 9.05, "\xC3\xA0 X = 10 : entre 9,2 et 8,9");
        near(*interpolateAt(ref, 30), 8.5, "\xC3\xA0 X = 30 : entre 8,9 et 8,1");
        check(!interpolateAt(ref, 50) && !interpolateAt(ref, -1) && !interpolateAt({}, 3), "hors de ses X : rien");
        check(!parseXYPoints("0,1 2;3", ref, &why) && ref.empty() && why.find("\xC2\xAB 2 \xC2\xBB") != std::string::npos,
              "un point illisible : refus\xC3\xA9, et dit (" + why + ")");
        check(parseXYPoints("", ref) && ref.empty(), "une r\xC3\xA9" "f\xC3\xA9rence vide : aucune");
    }

    // ---- le chronogramme : les segments
    {
        const std::deque<std::pair<double, double>> ch{{0, 0}, {5, 1}, {8, 1}, {12, 2}};
        const auto segs = stateSegments(ch, 2, 20);
        check(segs.size() == 3 && segs[0].from == 2 && segs[0].to == 5 && segs[0].value == 0 && segs[1].from == 5 && segs[1].to == 12
                  && segs[1].value == 1 && segs[2].from == 12 && segs[2].to == 20 && segs[2].value == 2,
              "fen\xC3\xAAtre 2-20 s : Arr\xC3\xAAt 2-5, Marche 5-12 (redite fondue), 2 de 12 \xC3\xA0 20");
        check(stateSegments(ch, 20, 10).empty() && stateSegments({}, 0, 10).empty(), "une fen\xC3\xAAtre vide, aucun changement : rien");
        const auto late = stateSegments({{30, 1}}, 0, 60);
        check(late.size() == 1 && late[0].from == 30, "avant le premier changement : rien de dessin\xC3\xA9");
    }

    // ---- les axes
    {
        check(niceTicks(0, 100, 5) == std::vector<double>{0, 20, 40, 60, 80, 100}, "0-100 : tous les 20");
        check(niceTicks(0, 7, 5) == std::vector<double>{0, 2, 4, 6}, "0-7 : tous les 2");
        check(niceTicks(5, 5, 5).empty(), "une \xC3\xA9" "chelle nulle : aucune graduation");
        const auto r = autoRange({12, 47}, 0, 1);
        near(r.first, 0, "\xC3\xA9" "chelle auto de 12 et 47 : de 0 ...");
        near(r.second, 50, "... \xC3\xA0 50 (arrondie aux graduations)");
        const auto neg = autoRange({-3, 4}, 0, 1, true);
        check(neg.first <= -3 && neg.second >= 4, "des valeurs n\xC3\xA9gatives : l'\xC3\xA9" "chelle les contient");
        const auto none = autoRange({}, 0, 100);
        check(none.first == 0 && none.second == 100, "sans valeur : l'\xC3\xA9" "chelle de repli");
    }

    // ---- en marche : les valeurs, la memoire, l'export
    Project p;
    for (const auto& [name, type, init] : std::vector<std::tuple<const char*, const char*, const char*>>{
             {"Niveau_1", "REAL", "30.0"}, {"Niveau_2", "REAL", "90.0"}, {"Debit", "REAL", "0.0"}, {"Pression", "REAL", "9.2"},
             {"Etat", "INT", "0"}, {"Poids", "REAL", "500.0"}, {"Essai", "BOOL", "FALSE"}})
        p.programs.variables.push_back(hmiVar(p, name, type, init));
    View v = makeView(p, "Vue_Graphiques");
    v.width = 1400;
    v.height = 900;
    const Id bar = edit::add(p, v, Kind::BarChart, 10, 10);
    v.object(bar)->name = "Barres";
    v.object(bar)->set("variables", "Niveau_1; Niveau_2");
    v.object(bar)->set("names", "Cuve 1;Cuve 2");
    v.object(bar)->set("text", "Niveaux \xC3\xA0 {Niveau_1:0} %");
    const Id pie = edit::add(p, v, Kind::PieChart, 450, 10);
    v.object(pie)->name = "Anneau";
    v.object(pie)->set("variables", "Niveau_1; Niveau_2");
    v.object(pie)->setNumber("hole", 50);
    const Id radar = edit::add(p, v, Kind::RadarChart, 800, 10);
    v.object(radar)->name = "Radar";
    v.object(radar)->set("variables", "Niveau_1; Niveau_2; Pression * 10.0");
    v.object(radar)->set("references", "50; 50; Niveau_1 + 10.0");
    const Id xy = edit::add(p, v, Kind::XYChart, 10, 300);
    v.object(xy)->name = "Courbe_Pompe";
    v.object(xy)->set("xVariable", "Debit");
    v.object(xy)->set("variables", "Pression");
    v.object(xy)->setNumber("maxPoints", 12);
    v.object(xy)->set("reset", "Essai");
    const Id st = edit::add(p, v, Kind::StateChart, 460, 300);
    v.object(st)->name = "Etats";
    v.object(st)->set("variables", "Etat");
    v.object(st)->set("names", "Pompe");
    const Id hist = edit::add(p, v, Kind::Histogram, 10, 620);
    v.object(hist)->name = "Pesees";
    v.object(hist)->set("variable", "Poids");
    v.object(hist)->setNumber("samplePeriod", 200);
    v.object(hist)->setNumber("min", 490);
    v.object(hist)->setNumber("max", 510);
    v.object(hist)->set("low", "495");
    v.object(hist)->set("high", "505");
    p.views = {v};
    p.config.startView = v.id;
    Runtime rt;
    rt.bind(&p, nullptr);
    rt.start(0);
    double t = 0;
    const auto run = [&](double seconds) {
        const double end = t + seconds;
        while (t < end - 1e-9) {
            t += 0.05;
            rt.tick(t);
        }
    };
    run(0.5);
    const Object liveBar = lot11Live(rt, bar, t);
    const auto barValues = liveNumbers(liveBar.text("liveValues"));
    check(barValues.size() == 2 && barValues[0] && *barValues[0] == 30.0 && barValues[1] && *barValues[1] == 90.0,
          "les barres : leurs expressions \xC3\xA9valu\xC3\xA9" "es \xC3\xA0 chaque image (30, 90)");
    const auto radarValues = liveNumbers(lot11Live(rt, radar, t).text("liveValues"));
    const auto radarRefs = liveNumbers(lot11Live(rt, radar, t).text("liveReferences"));
    check(radarValues.size() == 3 && radarValues[2] && std::fabs(*radarValues[2] - 92.0) < 1e-9 && radarRefs.size() == 3 && radarRefs[2]
              && std::fabs(*radarRefs[2] - 40.0) < 1e-9,
          "le radar : ses axes et sa consigne, des expressions (Pression * 10 = 92 ; Niveau_1 + 10 = 40)");
    rt.environment().write("Niveau_1", sim::Value::real(55.0));
    run(0.1);
    const auto after = liveNumbers(lot11Live(rt, pie, t).text("liveValues"));
    check(after.size() == 2 && after[0] && *after[0] == 55.0, "une valeur change : le camembert suit \xC3\xA0 l'image suivante");
    // La courbe XY : un point par cycle ; la trace bornee ; la remise a zero.
    const auto* xySeries = rt.chartSeries(v.id, xy);
    check(xySeries && xySeries->size() == 1 && !(*xySeries)[0].points.empty() && (*xySeries)[0].points.back() == std::make_pair(0.0, 9.2),
          "la courbe XY : des points (d\xC3\xA9" "bit, pression) \xC3\xA0 chaque cycle");
    rt.environment().write("Debit", sim::Value::real(20.0));
    rt.environment().write("Pression", sim::Value::real(8.9));
    run(0.3);
    xySeries = rt.chartSeries(v.id, xy);
    check(xySeries && (*xySeries)[0].points.back() == std::make_pair(20.0, 8.9), "le d\xC3\xA9" "bit monte \xC3\xA0 20 : le dernier point est (20 ; 8,9)");
    run(2.0);
    check(rt.chartSeries(v.id, xy) && (*rt.chartSeries(v.id, xy))[0].points.size() == 12, "Points gard\xC3\xA9s = 12 : la trace n'en garde pas plus");
    rt.environment().write("Essai", sim::Value::boolean(true));
    run(0.1);
    check(rt.chartSeries(v.id, xy) && (*rt.chartSeries(v.id, xy))[0].points.size() <= 2 && journalHas(rt, "Action", "courbe XY remise \xC3\xA0 z\xC3\xA9ro"),
          "Remise \xC3\xA0 z\xC3\xA9ro (front montant de Essai) : la trace repart, le journal le dit");
    // Le chronogramme : les changements seulement.
    rt.environment().write("Etat", sim::Value::integer(sim::Type::Int, 1));
    run(1.0);
    rt.environment().write("Etat", sim::Value::integer(sim::Type::Int, 2));
    run(1.0);
    const auto* stSeries = rt.chartSeries(v.id, st);
    check(stSeries && stSeries->size() == 1 && (*stSeries)[0].points.size() == 3 && (*stSeries)[0].points[0].second == 0
              && (*stSeries)[0].points[1].second == 1 && (*stSeries)[0].points[2].second == 2,
          "le chronogramme ne garde que les changements : 0, 1, 2 (pas une mesure par cycle)");
    // L'histogramme : une mesure toutes les 200 ms.
    const auto* hSeries = rt.chartSeries(v.id, hist);
    const std::size_t samples = hSeries && !hSeries->empty() ? (*hSeries)[0].points.size() : 0;
    check(samples >= 24 && samples <= 26, "l'histogramme : une mesure toutes les 200 ms (" + std::to_string(samples) + " en 5 s)");
    // L'export des graphiques (source objet:Nom).
    ExportTable table;
    std::string why;
    check(rt.exportTable("objet:Barres", table, &why) && table.headers == std::vector<std::string>{"\xC3\x89l\xC3\xA9ment", "Valeur"} && table.rows.size() == 2
              && table.rows[0][0] == "Cuve 1" && table.title == "Niveaux \xC3\xA0 55 %",
          "exporter les barres : une ligne par barre, le titre \xC3\xA0 trous rempli " + why);
    check(rt.exportTable("objet:Anneau", table) && table.headers.size() == 3 && table.headers[2] == "Part" && table.rows[1][2] == "62.1 %",
          "exporter le camembert : la part de chacune (90 sur 145 : 62,1 %)");
    check(rt.exportTable("objet:Radar", table) && table.headers.back() == "Consigne" && table.rows[0][2] == "50",
          "exporter le radar : la consigne \xC3\xA0 c\xC3\xB4t\xC3\xA9 de chaque axe");
    check(rt.exportTable("objet:Courbe_Pompe", table) && table.headers == std::vector<std::string>{"Courbe", "X", "Y"} && !table.rows.empty(),
          "exporter la courbe XY : courbe, X, Y");
    check(rt.exportTable("objet:Etats", table) && table.headers.size() == 5 && table.rows.size() == 3 && table.rows[1][0] == "Pompe",
          "exporter le chronogramme : ses trois segments");
    check(rt.exportTable("objet:Pesees", table) && table.rows.size() >= 13 && table.rows[10][0] == "Mesures",
          "exporter l'histogramme : ses classes, puis ses statistiques");
    check(!rt.exportTable("objet:Absent", table, &why) && why.find("introuvable") != std::string::npos, "un objet absent : refus\xC3\xA9, dit");

    // ---- Generer
    {
        Project q;
        View w = makeView(q, "Vue_Check");
        const Id empty = edit::add(q, w, Kind::BarChart, 10, 10);
        w.object(empty)->name = "Vide";
        const Id inverted = edit::add(q, w, Kind::BarChart, 10, 300);
        w.object(inverted)->name = "Inverse";
        w.object(inverted)->set("variables", "Inconnue_X");
        w.object(inverted)->setNumber("min", 100);
        w.object(inverted)->setNumber("max", 0);
        const Id badRef = edit::add(q, w, Kind::XYChart, 500, 10);
        w.object(badRef)->name = "Ref";
        w.object(badRef)->set("reference", "0,1 2");
        const Id rad = edit::add(q, w, Kind::RadarChart, 500, 300);
        w.object(rad)->name = "Rad";
        w.object(rad)->set("variables", "1;2;3");
        w.object(rad)->set("references", "1;2");
        const Id h2 = edit::add(q, w, Kind::Histogram, 900, 10);
        w.object(h2)->name = "Hist";
        w.object(h2)->set("low", "80");
        w.object(h2)->set("high", "20");
        q.views = {w};
        q.config.startView = w.id;
        const auto issues = generate(q, [](std::string_view) { return false; });
        const auto has = [&](Id object, std::string_view text, Issue::Severity sev) {
            for (const auto& i : issues)
                if (i.object == object && i.severity == sev && i.message.find(text) != std::string::npos) return true;
            return false;
        };
        using S = Issue::Severity;
        check(has(empty, "aucune", S::Warning), "G\xC3\xA9n\xC3\xA9rer : un graphique sans valeur");
        check(has(inverted, "minimum doit \xC3\xAAtre sous le maximum", S::Error) && has(inverted, "Inconnue_X", S::Error),
              "... une \xC3\xA9" "chelle invers\xC3\xA9" "e, une variable inconnue");
        check(has(badRef, "courbe de r\xC3\xA9" "f\xC3\xA9rence", S::Error) && has(badRef, "aucune variable X", S::Error),
              "... une r\xC3\xA9" "f\xC3\xA9rence illisible, une courbe XY sans X");
        check(has(rad, "2 valeur(s) de consigne pour 3 axe(s)", S::Warning), "... une consigne qui n'a pas autant de valeurs que d'axes");
        check(has(h2, "aucune variable mesur\xC3\xA9" "e", S::Error) && has(h2, "tol\xC3\xA9rance basse au-dessus", S::Error),
              "... un histogramme sans variable, des tol\xC3\xA9rances invers\xC3\xA9" "es");
    }
}

// ------------------------------------------------ lot 11 : alarmes --
void alarmesLot11() {
    std::printf("lot 11 : les objets des alarmes, la consigne, la mise de c\xC3\xB4t\xC3\xA9, les sons\n");
    Supervision s;
    s.alarm("Pression_Basse", "Pression < 5.0", 2, "Armoire A").instruction =
        "V\xC3\xA9rifier la bouteille ({Pression:0.0} bar)\\nPuis ouvrir V2";
    s.alarm("Porte", "Porte_Ouverte", 3, "Armoire B");
    s.alarm("Vide", "Bouteille_Vide", 1, "Armoire A").instruction = "Changer la bouteille A";
    Resource crit, high;
    crit.id = s.p.allocate();
    crit.name = "critique.wav";
    crit.format = "WAV";
    high.id = s.p.allocate();
    high.name = "haute.wav";
    high.format = "WAV";
    s.p.assets.resources = {crit, high};
    s.p.alarmSettings.sounds[0] = "critique.wav";
    s.p.alarmSettings.sounds[1] = "haute.wav";
    s.p.alarmSettings.repeatS = 2;
    s.p.programs.variables.push_back(hmiVar(s.p, "Zone_Choisie", "STRING", "''"));
    s.p.programs.variables.push_back(hmiVar(s.p, "Mis", "INT", "0"));
    s.p.programs.scripts.push_back(generalScript(s.p, "Ecarter", "Mis := IHM_METTRE_DE_COTE('Porte', 1, 'essai du capteur');"));
    s.p.programs.scripts.push_back(generalScript(s.p, "Reprendre", "Mis := IHM_REMETTRE('Porte');"));
    s.p.programs.scripts.push_back(generalScript(s.p, "Taire", "IHM_FAIRE_TAIRE();"));
    auto add = [&](Kind k, const char* name, double x, double y) {
        const Id id = edit::add(s.p, s.v(), k, x, y);
        s.v().object(id)->name = name;
        return id;
    };
    s.v().width = 1400;
    s.v().height = 900;
    const Id banner = add(Kind::AlarmBanner, "Bandeau", 0, 0);
    const Id counter = add(Kind::AlarmCounter, "Compteur", 920, 0);
    const Id summary = add(Kind::AlarmSummary, "Resume", 0, 60);
    s.v().object(summary)->set("variable", "Zone_Choisie");
    const Id instr = add(Kind::AlarmInstruction, "Consigne", 560, 60);
    const Id list = add(Kind::History, "Liste", 0, 300);
    const Id shelveBtn = add(Kind::Button, "Btn_Cote", 600, 300);
    s.v().object(shelveBtn)->actions.push_back(act(Trigger::Click, Operation::ShelveAlarm, {}, "5; Essai de {Pression:0.0} bar"));
    const Id muteBtn = add(Kind::Button, "Btn_Taire", 600, 380);
    s.v().object(muteBtn)->actions.push_back(act(Trigger::Click, Operation::SilenceAlarms));
    (void)counter;
    (void)instr;
    std::vector<std::string> sounds;
    Runtime::Hooks hooks;
    hooks.playSound = [&](const std::string& name) { sounds.push_back(name); };
    s.rt.setHooks(hooks);
    s.start();
    s.run(0.5);
    const Object& bo = *s.v().object(banner);
    check(s.rt.bannerAlarm(bo) == -1 && bannerCount(s.rt.alarms(), "") == 0, "sans alarme : le bandeau n'en montre aucune");

    // ---- une alarme apparait : sa consigne remplie, son son
    s.plc.values["Pression"] = sim::Value::real(4.0);
    s.run(0.5);
    const auto* pb = s.live("Pression_Basse");
    check(pb && pb->instruction == "V\xC3\xA9rifier la bouteille (4.0 bar)\nPuis ouvrir V2",
          "la consigne est remplie \xC3\xA0 l'apparition (4.0 bar) ; \\n passe \xC3\xA0 la ligne");
    check(sounds == std::vector<std::string>{"haute.wav"}, "le son de sa priorit\xC3\xA9 (2 : haute.wav), une fois");
    s.plc.values["Bouteille_Vide"] = sim::Value::boolean(true);
    s.run(0.3);
    check(sounds.size() == 2 && sounds[1] == "critique.wav", "une alarme critique : critique.wav");
    // ---- le bandeau : la plus grave, la suivante, acquitter
    const auto& alarms = s.rt.alarms();
    int shown = s.rt.bannerAlarm(bo);
    check(shown >= 0 && alarms[static_cast<std::size_t>(shown)].name == "Vide" && bannerCount(alarms, "") == 2,
          "le bandeau montre la plus grave (Vide, critique) ; +1 autre");
    check(alarmCount(alarms, s.rt.shelvedAlarms(), "", "\xC3\xA0 acquitter") == 2 && strongestPriority(alarms, "", true) == 1
              && alarmCount(alarms, s.rt.shelvedAlarms(), "Armoire B", "\xC3\xA0 acquitter") == 0,
          "le compteur : 2 \xC3\xA0 acquitter, priorit\xC3\xA9 la plus forte 1 ; 0 dans l'armoire B");
    s.rt.objectPart(banner, "suivante", s.t);
    shown = s.rt.bannerAlarm(bo);
    check(shown >= 0 && alarms[static_cast<std::size_t>(shown)].name == "Pression_Basse", "\xC2\xAB +1 \xC2\xBB : la suivante");
    s.rt.objectPart(banner, "acquitter", s.t);
    check(s.live("Pression_Basse") && s.live("Pression_Basse")->acked && !s.live("Vide")->acked && s.rt.selectedAlarm() == "Pression_Basse"
              && lot11Sys(s.rt, "AlarmSelected").asString() == "Pression_Basse",
          "Acquitter : l'alarme montr\xC3\xA9" "e est acquitt\xC3\xA9" "e, et choisie (SYS.AlarmSelected)");
    // ---- la consigne de l'alarme choisie
    const auto* ia = instructionAlarm(s.rt.alarms(), "", s.rt.selectedAlarm());
    check(ia && ia->name == "Pression_Basse", "la consigne : celle de l'alarme choisie");
    const auto* first = instructionAlarm(s.rt.alarms(), "", "");
    check(first && first->name == "Vide", "... sans choix : la premi\xC3\xA8re \xC3\xA0 acquitter");
    check(instructionAlarm(s.rt.alarms(), "Porte", "") == nullptr && instructionAlarm(s.rt.alarms(), "Vide", "Pression_Basse")->name == "Vide",
          "... une alarme donn\xC3\xA9" "e : elle, m\xC3\xAAme pas en cours (aucune)");
    // ---- le resume par zone
    const auto zones = zoneSummaries(s.p, s.rt.alarms(), s.rt.shelvedAlarms(), "");
    check(zones.size() == 2 && zones[0].name == "Armoire A" && zones[0].current == 2 && zones[0].unacked == 1 && zones[0].highest == 1
              && zones[1].name == "Armoire B" && zones[1].current == 0 && zones[1].highest == 0,
          "le r\xC3\xA9sum\xC3\xA9 : Armoire A (2 en cours, 1 \xC3\xA0 acquitter, critique), Armoire B calme");
    check(zonesOf(s.p, "Armoire B; Local ;Armoire B") == std::vector<std::string>{"Armoire B", "Local"}, "des zones donn\xC3\xA9" "es : dans l'ordre, sans doublon");
    s.rt.objectPart(summary, "zone:1", s.t);
    check(s.rt.selectedZone() == "Armoire B" && s.rt.variable("Zone_Choisie") && s.rt.variable("Zone_Choisie")->asString() == "Armoire B"
              && lot11Sys(s.rt, "AlarmZoneSelected").asString() == "Armoire B",
          "un clic sur une tuile : la zone choisie, \xC3\xA9" "crite dans sa variable et SYS.AlarmZoneSelected");
    // ---- la liste : un clic sur une ligne choisit son alarme
    s.rt.objectPart(list, "ligne:0", s.t);
    check(s.rt.selectedAlarm() == s.rt.alarms()[0].name, "un clic sur la 1re ligne de la liste : son alarme est choisie");
    check(historyAlarmRows(s.rt.alarms(), "alarmes", "Armoire A").size() == 2 && historyAlarmRows(s.rt.alarms(), "acquitt\xC3\xA9" "es", "").size() == 1,
          "les lignes : 2 dans l'armoire A, 1 acquitt\xC3\xA9" "e");
    check(historyHit(400, 200, 10, kHistoryHeaderH + kHistoryRowH * 1 + 5, 5) == "ligne:1" && historyHit(400, 200, 10, 10, 5).empty()
              && historyHit(400, 200, 10, kHistoryHeaderH + kHistoryRowH * 3 + 5, 2).empty(),
          "le clic sur une ligne : ligne:1 ; l'en-t\xC3\xAAte, sous la derni\xC3\xA8re : rien");
    // 1.11 (REP-1, decision 74) : le groupe d'un bandeau marque ($Armoire A$, pour Dupliquer...)
    // se lit sans ses $ : le moteur montre la meme alarme que pour Armoire A.
    {
        Object plain = *s.v().object(banner);
        plain.set("group", "Armoire A");
        Object marked = plain;
        marked.set("group", "$Armoire A$");
        const int shownPlain = s.rt.bannerAlarm(plain);
        check(shownPlain >= 0 && s.rt.bannerAlarm(marked) == shownPlain,
              "REP-1 : le bandeau du groupe $Armoire A$ montre l'alarme d'Armoire A (" + std::to_string(shownPlain) + ")");
    }

    // ---- le son se repete, puis se tait
    const std::size_t before = sounds.size();
    s.run(2.2);
    check(sounds.size() == before + 1 && sounds.back() == "critique.wav", "Vide attend : son son revient au bout de 2 s");
    s.rt.press(muteBtn, s.t);
    s.rt.release(muteBtn, s.t, true);
    check(s.rt.alarmsSilenced() && lot11Sys(s.rt, "AlarmSilenced").isTruthy() && eventHas(s.rt, "Silence", "prochaine apparition"),
          "Faire taire : plus de son (SYS.AlarmSilenced), l'\xC3\xA9v\xC3\xA9nement le dit");
    const std::size_t muted = sounds.size();
    s.run(4.5);
    check(sounds.size() == muted && s.live("Vide") && !s.live("Vide")->acked, "... rien pendant 4,5 s, l'alarme reste \xC3\xA0 acquitter");
    s.plc.values["Porte_Ouverte"] = sim::Value::boolean(true);
    s.run(0.3);
    check(!s.rt.alarmsSilenced() && s.live("Porte"), "une nouvelle alarme : le silence prend fin");

    // ---- mettre de cote
    std::string why;
    check(s.rt.shelve("Porte", 0.05, "Capteur en essai", s.t, &why) == 1 && !s.live("Porte") && s.rt.shelvedAlarms().size() == 1
              && s.rt.isShelved(s.rt.shelvedAlarms()[0].alarm),
          "Porte mise de c\xC3\xB4t\xC3\xA9 3 s : elle quitte la liste " + why);
    check(s.rt.shelvedAlarms()[0].reason == "Capteur en essai" && s.rt.shelvedAlarms()[0].group == "Armoire B"
              && std::fabs(s.rt.shelvedAlarms()[0].until - (s.t + 3.0)) < 1e-6 && lot11Sys(s.rt, "AlarmShelvedCount").asInteger() == 1,
          "... pourquoi, sa zone, jusqu'\xC3\xA0 quand (SYS.AlarmShelvedCount = 1)");
    check(eventHas(s.rt, "Mise de c\xC3\xB4t\xC3\xA9", "Capteur en essai"), "l'\xC3\xA9v\xC3\xA9nement : la dur\xC3\xA9" "e et la raison");
    check(alarmCount(s.rt.alarms(), s.rt.shelvedAlarms(), "", "mises de c\xC3\xB4t\xC3\xA9") == 1 && zoneSummaries(s.p, s.rt.alarms(), s.rt.shelvedAlarms(), "")[1].shelved == 1,
          "le compteur \xC2\xAB mises de c\xC3\xB4t\xC3\xA9 \xC2\xBB, le r\xC3\xA9sum\xC3\xA9 de la zone");
    s.run(1.0);
    check(!s.live("Porte"), "sa condition est toujours vraie : elle ne revient pas avant la fin");
    s.run(2.5);
    check(s.rt.shelvedAlarms().empty() && eventHas(s.rt, "Fin de mise de c\xC3\xB4t\xC3\xA9", "d\xC3\xA9lai \xC3\xA9" "coul\xC3\xA9") && s.live("Porte"),
          "au bout de 3 s : la fin (d\xC3\xA9lai \xC3\xA9" "coul\xC3\xA9), et elle revient");
    s.p.alarmSettings.maxShelveMin = 10;
    check(s.rt.shelve("Porte", 600, "", s.t) == 1 && std::fabs(s.rt.shelvedAlarms()[0].until - (s.t + 600.0)) < 1e-6
              && eventHas(s.rt, "Mise de c\xC3\xB4t\xC3\xA9", "limit\xC3\xA9" "e \xC3\xA0 10 min"),
          "au-del\xC3\xA0 de la limite (10 min) : limit\xC3\xA9" "e, et dit");
    check(s.rt.unshelve("*", s.t) == 1 && s.rt.shelvedAlarms().empty(), "Remettre en service (*) : toutes");
    s.run(0.2);
    check(s.live("Porte") != nullptr, "... elle revient au cycle suivant");
    check(s.rt.shelve("groupe:Armoire A", 0, "maintenance", s.t) == 2 && s.rt.shelvedAlarms().size() == 2 && s.rt.shelvedAlarms()[0].until < 0,
          "une zone enti\xC3\xA8re, sans limite : ses deux alarmes");
    check(s.rt.unshelve("groupe:Armoire A", s.t) == 2, "... et remises en service par zone");
    check(s.rt.shelve("Inconnue", 5, "", s.t, &why) == 0 && why.find("introuvable") != std::string::npos, "une alarme inconnue : refus\xC3\xA9" "e");
    s.rt.selectAlarm("");
    check(s.rt.shelve("", 5, "", s.t, &why) == 0 && why.find("aucune alarme choisie") != std::string::npos, "sans alarme choisie : refus\xC3\xA9, dit");
    // L'action : l'alarme choisie d'un clic, la raison a trous.
    s.run(0.2);
    s.rt.selectAlarm("Porte");
    s.rt.press(shelveBtn, s.t);
    s.rt.release(shelveBtn, s.t, true);
    check(s.rt.shelvedAlarms().size() == 1 && s.rt.shelvedAlarms()[0].name == "Porte" && s.rt.shelvedAlarms()[0].reason == "Essai de 4.0 bar"
              && std::fabs(s.rt.shelvedAlarms()[0].until - (s.t + 300.0)) < 1e-6,
          "l'action \xC2\xAB Mettre de c\xC3\xB4t\xC3\xA9 une alarme \xC2\xBB : la choisie, 5 min, raison remplie");
    // Les fonctions IHM_.
    check(s.rt.callScript("Reprendre", s.t) && lot11Number(s.rt, "Mis") == 1 && s.rt.shelvedAlarms().empty(), "IHM_REMETTRE('Porte') : 1");
    check(s.rt.callScript("Ecarter", s.t) && lot11Number(s.rt, "Mis") == 1 && s.rt.shelvedAlarms().size() == 1
              && s.rt.shelvedAlarms()[0].reason == "essai du capteur",
          "IHM_METTRE_DE_COTE('Porte', 1, 'essai du capteur') : 1");
    check(s.rt.callScript("Taire", s.t) && s.rt.alarmsSilenced(), "IHM_FAIRE_TAIRE()");
    check(historyShelvedRows(s.rt.shelvedAlarms(), "").size() == 1 && historyShelvedRows(s.rt.shelvedAlarms(), "Armoire A").empty(),
          "la liste \xC2\xAB mises de c\xC3\xB4t\xC3\xA9 \xC2\xBB : filtr\xC3\xA9" "e par zone");
    ExportTable et;
    Object shelvedList = makeObject(Kind::History, 999, "X", 0, 0, 1);
    check(s.rt.exportTable("alarmes", et) && et.headers.size() == 7 && et.rows.size() == s.rt.alarms().size(), "exporter les alarmes en cours");
    (void)shelvedList;
    // Sous securite, sans la permission Acquitter : refuse.
    s.p.security.enabled = true;
    check(s.rt.shelve("Vide", 5, "", s.t, &why) == 0 && why.find("Acquitter") != std::string::npos && eventHas(s.rt, "Acc\xC3\xA8s refus\xC3\xA9", "mise de c\xC3\xB4t\xC3\xA9"),
          "sous s\xC3\xA9" "curit\xC3\xA9, sans la permission Acquitter : refus\xC3\xA9 (Acc\xC3\xA8s refus\xC3\xA9)");
    check(s.rt.unshelve("*", s.t, &why) == 0 && why.find("Acquitter") != std::string::npos, "... remettre en service aussi");
    s.p.security.enabled = false;

    // ---- les statistiques
    {
        std::deque<AlarmOccurrence> since;
        const auto occ = [](const char* name, const char* group, int prio, const char* from, const char* to) {
            AlarmOccurrence a;
            a.name = name;
            a.group = group;
            a.priority = prio;
            a.appeared = from;
            a.cleared = to;
            return a;
        };
        since.push_back(occ("A", "Z1", 3, "2026-09-24 10:00:00.000", "2026-09-24 10:00:30.000"));
        since.push_back(occ("A", "Z1", 3, "2026-09-24 10:10:00.000", "2026-09-24 10:10:30.000"));
        since.push_back(occ("A", "Z1", 3, "2026-09-24 10:20:00.000", "2026-09-24 10:20:30.000"));
        since.push_back(occ("B", "Z2", 2, "2026-09-24 11:00:00.000", "2026-09-24 11:10:00.000"));
        LiveAlarm c;
        c.name = "C";
        c.group = "Z1";
        c.priority = 1;
        c.active = true;
        c.appeared = "2026-09-24 11:59:00.000";
        const std::vector<LiveAlarm> live{c};
        const auto byCount = alarmStatistics(since, nullptr, live, "depuis le lancement", "", "nombre", 5, "2026-09-24 12:00:00.000");
        check(byCount.size() == 3 && byCount[0].name == "A" && byCount[0].count == 3 && byCount[1].name == "B" && byCount[2].name == "C"
                  && byCount[2].current,
              "par nombre : A (3 fois), puis B et C (1 fois : la plus longue d'abord) ; C en cours");
        near(byCount[0].seconds, 90, "A : 3 x 30 s actives");
        near(byCount[2].seconds, 60, "C, active depuis 1 min");
        const auto byTime = alarmStatistics(since, nullptr, live, "depuis le lancement", "", "dur\xC3\xA9" "e", 2, "2026-09-24 12:00:00.000");
        check(byTime.size() == 2 && byTime[0].name == "B" && byTime[1].name == "A", "par dur\xC3\xA9" "e, les 2 premi\xC3\xA8res : B (10 min), A (1 min 30)");
        const auto zone = alarmStatistics(since, nullptr, live, "depuis le lancement", "Z2", "nombre", 5, "2026-09-24 12:00:00.000");
        check(zone.size() == 1 && zone[0].name == "B", "une zone : seulement ses alarmes");
        std::vector<AlarmOccurrence> kept(since.begin(), since.end());
        kept.push_back(occ("D", "Z1", 4, "2026-09-01 08:00:00.000", "2026-09-01 08:05:00.000"));
        const auto all = alarmStatistics(since, &kept, live, "tout l'historique", "", "nombre", 10, "2026-09-24 12:00:00.000");
        const auto day = alarmStatistics(since, &kept, live, "24 h", "", "nombre", 10, "2026-09-24 12:00:00.000");
        check(all.size() == 4 && day.size() == 3, "tout l'historique : D aussi (le 1er septembre) ; 24 h : sans elle");
        near(stampToSeconds("2026-09-24 12:00:00.500") - stampToSeconds("2026-09-23 12:00:00"), 86400.5, "les horodatages en secondes");
        check(stampToSeconds("hier") < 0, "... et ce qui n'en est pas un");
    }

    // ---- le dessin se clique : bandeau, resume
    {
        const Object b = makeObject(Kind::AlarmBanner, 1, "B", 0, 0, 1);
        const auto l = bannerLayout(b, 900, 48);
        check(l.ack.w > 0 && l.count.w > 0 && l.message.w > 0 && l.ack.x > l.message.x, "le bandeau : le message, +N, Acquitter \xC3\xA0 droite");
        same(bannerHit(b, 900, 48, l.ack.x + l.ack.w / 2, 24), "acquitter", "un clic sur Acquitter");
        same(bannerHit(b, 900, 48, l.count.x + l.count.w / 2, 24), "suivante", "un clic sur +N");
        same(bannerHit(b, 900, 48, l.message.x + 5, 24), "", "ailleurs : le bandeau (ses actions)");
        Object nb = b;
        nb.setFlag("ackButton", false);
        nb.setFlag("showCount", false);
        const auto l2 = bannerLayout(nb, 900, 48);
        check(l2.ack.w == 0 && l2.count.w == 0 && bannerHit(nb, 900, 48, 880, 24).empty(), "sans bouton ni compte : tout le bandeau est le message");
        Object sm = makeObject(Kind::AlarmSummary, 2, "S", 0, 0, 1);
        const auto tiles = summaryTiles(sm, 540, 200, 4);
        check(tiles.size() == 4 && tiles[3].y > tiles[0].y && std::fabs(tiles[1].y - tiles[0].y) < 1e-9, "quatre zones, trois par ligne : deux lignes");
        same(summaryHit(sm, 540, 200, tiles[3].x + tiles[3].w / 2, tiles[3].y + tiles[3].h / 2, 4), "zone:3", "un clic sur la 4e tuile");
        check(bannerPick({}, "", "la plus grave", 0, 4000, 0) == -1, "bannerPick sans alarme : -1");
        std::vector<LiveAlarm> la(3);
        la[0].name = "X";
        la[0].acked = true;
        la[0].appeared = "2026-09-24 10:00:00";
        la[1].name = "Y";
        la[1].appeared = "2026-09-24 10:05:00";
        la[2].name = "Z";
        la[2].appeared = "2026-09-24 10:01:00";
        check(bannerPick(la, "", "la plus grave", 0, 4000, 0) == 1, "la plus grave : la premi\xC3\xA8re \xC3\xA0 acquitter (Y)");
        check(bannerPick(la, "", "la plus r\xC3\xA9" "cente", 0, 4000, 0) == 1 && bannerPick(la, "", "la plus r\xC3\xA9" "cente", 0, 4000, 1) == 2,
              "la plus r\xC3\xA9" "cente : Y ; la suivante, Z");
        check(bannerPick(la, "", "d\xC3\xA9" "filement", 0, 4000, 0) == 0 && bannerPick(la, "", "d\xC3\xA9" "filement", 4.1, 4000, 0) == 1
                  && bannerPick(la, "", "d\xC3\xA9" "filement", 8.2, 4000, 0) == 2 && bannerPick(la, "", "d\xC3\xA9" "filement", 12.3, 4000, 0) == 0,
              "le d\xC3\xA9" "filement : chacune 4 s, en boucle");
    }

    // ---- le projet : consigne et reglages, enregistres et relus ; Generer
    {
        const fs::path dir = lot11Temp("projet_alarmes");
        fs::remove_all(dir);
        fs::create_directories(dir);
        Project q = s.p;
        q.security.enabled = false;
        check(static_cast<bool>(save(q, dir.string())), "enregistrer le projet des alarmes");
        auto back = load(dir.string());
        check(back && back->alarms.size() == 3 && back->alarms[0].instruction == q.alarms[0].instruction
                  && back->alarmSettings == q.alarmSettings && back->alarmSettings.sounds[0] == "critique.wav" && back->alarmSettings.repeatS == 2
                  && back->alarmSettings.maxShelveMin == 10,
              "relu : la consigne, les sons par priorit\xC3\xA9, la r\xC3\xA9p\xC3\xA9tition, la limite de mise de c\xC3\xB4t\xC3\xA9");
        check(back && back->views == q.views, "... et les objets des alarmes \xC3\xA0 l'identique");
        std::ifstream in(dir / "ihm" / "ihm.txt");
        std::stringstream ss;
        ss << in.rdbuf();
        // Lot 12 : le format 11 ; celui du lot 11 (10) reste lu.
        check(kFormatVersion >= 10 && ss.str().find("format=" + std::to_string(kPlainFormat)) != std::string::npos,
              "le format 10 (lot 11) ou plus r\xC3\xA9" "cent");

        Project g = s.p;
        g.security.enabled = false;
        g.alarmSettings.sounds[3] = "absent.wav";
        View& gv = g.views[0];
        const Id ins = edit::add(g, gv, Kind::AlarmInstruction, 10, 700);
        gv.object(ins)->name = "Ins";
        gv.object(ins)->set("alarm", "Nulle_Part");
        const Id bz = edit::add(g, gv, Kind::AlarmBanner, 10, 800);
        gv.object(bz)->name = "Bz";
        gv.object(bz)->set("group", "Zone X");
        const Id bad = edit::add(g, gv, Kind::Button, 500, 800);
        gv.object(bad)->name = "Btn_Bad";
        gv.object(bad)->actions.push_back(act(Trigger::Click, Operation::ShelveAlarm, "Nope", "abc +"));
        g.alarms[0].instruction = "Voir {Variable_Absente}";
        const auto issues = generate(g, [](std::string_view root) { return root == "Pression" || root == "Porte_Ouverte" || root == "Bouteille_Vide"; });
        const auto has = [&](std::string_view text, Issue::Severity sev) {
            for (const auto& i : issues) if (i.severity == sev && i.message.find(text) != std::string::npos) return true;
            return false;
        };
        using S = Issue::Severity;
        check(has("alarme 'Nulle_Part' introuvable", S::Error), "G\xC3\xA9n\xC3\xA9rer : la consigne d'une alarme inconnue");
        check(has("aucune alarme du groupe \xC2\xAB Zone X \xC2\xBB", S::Warning), "... un bandeau sur une zone sans alarme");
        check(has("alarme 'Nope' introuvable", S::Error) && has("dur\xC3\xA9" "e illisible", S::Error), "... une mise de c\xC3\xB4t\xC3\xA9 d'une alarme inconnue, une dur\xC3\xA9" "e illisible");
        check(has("son de la priorit\xC3\xA9 4 introuvable", S::Error), "... un son d'alarme absent des ressources");
        check(has("variable inexistante dans la consigne : Variable_Absente", S::Error), "... une variable inconnue dans une consigne");
    }
}

// ------------------------------------------------ lot 11 : production --
void productionLot11() {
    std::printf("lot 11 : la production (TRS, tableau de variables, \xC3\xA9" "diteur de recette, export)\n");
    // ---- le TRS
    {
        const auto f = productionFigures(90, 10, 3000, 3600, 120, 95, 150);
        near(f.availability, 3000.0 / 3600.0, "disponibilit\xC3\xA9 : 3000 s de marche sur 3600", 1e-9);
        near(f.performance, 1.0, "performance : 100 pi\xC3\xA8" "ces faites, 100 possibles (120/h pendant 3000 s)", 1e-9);
        near(f.quality, 0.9, "qualit\xC3\xA9 : 90 bonnes sur 100", 1e-9);
        near(f.oee, 0.75, "TRS = 0,833 x 1 x 0,9 = 75 %", 1e-9);
        check(f.total == 100 && f.target == 150 && f.rate == 95, "le total, l'objectif, la cadence");
        near(productionFigures(200, 0, 3000, 3600, 120, 0, 0).performance, 1.0, "plus de pi\xC3\xA8" "ces que possible : la performance plafonne \xC3\xA0 100 %");
        check(productionFigures(10, 0, 100, 100, 0, 0, 0).performance == 0 && productionFigures(0, 0, 100, 100, 60, 0, 0).quality == 1.0,
              "sans cadence nominale, performance 0 ; sans pi\xC3\xA8" "ce, qualit\xC3\xA9 100 %");
        std::vector<int> shifts;
        std::string why;
        check(parseShifts("22:00; 6h;14:00", shifts) && shifts == std::vector<int>{360, 840, 1320}, "les d\xC3\xA9" "buts de poste, rang\xC3\xA9s : 6 h, 14 h, 22 h");
        check(!parseShifts("06:00;25:00", shifts, &why) && shifts.empty() && why.find("25:00") != std::string::npos, "une heure illisible : refus\xC3\xA9" "e");
        check(parseShifts("", shifts) && shifts.empty() && currentShift(shifts, 600) == -1, "sans poste : -1");
        (void)parseShifts("06:00;14:00;22:00", shifts);
        check(currentShift(shifts, 300) == 1320 && currentShift(shifts, 360) == 360 && currentShift(shifts, 900) == 840 && currentShift(shifts, 1439) == 1320,
              "le poste en cours : \xC3\xA0 5 h celui de 22 h (la veille), \xC3\xA0 6 h celui de 6 h, \xC3\xA0 15 h celui de 14 h");
        same(minutesText(360) + " " + minutesText(1320), "06:00 22:00", "minutesText");
        const Object pc = makeObject(Kind::ProductionCounter, 1, "P", 0, 0, 1);
        const auto l = productionLayout(pc, 560, 220);
        check(l.reset.w > 0 && l.tiles[3].w > 0 && l.bars[2].w > 0 && l.progress.w == 0, "le dessin : RAZ, quatre tuiles, trois barres ; sans objectif, pas de progression");
        same(productionHit(pc, 560, 220, l.reset.x + l.reset.w / 2, l.reset.y + l.reset.h / 2), "raz", "un clic sur RAZ");
        Object withTarget = pc;
        withTarget.setNumber("target", 500);
        check(productionLayout(withTarget, 560, 220).progress.w > 0, "avec un objectif : sa barre");
    }

    // ---- en marche : les compteurs du poste
    Project p;
    for (const auto& [name, type, init] : std::vector<std::tuple<const char*, const char*, const char*>>{
             {"Bons", "DINT", "0"}, {"Rebuts", "DINT", "0"}, {"Marche", "BOOL", "TRUE"}, {"Consigne", "REAL", "60.0"},
             {"Temp", "REAL", "20.0"}, {"Mode", "BOOL", "FALSE"}, {"Nom", "STRING", "'A'"}, {"Consigne_P", "REAL", "6.0"},
             {"Nom_Gaz", "STRING", "''"}, {"Ok", "BOOL", "FALSE"}})
        p.programs.variables.push_back(hmiVar(p, name, type, init));
    Recipe gaz;
    gaz.id = p.allocate();
    gaz.name = "Gaz";
    gaz.fields = {{"Pression", "Consigne_P", "bar", "0", "10"}, {"Gaz", "Nom_Gaz", "", "", ""}};
    RecipeRecord azote, argon;
    azote.id = p.allocate();
    azote.name = "Azote";
    azote.values = {"6.5", "'Azote'"};
    argon.id = p.allocate();
    argon.name = "Argon";
    argon.values = {"5.0", "'Argon'"};
    gaz.records = {azote, argon};
    p.recipes.push_back(gaz);
    View v = makeView(p, "Vue_Ligne");
    v.width = 1400;
    v.height = 900;
    const Id pc = edit::add(p, v, Kind::ProductionCounter, 10, 10);
    v.object(pc)->name = "Compteurs";
    v.object(pc)->set("good", "Bons");
    v.object(pc)->set("bad", "Rebuts");
    v.object(pc)->set("running", "Marche");
    v.object(pc)->setNumber("idealRate", 3600);
    v.object(pc)->set("shifts", "");
    v.object(pc)->setNumber("rateWindow", 10);
    const Id tab = edit::add(p, v, Kind::VariableTable, 600, 10);
    v.object(tab)->name = "Tableau";
    v.object(tab)->set("variables", "Consigne; Temp * 1.0; Mode; Nom");
    v.object(tab)->set("names", "Consigne;Calcul;Mode;Nom");
    v.object(tab)->set("units", "\xC2\xB0" "C;;;");
    const Id ed = edit::add(p, v, Kind::RecipeEditor, 10, 300);
    v.object(ed)->name = "Editeur";
    v.object(ed)->set("recipe", "Gaz");
    const Id exp = edit::add(p, v, Kind::ExportButton, 700, 300);
    v.object(exp)->name = "Export_PDF";
    v.object(exp)->set("exportSource", "objet:Compteurs");
    v.object(exp)->set("fileFormat", "PDF");
    v.object(exp)->set("fileName", "trs_{SYS.Date}");
    const Id actBtn = edit::add(p, v, Kind::Button, 700, 400);
    v.object(actBtn)->name = "Btn_Export";
    v.object(actBtn)->actions.push_back(act(Trigger::Click, Operation::Export, "recette:Gaz", "gaz.csv"));
    p.views = {v};
    p.config.startView = v.id;
    p.programs.scripts.push_back(generalScript(p, "Exporter", "Ok := IHM_EXPORTER('\xC3\xA9v\xC3\xA9nements', 'ev.xlsx');"));
    std::vector<ExportRequest> written;
    std::vector<RecipeRequest> recipeCalls;
    Runtime rt;
    Runtime::Hooks hooks;
    hooks.exportFile = [&](const ExportRequest& rq, std::string* where) {
        written.push_back(rq);
        if (where) *where = "exports/" + rq.fileName;
        return true;
    };
    hooks.recipeRequest = [&](const RecipeRequest& rq) {
        recipeCalls.push_back(rq);
        Recipe* r = nullptr;
        for (auto& one : p.recipes) if (one.name == rq.recipe) r = &one;
        if (!r) return;
        if (rq.op == "enregistrer")
            if (auto* rec = r->record(rq.record)) rec->values = rq.values;
        if (rq.op == "ajouter") {
            RecipeRecord n;
            n.id = p.allocate();
            n.name = "Nouveau";
            n.values = rq.values;
            r->records.push_back(n);
        }
    };
    rt.setHooks(hooks);
    rt.bind(&p, nullptr);
    rt.start(0);
    double t = 0;
    double nextPiece = 0.5;
    int made = 0;
    // Une piece par seconde tant que la ligne tourne (de 0 a 8 s) ; la 4e au rebut.
    const auto run = [&](double seconds) {
        const double end = t + seconds;
        while (t < end - 1e-9) {
            t += 0.05;
            const bool marche = t < 8.0;
            rt.environment().write("Marche", sim::Value::boolean(marche));
            if (marche && t >= nextPiece - 1e-9) {
                nextPiece += 1.0;
                ++made;
                const char* which = made == 4 ? "Rebuts" : "Bons";
                sim::Value cur;
                (void)rt.environment().read(which, cur);
                rt.environment().write(which, sim::Value::integer(sim::Type::DInt, cur.asInteger() + 1));
            }
            rt.tick(t);
        }
    };
    run(10.0);
    auto f = rt.production(pc);
    check(f.good == 7 && f.bad == 1 && f.total == 8, "10 s : 7 bonnes, 1 rebut (" + formatNumber(f.good) + ", " + formatNumber(f.bad) + ")");
    near(f.availability, 0.8, "disponibilit\xC3\xA9 : 8 s de marche sur 10", 0.02);
    near(f.performance, 1.0, "performance : 8 pi\xC3\xA8" "ces en 8 s, \xC3\xA0 une par seconde", 0.03);
    near(f.quality, 0.875, "qualit\xC3\xA9 : 7 sur 8", 1e-9);
    near(f.oee, 0.7, "TRS : 0,8 x 1 x 0,875 = 70 %", 0.03);
    check(!f.running && f.shift.rfind("Depuis ", 0) == 0, "\xC3\xA0 l'arr\xC3\xAAt ; sans poste, \xC2\xAB Depuis \xC2\xBB l'heure du lancement");
    // L'automate remet son compteur a zero : l'objet garde le compte.
    rt.environment().write("Bons", sim::Value::integer(sim::Type::DInt, 0));
    run(0.2);
    rt.environment().write("Bons", sim::Value::integer(sim::Type::DInt, 2));
    run(0.2);
    check(rt.production(pc).good == 9, "le compteur de l'automate repart de z\xC3\xA9ro : l'objet continue (7 + 2 = 9)");
    ExportTable table;
    check(rt.exportTable("objet:Compteurs", table) && table.rows.size() >= 11 && table.rows[1][0] == "Pi\xC3\xA8" "ces bonnes" && table.rows[1][1] == "9"
              && table.rows[8][0] == "TRS",
          "exporter les compteurs : chaque indicateur et sa valeur");
    rt.objectPart(pc, "raz", t);
    run(0.2);
    check(rt.production(pc).good == 0 && rt.production(pc).bad == 0 && eventHas(rt, "Production", "remis \xC3\xA0 z\xC3\xA9ro")
              && rt.production(pc).shift.rfind("Depuis ", 0) == 0,
          "RAZ : le poste repart de z\xC3\xA9ro, l'\xC3\xA9v\xC3\xA9nement le dit");
    p.security.enabled = true;
    rt.environment().write("Bons", sim::Value::integer(sim::Type::DInt, 5));
    run(0.2);
    rt.objectPart(pc, "raz", t);
    run(0.1);
    check(rt.production(pc).good == 3 && eventHas(rt, "Acc\xC3\xA8s refus\xC3\xA9", "permission \xC2\xAB Piloter \xC2\xBB"), "sous s\xC3\xA9" "curit\xC3\xA9, sans Piloter : RAZ refus\xC3\xA9" "e");
    p.security.enabled = false;

    // ---- le tableau de variables
    {
        const auto rows = variableRows(*p.views[0].object(tab));
        check(rows.size() == 4 && rows[0].unit == "\xC2\xB0" "C" && rows[1].expression == "Temp * 1.0" && rows[3].name == "Nom",
              "quatre lignes : expression, nom, unit\xC3\xA9");
        rt.objectPart(tab, "ligne:0", t);
        const auto* fs0 = rt.formState(tab);
        check(rt.focusedObject() == tab && fs0 && fs0->focus == "ligne:0" && fs0->text.at("ligne:0") == "60.00",
              "un clic sur la consigne : la saisie, sa valeur au format (60.00)");
        rt.typeText("75", t);
        rt.typeKey(EditKey::Enter, t);
        run(0.1);
        near(lot11Number(rt, "Consigne"), 75.0, "75, Entr\xC3\xA9" "e : la consigne est \xC3\xA9" "crite");
        check(rt.focusedObject() == kNoId && journalHas(rt, "Action", "saisie : Consigne = 75"), "... la saisie se ferme, le journal le dit");
        const auto shownValues = splitLiveValues(lot11Live(rt, tab, t).text("liveValues"));
        check(shownValues.size() == 4 && shownValues[0] == "75.00" && shownValues[1] == "20.00" && shownValues[2] == "FALSE",
              "le tableau montre ses r\xC3\xA9" "els \xC3\xA0 son format (75.00, 20.00), le reste tel quel");
        rt.objectPart(tab, "ligne:1", t);
        check(rt.formState(tab) && rt.formState(tab)->error && rt.formState(tab)->message.find("calcul") != std::string::npos && rt.focusedObject() == kNoId,
              "un calcul (Temp * 1.0) : en lecture seule, dit");
        rt.objectPart(tab, "ligne:2", t);
        rt.typeText("peut-\xC3\xAAtre", t);
        rt.typeKey(EditKey::Enter, t);
        check(rt.formState(tab)->error && rt.formState(tab)->message.find("vrai ou faux") != std::string::npos, "un bool\xC3\xA9" "en : vrai ou faux attendu");
        rt.typeKey(EditKey::Escape, t);
        rt.objectPart(tab, "ligne:2", t);
        rt.typeText("vrai", t);
        rt.typeKey(EditKey::Enter, t);
        check(rt.variable("Mode") && rt.variable("Mode")->isTruthy(), "\xC2\xAB vrai \xC2\xBB : Mode = TRUE");
        rt.objectPart(tab, "ligne:3", t);
        rt.typeText("Azote", t);
        rt.typeKey(EditKey::Enter, t);
        check(rt.variable("Nom") && rt.variable("Nom")->asString() == "Azote", "une cha\xC3\xAEne : Nom = 'Azote'");
        check(rt.exportTable("objet:Tableau", table) && table.rows.size() == 4 && table.rows[0][1] == "75" && table.rows[0][2] == "\xC2\xB0" "C",
              "exporter le tableau : nom, valeur, unit\xC3\xA9, expression");
        p.views[0].object(tab)->setFlag("writable", false);
        rt.objectPart(tab, "ligne:0", t);
        check(rt.formState(tab)->message.find("lecture seule") != std::string::npos && rt.focusedObject() == kNoId, "Valeurs modifiables d\xC3\xA9" "coch\xC3\xA9 : lecture seule");
        p.views[0].object(tab)->setFlag("writable", true);
        const Object& to = *p.views[0].object(tab);
        const auto g = variableTableLayout(to, 480, 220);
        const auto cell = g.cell(2, 1);
        same(variableTableHit(to, 480, 220, cell.x + cell.w / 2, cell.y + cell.h / 2, 4), "ligne:2", "le dessin se clique : la 3e valeur");
        same(variableTableHit(to, 480, 220, cell.x + cell.w / 2, 5, 4), "", "l'en-t\xC3\xAAte : rien");
    }

    // ---- l'editeur de recette
    {
        // 1.11 (REP-1, decision 74) : une recette marquee ($Gaz$, pour Dupliquer...) se lit sans ses $.
        p.views[0].object(ed)->set("recipe", "$Gaz$");
        run(0.2);
        check(rt.recipeEditor(ed) && rt.recipeEditor(ed)->recipe == "Gaz" && rt.recipeEditor(ed)->record == azote.id,
              "REP-1 : l'editeur de la recette $Gaz$ lit la recette Gaz (son premier jeu, Azote)");
        p.views[0].object(ed)->set("recipe", "Gaz");
        run(0.2);
        const auto* st = rt.recipeEditor(ed);
        check(st && st->recipe == "Gaz" && st->record == azote.id && st->values == std::vector<std::string>{"6.5", "'Azote'"} && !st->dirty(),
              "l'\xC3\xA9" "diteur montre le premier jeu (Azote), sans modification");
        check(st && st->installed.size() == 2 && std::atof(st->installed[0].c_str()) == 6.0, "... et l'installation (Consigne_P = 6)");
        rt.objectPart(ed, "ligne:0", t);
        rt.typeText("7.5", t);
        rt.typeKey(EditKey::Enter, t);
        st = rt.recipeEditor(ed);
        check(st->values[0] == "7.5" && st->edited[0] && !st->edited[1] && st->dirty(), "7.5 : la valeur est modifi\xC3\xA9" "e (en jaune), pas encore enregistr\xC3\xA9" "e");
        rt.objectPart(ed, "suivant", t);
        check(rt.recipeEditor(ed)->record == azote.id && rt.recipeEditor(ed)->error, "\xE2\x80\xBA avec des modifications : refus\xC3\xA9 (Enregistrer ou Annuler d'abord)");
        rt.objectPart(ed, "bouton:Appliquer", t);
        run(0.2);
        near(lot11Number(rt, "Consigne_P"), 7.5, "Appliquer : les valeurs montr\xC3\xA9" "es vont dans l'installation");
        check(rt.variable("Nom_Gaz")->asString() == "Azote" && rt.recipeEditor(ed)->message.find("pas enregistr") != std::string::npos,
              "... toutes (Nom_Gaz = Azote) ; le message dit \xC2\xAB pas enregistr\xC3\xA9" "es \xC2\xBB");
        rt.objectPart(ed, "bouton:Enregistrer", t);
        check(!recipeCalls.empty() && recipeCalls.back().op == "enregistrer" && recipeCalls.back().values == std::vector<std::string>{"7.5", "'Azote'"}
                  && p.recipes[0].records[0].values[0] == "7.5" && !rt.recipeEditor(ed)->dirty() && eventHas(rt, "Recette", "Azote enregistr"),
              "Enregistrer : le jeu garde 7.5 (le projet change), l'\xC3\xA9v\xC3\xA9nement le dit");
        rt.objectPart(ed, "ligne:0", t);
        rt.typeText("12", t);
        rt.typeKey(EditKey::Enter, t);
        check(rt.formState(ed) && rt.formState(ed)->error && rt.formState(ed)->message.find("de 0 \xC3\xA0 10") != std::string::npos,
              "12 bar : hors des bornes de l'\xC3\xA9l\xC3\xA9ment (de 0 \xC3\xA0 10), refus\xC3\xA9");
        rt.typeKey(EditKey::Escape, t);
        rt.environment().write("Consigne_P", sim::Value::real(8.0));
        run(0.2);
        rt.objectPart(ed, "bouton:Lire", t);
        st = rt.recipeEditor(ed);
        check(std::atof(st->values[0].c_str()) == 8.0 && st->edited[0] && st->message.find("1 valeur(s) lue(s)") != std::string::npos,
              "Lire : la valeur de l'installation (8) entre dans le jeu, \xC3\xA0 enregistrer");
        rt.objectPart(ed, "bouton:Annuler", t);
        st = rt.recipeEditor(ed);
        check(st->values[0] == "7.5" && !st->dirty(), "Annuler : retour au jeu enregistr\xC3\xA9");
        rt.objectPart(ed, "ligne:1", t);
        check(rt.formState(ed) && rt.formState(ed)->text.at("ligne:1") == "Azote", "un \xC3\xA9l\xC3\xA9ment de texte se tape sans ses apostrophes (Azote)");
        rt.typeText("Azote N2", t);
        rt.typeKey(EditKey::Enter, t);
        st = rt.recipeEditor(ed);
        check(st->values[1] == "'Azote N2'" && st->edited[1], "un \xC3\xA9l\xC3\xA9ment de texte : ce qui est tap\xC3\xA9 devient une cha\xC3\xAEne ('Azote N2')");
        rt.objectPart(ed, "bouton:Appliquer", t);
        check(rt.variable("Nom_Gaz")->asString() == "Azote N2", "... et s'applique tel quel");
        rt.objectPart(ed, "bouton:Lire", t);
        st = rt.recipeEditor(ed);
        check(st->values[1] == "'Azote N2'" && st->message.find("d\xC3\xA9j\xC3\xA0 ces valeurs") != std::string::npos,
              "Lire juste apr\xC3\xA8s Appliquer : l'installation a d\xC3\xA9j\xC3\xA0 ces valeurs (la cha\xC3\xAEne relue entre apostrophes)");
        rt.objectPart(ed, "bouton:Annuler", t);
        rt.objectPart(ed, "suivant", t);
        check(rt.recipeEditor(ed)->record == argon.id && rt.recipeEditor(ed)->values[0] == "5.0", "\xE2\x80\xBA : le jeu Argon");
        rt.objectPart(ed, "precedent", t);
        rt.objectPart(ed, "precedent", t);
        check(rt.recipeEditor(ed)->record == argon.id, "\xE2\x80\xB9 \xE2\x80\xB9 : en boucle");
        rt.objectPart(ed, "bouton:Nouveau", t);
        check(recipeCalls.back().op == "ajouter" && recipeCalls.back().values[0] == "5.0" && p.recipes[0].records.size() == 3,
              "Nouveau : un jeu cr\xC3\xA9\xC3\xA9 avec les valeurs montr\xC3\xA9" "es");
        p.security.enabled = true;
        rt.objectPart(ed, "bouton:Appliquer", t);
        check(rt.recipeEditor(ed)->error && rt.recipeEditor(ed)->message.find("Recettes") != std::string::npos, "sous s\xC3\xA9" "curit\xC3\xA9 : la permission Recettes");
        p.security.enabled = false;
        const Object& eo = *p.views[0].object(ed);
        const auto l = recipeEditorLayout(eo, 620, 300);
        check(l.buttons.size() == 5 && l.buttons[0].label == "Enregistrer" && l.buttons[4].label == "Nouveau" && l.compare,
              "le dessin : cinq boutons, dans l'ordre ; la comparaison");
        same(recipeEditorHit(eo, 620, 300, l.prev.x + l.prev.w / 2, l.prev.y + l.prev.h / 2, 2), "precedent", "\xE2\x80\xB9");
        same(recipeEditorHit(eo, 620, 300, l.buttons[1].box.x + 3, l.buttons[1].box.y + 3, 2), "bouton:Appliquer", "Appliquer");
        const auto c1 = l.grid.cell(1, 1);
        same(recipeEditorHit(eo, 620, 300, c1.x + c1.w / 2, c1.y + c1.h / 2, 2), "ligne:1", "la valeur du 2e \xC3\xA9l\xC3\xA9ment");
        same(recipeValueShown("'Azote N2'") + "|" + recipeValueShown("'l$'air $$'") + "|" + recipeValueShown("12.5") + "|" + recipeValueShown("'"),
             "Azote N2|l'air $|12.5|'", "recipeValueShown : une cha\xC3\xAEne sans apostrophes ($' et $$ rendus), le reste tel quel");
        const auto narrow = recipeEditorLayout(eo, 480, 300);
        check(!narrow.buttons.empty() && narrow.buttons[0].label == "Enregistrer" && narrow.buttons.size() < 5
                  && narrow.buttons.back().box.right() <= 480 && narrow.next.right() < narrow.buttons[0].box.x,
              "trop \xC3\xA9troit : les derniers boutons tombent, Enregistrer reste ; rien ne se chevauche");
        p.views[0].object(ed)->set("buttons", "Appliquer;Imprimer");
        const auto few = recipeEditorLayout(*p.views[0].object(ed), 620, 300);
        check(few.buttons.size() == 2 && few.buttons[1].label == "Imprimer", "les boutons choisis, dans l'ordre (un inconnu aussi : G\xC3\xA9n\xC3\xA9rer le signale)");
        rt.objectPart(ed, "bouton:Imprimer", t);
        check(journalHas(rt, "Erreur", "bouton inconnu : Imprimer"), "... un clic dessus : le journal le dit");
        p.views[0].object(ed)->set("buttons", "Enregistrer;Appliquer;Lire;Annuler;Nouveau");
    }

    // ---- l'export : formats, noms, fichiers
    {
        check(exportFormatFrom("excel") == ExportFormat::Excel && exportFormatFrom("rapport.PDF") == ExportFormat::Pdf
                  && exportFormatFrom("x.txt") == ExportFormat::Csv && exportFormatFrom("CSV") == ExportFormat::Csv && !exportFormatFrom("doc"),
              "le format : son nom, ou l'extension du fichier");
        same(exportFileName("alarmes 2026/09/24: nuit.csv", ExportFormat::Excel), "alarmes 2026-09-24- nuit.xlsx",
             "un nom s\xC3\xBBr : / et : deviennent des tirets, l'extension suit le format");
        same(exportFileName("", ExportFormat::Pdf), "export.pdf", "un nom vide : export");
        same(exportFileName("  .rapport. ", ExportFormat::Csv), "rapport.csv", "les points et espaces du bord s'en vont");
        ExportTable t1;
        t1.title = "Essai \xC3\xA0 12 \xC2\xB0" "C";
        t1.subtitle = "2026-09-24 12:00:00 - Poste";
        t1.headers = {"Nom", "Valeur"};
        t1.rows = {{"a;b", "12.5"}, {"dit \"x\"", ""}};
        const std::string csv = exportCsv(t1);
        check(csv.rfind("\xEF\xBB\xBFNom;Valeur\r\n", 0) == 0 && csv.find("\"a;b\";12.5\r\n") != std::string::npos
                  && csv.find("\"dit \"\"x\"\"\";\r\n") != std::string::npos,
              "CSV : le BOM, le s\xC3\xA9parateur ;, les guillemets quand il faut");
        const Bytes xlsx = exportXlsx(t1);
        const std::string xs = lot11Text(xlsx);
        check(xs.rfind("PK\x03\x04", 0) == 0 && xs.find("xl/worksheets/sheet1.xml") != std::string::npos && xs.find("<c r=\"B4\"><v>12.5</v></c>") != std::string::npos
                  && xs.find("ySplit=\"3\"") != std::string::npos && xs.find("<autoFilter ref=\"A3:B5\"/>") != std::string::npos,
              "Excel : un classeur (zip), les nombres en nombres, l'en-t\xC3\xAAte fig\xC3\xA9 et filtrable");
        const fs::path xf = lot11Temp("essai.xlsx");
        {
            std::ofstream out(xf, std::ios::binary);
            out.write(reinterpret_cast<const char*>(xlsx.data()), static_cast<std::streamsize>(xlsx.size()));
        }
        const auto ex = readExternal(ExternalKind::Excel, xf.string());
        bool found = false, number = false;
        for (const auto& r : ex.rows)
            for (std::size_t k = 0; k < r.size(); ++k) {
                found = found || r[k] == "a;b";
                number = number || (r[k] == "12.5" && k == 1);
            }
        for (const auto& h : ex.headers) found = found || h == "a;b";
        check(ex.ok() && found && number && !ex.parts.empty() && ex.parts[0] == "Essai \xC3\xA0 12 \xC2\xB0" "C", "... relu par le lecteur Excel du projet : l'onglet, les cellules " + ex.error);
        const Bytes pdf = exportPdf(t1);
        const std::string ps = lot11Text(pdf);
        bool offsets = ps.find("xref\n0 7\n") != std::string::npos;
        const auto xref = ps.find("xref\n");
        for (int n = 1; n <= 6 && xref != std::string::npos; ++n) {
            const std::string entry = ps.substr(xref + 5 + 4 + 20 * static_cast<std::size_t>(n), 10);
            const auto off = static_cast<std::size_t>(std::atol(entry.c_str()));
            offsets = offsets && ps.compare(off, std::to_string(n).size() + 6, std::to_string(n) + " 0 obj") == 0;
        }
        check(ps.rfind("%PDF-1.4", 0) == 0 && ps.size() > 6 && ps.compare(ps.size() - 6, 6, "%%EOF\n") == 0 && offsets,
              "PDF : l'en-t\xC3\xAAte, la fin, chaque objet \xC3\xA0 sa place dans la table xref");
        check(ps.find("/MediaBox [0 0 842 595]") != std::string::npos && ps.find("(Essai \\340 12 \\260C) Tj") != std::string::npos
                  && ps.find("/Helvetica-Bold") != std::string::npos && ps.find("(Page 1 / 1) Tj") != std::string::npos,
              "... A4 paysage, le titre en Windows-1252 (\xC3\xA0 : \\340), le num\xC3\xA9ro de page");
        same(toWinAnsi("\xC3\xA9\xE2\x82\xAC\xE2\x9C\x93"), "\xE9\x80?", "toWinAnsi : \xC3\xA9, \xE2\x82\xAC, et \xC2\xAB ? \xC2\xBB pour ce que la police n'a pas");
        ExportTable big;
        big.title = "Long";
        big.headers = {"N"};
        for (int i = 0; i < 100; ++i) big.rows.push_back({std::to_string(i)});
        const std::string bs = lot11Text(exportPdf(big));
        check(bs.find("/Count 4") != std::string::npos && bs.find("(Page 4 / 4) Tj") != std::string::npos && bs.find("(Long \\(suite\\)) Tj") != std::string::npos,
              "100 lignes : quatre pages, l'en-t\xC3\xAAte r\xC3\xA9p\xC3\xA9t\xC3\xA9 (\xC2\xAB suite \xC2\xBB)");
    }

    // ---- l'export en marche : bouton, action, fonction
    {
        const std::string date = lot11Sys(rt, "Date").asString();
        rt.press(exp, t);
        rt.release(exp, t, true);
        check(written.size() == 1 && written[0].fileName == "trs_" + date + ".pdf" && written[0].format == "PDF" && written[0].source == "objet:Compteurs"
                  && written[0].data && lot11Text(*written[0].data).rfind("%PDF", 0) == 0,
              "le bouton d'export : trs_<date>.pdf, en PDF, le contenu des compteurs");
        check(rt.lastExport() == written[0].fileName && lot11Sys(rt, "LastExport").asString() == written[0].fileName
                  && lot11Sys(rt, "ExportCount").asInteger() == 1 && eventHas(rt, "Export", "objet:Compteurs"),
              "SYS.LastExport, SYS.ExportCount, l'\xC3\xA9v\xC3\xA9nement");
        rt.press(actBtn, t);
        rt.release(actBtn, t, true);
        check(written.size() == 2 && written[1].fileName == "gaz.csv" && written[1].format == "CSV" && written[1].rows == 3
                  && lot11Text(*written[1].data).find("Azote;7.5;Azote") != std::string::npos,
              "l'action Exporter des donn\xC3\xA9" "es : recette:Gaz en CSV (ses trois jeux)");
        check(rt.callScript("Exporter", t) && rt.variable("Ok")->isTruthy() && written.size() == 3 && written[2].fileName == "ev.xlsx"
                  && written[2].format == "Excel",
              "IHM_EXPORTER('\xC3\xA9v\xC3\xA9nements', 'ev.xlsx') : vrai, en Excel");
        std::string why;
        check(!rt.exportData("recette:Inconnue", "x", "CSV", t, "test", &why) && why.find("introuvable") != std::string::npos
                  && journalHas(rt, "Erreur", "export : recette 'Inconnue' introuvable"),
              "une source inconnue : rien d'\xC3\xA9" "crit, le journal le dit");
        check(rt.exportTable("syst\xC3\xA8me", table) && !table.rows.empty() && rt.exportTable("\xC3\xA9v\xC3\xA9nements", table) && table.headers.size() == 5,
              "les sources syst\xC3\xA8me et \xC3\xA9v\xC3\xA9nements");
        check(!rt.exportTable("mesures", table, &why) && why.find("historique") != std::string::npos, "les mesures : sans historique, refus\xC3\xA9");
        Runtime bare;
        bare.bind(&p, nullptr);
        bare.start(0);
        check(!bare.exportData("alarmes", "a", "CSV", 0.1, {}, &why) && why.find("ne sait pas") != std::string::npos,
              "sans \xC3\xA9" "cran pour l'\xC3\xA9" "crire : refus\xC3\xA9, dit");
    }

    // ---- enregistre et relu ; Generer
    {
        const fs::path dir = lot11Temp("projet_production");
        fs::remove_all(dir);
        fs::create_directories(dir);
        Project q = p;
        // Tous les objets du lot 11 dans une vue : ils reviennent a l'identique.
        View all = makeView(q, "Vue_Tous");
        double x = 0;
        for (const auto k : {Kind::BarChart, Kind::XYChart, Kind::StateChart, Kind::PieChart, Kind::RadarChart, Kind::Histogram, Kind::AlarmBanner,
                             Kind::AlarmCounter, Kind::AlarmSummary, Kind::AlarmInstruction, Kind::AlarmStats, Kind::ProductionCounter,
                             Kind::VariableTable, Kind::RecipeEditor, Kind::ExportButton}) {
            (void)edit::add(q, all, k, x, 10);
            x += 20;
        }
        all.objects.back().set("fileName", "a;b \"c\"");
        q.views.push_back(all);
        check(static_cast<bool>(save(q, dir.string())), "enregistrer les quinze objets du lot 11");
        auto back = load(dir.string());
        check(back && back->views == q.views && back->recipes == q.recipes, "relus \xC3\xA0 l'identique");
        check(kFormatVersion >= 10, "le format des projets : 10 ou plus (lot 12 : 11)");

        Project g;
        View w = makeView(g, "V");
        const Id c1 = edit::add(g, w, Kind::ProductionCounter, 10, 10);
        w.object(c1)->set("shifts", "6h;30:00");
        const Id r1 = edit::add(g, w, Kind::RecipeEditor, 10, 300);
        w.object(r1)->set("recipe", "Absente");
        const Id e1 = edit::add(g, w, Kind::ExportButton, 600, 10);
        w.object(e1)->set("exportSource", "objet:Rien");
        const Id e2 = edit::add(g, w, Kind::ExportButton, 600, 100);
        w.object(e2)->set("exportSource", "nulle part");
        w.object(e2)->set("fileFormat", "Word");
        const Id val = edit::add(g, w, Kind::Valve, 900, 10);
        w.object(val)->set("opening", "abc");
        const Id val2 = edit::add(g, w, Kind::Valve, 900, 100);
        w.object(val2)->set("opening", "150");
        const Id val3 = edit::add(g, w, Kind::Valve, 900, 200);
        w.object(val3)->set("valveType", "r\xC3\xA9glante");
        const Id tank = edit::add(g, w, Kind::Tank, 1000, 10);
        w.object(tank)->set("low", "80");
        w.object(tank)->set("high", "20");
        w.object(tank)->set("highAlarm", "x");
        g.views = {w};
        g.config.startView = w.id;
        const auto issues = generate(g, [](std::string_view) { return false; });
        const auto has = [&](Id object, std::string_view text, Issue::Severity sev) {
            for (const auto& i : issues)
                if (i.object == object && i.severity == sev && i.message.find(text) != std::string::npos) return true;
            return false;
        };
        using S = Issue::Severity;
        check(has(c1, "aucun compteur de pi\xC3\xA8" "ces bonnes", S::Error) && has(c1, "d\xC3\xA9" "buts de poste", S::Error), "G\xC3\xA9n\xC3\xA9rer : des compteurs sans compteur, un poste illisible");
        check(has(r1, "recette 'Absente' introuvable", S::Error), "... une recette introuvable");
        check(has(e1, "donn\xC3\xA9" "es export\xC3\xA9" "es", S::Error) && has(e2, "donn\xC3\xA9" "es export\xC3\xA9" "es", S::Error) && has(e2, "format inconnu", S::Warning),
              "... un export sans source valable, un format inconnu");
        check(has(val, "n'est pas un nombre", S::Error) && has(val2, "hors de 0 \xC3\xA0 100", S::Warning) && has(val3, "sans ouverture", S::Info),
              "... la vanne r\xC3\xA9glante : une ouverture illisible, hors bornes, absente");
        check(has(tank, "seuil bas au-dessus du seuil haut", S::Warning) && has(tank, "n'est pas un nombre", S::Error),
              "... la cuve : des seuils invers\xC3\xA9s, un seuil illisible");
    }
}

// ------------------------------------------------ lot 11 : exemples et restes du lot 10 --
void exemplesLot11() {
    std::printf("lot 11 : les exemples anim\xC3\xA9s, la vanne r\xC3\xA9glante, les seuils des contenants\n");
    // Chaque exemple du lot 11 tourne, avec un ecran qui sait enregistrer et exporter.
    std::string failures11;
    for (const auto k : {Kind::BarChart, Kind::XYChart, Kind::StateChart, Kind::PieChart, Kind::RadarChart, Kind::Histogram, Kind::AlarmBanner,
                         Kind::AlarmCounter, Kind::AlarmSummary, Kind::AlarmInstruction, Kind::AlarmStats, Kind::ProductionCounter,
                         Kind::VariableTable, Kind::RecipeEditor, Kind::ExportButton}) {
        auto ex = examples::exampleFor(k);
        if (!ex) { failures11 += std::string(kindKey(k)) + " (pas d'exemple) "; continue; }
        Runtime rt;
        std::size_t exports = 0;
        std::vector<std::string> formats;
        Runtime::Hooks h;
        h.exportFile = [&](const ExportRequest& rq, std::string*) {
            ++exports;
            formats.push_back(rq.format);
            return true;
        };
        h.recipeRequest = [&](const RecipeRequest& rq) {
            if (rq.op != "enregistrer") return;
            for (auto& r : ex->project.recipes)
                if (r.name == rq.recipe)
                    if (auto* rec = r.record(rq.record)) rec->values = rq.values;
        };
        rt.setHooks(h);
        rt.bind(&ex->project, nullptr);
        rt.start(0.0);
        double played = 0;
        std::size_t steps = 0;
        std::map<std::string, std::string> probe;
        for (double t = 0.05; t <= ex->period + 1e-9; t += 0.05) {
            rt.tick(t);
            steps += examples::play(*ex, rt, played, t, t);
            played = t;
            const auto* v = rt.composedView(rt.currentView());
            const Object* self = nullptr;
            if (v) for (const auto& o : v->objects) if (o.kind == k && !self) self = &o;
            if (!self) continue;
            if (k == Kind::AlarmBanner && std::fabs(t - 10.0) < 0.026) {
                const int shown = rt.bannerAlarm(*self);
                probe["avant"] = shown >= 0 ? rt.alarms()[static_cast<std::size_t>(shown)].name : "";
            }
            if (k == Kind::ProductionCounter && std::fabs(t - 11.9) < 0.026) probe["avant"] = formatNumber(rt.production(self->id).good);
            if (k == Kind::ProductionCounter && std::fabs(t - 12.5) < 0.026) probe["apres"] = formatNumber(rt.production(self->id).good);
        }
        if (!ex->steps.empty() && steps != ex->steps.size()) failures11 += std::string(kindKey(k)) + " (gestes) ";
        switch (k) {
            case Kind::AlarmBanner: {
                const auto* acked = [&]() -> const LiveAlarm* {
                    for (const auto& a : rt.alarms()) if (a.name == probe["avant"]) return &a;
                    return nullptr;
                }();
                check(!probe["avant"].empty() && acked && acked->acked, "l'exemple du bandeau : \xC2\xAB +2 \xC2\xBB puis Acquitter acquitte l'alarme montr\xC3\xA9" "e (" + probe["avant"] + ")");
                break;
            }
            case Kind::ProductionCounter:
                check(std::atof(probe["avant"].c_str()) > 100 && std::atof(probe["apres"].c_str()) < 20,
                      "l'exemple des compteurs : RAZ \xC3\xA0 12 s (" + probe["avant"] + " puis " + probe["apres"] + ")");
                break;
            case Kind::VariableTable:
                near(lot11Number(rt, "Consigne_Temp"), 75.0, "l'exemple du tableau : la consigne passe \xC3\xA0 75 au clavier");
                break;
            case Kind::RecipeEditor: {
                const auto* r = ex->project.recipes.empty() ? nullptr : &ex->project.recipes[0];
                check(r && !r->records.empty() && r->records[0].values[0] == "7.5", "l'exemple de l'\xC3\xA9" "diteur : 7.5 enregistr\xC3\xA9 dans le jeu");
                break;
            }
            case Kind::ExportButton:
                check(exports == 3 && formats == std::vector<std::string>{"CSV", "Excel", "PDF"}, "l'exemple du bouton d'export : trois fichiers, trois formats");
                break;
            case Kind::AlarmCounter:
                check(rt.unacknowledged() == 0, "l'exemple du compteur : tout est acquitt\xC3\xA9 \xC3\xA0 la fin");
                break;
            default:
                break;
        }
    }
    check(failures11.empty(), "les quinze exemples du lot 11 jouent leurs gestes " + failures11);

    // ---- la vanne reglante et les seuils des contenants (restes du lot 10)
    const auto valve = makeObject(Kind::Valve, 1, "V", 0, 0, 1);
    check(valve.find("opening") && valve.text("opening").empty() && valve.find("moving"), "la vanne : une ouverture et un mouvement (vides : tout ou rien)");
    bool thresholds = true;
    for (const auto k : {Kind::Tank, Kind::Silo, Kind::Hopper, Kind::GasBottle}) {
        const auto o = makeObject(k, 1, "C", 0, 0, 1);
        for (const char* key : {"lowAlarm", "low", "high", "highAlarm"}) thresholds = thresholds && o.find(key) && o.text(key).empty();
        thresholds = thresholds && o.text("colorWarning") == "#F2C94C" && o.text("colorAlarm") == "#E5534B";
    }
    check(thresholds, "cuve, silo, tr\xC3\xA9mie, bouteille : quatre seuils (vides), leurs couleurs");
    auto ex = examples::exampleFor(Kind::Valve);
    const Object* ev = nullptr;
    if (ex) for (const auto& o : ex->project.views[0].objects) if (o.kind == Kind::Valve) ev = &o;
    check(ev && ev->text("valveType") == "r\xC3\xA9glante" && !ev->find("opening")->expr.empty() && !ev->find("moving")->expr.empty(),
          "l'exemple de la vanne : r\xC3\xA9glante, son ouverture et son mouvement pilot\xC3\xA9s");
    auto tex = examples::exampleFor(Kind::Tank);
    const Object* et = nullptr;
    if (tex) for (const auto& o : tex->project.views[0].objects) if (o.kind == Kind::Tank) et = &o;
    check(et && et->text("low") == "25" && et->text("high") == "80" && et->text("highAlarm") == "88", "l'exemple de la cuve : ses seuils L, H, HH");
    // Les variables d'instances les publient.
    Project p;
    p.programs.variables.push_back(hmiVar(p, "Pos", "REAL", "42.0"));
    View w = makeView(p, "Vue_V");
    const Id vid = edit::add(p, w, Kind::Valve, 10, 10);
    w.object(vid)->name = "V_12";
    w.object(vid)->set("valveType", "r\xC3\xA9glante");
    w.object(vid)->setExpr("opening", "Pos");
    p.views = {w};
    p.config.startView = w.id;
    Runtime rt;
    rt.bind(&p, nullptr);
    rt.start(0);
    rt.tick(0.1);
    const Object live = lot11Live(rt, vid, 0.1);
    double opening = 0;
    check(parseNumber(live.text("opening"), opening) && opening == 42.0, "en marche : l'ouverture suit son expression (42 %)");
    sim::Value out;
    check(rt.publicRead("Vue_V.V_12.Opening", out) && std::fabs(out.asReal() - 42.0) < 1e-9, "variable d'instance : Vue_V.V_12.Opening = 42");
}
// ------------------------------------------------------ fin du lot 11 --

// ============================================================== lot 12 ======
//  La navigation et la structure : les sept objets, leur geometrie, la mise en
//  page en marche, l'historique, la vue d'accueil, le glisser, les clics.
namespace {
// Une vue ordinaire du projet, a la taille d'un ecran, avec un premier calque.
View& lot12View(Project& p, const char* name, Id up = kNoId) {
    View v = makeView(p, name);
    v.width = 1280;
    v.height = 800;
    v.upView = up;
    p.views.push_back(std::move(v));
    return p.views.back();
}
Object& lot12Add(Project& p, View& v, Kind k, const char* name, double x, double y, double w, double h) {
    const Id id = edit::add(p, v, k, x, y);
    Object& o = *v.object(id);
    o.name = name;
    o.setNumber("w", w);
    o.setNumber("h", h);
    return o;
}
} // namespace

void navigationLot12() {
    std::printf("lot 12 : les objets de navigation et de structure (g\xC3\xA9om\xC3\xA9trie, mise en page)\n");
    const Kind kinds[] = {Kind::NavBar, Kind::Breadcrumb, Kind::TabContainer, Kind::Frame, Kind::ScrollPanel, Kind::CollapsiblePanel, Kind::ZoneMap};
    bool placeable = true, keys = true;
    for (const auto k : kinds) {
        placeable = placeable && kindIsNavigation(k)
                 && std::find(std::begin(kPlaceableKinds), std::end(kPlaceableKinds), k) != std::end(kPlaceableKinds);
        keys = keys && kindFromKey(kindKey(k)) == k;
    }
    check(placeable && keys && !kindIsNavigation(Kind::Container) && !kindIsNavigation(Kind::ExportButton),
          "sept objets dans la biblioth\xC3\xA8que, leur cl\xC3\xA9 relue");
    same(std::string(kindLabel(Kind::NavBar)) + " | " + std::string(kindLabel(Kind::ZoneMap)),
         "Barre de navigation | Plan \xC3\xA0 zones", "leurs libell\xC3\xA9s");
    check(kindHoldsChildren(Kind::TabContainer) && kindHoldsChildren(Kind::Frame) && kindHoldsChildren(Kind::ScrollPanel)
              && kindHoldsChildren(Kind::CollapsiblePanel) && kindHoldsChildren(Kind::Container) && !kindHoldsChildren(Kind::NavBar)
              && !kindHoldsChildren(Kind::Group),
          "le conteneur, les onglets, le cadre et les panneaux tiennent des enfants (pas le groupe)");
    const auto tabs0 = makeObject(Kind::TabContainer, 1, "T", 0, 0, 1);
    check(tabs0.text("tabs") == "Page 1;Page 2;Page 3" && tabs0.number("page") == 1 && tabs0.find("variable"), "un conteneur neuf : trois pages, la premi\xC3\xA8re montr\xC3\xA9" "e");
    check(makeObject(Kind::CollapsiblePanel, 1, "C", 0, 0, 1).flag("pushBelow") && !makeObject(Kind::CollapsiblePanel, 1, "C", 0, 0, 1).flag("collapsed"),
          "un panneau repliable neuf : d\xC3\xA9pli\xC3\xA9, il pousse ce qui est dessous");

    // ---- la barre de navigation
    Project p;
    View& accueil = lot12View(p, "Vue_Accueil");
    const Id accueilId = accueil.id;
    const Id ligneId = lot12View(p, "Vue_Ligne_1", accueilId).id;
    const Id detailId = lot12View(p, "Vue_Detail", ligneId).id;
    View popup = makeView(p, "Popup_Aide");
    popup.role = "popup";
    p.views.push_back(popup);
    View modele = makeView(p, "Modele_Cadre");
    modele.role = "modele";
    p.views.push_back(modele);
    p.config.startView = accueilId;
    Object bar = makeObject(Kind::NavBar, 99, "Barre", 0, 0, 1);
    auto items = navItems(&p, bar);
    std::string auto3;
    for (const auto& it : items) auto3 += it.view + "=" + it.label + ";";
    same(auto3, "Vue_Accueil=Accueil;Vue_Ligne_1=Ligne 1;Vue_Detail=Detail;", "sans liste : les vues ordinaires (ni popup, ni mod\xC3\xA8le), Vue_ et _ \xC3\xB4t\xC3\xA9s");
    bar.set("views", "Vue_Detail; Vue_Accueil");
    bar.set("labels", ";Maison");
    items = navItems(&p, bar);
    check(items.size() == 2 && items[0].label == "Detail" && items[1].label == "Maison", "une liste : dans son ordre, un libell\xC3\xA9 vide garde le nom");
    bar.setFlag("backForward", true);
    bar.setNumber("w", 600);
    bar.setNumber("h", 48);
    const auto nl = navBarLayout(bar, 600, 48, 2);
    check(nl.back.w > 0 && nl.forward.x > nl.back.x && nl.items.size() == 2 && nl.items[0].x > nl.forward.right(),
          "Pr\xC3\xA9" "c\xC3\xA9" "dent, Suivant, puis les boutons");
    same(navBarHit(bar, 600, 48, nl.back.cx(), 20, 2) + " " + navBarHit(bar, 600, 48, nl.forward.cx(), 20, 2) + " "
             + navBarHit(bar, 600, 48, nl.items[1].cx(), 20, 2),
         "precedent suivant vue:1", "les clics de la barre");
    bar.set("orientation", "verticale");
    const auto vl = navBarLayout(bar, 200, 400, 2);
    check(vl.vertical && vl.items[1].y > vl.items[0].bottom() - 1 && vl.items[0].w > 150, "verticale : les boutons empil\xC3\xA9s");

    // ---- le fil d'Ariane
    Object crumbs = makeObject(Kind::Breadcrumb, 98, "Fil", 0, 0, 1);
    auto trail = breadcrumbTrail(p, crumbs, "Vue_Detail", {}, "Vue_Accueil");
    std::string tr;
    for (const auto& c : trail) tr += c.label + ">";
    same(tr, "Accueil>Ligne 1>Detail>", "hi\xC3\xA9rarchie : les vues parentes, jusqu'\xC3\xA0 la racine");
    p.view(accueilId)->upView = detailId;     // une boucle
    trail = breadcrumbTrail(p, crumbs, "Vue_Detail", {}, "Vue_Accueil");
    check(trail.size() == 3 && trail.back().view == "Vue_Detail", "une boucle de vues parentes s'arr\xC3\xAAte");
    p.view(accueilId)->upView = kNoId;
    trail = breadcrumbTrail(p, crumbs, "Vue_Ligne_1", {}, "Vue_Detail");
    check(trail.size() == 3 && trail.front().view == "Vue_Detail", "l'accueil en t\xC3\xAAte quand la cha\xC3\xAEne n'y remonte pas");
    crumbs.set("trail", "historique");
    crumbs.setNumber("maxItems", 3);
    trail = breadcrumbTrail(p, crumbs, "Vue_Detail", {"Vue_Accueil", "Vue_Ligne_1", "Vue_Accueil", "Vue_Ligne_1"}, "");
    check(trail.size() == 3 && trail[0].back == 2 && trail[1].back == 1 && trail[2].back == 0, "historique : les derni\xC3\xA8res vues, et les pas pour y revenir");
    const auto cl = breadcrumbLayout(crumbs, 600, 36, trail);
    check(cl.crumbs.size() == 3 && cl.separators.size() == 2 && breadcrumbHit(crumbs, 600, 36, cl.crumbs[1].cx(), 18, trail) == "etape:1",
          "une \xC3\xA9tape se clique");
    const auto tight = breadcrumbLayout(crumbs, 90, 36, trail);
    check(tight.crumbs.back().w > 0 && tight.crumbs.front().w == 0, "trop long : le d\xC3\xA9" "but sort, la vue courante reste");

    // ---- le conteneur a onglets
    Object t = makeObject(Kind::TabContainer, 97, "Onglets", 0, 0, 1);
    t.set("tabs", "R\xC3\xA9glages;Mesures");
    const auto tl = tabLayout(t, 500, 300, 2);
    check(tl.tabs.size() == 2 && tl.content.y == 34 && tl.content.h == 266, "deux onglets en haut, la page dessous");
    same(tabHit(t, 500, 300, tl.tabs[1].cx(), 10, 2) + " " + tabHit(t, 500, 300, 250, 200, 2), "onglet:2 ", "un clic sur le 2e onglet ; la page ne se clique pas");
    t.setNumber("page", 7);
    check(shownTabPage(t) == 2, "une page au-del\xC3\xA0 du nombre d'onglets : la derni\xC3\xA8re");
    t.set("tabPosition", "bas");
    check(tabLayout(t, 500, 300, 2).tabs[0].y == 266 && tabLayout(t, 500, 300, 2).content.y == 0, "les onglets en bas");

    // ---- le cadre
    Object fr = makeObject(Kind::Frame, 96, "Cadre", 0, 0, 1);
    fr.set("title", "Pompe");
    const auto fl = frameLayout(fr, 300, 200);
    check(fl.band.w == 0 && fl.top > 0 && fl.title.w > 0 && fl.content.y >= fl.top, "bordure : le titre coupe la ligne du haut");
    fr.set("titleStyle", "bandeau");
    check(frameLayout(fr, 300, 200).band.w == 300 && frameLayout(fr, 300, 200).top == 0, "bandeau : une bande en haut");

    // ---- le panneau repliable
    Object cp = makeObject(Kind::CollapsiblePanel, 95, "Panneau", 0, 0, 1);
    same(collapsibleHit(cp, 360, 220, 100, 10) + "|" + collapsibleHit(cp, 360, 220, 100, 100), "entete|", "le bandeau se clique, pas le contenu");

    // ---- le plan a zones
    const auto zones = parseMapZones("Armoire A | 10,10 40,10 40,50 10,50 | | Vue_Ligne_1 | #3A6EA5\n\nStockage | 50,10,40,80 | Local\n");
    check(zones.size() == 2 && zones[0].points.size() == 4 && zones[0].view == "Vue_Ligne_1" && zones[0].color == "#3A6EA5"
              && zones[0].alarmGroup() == "Armoire A" && zones[1].points.size() == 4 && zones[1].points[2] == std::make_pair(90.0, 90.0)
              && zones[1].alarmGroup() == "Local",
          "les zones : nom, points (un rectangle x,y,l,h), groupe (vide : le nom), vue, couleur");
    same(formatMapZones(zones), "Armoire A | 10,10 40,10 40,50 10,50 |  | Vue_Ligne_1 | #3A6EA5\nStockage | 50,10 90,10 90,90 50,90 | Local",
         "\xC3\xA9" "crites comme elles se relisent");
    check(parseMapZones(formatMapZones(zones)).size() == 2, "relues");
    check(pointInPolygon(zones[0].points, 20, 20) && !pointInPolygon(zones[0].points, 45, 20), "un point dans un polygone");
    Object map = makeObject(Kind::ZoneMap, 94, "Plan", 0, 0, 1);
    map.set("mapZones", formatMapZones(zones));
    same(zoneMapHit(map, 1000, 500, 200, 100) + " " + zoneMapHit(map, 1000, 500, 700, 250) + " " + zoneMapHit(map, 1000, 500, 460, 480),
         "zone:0 zone:1 ", "un clic dans une zone (en % du plan)");
    const auto zc = zoneCenter(zones[0], 1000, 500);
    near(zc.first, 250, "le centre d'une zone (x)");

    // ---- la mise en page en marche
    Project q;
    View& v = lot12View(q, "Vue_Struct");
    const Id tabsId = lot12Add(q, v, Kind::TabContainer, "Onglets", 20, 20, 400, 300).id;
    Object& a1 = lot12Add(q, v, Kind::Text, "Page1", 40, 80, 100, 30);
    const Id a1Id = a1.id;
    check(adopt(v, a1Id, tabsId) && v.object(a1Id)->parent == tabsId && v.object(a1Id)->number("tabPage") == 1,
          "ranger un objet dans le conteneur : sa page est celle montr\xC3\xA9" "e");
    Object& a2 = lot12Add(q, v, Kind::Text, "Page2", 40, 80, 100, 30);
    const Id a2Id = a2.id;
    v.object(tabsId)->setNumber("page", 2);
    check(adopt(v, a2Id, tabsId) && v.object(a2Id)->number("tabPage") == 2, "\xE2\x80\xA6 la page 2 montr\xC3\xA9" "e : sur la page 2");
    check(!v.effectivelyHidden(*v.object(a2Id)) && v.effectivelyHidden(*v.object(a1Id)), "dans l'\xC3\xA9" "diteur : l'autre page ne se voit pas");
    check(edit::hitTest(v, 60, 90) == a2Id, "un clic prend l'enfant de la page montr\xC3\xA9" "e, pas le conteneur");
    // L'ordre de dessin : un enfant passe au-dessus de son parent.
    check(v.indexOf(a2Id) > v.indexOf(tabsId), "un objet rang\xC3\xA9 est dessin\xC3\xA9 au-dessus de son parent");
    check(!adopt(v, tabsId, a2Id), "pas dans un de ses descendants");
    const Id panelId = lot12Add(q, v, Kind::CollapsiblePanel, "Panneau", 500, 20, 300, 200).id;
    Object& inside = lot12Add(q, v, Kind::Text, "Dedans", 510, 80, 200, 30);
    const Id insideId = inside.id;
    (void)adopt(v, insideId, panelId);
    const Id belowId = lot12Add(q, v, Kind::Text, "Dessous", 520, 240, 200, 30).id;
    const Id wideId = lot12Add(q, v, Kind::Text, "Large", 450, 260, 600, 30).id;
    const Id scrollId = lot12Add(q, v, Kind::ScrollPanel, "Defilant", 20, 400, 300, 200).id;
    Object& far = lot12Add(q, v, Kind::Text, "Loin", 40, 700, 200, 60);
    const Id farId = far.id;
    (void)adopt(v, farId, scrollId);
    const Id holderHit = holderAt(v, 100, 500);
    check(holderHit == scrollId, "le panneau sous un point : o\xC3\xB9 va un objet pos\xC3\xA9");
    // En marche : la page 2, le panneau replie, le defilement.
    View shown = v;
    shown.object(panelId)->setFlag("collapsed", true);
    shown.object(scrollId)->setNumber("scrollY", 5000);
    layoutStructures(shown);
    check(!shown.object(a1Id)->flag("visible", true) && shown.object(a2Id)->flag("visible", true), "en marche : l'autre page est cach\xC3\xA9" "e");
    check(!shown.object(insideId)->flag("visible", true), "le contenu du panneau repli\xC3\xA9 est cach\xC3\xA9");
    near(shown.object(panelId)->number("h"), 34, "le panneau repli\xC3\xA9 : la hauteur de son bandeau");
    near(shown.object(belowId)->number("y"), 240 - 166, "l'objet du dessous remonte d'autant (166)");
    near(shown.object(wideId)->number("y"), 260, "un objet plus large ne remonte pas");
    const auto sl = scrollLayout(v, *v.object(scrollId));
    near(shown.object(scrollId)->number("scrollY"), sl.maxY, "le d\xC3\xA9" "filement est born\xC3\xA9 au contenu");
    near(shown.object(farId)->number("y"), 700 - sl.maxY, "les enfants du panneau d\xC3\xA9" "filant se d\xC3\xA9" "calent");
    check(sl.maxY > 0 && sl.vbar.w > 0 && sl.vthumb.h >= 24, "le contenu d\xC3\xA9passe : une barre verticale");
    same(scrollHit(sl, sl.vbar.cx(), sl.vbar.bottom() - 1), "vbarre:1.0000", "le bas de la barre : 100 %");
    Box clip{};
    check(childClip(shown, *shown.object(scrollId), clip) && clippedAt(shown, *shown.object(farId), 100, 300)
              && !clippedAt(shown, *shown.object(farId), shown.object(farId)->number("x") + 5, shown.object(farId)->number("y") + 5),
          "un enfant hors du panneau ne se clique pas, dedans oui");
    // Une structure invisible cache ses enfants.
    View hidden = v;
    hidden.object(tabsId)->setFlag("visible", false);
    layoutStructures(hidden);
    check(!hidden.object(a2Id)->flag("visible", true), "un conteneur invisible cache ses enfants");
    // Un groupe dans un cadre : pris en entier.
    const Id frameId = lot12Add(q, v, Kind::Frame, "Cadre", 850, 400, 300, 200).id;
    const Id r1 = lot12Add(q, v, Kind::Rectangle, "R1", 870, 450, 40, 40).id;
    const Id r2 = lot12Add(q, v, Kind::Rectangle, "R2", 930, 450, 40, 40).id;
    const Id grp = edit::group(q, v, {r1, r2});
    (void)adopt(v, grp, frameId);
    check(edit::hitTest(v, 880, 460) == grp, "un groupe dans un cadre se prend en entier");
    const Id r3 = lot12Add(q, v, Kind::Rectangle, "R3", 1000, 450, 40, 40).id;
    (void)adopt(v, r3, frameId);
    check(edit::hitTest(v, 1010, 460) == r3, "un enfant direct du cadre se prend seul");
    edit::move(v, {frameId}, 10, 0);
    near(v.object(r3)->number("x"), 1010, "le cadre d\xC3\xA9plac\xC3\xA9 emm\xC3\xA8ne ses enfants");
}

void enMarcheLot12() {
    std::printf("lot 12 : la navigation en marche (historique, accueil, glisser, clics)\n");
    Project p;
    const Id a = lot12View(p, "Vue_A").id;
    const Id b = lot12View(p, "Vue_B", a).id;
    const Id c = lot12View(p, "Vue_C", b).id;
    const Id d = lot12View(p, "Vue_D").id;
    p.config.startView = a;
    Runtime rt;
    rt.bind(&p, nullptr);
    rt.start(0);
    const Transition none{};
    rt.navigate(b, none, 0.1);
    rt.navigate(c, none, 0.2);
    check(rt.backHistory().size() == 2 && rt.forwardHistory().empty(), "deux navigations : deux vues derri\xC3\xA8re");
    check(rt.goBack(none, 0.3) && rt.currentView() == b && rt.forwardHistory().size() == 1, "Pr\xC3\xA9" "c\xC3\xA9" "dent : la vue d'avant, la quitt\xC3\xA9" "e devant");
    check(rt.goBack(none, 0.4) && rt.currentView() == a && rt.forwardHistory().size() == 2, "encore : la premi\xC3\xA8re");
    std::string why;
    check(!rt.goBack(none, 0.5, 1, &why) && !why.empty(), "rien derri\xC3\xA8re : refus\xC3\xA9 (" + why + ")");
    check(rt.goForward(none, 0.6) && rt.currentView() == b, "Suivant : on repart");
    sim::Value out;
    check(rt.publicRead("SYS.CanGoBack", out) && out.isTruthy() && rt.publicRead("SYS.CanGoForward", out) && out.isTruthy(),
          "SYS.CanGoBack et SYS.CanGoForward");
    rt.navigate(d, none, 0.7);
    check(rt.forwardHistory().empty() && rt.backHistory().size() == 2, "une navigation ordinaire oublie Suivant");
    rt.navigate(c, none, 0.8);
    check(rt.goBack(none, 0.9, 2) && rt.currentView() == b && rt.forwardHistory().size() == 2, "deux pas en arri\xC3\xA8re d'un coup");
    check(rt.publicRead("SYS.HistoryDepth", out) && out.asInteger() == 1, "SYS.HistoryDepth");
    check(rt.publicRead("SYS.NavigationPath", out) && out.asString() == "A > B", "SYS.NavigationPath : A > B");
    for (int k = 0; k < 60; ++k) rt.navigate(k % 2 ? a : b, none, 1.0 + k * 0.01);
    check(rt.backHistory().size() == 50, "l'historique garde 50 vues au plus");
    rt.navigate(b, none, 1.9);
    check(rt.goHome(none, 2.0) && rt.currentView() == a, "Vue d'accueil : la vue de d\xC3\xA9marrage");
    check(!rt.goHome(none, 2.05, &why) && why.find("d\xC3\xA9j\xC3\xA0") != std::string::npos, "d\xC3\xA9j\xC3\xA0 sur l'accueil : rien \xC3\xA0 faire");
    check(rt.publicRead("SYS.HomeView", out) && out.asString() == "Vue_A", "SYS.HomeView");

    // ---- les actions et les fonctions IHM
    View& vb = *p.view(b);
    auto act = [](Operation op) { Action x; x.trigger = Trigger::Click; x.operation = op; return x; };
    const Id backBtn = edit::add(p, vb, Kind::Button, 10, 10);
    vb.object(backBtn)->actions.push_back(act(Operation::NavigateBack));
    const Id homeBtn = edit::add(p, vb, Kind::Button, 10, 60);
    vb.object(homeBtn)->actions.push_back(act(Operation::NavigateHome));
    p.programs.scripts.push_back(generalScript(p, "Retour", "IHM_PRECEDENTE();"));
    rt.navigate(b, none, 3.0);
    rt.press(backBtn, 3.1);
    rt.release(backBtn, 3.1, true);
    check(rt.currentView() == a, "l'action Vue pr\xC3\xA9" "c\xC3\xA9" "dente");
    rt.navigate(b, none, 3.2);
    rt.navigate(c, none, 3.3);
    check(rt.callScript("Retour", 3.4) && rt.currentView() == b, "IHM_PRECEDENTE()");
    rt.press(homeBtn, 3.5);
    rt.release(homeBtn, 3.5, true);
    check(rt.currentView() == a, "l'action Vue d'accueil");
    check(describeAction(act(Operation::NavigateBack)).find("Vue pr\xC3\xA9" "c\xC3\xA9" "dente") != std::string::npos
              && operationFromLabel("Vue suivante") == Operation::NavigateForward,
          "les libell\xC3\xA9s des op\xC3\xA9rations");

    // ---- la vue de demarrage du groupe, a la connexion et au lancement
    p.security.enabled = true;
    auto* maint = p.groupByName("Maintenance") ? const_cast<UserGroup*>(p.groupByName("Maintenance")) : nullptr;
    check(maint != nullptr, "le groupe Maintenance existe");
    if (maint) maint->startView = d;
    User u;
    u.id = p.allocate();
    u.login = "tech";
    u.group = maint ? maint->id : kNoId;
    u.salt = randomHex(16);
    u.passwordHash = passwordHash(u.salt, "1234");
    p.security.users.push_back(u);
    rt.logout(4.0);
    check(rt.login("tech", "1234", 4.1) && rt.currentView() == d, "connexion : la vue de d\xC3\xA9marrage du groupe s'ouvre");
    check(rt.homeView() == d, "l'accueil de l'utilisateur est celle de son groupe");
    p.security.startUser = "tech";
    Runtime rt2;
    rt2.bind(&p, nullptr);
    rt2.start(0);
    check(rt2.currentView() == d, "au lancement, l'utilisateur de d\xC3\xA9part ouvre la vue de son groupe");
    // Sans la permission Naviguer : refuse.
    p.security.startUser.clear();
    Runtime rt3;
    rt3.bind(&p, nullptr);
    rt3.start(0);
    rt3.navigate(b, none, 0.1);
    rt3.press(backBtn, 0.2);
    rt3.release(backBtn, 0.2, true);
    check(rt3.currentView() == b, "sans utilisateur, sous s\xC3\xA9" "curit\xC3\xA9 : Vue pr\xC3\xA9" "c\xC3\xA9" "dente est refus\xC3\xA9" "e");
    p.security.enabled = false;
    if (maint) maint->startView = kNoId;

    // ---- glisser
    Runtime rs;
    rs.bind(&p, nullptr);
    rs.start(0);
    check(!rs.swipe(1, 0.1, &why) && why.find("Configuration") != std::string::npos, "glisser : d\xC3\xA9sactiv\xC3\xA9 par d\xC3\xA9" "faut");
    p.config.swipeNavigation = true;
    check(rs.swipe(1, 0.2) && rs.currentView() == b, "glisser vers la gauche : la vue suivante (dans l'ordre du projet)");
    check(rs.animation() && rs.animation()->spec.kind == TransitionKind::Slide && rs.animation()->spec.direction == "droite",
          "... elle arrive en glissant depuis la droite");
    rs.tick(1.0);
    check(rs.swipe(-1, 1.1) && rs.currentView() == a, "vers la droite : la pr\xC3\xA9" "c\xC3\xA9" "dente");
    rs.tick(2.0);
    check(!rs.swipe(-1, 2.1, &why), "d\xC3\xA9j\xC3\xA0 sur la premi\xC3\xA8re : refus\xC3\xA9");
    // L'ordre d'une barre de navigation de la vue.
    Object& navOnA = *p.view(a)->object(edit::add(p, *p.view(a), Kind::NavBar, 0, 0));
    navOnA.name = "Barre";
    navOnA.set("views", "Vue_A;Vue_D;Vue_B");
    check(rs.swipe(1, 2.2) && rs.currentView() == d, "l'ordre est celui de la barre de navigation de la vue");

    // ---- les clics des objets
    Project q;
    View& qv = lot12View(q, "Vue_Q");
    const Id qv2 = lot12View(q, "Vue_Q2", qv.id).id;
    View& qvr = *q.view(q.views.front().id);
    q.config.startView = qvr.id;
    q.programs.variables.push_back(hmiVar(q, "Page_Var", "INT", "1"));
    q.programs.variables.push_back(hmiVar(q, "Zone_Var", "STRING", "''"));
    q.programs.variables.push_back(hmiVar(q, "Replie_Var", "BOOL", "FALSE"));
    const Id barId = lot12Add(q, qvr, Kind::NavBar, "Barre", 0, 0, 600, 48).id;
    qvr.object(barId)->set("views", "Vue_Q;Vue_Q2");
    qvr.object(barId)->set("transition", "Glissement");
    const Id tabId = lot12Add(q, qvr, Kind::TabContainer, "Onglets", 0, 60, 400, 300).id;
    const Id tabVarId = lot12Add(q, qvr, Kind::TabContainer, "Onglets_Var", 420, 60, 400, 300).id;
    qvr.object(tabVarId)->set("variable", "Page_Var");
    const Id scrId = lot12Add(q, qvr, Kind::ScrollPanel, "Defilant", 0, 400, 300, 200).id;
    const Id deep = lot12Add(q, qvr, Kind::Text, "Profond", 10, 1000, 100, 40).id;
    (void)adopt(qvr, deep, scrId);
    const Id colId = lot12Add(q, qvr, Kind::CollapsiblePanel, "Repli", 320, 400, 300, 150).id;
    const Id colVarId = lot12Add(q, qvr, Kind::CollapsiblePanel, "Repli_Var", 640, 400, 300, 150).id;
    qvr.object(colVarId)->set("variable", "Replie_Var");
    const Id mapId = lot12Add(q, qvr, Kind::ZoneMap, "Plan", 0, 620, 600, 160).id;
    qvr.object(mapId)->set("mapZones", "Armoire A | 0,0 50,0 50,100 0,100\nAilleurs | 50,0 100,0 100,100 50,100 | | Vue_Q2");
    qvr.object(mapId)->set("variable", "Zone_Var");
    Runtime rq;
    rq.bind(&q, nullptr);
    rq.start(0);
    rq.objectPart(tabId, "onglet:2", 0.1);
    check(rq.composedView(qvr.id)->object(tabId)->number("page") == 2, "un onglet cliqu\xC3\xA9 : la page \xC3\xA9" "crite en marche (Vue.Objet.Page)");
    check(rq.publicRead("Vue_Q.Onglets.Page", out) && out.asReal() == 2, "\xE2\x80\xA6 et lue comme variable d'instance");
    rq.objectPart(tabVarId, "onglet:3", 0.2);
    check(rq.variable("Page_Var") && rq.variable("Page_Var")->asInteger() == 3, "reli\xC3\xA9 \xC3\xA0 une variable : le clic l'\xC3\xA9" "crit");
    {
        LiveView lv;
        lv.bind(*rq.composedView(qvr.id));
        const View ev = lv.evaluate(rq.environment());
        check(ev.object(tabVarId)->number("page") == 3, "\xE2\x80\xA6 et la page montr\xC3\xA9" "e suit la variable");
    }
    const int wrote = rq.publicWrite("Vue_Q.Onglets.Page", sim::Value::integer(sim::Type::Int, 1));
    rq.tick(0.25);
    check(wrote == 1 && rq.composedView(qvr.id)->object(tabId)->number("page") == 1,
          "un script \xC3\xA9" "crit Vue_Q.Onglets.Page := 1");
    rq.objectPart(scrId, "vbarre:1", 0.3);
    const auto qsl = scrollLayout(*rq.composedView(qvr.id), *rq.composedView(qvr.id)->object(scrId));
    near(rq.composedView(qvr.id)->object(scrId)->number("scrollY"), std::round(qsl.maxY), "la barre tir\xC3\xA9" "e en bas : le bout du contenu");
    rq.objectPart(scrId, "defiler:-40", 0.35);
    near(rq.composedView(qvr.id)->object(scrId)->number("scrollY"), std::round(qsl.maxY) - 40, "la molette remonte de 40");
    rq.objectPart(colId, "entete", 0.4);
    check(rq.composedView(qvr.id)->object(colId)->flag("collapsed"), "un clic sur le bandeau replie le panneau");
    rq.objectPart(colId, "entete", 0.45);
    check(!rq.composedView(qvr.id)->object(colId)->flag("collapsed"), "\xE2\x80\xA6 un autre le d\xC3\xA9plie");
    rq.objectPart(colVarId, "entete", 0.5);
    check(rq.variable("Replie_Var") && rq.variable("Replie_Var")->isTruthy(), "reli\xC3\xA9 \xC3\xA0 une variable : le repli l'\xC3\xA9" "crit");
    rq.objectPart(mapId, "zone:0", 0.6);
    check(rq.selectedZone() == "Armoire A" && rq.variable("Zone_Var") && rq.variable("Zone_Var")->asString() == "Armoire A"
              && rq.currentView() == qvr.id,
          "une zone cliqu\xC3\xA9" "e : choisie (SYS.AlarmZoneSelected, la variable)");
    rq.objectPart(mapId, "zone:1", 0.7);
    check(rq.currentView() == qv2 && rq.animation() && rq.animation()->spec.kind == TransitionKind::Zoom, "une zone qui a une vue l'ouvre (en zoomant)");
    rq.tick(2.0);
    check(rq.goBack(none, 2.1) && rq.currentView() == qvr.id, "Pr\xC3\xA9" "c\xC3\xA9" "dent revient au plan");
    rq.objectPart(barId, "vue:1", 2.2);
    check(rq.currentView() == qv2 && rq.animation() && rq.animation()->spec.kind == TransitionKind::Slide
              && rq.animation()->spec.direction == "droite",
          "la barre : un clic navigue, le glissement vient du c\xC3\xB4t\xC3\xA9 de la vue choisie");
    rq.tick(3.0);
    rq.navigate(qvr.id, none, 3.1);
    rq.objectPart(barId, "precedent", 3.2);
    check(rq.currentView() == qv2, "la fl\xC3\xA8" "che Pr\xC3\xA9" "c\xC3\xA9" "dent de la barre");
    // Le fil d'Ariane en historique : une etape revient de plusieurs pas.
    View& q2v = *q.view(qv2);
    const Id filId = lot12Add(q, q2v, Kind::Breadcrumb, "Fil", 0, 0, 600, 36).id;
    q2v.object(filId)->set("trail", "historique");
    rq.tick(4.0);
    rq.navigate(qvr.id, none, 4.1);
    rq.navigate(qv2, none, 4.2);
    const auto histBefore = rq.backHistory().size();
    rq.objectPart(filId, "etape:0", 4.3);
    check(rq.backHistory().size() + 2 <= histBefore + 1 && rq.currentView() != qv2, "une \xC3\xA9tape du fil (historique) revient de plusieurs pas");
    // La mise en page en marche : le panneau defilant decale le texte profond.
    View live = *rq.composedView(qvr.id);
    layoutStructures(live);
    check(live.object(deep)->number("y") < 1000, "en marche, le contenu du panneau d\xC3\xA9" "filant est d\xC3\xA9" "cal\xC3\xA9");
    rq.setViewZoom(250);
    check(rq.publicRead("SYS.ViewZoom", out) && std::fabs(out.asReal() - 250) < 1e-9, "SYS.ViewZoom");
}

void persistanceLot12() {
    std::printf("lot 12 : le disque (format 11), G\xC3\xA9n\xC3\xA9rer\n");
    Project p;
    View& v = lot12View(p, "Vue_Nav");
    const Id up = v.id;
    View& w = lot12View(p, "Vue_Enfant", up);
    w.zoomable = true;
    const Id wid = w.id;
    View& vv = *p.view(up);
    for (const auto k : {Kind::NavBar, Kind::Breadcrumb, Kind::TabContainer, Kind::Frame, Kind::ScrollPanel, Kind::CollapsiblePanel, Kind::ZoneMap})
        (void)edit::add(p, vv, k, 10, 10);
    const Id tabs = vv.objects[2].id;
    const Id child = edit::add(p, vv, Kind::Text, 30, 80);
    (void)adopt(vv, child, tabs);
    p.config.swipeNavigation = true;
    p.security.groups[1].startView = wid;
    Style st;
    st.id = p.allocate();
    st.name = "Titre";
    st.props = {{"fontSize", "22", ""}, {"textColor", "#FFFFFF", ""}};
    p.styles.push_back(st);
    const fs::path dir = fs::temp_directory_path() / "hmi_test_lot12";
    fs::remove_all(dir);
    check(static_cast<bool>(save(p, dir.string())), "enregistrer les objets du lot 12");
    auto back = load(dir.string());
    check(back.has_value(), "relire");
    if (back) {
        const View* bv = back->viewByName("Vue_Nav");
        const View* bw = back->viewByName("Vue_Enfant");
        check(bv && bw && bv->objects == vv.objects, "les sept objets et l'enfant d'un onglet reviennent \xC3\xA0 l'identique");
        check(bw && bw->upView == up && bw->zoomable, "la vue parente, le zoom en marche");
        check(back->config.swipeNavigation && back->security.groups[1].startView == wid, "changer de vue en glissant, la vue d'un groupe");
        check(back->styles.size() == 1 && back->styles[0] == st, "les styles nomm\xC3\xA9s");
        check(back->nextId > st.id, "le compteur d'identifiants passe les styles");
    }
    std::ifstream index(dir / "ihm" / "ihm.txt");
    std::stringstream ss;
    ss << index.rdbuf();
    // Lot 13 : le format passe a 12 ; le lot 12 demande au moins 11.
    check(ss.str().find("format=" + std::to_string(kPlainFormat)) != std::string::npos && kFormatVersion >= 11,
          "le format 11 et suivants (lot 12 ; " + std::to_string(kFormatVersion) + " aujourd'hui)");

    // ---- Generer
    Project g;
    View& gv = lot12View(g, "Vue_G");
    Object& bar = *gv.object(edit::add(g, gv, Kind::NavBar, 0, 0));
    bar.set("views", "Vue_G;Vue_Inconnue");
    Object& tc = *gv.object(edit::add(g, gv, Kind::TabContainer, 0, 60));
    tc.set("tabs", "Un;Deux");
    const Id tcId = tc.id;
    const Id lost = edit::add(g, gv, Kind::Text, 10, 100);
    (void)adopt(gv, lost, tcId);
    gv.object(lost)->setNumber("tabPage", 5);
    Object& zm = *gv.object(edit::add(g, gv, Kind::ZoneMap, 0, 400));
    zm.set("mapZones", "Petite | 1,1 2,2\nVers | 10,10,20,20 | | Vue_Absente");
    zm.set("image", "plan.svg");
    gv.upView = gv.id;
    g.security.groups[0].startView = 424242;
    const auto issues = generate(g, [](std::string_view) { return false; }, {});
    const auto has = [&](const std::string& what) {
        for (const auto& i : issues) if (i.message.find(what) != std::string::npos) return true;
        return false;
    };
    check(has("vue 'Vue_Inconnue' introuvable"), "G\xC3\xA9n\xC3\xA9rer : une vue inconnue dans la barre");
    check(has("n'en a que 2"), "G\xC3\xA9n\xC3\xA9rer : un objet sur une page qui n'existe pas");
    check(has("au moins 3 points") && has("vue 'Vue_Absente' introuvable") && has("image 'plan.svg' introuvable"),
          "G\xC3\xA9n\xC3\xA9rer : les zones (trop peu de points, vue inconnue) et le plan absent");
    check(has("tournent en rond") && has("vue de d\xC3\xA9marrage n'existe plus"), "G\xC3\xA9n\xC3\xA9rer : les vues parentes en boucle, la vue d'un groupe");
}

void exemplesLot12() {
    std::printf("lot 12 : les exemples anim\xC3\xA9s\n");
    std::string failed;
    for (const auto k : {Kind::NavBar, Kind::Breadcrumb, Kind::TabContainer, Kind::Frame, Kind::ScrollPanel, Kind::CollapsiblePanel, Kind::ZoneMap}) {
        auto ex = examples::exampleFor(k);
        if (!ex) { failed += std::string(kindKey(k)) + " (pas d'exemple) "; continue; }
        Runtime rt;
        rt.bind(&ex->project, nullptr);
        rt.start(0.0);
        double played = 0;
        std::size_t steps = 0;
        std::map<std::string, std::string> probe;
        for (double t = 0.05; t <= ex->period + 1e-9; t += 0.05) {
            rt.tick(t);
            steps += examples::play(*ex, rt, played, t, t);
            played = t;
            const auto* cur = rt.composedView(rt.currentView());
            if (!cur) continue;
            if (k == Kind::NavBar && std::fabs(t - 4.0) < 0.026) probe["4s"] = cur->name;
            if (k == Kind::NavBar && std::fabs(t - 6.0) < 0.026) probe["6s"] = cur->name;
            if (k == Kind::Breadcrumb && std::fabs(t - 4.5) < 0.026) probe["4s"] = cur->name;
            if (k == Kind::TabContainer && std::fabs(t - 5.0) < 0.026)
                if (const auto* o = cur->objectByName("Onglets")) probe["page"] = formatNumber(o->number("page"));
            if (k == Kind::CollapsiblePanel && std::fabs(t - 2.0) < 0.026)
                if (const auto* o = cur->objectByName("Panneau_Pompe")) probe["repli"] = o->flag("collapsed") ? "oui" : "non";
            if (k == Kind::ScrollPanel && std::fabs(t - 3.5) < 0.026)
                if (const auto* o = cur->objectByName("Panneau")) probe["y"] = formatNumber(o->number("scrollY"));
            if (k == Kind::ZoneMap && std::fabs(t - 5.0) < 0.026) probe["zone"] = rt.selectedZone();
            if (k == Kind::ZoneMap && std::fabs(t - 7.0) < 0.026) probe["vue"] = cur->name;
        }
        if (!ex->steps.empty() && steps != ex->steps.size()) failed += std::string(kindKey(k)) + " (gestes) ";
        for (const auto& e : rt.journal())
            if (e.kind == "Erreur") failed += std::string(kindKey(k)) + " (" + e.message + ") ";
        switch (k) {
            case Kind::NavBar: check(probe["4s"] == "Vue_Alarmes" && probe["6s"] == "Vue_Ligne", "l'exemple de la barre : Alarmes, puis Pr\xC3\xA9" "c\xC3\xA9" "dent revient \xC3\xA0 Ligne 1"); break;
            case Kind::Breadcrumb: check(probe["4s"] == "Vue_Ligne_1", "l'exemple du fil : deux vues plus bas"); break;
            case Kind::TabContainer: check(probe["page"] == "3", "l'exemple des onglets : la page Aide \xC3\xA0 5 s"); break;
            case Kind::CollapsiblePanel: check(probe["repli"] == "oui", "l'exemple du panneau repliable : repli\xC3\xA9 \xC3\xA0 2 s"); break;
            case Kind::ScrollPanel: check(probe["y"] == "184", "l'exemple du panneau d\xC3\xA9" "filant : deux coups de molette (184)"); break;
            case Kind::ZoneMap:
                check(probe["zone"] == "Armoire A" && probe["vue"] == "Vue_Stockage", "l'exemple du plan : une zone choisie, une zone qui ouvre sa vue");
                break;
            default: break;
        }
    }
    check(failed.empty(), "les sept exemples du lot 12 jouent leurs gestes sans erreur " + failed);
}

void menuConnexionLot12() {
    std::printf("lot 12 : le menu natif de connexion (onglets selon le niveau, comptes, acc\xC3\xA8s, journal)\n");
    // ---- les onglets et leur nom
    {
        check(loginTabFrom("Comptes") == LoginTab::Comptes && loginTabFrom("acces") == LoginTab::Acces
                  && loginTabFrom("Acc\xC3\xA8s") == LoginTab::Acces && loginTabFrom("Mon compte") == LoginTab::Compte
                  && loginTabFrom("journal") == LoginTab::Journal && loginTabFrom("") == LoginTab::Connexion
                  && loginTabFrom("n'importe") == LoginTab::Connexion && loginTabLabel(LoginTab::Compte) == "Mon compte",
              "les onglets par leur nom (sans casse, avec ou sans accent) ; inconnu : Connexion");
        Project p;
        p.security = Security::defaults();
        const auto userIn = [&](std::size_t g) {
            User u;
            u.login = "u" + std::to_string(g);
            u.group = p.security.groups[g].id;
            return u;
        };
        const User op = userIn(0), maint = userIn(1), sup = userIn(2), adm = userIn(3);
        const auto names = [&](const User* u) {
            std::string out;
            for (const auto t : visibleLoginTabs(p, u)) out += (out.empty() ? "" : ",") + std::string(loginTabKey(t));
            return out;
        };
        check(names(nullptr) == "connexion,compte,comptes,acces,journal", "s\xC3\xA9" "curit\xC3\xA9 \xC3\xA9teinte : tous les onglets");
        p.security.enabled = true;
        check(names(nullptr) == "connexion" && names(&op) == "connexion,compte" && names(&maint) == "connexion,compte"
                  && names(&sup) == "connexion,compte,journal" && names(&adm) == "connexion,compte,comptes,acces,journal",
              "sous s\xC3\xA9" "curit\xC3\xA9 : personne Connexion ; niveau 1 et 2 + Mon compte ; niveau 3 + Journal ; Administrer : tout");
        p.security.menuLevelAccounts = 3;
        p.security.menuLevelJournal = 2;
        check(names(&maint) == "connexion,compte,journal" && names(&sup) == "connexion,compte,comptes,journal",
              "les niveaux se r\xC3\xA8glent : Journal d\xC3\xA8s 2, Comptes d\xC3\xA8s 3");
    }
    // ---- la geometrie : ce qui se dessine est ce qui se clique, sur chaque onglet
    {
        const std::vector<LoginTab> all{LoginTab::Connexion, LoginTab::Compte, LoginTab::Comptes, LoginTab::Acces, LoginTab::Journal};
        std::string wrong;
        for (const auto& [w, h] : {std::pair<double, double>{900, 560}, {600, 300}}) {
            const std::pair<LoginTab, std::vector<const char*>> parts[] = {
                {LoginTab::Connexion, {"fermer", "onglet:comptes", "onglet:journal", "precedent", "suivant", "champ:secret", "bouton:connexion", "bouton:deconnexion"}},
                {LoginTab::Compte, {"champ:ancien", "champ:nouveau", "champ:confirmation", "bouton:changer"}},
                {LoginTab::Comptes, {"ligne:0", "ligne:2", "bouton:ajouter", "bouton:motdepasse", "bouton:activer", "bouton:groupe:precedent",
                                     "bouton:groupe:suivant", "bouton:supprimer"}},
                {LoginTab::Acces, {"role:0,0", "role:3,2", "deconnexion:moins", "deconnexion:plus"}},
                {LoginTab::Journal, {"ligne:1"}},
            };
            for (const auto& [tab, list] : parts) {
                const auto l = loginMenuLayout(w, h, all, tab, 6, 4, 4);
                for (const char* part : list) {
                    Box b;
                    if (!loginMenuPartBox(l, tab, part, b)) { wrong += std::string(part) + " (absente) "; continue; }
                    const std::string hit = loginMenuHit(l, tab, b.cx(), b.cy(), 0, 6);
                    if (hit != part) wrong += std::string(part) + " -> " + hit + " ";
                    if (b.right() > w || b.bottom() > h || b.x < 0 || b.y < 0) wrong += std::string(part) + " (hors de l'\xC3\xA9" "cran) ";
                }
            }
        }
        check(wrong.empty(), "chaque partie a son cadre, un clic en son milieu la retrouve (900 x 560 et 600 x 300) " + wrong);
        const auto l = loginMenuLayout(900, 560, all, LoginTab::Comptes, 30, 4, 4);
        check(l.up.w > 0 && loginMenuHit(l, LoginTab::Comptes, l.up.cx(), l.up.cy()) == "defiler:-1"
                  && loginMenuHit(l, LoginTab::Comptes, l.rows[1].cx(), l.rows[1].cy(), 5, 30) == "ligne:6",
              "30 comptes : des fl\xC3\xA8" "ches ; une ligne cliqu\xC3\xA9" "e compte le d\xC3\xA9" "filement (5 + 1 = ligne 6)");
        const auto few = loginMenuLayout(900, 560, all, LoginTab::Comptes, 3, 4, 4);
        check(few.up.w == 0 && few.header.w > l.header.w && loginMenuHit(few, LoginTab::Comptes, few.rows[4].cx(), few.rows[4].cy(), 0, 3).empty(),
              "3 comptes : ni fl\xC3\xA8" "ches (l'en-t\xC3\xAAte prend toute la largeur), ni ligne cliquable sous le dernier");
        check(loginMenuHit(l, LoginTab::Comptes, 1, 1) == "dehors" && autoLogoutSteps().front() == 0 && autoLogoutSteps().back() == 120,
              "hors du panneau : \xC2\xAB dehors \xC2\xBB ; la d\xC3\xA9" "connexion automatique : de jamais \xC3\xA0 120 min");
    }

    // ---- en marche : l'operateur, puis l'administrateur
    Project p;
    p.security = Security::defaults();
    p.security.enabled = true;
    const auto user = [&](const char* login, std::size_t group, const char* pwd, bool enabled = true) {
        User u;
        u.id = p.allocate();
        u.login = login;
        u.fullName = std::string("Nom de ") + login;
        u.group = p.security.groups[group].id;
        u.salt = randomHex(16);
        u.passwordHash = passwordHash(u.salt, pwd);
        u.enabled = enabled;
        p.security.users.push_back(u);
        return u.id;
    };
    const Id opId = user("operateur", 0, "1234");
    const Id admId = user("admin", 3, "admin2026");
    const Id stagId = user("stagiaire", 0, "stage1", false);
    p.security.startUser = "operateur";
    View v = makeView(p, "Vue_Menu");
    const Id btn = edit::add(p, v, Kind::LoginMenuButton, 10, 10);
    v.object(btn)->name = "Btn_Connexion";
    const Id comptes = edit::add(p, v, Kind::Button, 10, 80);
    v.object(comptes)->name = "Btn_Comptes";
    v.object(comptes)->actions.push_back(act(Trigger::Click, Operation::ShowLogin, {}, "Comptes"));
    const Id sysBtn = edit::add(p, v, Kind::SystemButton, 10, 150);
    p.views = {v};
    p.config.startView = v.id;
    p.programs.variables.push_back(hmiVar(p, "Ok", "BOOL", "FALSE"));
    p.programs.scripts.push_back(generalScript(p, "Ouvrir_Journal", "Ok := IHM_MENU_CONNEXION('Journal');"));
    Runtime rt;
    std::vector<UserRequest> requests;
    Runtime::Hooks hooks;
    // L'ecran : les changements directs vont dans le projet (comme les commandes).
    hooks.userRequest = [&](const UserRequest& rq) {
        requests.push_back(rq);
        auto& sec = p.security;
        if (rq.op == "role") {
            for (auto& g : sec.groups)
                if (g.id == rq.group) {
                    std::erase(g.roles, rq.role);
                    if (rq.enabled) g.roles.push_back(rq.role);
                }
        } else if (rq.op == "deconnexion") {
            sec.autoLogoutMin = rq.minutes;
        } else if (auto* u = p.user(rq.user)) {
            if (rq.op == "groupe") u->group = rq.group;
            else if (rq.op == "activer") u->enabled = rq.enabled;
            else if (rq.op == "changer") { u->salt = rq.salt; u->passwordHash = rq.hash; }
        }
    };
    rt.setHooks(hooks);
    rt.bind(&p, nullptr);
    rt.start(0);
    double t = 0.1;
    const auto click = [&](Id id) {
        rt.press(id, t);
        rt.release(id, t, true);
        t += 0.1;
    };
    const auto part = [&](const char* what) {
        rt.loginPart(what, t);
        t += 0.1;
    };
    const auto sys = [&](const char* name) {
        sim::Value out;
        (void)rt.publicRead(std::string("SYS.") + name, out);
        return out;
    };
    const auto tabs = [&] {
        std::string out;
        for (const auto x : rt.loginTabs()) out += (out.empty() ? "" : ",") + std::string(loginTabKey(x));
        return out;
    };

    check(rt.userLogin() == "operateur" && !rt.loginShown() && !sys("LoginMenuOpen").isTruthy() && sys("LoginMenuTabs").asString() == "Connexion;Mon compte",
          "au d\xC3\xA9part : l'op\xC3\xA9rateur, le menu ferm\xC3\xA9 ; SYS.LoginMenuTabs = Connexion;Mon compte");
    click(comptes);
    check(rt.loginShown() && rt.loginTab() == LoginTab::Connexion && rt.loginForm().error
              && rt.loginForm().message.find("niveau 4") != std::string::npos,
          "l'action \xC2\xAB Menu de connexion \xC2\xBB sur Comptes, par l'op\xC3\xA9rateur : le menu s'ouvre sur Connexion et dit \xC2\xAB d\xC3\xA8s le niveau 4 \xC2\xBB");
    check(sys("LoginMenuOpen").isTruthy() && sys("LoginMenuTab").asString() == "Connexion", "SYS.LoginMenuOpen, SYS.LoginMenuTab = Connexion");
    check(rt.loginAccount() && rt.loginAccount()->login == "operateur" && rt.keyboardMode().empty(),
          "le compte montr\xC3\xA9 : l'utilisateur connect\xC3\xA9 ; pas de clavier virtuel tant qu'aucun champ n'est touch\xC3\xA9");
    part("onglet:comptes");
    check(rt.loginTab() == LoginTab::Connexion && rt.loginForm().error, "un onglet qu'il ne voit pas : refus\xC3\xA9");
    part("suivant");
    check(rt.loginAccount() && rt.loginAccount()->login == "admin", "\xE2\x96\xB6 : l'administrateur (le stagiaire, d\xC3\xA9sactiv\xC3\xA9, n'est pas propos\xC3\xA9)");
    part("champ:secret");
    check(rt.keyboardMode() == "complet" && rt.loginFocused(), "le champ touch\xC3\xA9 : le clavier virtuel complet");
    rt.typeText("admin2025", t);
    rt.typeKey(EditKey::Enter, t);
    t += 0.1;
    check(rt.userLogin() == "operateur" && rt.loginForm().error && rt.loginForm().message == "mot de passe incorrect"
              && rt.loginForm().text.at("secret").empty() && eventHas(rt, "Connexion refus\xC3\xA9" "e", "admin"),
          "un mauvais mot de passe : refus\xC3\xA9, le champ vid\xC3\xA9, l'\xC3\xA9v\xC3\xA9nement \xC2\xAB Connexion refus\xC3\xA9" "e \xC2\xBB");
    rt.typeText("admin2026", t);
    bool secretLogged = false;
    for (const auto& e : rt.journal()) secretLogged = secretLogged || e.message.find("admin2026") != std::string::npos;
    rt.typeKey(EditKey::Enter, t);
    t += 0.1;
    for (const auto& e : rt.journal()) secretLogged = secretLogged || e.message.find("admin2026") != std::string::npos;
    check(rt.userLogin() == "admin" && rt.loginTab() == LoginTab::Comptes && !rt.loginForm().error
              && rt.loginForm().message.find("Bienvenue") == 0 && !secretLogged,
          "le bon : l'administrateur est connect\xC3\xA9, l'onglet Comptes demand\xC3\xA9 s'ouvre ; le mot de passe n'est jamais au journal");
    check(tabs() == "connexion,compte,comptes,acces,journal" && rt.loginRows() == 3, "ses onglets : les cinq ; trois comptes");

    // ---- Comptes : le groupe, l'activation, les refus
    part("ligne:0");
    part("bouton:groupe:suivant");
    check(!requests.empty() && requests.back().op == "groupe" && requests.back().user == opId && p.user(opId)->group == p.security.groups[1].id
              && eventHas(rt, "Compte modifi\xC3\xA9", "Maintenance"),
          "l'op\xC3\xA9rateur passe en Maintenance : une demande \xC2\xAB groupe \xC2\xBB \xC3\xA0 l'\xC3\xA9" "cran, l'\xC3\xA9v\xC3\xA9nement \xC2\xAB Compte modifi\xC3\xA9 \xC2\xBB");
    part("ligne:2");
    part("bouton:activer");
    check(requests.back().op == "activer" && requests.back().enabled && p.user(stagId)->enabled, "le stagiaire activ\xC3\xA9");
    const std::size_t before = requests.size();
    part("ligne:1");
    part("bouton:activer");
    check(requests.size() == before && rt.loginForm().error && p.user(admId)->enabled, "se d\xC3\xA9sactiver soi-m\xC3\xAAme : refus\xC3\xA9");
    part("bouton:groupe:suivant");
    check(requests.size() == before && rt.loginForm().message.find("Administrer") != std::string::npos,
          "se mettre dans un groupe sans Administrer : refus\xC3\xA9");
    part("bouton:supprimer");
    check(requests.size() == before && rt.loginForm().error, "se supprimer : refus\xC3\xA9");
    part("ligne:0");
    part("bouton:supprimer");
    part("bouton:motdepasse");
    part("bouton:ajouter");
    check(requests.size() == before + 3 && requests[before].op == "supprimer" && requests[before + 1].op == "motdepasse"
              && requests[before + 2].op == "ajouter",
          "supprimer, donner un mot de passe, ajouter : demand\xC3\xA9s \xC3\xA0 l'\xC3\xA9" "cran (ses dialogues)");

    // ---- Acces : un role, la deconnexion automatique, et pas de porte fermee sur soi
    part("onglet:acces");
    part("role:0,2");
    check(requests.back().op == "role" && requests.back().role == "R\xC3\xA9glages" && requests.back().enabled
              && std::find(p.security.groups[0].roles.begin(), p.security.groups[0].roles.end(), "R\xC3\xA9glages") != p.security.groups[0].roles.end()
              && eventHas(rt, "Acc\xC3\xA8s modifi\xC3\xA9", "R\xC3\xA9glages"),
          "une case : Op\xC3\xA9rateur re\xC3\xA7oit le r\xC3\xB4le R\xC3\xA9glages");
    part("role:0,2");
    check(!requests.back().enabled && p.security.groups[0].roles == std::vector<std::string>{"Conduite"}, "... la m\xC3\xAAme case le lui retire");
    const std::size_t roles = requests.size();
    part("role:3,3");
    check(requests.size() == roles && rt.loginForm().message.find("perdrais") != std::string::npos,
          "retirer Administration \xC3\xA0 son propre groupe : refus\xC3\xA9 (tu perdrais la permission Administrer)");
    part("deconnexion:plus");
    part("deconnexion:plus");
    part("deconnexion:plus");
    check(p.security.autoLogoutMin == 5 && requests.back().op == "deconnexion" && requests.back().minutes == 5,
          "la d\xC3\xA9" "connexion automatique : jamais, 1, 2, 5 min");
    part("deconnexion:moins");
    check(p.security.autoLogoutMin == 2, "... et moins : 2 min");

    // ---- Journal
    part("onglet:journal");
    const auto journal = rt.loginJournal();
    check(rt.loginRows() == journal.size() && journal.size() >= 6 && journal.front().kind == "Acc\xC3\xA8s modifi\xC3\xA9"
              && std::any_of(journal.begin(), journal.end(), [](const HistoryEvent& e) { return e.kind == "Connexion refus\xC3\xA9" "e"; }),
          "le journal : les plus r\xC3\xA9" "cents d'abord (l'acc\xC3\xA8s modifi\xC3\xA9), les refus aussi");
    part("defiler:=2");
    check(rt.loginScroll() == 2, "d\xC3\xA9" "filer : la premi\xC3\xA8re ligne montr\xC3\xA9" "e");

    // ---- Mon compte : changer son mot de passe
    part("onglet:compte");
    check(rt.loginScroll() == 0 && !rt.loginFocused(), "un autre onglet : ni d\xC3\xA9" "filement ni focus");
    part("champ:ancien");
    rt.typeText("admin2026", t);
    rt.typeKey(EditKey::Tab, t);
    rt.typeText("abc", t);
    rt.typeKey(EditKey::Tab, t);
    rt.typeText("abc", t);
    rt.typeKey(EditKey::Enter, t);
    t += 0.1;
    check(rt.loginForm().error && rt.loginForm().message == "au moins 6 caract\xC3\xA8res" && rt.loginForm().focus == "nouveau",
          "un nouveau mot de passe trop court : refus\xC3\xA9, retour au champ Nouveau");
    rt.typeKey(EditKey::Backspace, t);
    rt.typeKey(EditKey::Backspace, t);
    rt.typeKey(EditKey::Backspace, t);
    rt.typeText("Nouveau2026", t);
    rt.typeKey(EditKey::Enter, t);
    rt.typeText("Nouveau2026", t);
    rt.typeKey(EditKey::Enter, t);
    t += 0.1;
    check(!rt.loginForm().error && requests.back().op == "changer" && passwordMatches(p.user(admId)->salt, p.user(admId)->passwordHash, "Nouveau2026")
              && eventHas(rt, "Mot de passe chang\xC3\xA9", "admin"),
          "Nouveau2026 confirm\xC3\xA9 : le mot de passe chang\xC3\xA9 (empreinte sal\xC3\xA9" "e), l'\xC3\xA9v\xC3\xA9nement");

    // ---- Echap, les deux menus natifs, l'objet, IHM_MENU_CONNEXION
    part("champ:ancien");
    rt.typeKey(EditKey::Escape, t);
    check(rt.loginShown() && !rt.loginFocused(), "Echap dans un champ : le champ se vide et perd le focus");
    rt.typeKey(EditKey::Escape, t);
    check(!rt.loginShown(), "... Echap encore : le menu se ferme");
    click(btn);
    check(rt.loginShown() && rt.loginTab() == LoginTab::Connexion, "l'objet Menu de connexion : un clic l'ouvre, sur son onglet");
    click(sysBtn);
    check(rt.systemShown() && !rt.loginShown(), "Param\xC3\xA8tres syst\xC3\xA8me s'ouvre : le menu de connexion se ferme (un \xC3\xA0 la fois)");
    std::string why;
    check(rt.callScript("Ouvrir_Journal", t, &why) && rt.loginShown() && !rt.systemShown() && rt.loginTab() == LoginTab::Journal
              && rt.variable("Ok") && rt.variable("Ok")->isTruthy(),
          "IHM_MENU_CONNEXION('Journal') : le menu sur le Journal (vrai), Param\xC3\xA8tres syst\xC3\xA8me ferm\xC3\xA9 " + why);
    part("onglet:connexion");
    part("bouton:deconnexion");
    check(rt.userLogin().empty() && tabs() == "connexion" && rt.loginTab() == LoginTab::Connexion && rt.loginAccount()->login == "admin",
          "se d\xC3\xA9" "connecter : plus que Connexion ; le compte reste montr\xC3\xA9 (se reconnecter en un geste)");
    check(rt.callScript("Ouvrir_Journal", t, &why) && !rt.variable("Ok")->isTruthy() && rt.loginTab() == LoginTab::Connexion,
          "IHM_MENU_CONNEXION('Journal') sans personne : faux, le menu sur Connexion");
    // L'operateur (passe en Maintenance, niveau 2) avec les comptes visibles des le niveau 2 : il voit, il ne change pas.
    p.security.menuLevelAccounts = 2;
    part("precedent");
    check(rt.loginAccount()->login == "operateur", "\xE2\x97\x80 : l'op\xC3\xA9rateur");
    rt.typeText("1234", t);
    rt.typeKey(EditKey::Enter, t);
    t += 0.1;
    part("onglet:comptes");
    check(rt.userLogin() == "operateur" && rt.loginTab() == LoginTab::Comptes, "comptes visibles d\xC3\xA8s le niveau 2 : l'op\xC3\xA9rateur (Maintenance) les voit");
    const std::size_t seen = requests.size();
    part("ligne:2");
    part("bouton:activer");
    check(requests.size() == seen && rt.loginForm().message.find("Administrer") != std::string::npos
              && eventHas(rt, "Acc\xC3\xA8s refus\xC3\xA9", "Activer"),
          "... mais activer demande Administrer : refus\xC3\xA9, \xC2\xAB Acc\xC3\xA8s refus\xC3\xA9 \xC2\xBB");
    part("dehors");
    check(!rt.loginShown(), "un clic dehors : le menu se ferme");
    rt.logout(t, "test");
    rt.start(t + 1);
    check(!rt.loginShown(), "red\xC3\xA9marrer l'IHM : le menu repart ferm\xC3\xA9");

    // ---- le disque, Generer, l'exemple, l'aide
    {
        Project q;
        q.security = Security::defaults();
        q.security.menuLevelAccounts = 3;
        q.security.menuLevelAccess = 4;
        q.security.menuLevelJournal = 1;
        View& qv = lot12View(q, "Vue_Q");
        const Id bid = edit::add(q, qv, Kind::LoginMenuButton, 0, 0);
        qv.object(bid)->set("tab", "Journal");
        qv.object(bid)->actions.push_back(act(Trigger::Click, Operation::ShowLogin, {}, "Comptes"));
        const Id holder = edit::add(q, qv, Kind::Frame, 0, 100);
        const Id inside = edit::add(q, qv, Kind::Text, 20, 140);
        (void)adopt(qv, inside, holder);
        const fs::path dir = fs::temp_directory_path() / "hmi_test_lot12_menu";
        fs::remove_all(dir);
        check(static_cast<bool>(save(q, dir.string())), "enregistrer le menu de connexion");
        auto back = load(dir.string());
        check(back && back->security.menuLevelAccounts == 3 && back->security.menuLevelAccess == 4 && back->security.menuLevelJournal == 1
                  && back->viewByName("Vue_Q") && back->viewByName("Vue_Q")->objects == qv.objects,
              "les niveaux des onglets, l'objet et son action reviennent \xC3\xA0 l'identique");
        qv.object(bid)->set("tab", "Mes comptes");
        const auto issues = generate(q, [](std::string_view) { return false; }, {});
        const auto has = [&](const std::string& what) {
            for (const auto& i : issues) if (i.message.find(what) != std::string::npos) return true;
            return false;
        };
        check(has("onglet inconnu") && has("est de trop") && has("s\xC3\xA9" "curit\xC3\xA9 inactive") && !has("ni un groupe ni un conteneur"),
              "G\xC3\xA9n\xC3\xA9rer : un onglet inconnu, l'action en double, la s\xC3\xA9" "curit\xC3\xA9 inactive ; un enfant de cadre n'est pas une erreur");
        check(kindKey(Kind::LoginMenuButton) == "LoginMenuButton" && kindFromKey("LoginMenuButton") == Kind::LoginMenuButton
                  && kindLabel(Kind::LoginMenuButton) == "Menu de connexion" && operationLabel(Operation::ShowLogin) == "Menu de connexion"
                  && operationFromLabel("Menu de connexion") == Operation::ShowLogin
                  && describeAction(act(Trigger::Click, Operation::ShowLogin, {}, "Comptes")).find("(Comptes)") != std::string::npos,
              "l'objet et l'op\xC3\xA9ration : LoginMenuButton, \xC2\xAB Menu de connexion \xC2\xBB ; l'action dit son onglet");
        const Object o = makeObject(Kind::LoginMenuButton, 1, "M", 0, 0, 1);
        check(o.text("text") == "Se connecter" && o.text("tab") == "Connexion" && o.flag("showUser", false) && o.flag("icon", false),
              "l'objet : \xC2\xAB Se connecter \xC2\xBB, onglet Connexion, l'utilisateur et la silhouette montr\xC3\xA9s");
    }
    {
        auto ex = examples::exampleFor(Kind::LoginMenuButton);
        check(ex.has_value(), "l'exemple du menu de connexion existe");
        if (ex) {
            Runtime ert;
            ert.bind(&ex->project, nullptr);
            ert.start(0.0);
            double played = 0;
            std::size_t steps = 0;
            std::string at4, at13;
            for (double tt = 0.05; tt <= ex->period + 1e-9; tt += 0.05) {
                ert.tick(tt);
                steps += examples::play(*ex, ert, played, tt, tt);
                played = tt;
                if (std::fabs(tt - 4.0) < 0.026) {
                    for (const auto x : ert.loginTabs()) at4 += std::string(loginTabKey(x)) + ",";
                    at4 += ert.userLogin();
                }
                if (std::fabs(tt - 7.5) < 0.026) at13 = std::string(loginTabKey(ert.loginTab()));
            }
            check(steps == ex->steps.size() && at4 == "connexion,compte,comptes,acces,journal,admin" && at13 == "acces"
                      && ert.userLogin().empty() && !ert.loginShown(),
                  "l'exemple : l'administrateur se connecte (cinq onglets), Acc\xC3\xA8s \xC3\xA0 7,5 s ; \xC3\xA0 la fin, ferm\xC3\xA9 et d\xC3\xA9" "connect\xC3\xA9 " + at4);
        }
    }
    check(guide::topic("menu-connexion") && guide::topicForKind("LoginMenuButton") && !guide::search("IHM_MENU_CONNEXION").empty()
              && isHmiFunction("IHM_MENU_CONNEXION"),
          "l'aide : la page du menu, celle de l'objet ; IHM_MENU_CONNEXION connue des scripts");
}

void conceptionLot12() {
    std::printf("lot 12 : concevoir plus vite (variables pos\xC3\xA9" "es, vue d'un type, rechercher, styles, mod\xC3\xA8les, espacement)\n");
    using namespace hmi::design;
    // ---- les variables : l'objet qui leur va
    check(shapeOf("BOOL") == VarShape::Bool && shapeOf("ebool") == VarShape::Bool && shapeOf("REAL") == VarShape::Number
              && shapeOf("UDINT") == VarShape::Number && shapeOf("STRING[32]") == VarShape::Text && shapeOf("T_ANA", true) == VarShape::Structure
              && shapeOf("ARRAY[0..3] OF INT") == VarShape::Other && shapeOf("T_ANA") == VarShape::Other,
          "BOOL, nombres, textes, structures (avec membres), le reste");
    check(nameStem("Armoires[0].ana.PT1") == "Armoires_0_ana_PT1" && nameStem("1er") == "V_1er" && equipmentPopupName("T_ANA") == "Popup_T_ANA",
          "les noms tir\xC3\xA9s d'un chemin");
    Project p;
    View& v = lot12View(p, "Vue_Poste");
    const Id vid = v.id;
    VarInfo marche{"Pompe_Marche", "BOOL", "Pompe en marche", true, {}};
    VarInfo pression{"Armoires[0].ana.PT1.mes", "REAL", "", true, {}};
    VarInfo nom{"Nom_Recette", "STRING", "", false, {}};
    VarInfo ana{"Armoires[0].ana.PT1", "T_ANA", "Transmetteur PT1", true,
                {{"mes", "REAL", "Mesure", true, {}}, {"defaut", "BOOL", "", true, {}}, {"libelle", "STRING", "Libell\xC3\xA9", true, {}},
                 {"sous", "T_SOUS", "", true, {}}}};
    const Id a = placeVariable(p, vid, marche, 10, 10);
    const Id b = placeVariable(p, vid, pression, 10, 60);
    const Id c = placeVariable(p, vid, nom, 10, 130);
    const Object* oa = p.view(vid)->object(a);
    const Object* ob = p.view(vid)->object(b);
    const Object* oc = p.view(vid)->object(c);
    check(oa && oa->kind == Kind::Indicator && oa->expr("value") == "Pompe_Marche" && oa->name == "Voyant_Pompe_Marche",
          "un BOOL : un voyant (nomm\xC3\xA9 d'apr\xC3\xA8s elle), sa valeur est la variable");
    const Id a2 = placeVariable(p, vid, marche, 60, 10);
    check(p.view(vid)->object(a2) && p.view(vid)->object(a2)->name == "Voyant_Pompe_Marche_2", "pos\xC3\xA9" "e deux fois : Voyant_Pompe_Marche_2");
    edit::remove(*p.view(vid), {a2});
    check(ob && ob->kind == Kind::NumericDisplay && ob->expr("value") == "Armoires[0].ana.PT1.mes" && ob->text("format") == "0.00"
              && ob->text("label") == "mes",
          "un REAL : un afficheur (0.00), son libell\xC3\xA9 le dernier morceau du chemin");
    check(oc && oc->kind == Kind::Text && oc->text("text") == "{Nom_Recette}", "un texte : un texte \xC3\xA0 trous");
    check(placeVariable(p, vid, VarInfo{"Tab", "ARRAY[0..3] OF INT", "", true, {}}, 0, 0) == kNoId, "un tableau : rien");
    const std::size_t views = p.views.size();
    const Id d = placeVariable(p, vid, ana, 300, 10);
    const View* popup = p.viewByName("Popup_T_ANA");
    const Object* od = p.view(vid)->object(d);
    check(od && od->kind == Kind::Button && od->actions.size() == 1 && od->actions[0].operation == Operation::Popup
              && od->actions[0].target == "Popup_T_ANA" && od->actions[0].value == "Equipement := Armoires[0].ana.PT1",
          "une structure : un bouton qui ouvre Popup_T_ANA avec Equipement := Armoires[0].ana.PT1");
    check(popup && p.views.size() == views + 1 && popup->role == "popup" && popup->param("Equipement")
              && popup->param("Equipement")->defaultValue == "Armoires[0].ana.PT1",
          "... sa popup d'\xC3\xA9quipement, g\xC3\xA9n\xC3\xA9r\xC3\xA9" "e (r\xC3\xB4le popup, param\xC3\xA8tre Equipement)");
    if (popup) {
        bool mes = false, defaut = false, libelle = false, sous = false;
        for (const auto& o : popup->objects) {
            mes = mes || (o.kind == Kind::NumericDisplay && o.expr("value") == "Equipement.mes");
            defaut = defaut || (o.kind == Kind::Indicator && o.expr("value") == "Equipement.defaut");
            libelle = libelle || (o.kind == Kind::Text && o.text("text") == "{Equipement.libelle}");
            sous = sous || o.text("text").find("sous") != std::string::npos;
        }
        check(mes && defaut && libelle && !sous, "... une ligne par membre, lue \xC3\xA0 travers Equipement ; pas la structure imbriqu\xC3\xA9" "e");
    }
    VarInfo ana2 = ana;
    ana2.name = "Armoires[1].ana.PT1";
    const Id e = placeVariable(p, vid, ana2, 300, 80);
    check(p.views.size() == views + 1 && p.view(vid)->object(e) && p.view(vid)->object(e)->actions[0].target == "Popup_T_ANA",
          "une autre instance du m\xC3\xAAme type : la m\xC3\xAAme popup (pas une deuxi\xC3\xA8me)");
    {
        std::vector<VarInfo> many;
        for (int i = 0; i < 14; ++i) many.push_back({"m" + std::to_string(i), "INT", "", true, {}});
        TypeViewOptions o;
        o.typeName = "T_GRAND";
        const Id big = generateTypeView(p, o, many);
        const View* bv = p.view(big);
        check(bv && bv->width > 900 && bv->name == "Popup_T_GRAND", "14 membres : deux colonnes");
        check(generateTypeView(p, o, {{"s", "T_X", "", true, {}}}) == kNoId, "rien \xC3\xA0 montrer : pas de vue");
    }

    // ---- rechercher / remplacer
    FindOptions none;
    std::size_t n = 0;
    check(replaced("Armoires[0].x + armoires[0].y", "Armoires[0]", "Armoires[1]", none, &n) == "Armoires[1].x + Armoires[1].y" && n == 2,
          "remplacer sans casse : les deux");
    FindOptions exact;
    exact.matchCase = true;
    check(replaced("Armoires[0].x + armoires[0].y", "Armoires[0]", "B", exact, &n) == "B.x + armoires[0].y" && n == 1, "... avec la casse : une");
    FindOptions word;
    word.wholeWord = true;
    check(replaced("Pompe + Pompe_1 + (Pompe)", "Pompe", "P2", word, &n) == "P2 + Pompe_1 + (P2)" && n == 2, "... mot entier : pas Pompe_1");
    Project q;
    View& qv = lot12View(q, "Vue_A");
    Object& t = *qv.object(edit::add(q, qv, Kind::Text, 10, 10));
    t.set("text", "PT1 : {Armoires[0].ana.PT1.mes} bar");
    Object& ind = *qv.object(edit::add(q, qv, Kind::Indicator, 10, 50));
    ind.setExpr("value", "Armoires[0].defaut");
    ind.actions.push_back(act(Trigger::Click, Operation::Popup, "Popup_Armoire", "Armoire := Armoires[0]"));
    qv.scripts.push_back(Script{q.allocate(), "Ouverture", ScriptLang::ST, "OnOpen", "Armoires[0].vu := TRUE;", 1000, "", ""});
    const Id qa = qv.id;
    View& qb = lot12View(q, "Vue_B");
    Object& tb = *qb.object(edit::add(q, qb, Kind::Text, 10, 10));
    tb.set("text", "{Armoires[0].nom}");
    const Id qbid = qb.id;
    q.programs.scripts.push_back(generalScript(q, "Tour", "IF Armoires[0].defaut THEN x := 1; END_IF;"));
    AlarmDef al;
    al.id = q.allocate();
    al.name = "Defaut_A";
    al.condition = "Armoires[0].defaut";
    al.message = "Armoire A";
    q.alarms.push_back(al);
    const auto hits = find(q, "Armoires[0]", "Armoires[1]", none);
    check(hits.size() == 7, "7 champs touch\xC3\xA9s : texte, expression, action, script de vue, texte de B, script g\xC3\xA9n\xC3\xA9ral, alarme ("
                                + std::to_string(hits.size()) + ")");
    bool preview = false;
    for (const auto& h : hits)
        preview = preview || (h.view == qa && h.before == "PT1 : {Armoires[0].ana.PT1.mes} bar" && h.after == "PT1 : {Armoires[1].ana.PT1.mes} bar");
    check(preview, "l'aper\xC3\xA7u : avant, apr\xC3\xA8s");
    FindOptions onlyA;
    onlyA.view = qa;
    check(find(q, "Armoires[0]", "x", onlyA).size() == 4, "dans Vue_A seule : 4 champs (texte, expression, action, script)");
    const Project before = q;
    check(replaceAll(q, "Armoires[0]", "Armoires[1]", onlyA) == 4 && q.view(qbid)->objects[0].text("text") == "{Armoires[0].nom}"
              && q.programs.scripts[0].body == before.programs.scripts[0].body,
          "remplacer dans Vue_A : Vue_B, les scripts g\xC3\xA9n\xC3\xA9raux ne bougent pas");
    q = before;
    std::size_t changed = 0;
    const Id copy = duplicateViewReplacing(q, qa, "Vue_A2", "Armoires[0]", "Armoires[2]", {}, &changed);
    const View* cv = q.view(copy);
    const View* ov = q.view(qa);
    bool ids = cv && ov && cv->objects.size() == ov->objects.size() && cv->layers.front().id != ov->layers.front().id;
    if (ids)
        for (std::size_t i = 0; i < cv->objects.size(); ++i)
            ids = ids && cv->objects[i].id != ov->objects[i].id && cv->objects[i].layer == cv->layers.front().id;
    check(cv && cv->name == "Vue_A2" && changed == 4 && ids && cv->objects[0].text("text") == "PT1 : {Armoires[2].ana.PT1.mes} bar"
              && ov->objects[0].text("text") == "PT1 : {Armoires[0].ana.PT1.mes} bar" && cv->scripts[0].body == "Armoires[2].vu := TRUE;"
              && cv->scripts[0].id != ov->scripts[0].id,
          "dupliquer en rempla\xC3\xA7" "ant : Vue_A2, identifiants neufs, 4 champs chang\xC3\xA9s, l'original intact");

    // ---- les styles nommes
    Project s;
    View& sv = lot12View(s, "Vue_S");
    const Id sid = sv.id;
    Object& t1 = *sv.object(edit::add(s, sv, Kind::Text, 10, 10));
    t1.setNumber("fontSize", 22);
    t1.set("textColor", "#FFD166");
    const Id t1id = t1.id;
    const Id t2id = edit::add(s, *s.view(sid), Kind::Text, 10, 60);
    const Id t3id = edit::add(s, *s.view(sid), Kind::Text, 10, 110);
    Style st = styleFromObject(s, *s.view(sid)->object(t1id), "Titre");
    s.styles.push_back(st);
    bool keys = false;
    for (const auto& prop : st.props) keys = keys || (prop.key == "fontSize" && prop.value == "22");
    check(st.name == "Titre" && keys && st.id != kNoId, "un style fait d'un objet : ses valeurs d'apparence");
    for (Id id : {t1id, t2id, t3id}) applyStyle(*s.view(sid)->object(id), st);
    check(s.view(sid)->object(t2id)->number("fontSize") == 22 && s.view(sid)->object(t2id)->text("textColor") == "#FFD166"
              && s.view(sid)->object(t2id)->text("namedStyle") == "Titre" && styleUsers(s, "titre") == 3,
          "appliqu\xC3\xA9 : les valeurs copi\xC3\xA9" "es, trois objets le citent (nom sans casse)");
    s.view(sid)->object(t3id)->setNumber("fontSize", 30);     // l'objet change sa taille lui-meme
    Style after = st;
    for (auto& prop : after.props) if (prop.key == "fontSize") prop.value = "26";
    after.name = "Grand_Titre";
    check(propagateStyle(s, st, after) == 3 && s.view(sid)->object(t2id)->number("fontSize") == 26
              && s.view(sid)->object(t3id)->number("fontSize") == 30 && s.view(sid)->object(t3id)->text("namedStyle") == "Grand_Titre",
          "le style change : les objets suivent, sauf la taille que le troisi\xC3\xA8me avait chang\xC3\xA9" "e ; renomm\xC3\xA9, ils le suivent aussi");
    s.styles[0] = after;
    check(forgetStyle(s, "Grand_Titre") == 3 && s.styles.empty() && s.view(sid)->object(t2id)->text("namedStyle").empty()
              && s.view(sid)->object(t2id)->number("fontSize") == 26,
          "retir\xC3\xA9 : les objets gardent leurs valeurs, ne le citent plus");

    // ---- les modeles de vues
    std::string empty;
    for (const auto& tpl : viewTemplates()) {
        Project m;
        View mv = makeView(m, "V");
        fillFromTemplate(m, mv, tpl.key);
        if ((tpl.key == "vide") != mv.objects.empty()) empty += std::string(tpl.key) + " ";
        if (tpl.key == "equipement" && (mv.role != "popup" || !mv.param("Equipement"))) empty += "equipement(role) ";
    }
    // 1.10.2 : treize de plus (accueil... pied), dix-neuf en tout.
    check(viewTemplates().size() == 19 && empty.empty() && viewTemplate("Tableau de bord") && viewTemplate("alarmes")
              && viewTemplate("Popup moteur") && viewTemplate("pied"),
          "dix-neuf mod\xC3\xA8les : vide ne pose rien, les autres leurs objets ; la popup d'\xC3\xA9quipement a son param\xC3\xA8tre " + empty);

    // ---- l'espacement egal
    {
        View g;
        g.width = 1000;
        g.height = 600;
        g.grid.snapGrid = false;
        g.grid.snapObjects = true;
        Layer l;
        l.id = 1;
        g.layers.push_back(l);
        const auto box = [&](Id id, double x, double y, double w, double h) {
            Object o = makeObject(Kind::Rectangle, id, "R" + std::to_string(id), x, y, 1);
            o.setNumber("w", w);
            o.setNumber("h", h);
            g.objects.push_back(o);
        };
        box(11, 0, 100, 100, 60);
        box(12, 150, 100, 100, 60);     // un ecart de 50
        const Box moving{500, 300, 100, 60};
        // Deplace vers x = 303 (loin de tout alignement a 3 px pres) : accroche a 300 = 250 + 50.
        auto r = edit::snapMove(g, moving, 303 - 500, 100 - 300 + 7, {}, 6.0);
        check(std::fabs(moving.x + r.dx - 300) < 1e-9 && r.spacing.size() == 2 && std::fabs(r.spacing[0].gap - 50) < 1e-9
                  && std::fabs(r.spacing[1].gap - 50) < 1e-9,
              "l'\xC3\xA9" "cart de 50 d\xC3\xA9j\xC3\xA0 pris : repris \xC3\xA0 droite (x = 300), deux cotes");
        View g2 = g;
        g2.objects.pop_back();
        Object far = makeObject(Kind::Rectangle, 13, "R13", 300, 100, 1);
        far.setNumber("w", 100);
        far.setNumber("h", 60);
        g2.objects.push_back(far);
        // Entre 0..100 et 300..400, une boite de 100 : au milieu, x = 150.
        r = edit::snapMove(g2, moving, 148 - 500, 100 - 300 + 7, {}, 6.0);
        check(std::fabs(moving.x + r.dx - 150) < 1e-9 && r.spacing.size() == 2 && std::fabs(r.spacing[0].gap - 50) < 1e-9,
              "entre deux voisins : au milieu (50 de chaque c\xC3\xB4t\xC3\xA9)");
        r = edit::snapMove(g2, moving, 130 - 500, 100 - 300 + 7, {}, 6.0);
        check(r.spacing.empty(), "trop loin (20 px) : pas d'accroche");
    }
    check(guide::topic("concevoir-vite") && guide::topic("styles-nommes") && guide::topic("rechercher-remplacer"),
          "l'aide : concevoir plus vite, les styles, rechercher / remplacer");
}
